window.THINKING_FRAMES = [{"id":"01542348-a785-433b-b5df-509413e764df","name":"EVM 挣值管理","category":"项目管理","scene":"项目进度和成本绩效的量化监控与预测场景","core_logic":"挣值管理通过三个核心指标：计划价值(PV)、挣值(EV)、实际成本(AC)，计算进度偏差(SV)、成本偏差(CV)、进度绩效指数(SPI)、成本绩效指数(CPI)，实现对项目进度和成本的量化评估和趋势预测。","steps":"[{\"name\": \"制定基准计划(PV)\", \"description\": \"\"}, {\"name\": \"定期统计实际成本(AC)\", \"description\": \"\"}, {\"name\": \"计算已完成工作的价值(EV)\", \"description\": \"\"}, {\"name\": \"计算SV/CV/SPI/CPI等指标\", \"description\": \"\"}, {\"name\": \"分析偏差原因并预测趋势\", \"description\": \"\"}, {\"name\": \"制定纠偏措施\", \"description\": \"\"}]","itto":"{\"tools\": [\"挣值计算、偏差分析\"], \"inputs\": [\"项目基准计划、实际成本数据\"], \"outputs\": [\"绩效报告、预测结果、纠偏措施\"]}","tools":"挣值分析软件、S曲线图、预测技术","cases":"PV、EV、AC、SV、CV、SPI、CPI。案例：某项目进度落后，用EVM发现成本超支，及时纠偏。","viz_type":"process","viz_config":"{}","keywords":"EVM,挣值管理,进度偏差,成本偏差,SPI CPI","sort_order":16,"_created_at":"2026-09-15T18:34:13.663+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.777+08:00","_updated_by":"()","code":"PM-EVM-001","aliases":"EVM,挣值管理,Earned Value Management","summary":"通过PV/EV/AC三个指标综合度量项目进度和成本绩效的方法","problem_statement":"项目进度和成本全靠感觉判断，说不清是超前还是滞后、是节约还是超支，等发现问题时往往已经失控；EVM 通过PV/EV/AC三个核心指标量化计算进度偏差和成本偏差，让项目状态一目了然、问题提前暴露。","triggers":"EVM,挣值,进度偏差,成本偏差,SPI CPI","applicable":"中大型项目的进度成本监控、项目汇报、预测预警","not_applicable":"小型简单项目、无法量化工作价值的创意项目","related_frameworks":"关键路径法,甘特图,PMBOK 五大过程组","templates":"EVM挣值分析表模板","limitations":"需要成熟的项目管理基础；EV的计算有主观性（完成百分比估计）；偏向成本和进度维度","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"03e5c486-f1b6-4ae7-b097-7bd5157c27d5","name":"金字塔原理","category":"写作表达","scene":"商务汇报、方案撰写、咨询报告、面试表达、技术文档、电梯演讲。","core_logic":"芭芭拉·明托提出的结构化思考与表达方法：核心是「结论先行、以上统下、归类分组、逻辑递进」。先抛出中心思想，再用 3-5 个主要论点支撑，每个论点又有若干论据支撑，形成自上而下的金字塔结构，让听众/读者快速抓住重点。","steps":"[]","itto":"{\"tools\": [\"MECE原则\", \"归纳法\", \"演绎法\"], \"inputs\": [\"核心观点\", \"论据素材\"], \"outputs\": [\"结构化表达\", \"清晰逻辑\"]}","tools":"MECE 原则、SCQA 架构、归纳推理、演绎推理、思维导图","cases":"某咨询顾问用金字塔原理撰写客户方案：封面直接给出结论「建议进军东南亚市场，预计 3 年回本」，正文第一层三个论点（市场吸引力大、我们有优势、投入可控），每个论点下再用数据和案例层层支撑，客户读完第一页就理解了核心建议。","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"中心思想\", \"description\": \"结论先行，先抛出核心观点或结论\"}, {\"name\": \"主要论点\", \"items\": [\"论点一：问题背景与重要性\", \"论点二：核心原因分析\", \"论点三：解决方案与建议\"]}, {\"name\": \"支撑论据\", \"items\": [\"数据支撑\", \"案例佐证\", \"逻辑推理\", \"专家观点\", \"事实依据\", \"对比分析\"]}]}","keywords":"金字塔,结构化思考,芭芭拉明托,MECE","sort_order":7,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.786+08:00","_updated_by":"()","code":"META-THK-001","aliases":"金字塔","summary":"芭芭拉·明托提出的结构化思考与表达方法：核心是「结论先行、以上统下、归类分组、逻辑递进」。先抛出中心思想，再用 3-5 个主要论点支撑，每个论点又有若干论据支撑","problem_statement":"说话写文章逻辑混乱、东拉西扯，听众抓不住重点，说了半天别人不知道你想表达什么；金字塔原理遵循结论先行、以上统下、归类分组、逻辑递进的原则，让表达自上而下清晰有力。","triggers":"表达混乱、逻辑不清、说服力不足","applicable":"商务汇报、方案撰写、咨询报告、面试表达、技术文档、电梯演讲。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某咨询顾问用金字塔原理撰写客户方案：封面直接给出结论「建议进军东南亚市场，预计 3 年回本」，正文第一层三个论点（市场吸引力大、我们有优势、投入可控），每个论点下再用数据和案例层层支撑，客户读完第一页","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"META"},{"id":"04263435-7c2b-4c04-83e1-a43351f3d61a","name":"价值主张画布","category":"需求管理","scene":"产品定位、价值主张设计、商业模式验证的场景","core_logic":"价值主张画布由两部分组成：用户侧（用户任务、痛点、收益）和产品侧（产品与服务、痛点缓解、收益创造）。通过逐一匹配，检验产品价值主张是否真正解决了用户的核心痛点、创造了用户期望的收益。","steps":"[{\"name\": \"描述目标用户的核心任务\", \"description\": \"\"}, {\"name\": \"列出用户痛点\", \"description\": \"\"}, {\"name\": \"列出用户期望的收益\", \"description\": \"\"}, {\"name\": \"列出产品/服务内容\", \"description\": \"\"}, {\"name\": \"说明产品如何缓解痛点\", \"description\": \"\"}, {\"name\": \"说明产品如何创造收益\", \"description\": \"\"}, {\"name\": \"检查匹配度\", \"description\": \"\"}]","itto":"{\"tools\": [\"画布分析\"], \"inputs\": [\"用户画像、产品概念\"], \"outputs\": [\"价值主张图、匹配度评估\"]}","tools":"价值主张画布、商业模式画布、用户访谈","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"产品侧\", \"y_label\": \"用户侧\", \"quadrants\": {\"q1\": \"价值匹配\"}}","keywords":"价值主张画布,VPC,用户痛点,产品价值,产品定位","sort_order":8,"_created_at":"2026-09-15T18:34:20+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.794+08:00","_updated_by":"()","code":"PROD-VPC-001","aliases":"价值主张画布,Value Proposition Canvas,VPC","summary":"系统描述用户痛点与产品价值点对应关系的分析工具","problem_statement":"产品功能做了一堆但用户并不买账，不知道自己的产品到底解决了用户什么痛点、创造了什么价值；价值主张画布通过用户侧痛点收益与产品侧价值点的逐一匹配，检验价值主张是否真正击中用户核心需求。","triggers":"价值主张,画布,用户痛点,产品价值,VPC","applicable":"产品定位、商业模式设计、营销策划、产品创新","not_applicable":"纯内部工具产品、需求非常明确的定制开发","related_frameworks":"JTBD 理论,商业模式画布,设计思维","templates":"价值主张画布模板","limitations":"需要深入的用户洞察；是静态工具需要持续更新；需要配合商业模式画布使用","mastery_level":"L2","last_used_date":null,"domain_code":"PROD"},{"id":"050e2dd3-4f26-4ef7-b6bb-014d1e296b92","name":"间隔重复","category":"学习方法","scene":"语言学习、考试备考、知识记忆、长期记忆巩固的场景","core_logic":"间隔重复基于艾宾浩斯遗忘曲线和间隔效应：人对新学知识的遗忘是先快后慢的，在快要遗忘的时候进行复习效果最好。通过科学安排复习间隔（越来越长），用最少的复习次数将知识转化为长期记忆。","steps":"[{\"name\": \"整理要记忆的知识点\", \"description\": \"\"}, {\"name\": \"制作成闪卡(Anki等)\", \"description\": \"\"}, {\"name\": \"第一天学习新材料\", \"description\": \"\"}, {\"name\": \"按间隔算法安排复习\", \"description\": \"\"}, {\"name\": \"标记掌握程度，调整间隔\", \"description\": \"\"}, {\"name\": \"长期坚持形成长期记忆\", \"description\": \"\"}]","itto":"{\"tools\": [\"Anki、闪卡工具、间隔算法\"], \"inputs\": [\"待记忆的知识点\"], \"outputs\": [\"长期记忆、知识体系\"]}","tools":"Anki、Quizlet、Memrise、SuperMemo","cases":"需补充","viz_type":"cycle","viz_config":"{}","keywords":"间隔重复,艾宾浩斯,记忆方法,遗忘曲线,Spaced Repetition","sort_order":4,"_created_at":"2026-09-15T18:34:26.561+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.803+08:00","_updated_by":"()","code":"LRN-STU-003","aliases":"间隔重复,Spaced Repetition,艾宾浩斯","summary":"根据遗忘曲线安排复习时间，用最少时间获得最佳记忆效果的学习策略","problem_statement":"学过就忘，复习了又忘，花了大量时间但记忆效果很差，知识永远停留在'好像看过'的层面；间隔重复根据遗忘曲线安排复习节奏，在记忆即将消退时精准复习，用最少时间获得最佳长期记忆效果。","triggers":"间隔重复,艾宾浩斯,记忆,遗忘曲线,复习","applicable":"语言学习、考试备考、知识记忆、词汇积累","not_applicable":"理解型学习、技能型学习（需要练习而非记忆）","related_frameworks":"费曼学习法,SQ3R 阅读法,卡片盒笔记法（Zettelkasten）","templates":"间隔重复学习计划表","limitations":"更适合事实性知识记忆；需要长期坚持；工具和方法有一定学习成本","mastery_level":"L2","last_used_date":null,"domain_code":"LEARN"},{"id":"0557c518-10e6-4e47-b40c-bfd906816986","name":"情境领导模型","category":"团队管理","scene":"团队管理、一对一辅导、新任领导适应的场景","core_logic":"情境领导模型认为没有最好的领导风格，只有最适合的。根据下属的准备度（能力+意愿）分为四档：R1(没能力没意愿)→指令型；R2(没能力有意愿)→教练型；R3(有能力没意愿)→支持型；R4(有能力有意愿)→授权型。","steps":"[{\"name\": \"评估下属的能力水平\", \"description\": \"\"}, {\"name\": \"评估下属的意愿/信心水平\", \"description\": \"\"}, {\"name\": \"确定准备度阶段(R1-R4)\", \"description\": \"\"}, {\"name\": \"选择对应的领导风格(S1-S4)\", \"description\": \"\"}, {\"name\": \"动态调整，随下属成长而变化\", \"description\": \"\"}]","itto":"{\"tools\": [\"一对一沟通、反馈\"], \"inputs\": [\"下属情况、任务要求\"], \"outputs\": [\"有效领导、下属发展\"]}","tools":"一对一沟通、反馈技巧、教练技术","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"任务行为（指导）\", \"y_label\": \"关系行为（支持）\", \"quadrants\": {\"q1\": \"教练型S2\", \"q2\": \"授权型S4\", \"q3\": \"指令型S1\", \"q4\": \"支持型S3\"}}","keywords":"情境领导,领导风格,权变理论,团队管理,下属发展","sort_order":2,"_created_at":"2026-09-15T18:34:20.052+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.811+08:00","_updated_by":"()","code":"TEAM-LEAD-001","aliases":"情境领导,Situational Leadership,赫塞-布兰查德","summary":"根据下属的能力和意愿调整领导风格的权变领导理论","problem_statement":"领导风格一成不变，对新人管得太松导致跟不上，对老员工管得太细又打击积极性，团队效能上不去；情境领导模型根据下属的能力和意愿水平灵活调整领导风格，做到因人施教、因境施策。","triggers":"情境领导,领导风格,权变,下属辅导,授权","applicable":"团队管理、人员辅导、领导力发展、新任主管","not_applicable":"极扁平化自组织团队、完全平等的协作关系","related_frameworks":"塔克曼团队发展模型,GROW 教练模型,授权与分工","templates":"情境领导评估表","limitations":"对下属状态的评估有主观性；忽略了任务性质的影响；模型简化了复杂的领导情境","mastery_level":"L3","last_used_date":null,"domain_code":"TEAM"},{"id":"0604724d-fc61-4650-95a6-fc637518caf2","name":"PMBOK 五大过程组","category":"项目管理","scene":"系统化开展项目管理、建立项目管理流程的场景","core_logic":"PMBOK将项目管理划分为五大过程组：启动过程组（立项授权）、规划过程组（制定计划）、执行过程组（协调执行）、监控过程组（跟踪控制）、收尾过程组（正式收尾）。五个过程组贯穿项目全生命周期。","steps":"[{\"name\": \"启动：立项、授权、确定干系人\", \"description\": \"\"}, {\"name\": \"规划：制定范围/进度/成本/质量/风险等计划\", \"description\": \"\"}, {\"name\": \"执行：协调人力和资源完成工作\", \"description\": \"\"}, {\"name\": \"监控：跟踪、测量、控制变更\", \"description\": \"\"}, {\"name\": \"收尾：验收、移交、总结、归档\", \"description\": \"\"}]","itto":"{\"tools\": [\"PMBOK知识体系、项目管理工具\"], \"inputs\": [\"项目章程、商业论证\"], \"outputs\": [\"项目成果、收尾文档\"]}","tools":"项目管理软件、WBS、甘特图、EVM、RACI","cases":"需补充","viz_type":"cycle","viz_config":"{}","keywords":"PMBOK,过程组,项目管理体系,启动规划执行监控收尾","sort_order":10,"_created_at":"2026-09-15T18:34:13.577+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.819+08:00","_updated_by":"()","code":"PM-KNW-001","aliases":"PMBOK,项目管理五大过程组","summary":"项目管理的全流程框架：启动—规划—执行—监控—收尾","problem_statement":"做项目东一榔头西一棒子，启动没规划、执行不监控、收尾不总结，项目全靠人治难以复制；PMBOK 将项目管理拆解为启动-规划-执行-监控-收尾五大过程组，为每一步提供标准动作和工具集。","triggers":"PMBOK,过程组,项目管理,流程,全周期","applicable":"各类项目管理、企业项目管理体系建设、项目经理能力提升","not_applicable":"简单个人任务、纯探索性研究项目","related_frameworks":"十大知识领域,ITTO,PDCA 循环","templates":"PMBOK过程组映射表","limitations":"理论体系庞大，需要结合实际裁剪；偏向预测型项目，敏捷场景需调整","mastery_level":"L2","last_used_date":null,"domain_code":"PM"},{"id":"09025eb6-792f-46a1-81b9-2caa7b4cff0a","name":"政策过程：议程—制定—执行—评估—反馈","category":"科研写作","scene":"政策分析类论文、政策评估研究、公共管理研究、政策全过程分析","core_logic":"政策是一个动态循环的过程而非一次性产出。从问题进入议程、到政策制定、执行、评估，再根据评估结果反馈调整，形成一个完整的政策生命周期。理解政策过程有助于分析政策成功或失败的原因。","steps":"[{\"name\": \"议程设置 Agenda Setting\", \"description\": \"问题如何进入政策视野，被决策者关注并提上议事日程的过程\"}, {\"name\": \"政策制定 Policy Formulation\", \"description\": \"政策方案的设计、论证、选择和合法化过程，形成正式政策\"}, {\"name\": \"政策执行 Implementation\", \"description\": \"政策进入实施阶段，由执行机构将政策文本转化为实际行动\"}, {\"name\": \"政策评估 Evaluation\", \"description\": \"对政策效果、效率、效益进行系统评估，判断政策是否达成目标\"}, {\"name\": \"反馈调整 Feedback & Adjustment\", \"description\": \"根据评估结果反馈到政策制定端，调整或终止政策，进入下一轮\"}]","itto":"{\"tools\": [\"政策过程理论\", \"多源流模型\", \"执行偏差分析\", \"政策评估方法\"], \"inputs\": [\"社会问题\", \"政策需求\", \"政策资源\"], \"outputs\": [\"政策周期分析报告\", \"政策优化建议\"]}","tools":"多源流分析、街头官僚理论、政策执行偏差分析、成本效益评估、前后对比法","cases":"分析某项教育改革政策：为什么进入议程（多源流交汇）→ 政策方案如何形成（各方博弈）→ 执行中遇到什么问题（地方变通）→ 评估效果如何（政策目标是否实现）→ 是否需要调整（反馈建议）","viz_type":"cycle","viz_config":"{}","keywords":"政策过程,政策周期,议程设置,政策执行,政策评估,政策调研","sort_order":112,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.827+08:00","_updated_by":"()","code":"RES-WRI-007","aliases":"政策过程","summary":"政策是一个动态循环的过程而非一次性产出。从问题进入议程、到政策制定、执行、评估，再根据评估结果反馈调整，形成一个完整的政策生命周期。理解政策过程有助于分析政策成","problem_statement":"政策分析只研究政策文本本身，忽视政策形成和运行的全过程，无法解释政策为什么这样出台、为什么执行走样；政策过程框架将政策视为动态循环的生命周期，从议程设置到执行评估全链条分析。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"政策分析类论文、政策评估研究、公共管理研究、政策全过程分析","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"分析某项教育改革政策：为什么进入议程（多源流交汇）→ 政策方案如何形成（各方博弈）→ 执行中遇到什么问题（地方变通）→ 评估效果如何（政策目标是否实现）→ 是否需要调整（反馈建议）","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"098b624a-1f4c-4449-a76a-92b4182f6ab1","name":"变更控制（CCB）","category":"项目管理","scene":"项目范围变更、需求变更、配置变更等需要正式管控的场景","core_logic":"变更控制通过建立变更控制委员会(CCB)和标准化的变更流程（提出申请→影响分析→评审批准→执行实施→验证关闭），确保所有变更都经过充分评估和正式审批，避免随意变更导致的范围蔓延和项目失控。","steps":"[{\"name\": \"提交变更请求(CR)\", \"description\": \"\"}, {\"name\": \"进行影响分析（范围/进度/成本）\", \"description\": \"\"}, {\"name\": \"CCB评审和审批\", \"description\": \"\"}, {\"name\": \"批准后执行变更\", \"description\": \"\"}, {\"name\": \"验证变更并关闭\", \"description\": \"\"}, {\"name\": \"更新项目基线\", \"description\": \"\"}]","itto":"{\"tools\": [\"影响分析、CCB评审\"], \"inputs\": [\"变更请求\"], \"outputs\": [\"变更决策、更新后的项目计划\"]}","tools":"变更请求表单、影响分析模板、CCB会议、配置管理","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"变更控制,CCB,变更管理,需求变更,范围蔓延","sort_order":14,"_created_at":"2026-09-15T18:34:13.619+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.835+08:00","_updated_by":"()","code":"PM-CHG-001","aliases":"变更控制,CCB,变更管理,配置控制委员会","summary":"通过正式评审机制控制项目变更，防止范围蔓延的管理流程","problem_statement":"项目变更随意发生，今天加个需求明天改个范围，项目越做越胖、进度越拖越久，最后没人对结果负责；CCB 通过正式评审机制控制变更，防止范围蔓延，让每一次变更都有据可查、有人审批。","triggers":"变更控制,CCB,需求变更,范围蔓延,变更管理","applicable":"中大型项目、软件项目、工程项目、外包项目","not_applicable":"小型快速迭代项目、敏捷开发（有自己的变更方式）","related_frameworks":"需求跟踪矩阵 RTM,干系人参与计划,KANO 模型","templates":"变更控制流程模板、变更请求表单","limitations":"流程较繁琐，可能影响响应速度；需要明确的授权和职责划分","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"0a7cbf49-1a74-4ac0-816d-d36ccddb99f8","name":"8D 问题解决法","category":"思维方法","scene":"质量问题、客户投诉、重大缺陷的系统性解决场景","core_logic":"8D是福特公司开发的八步问题解决流程：组建团队→描述问题→临时措施→根因分析→永久纠正措施→验证措施→预防再发→团队祝贺。强调团队协作和永久预防。","steps":"[{\"name\": \"D1 组建问题解决团队\", \"description\": \"\"}, {\"name\": \"D2 描述问题(5W2H)\", \"description\": \"\"}, {\"name\": \"D3 实施临时遏制措施\", \"description\": \"\"}, {\"name\": \"D4 识别并验证根本原因\", \"description\": \"\"}, {\"name\": \"D5 选择永久纠正措施\", \"description\": \"\"}, {\"name\": \"D6 验证纠正措施效果\", \"description\": \"\"}, {\"name\": \"D7 预防再发措施\", \"description\": \"\"}, {\"name\": \"D8 祝贺团队\", \"description\": \"\"}]","itto":"{\"tools\": [\"团队协作、根因分析工具\"], \"inputs\": [\"质量问题/客户投诉\"], \"outputs\": [\"纠正措施报告、预防机制\"]}","tools":"5Why、鱼骨图、FMEA、统计过程控制","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"8D,质量改进,问题解决,根因分析,纠正措施","sort_order":8,"_created_at":"2026-09-15T18:34:03.255+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.843+08:00","_updated_by":"()","code":"SOL-THK-004","aliases":"8D,8 Disciplines,八步法","summary":"面向团队的结构化问题解决八步法，强调永久消除根本原因","problem_statement":"团队解决问题靠个人经验，东一榔头西一棒子，解决不彻底、同类问题反复发生，质量和效率都上不去；8D问题解决法提供八步结构化流程，强调团队协作和永久消除根本原因，让问题解决系统化、彻底化。","triggers":"8D,质量问题,根因,纠正措施,预防","applicable":"制造业质量问题、客户投诉处理、重大缺陷整改、供应链问题","not_applicable":"小问题日常事务、个人问题","related_frameworks":"5Why 分析法,根本原因分析 RCA,DMAIC","templates":"8D报告模板","limitations":"流程较复杂，适合重大问题；需要跨部门团队配合；周期较长","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"0a7ddb24-7662-491c-8f1b-2fc267541b21","name":"调研课题写作框架组合应用指南","category":"科研写作","scene":"论文写作起步阶段的框架选择和搭配规划，研究者选择合适的分析框架组合","core_logic":"调研课题写作很少只用一个框架，通常需要多个框架组合使用。本指南总结了四类最常见的论文类型的框架搭配方案：政策调研型、产业规划型、学位论文型、工程管理型。每种类型都有主框架+辅助框架的组合逻辑，帮助研究者快速找到适合自己论文的框架组合。","steps":"[]","itto":"{\"tools\": [\"框架组合方法\", \"研究设计\", \"论文结构规划\"], \"inputs\": [\"论文类型\", \"研究主题\", \"可用框架\"], \"outputs\": [\"论文写作框架方案\", \"最优框架组合\"]}","tools":"研究设计方法、论文结构规划、框架匹配","cases":"写一篇县域乡村振兴对策研究论文：属于政策调研论文类型 → 主框架用\"现状-问题-原因-对策\" → 辅助用PESTEL分析宏观环境 + SWOT分析发展定位 + 利益相关者分析参与主体 → 按IMRaD学术规范组织论文结构。","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"四大经典论文组合模板\", \"description\": \"根据不同类型的调研课题，推荐搭配不同的分析框架组合\"}, {\"name\": \"政策调研论文\", \"items\": [\"主结构：IMRaD 学术规范\", \"核心分析：现状—问题—原因—对策\", \"问题诊断：问题域界定 + 解空间设计\", \"适用：政府咨询报告、对策研究、政策建议类论文\"]}, {\"name\": \"产业规划论文\", \"items\": [\"宏观环境：PESTEL + 五力模型 + 价值链\", \"战略分析：SWOT 分析定位\", \"路径设计：问题—原因—对策 闭环\", \"适用：产业发展规划、区域经济研究、战略研究论文\"]}, {\"name\": \"学位论文\", \"items\": [\"章节结构：引言→文献综述→理论框架→研究方法→实证/案例→讨论→结论\", \"调研模块放在第4-6章核心位置\", \"理论框架：根据研究范式选择（实证/案例/质性/混合）\", \"适用：硕士博士学位论文、深度学术研究\"]}, {\"name\": \"工程管理论文\", \"items\": [\"问题域分析：明确问题边界和约束条件\", \"方案设计：多方案备选 + 评估比选\", \"实施保障：组织+资源+风险\", \"适用：工程管理、项目管理、系统设计类论文\"]}]}","keywords":"组合应用,论文框架,写作模板,研究设计,框架搭配,组合应用","sort_order":170,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.85+08:00","_updated_by":"()","code":"RES-WRI-014","aliases":"组合应用","summary":"调研课题写作很少只用一个框架，通常需要多个框架组合使用。本指南总结了四类最常见的论文类型的框架搭配方案：政策调研型、产业规划型、学位论文型、工程管理型。每种类型","problem_statement":"论文写作不知道该选什么框架、怎么搭配，要么单框架不够用要么多框架堆砌逻辑混乱，论文结构不伦不类；本指南针对政策调研型、产业规划型、学位论文型、工程管理型四类常见论文给出框架搭配方案。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"论文写作起步阶段的框架选择和搭配规划，研究者选择合适的分析框架组合","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"写一篇县域乡村振兴对策研究论文：属于政策调研论文类型 → 主框架用\"现状-问题-原因-对策\" → 辅助用PESTEL分析宏观环境 + SWOT分析发展定位 + 利益相关者分析参与主体 → 按IMRaD","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"0e37d595-93e3-456b-8fdd-97c1eca94e1b","name":"探索性/描述性/解释性研究结构","category":"科研写作","scene":"研究设计阶段选择合适的研究类型和论文结构，适用于各类学术研究的起步规划","core_logic":"根据研究目的和领域成熟度，研究可分为三大类：探索性研究（新领域、现象不明，重在发现问题）、描述性研究（现象已存在但缺乏系统了解，重在描绘全貌）、解释性研究（现象和变量明确，重在揭示因果机制）。三类研究对应不同的方法论和论文结构。","steps":"[]","itto":"{\"tools\": [\"研究设计方法\", \"定性定量方法\", \"案例研究\", \"统计分析\"], \"inputs\": [\"研究问题\", \"研究目标\", \"领域成熟度\"], \"outputs\": [\"对应类型的研究论文\", \"研究发现\"]}","tools":"研究方法论、案例研究法、调查研究法、实验法","cases":"新兴领域研究通常从探索性（个案研究提出命题）开始 → 逐渐发展到描述性（大样本调查描绘现状）→ 最终走向解释性（实证检验因果关系），是一个领域从萌芽到成熟的演进路径。","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"研究目的三层分类\", \"description\": \"按研究目的可分为探索性、描述性和解释性三类，对应不同的研究设计和论文结构\"}, {\"name\": \"三大研究类型\", \"items\": [\"探索性研究：新现象初探，提出问题和假设\", \"描述性研究：描绘现状和特征，回答是什么\", \"解释性研究：揭示因果关系，回答为什么\"]}, {\"name\": \"各自适用结构\", \"items\": [\"探索性：文献-案例-命题-展望\", \"描述性：背景-现状-特征-分类\", \"解释性：理论-假设-数据-检验-结论\"]}]}","keywords":"探索性研究,描述性研究,解释性研究,研究设计,学术通用","sort_order":104,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.858+08:00","_updated_by":"()","code":"RES-WRI-004","aliases":"探索性研究","summary":"根据研究目的和领域成熟度，研究可分为三大类：探索性研究（新领域、现象不明，重在发现问题）、描述性研究（现象已存在但缺乏系统了解，重在描绘全貌）、解释性研究（现象","problem_statement":"研究设计阶段不知道该用什么研究类型，方法与问题不匹配，该探索的硬要解释、该深入的非要泛化，论文质量上不去；三类研究结构帮你根据研究目的和领域成熟度选择匹配的研究类型和论文结构。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"研究设计阶段选择合适的研究类型和论文结构，适用于各类学术研究的起步规划","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"新兴领域研究通常从探索性（个案研究提出命题）开始 → 逐渐发展到描述性（大样本调查描绘现状）→ 最终走向解释性（实证检验因果关系），是一个领域从萌芽到成熟的演进路径。","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"104e8507-36fe-4ec0-bcec-3036928de8bf","name":"KANO 模型","category":"需求管理","scene":"需求优先级判断、产品功能规划、用户满意度管理的场景","core_logic":"KANO模型将需求分为五类：基本型需求（必备，有了也不高兴，没有会不满）、期望型需求（越好越满意）、兴奋型需求（惊喜，没有也不觉得缺，有了超满意）、无差异型、反向型。不同类型需求的投入策略不同。","steps":"[{\"name\": \"收集候选需求列表\", \"description\": \"\"}, {\"name\": \"设计KANO问卷（正反问题）\", \"description\": \"\"}, {\"name\": \"发放问卷收集数据\", \"description\": \"\"}, {\"name\": \"按KANO分类规则归类需求\", \"description\": \"\"}, {\"name\": \"结合重要度确定优先级\", \"description\": \"\"}, {\"name\": \"指导产品规划\", \"description\": \"\"}]","itto":"{\"tools\": [\"KANO问卷、统计分析\"], \"inputs\": [\"需求列表、目标用户\"], \"outputs\": [\"需求分类结果、优先级建议\"]}","tools":"KANO问卷、Better-Worse系数分析","cases":"基本型、期望型、兴奋型。案例：某产品需求评审，用KANO砍掉了30%的伪需求。","viz_type":"matrix","viz_config":"{\"x_label\": \"需求满足度\", \"y_label\": \"用户满意度\", \"quadrants\": {\"q1\": \"兴奋型需求\", \"q2\": \"基本型需求\", \"q3\": \"反向型需求\", \"q4\": \"期望型需求\"}}","keywords":"KANO,需求分类,用户满意度,基本型期望型兴奋型,优先级","sort_order":4,"_created_at":"2026-09-15T18:34:13.73+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.866+08:00","_updated_by":"()","code":"PROD-KANO-001","aliases":"KANO模型,狩野模型,卡诺模型","summary":"将用户需求分为基本型、期望型、兴奋型三类的需求分类模型","problem_statement":"需求优先级拍脑袋决定，该做的没做、不该做的做了一堆，资源投入与用户满意度不成正比；KANO模型将需求分为基本型、期望型、兴奋型三类，帮你识别哪些是'做了也不说好但不做就骂'的基础需求，哪些是能带来惊喜的加分项。","triggers":"KANO,需求分类,满意度,优先级,基本型期望型兴奋型","applicable":"产品需求分析、功能优先级排序、产品规划、用户满意度管理","not_applicable":"需求极少的小型产品、纯技术需求","related_frameworks":"MoSCoW 优先级,需求跟踪矩阵 RTM,JTBD 理论","templates":"KANO问卷模板","limitations":"需求类型会随时间变化（兴奋型会变成基本型）；问卷设计要求高；需要足够样本量","mastery_level":"L3","last_used_date":null,"domain_code":"PROD"},{"id":"113fe0f4-998f-4bf7-9819-6d6953d4cdf8","name":"原型法","category":"需求管理","scene":"需求验证、产品设计评审、用户测试、方案沟通的场景","core_logic":"在投入大量开发资源之前，用低成本的方式（纸面、线框图、可交互原型）制作产品雏形，让用户可以看到甚至操作，通过用户反馈快速验证需求理解是否正确、设计方案是否可行。","steps":"[{\"name\": \"明确原型目标和保真度\", \"description\": \"\"}, {\"name\": \"设计原型（纸面/线框/高保真）\", \"description\": \"\"}, {\"name\": \"内部评审迭代\", \"description\": \"\"}, {\"name\": \"用户测试收集反馈\", \"description\": \"\"}, {\"name\": \"根据反馈修改原型\", \"description\": \"\"}, {\"name\": \"最终确认后进入开发\", \"description\": \"\"}]","itto":"{\"tools\": [\"原型设计工具\"], \"inputs\": [\"需求文档、用户画像\"], \"outputs\": [\"验证后的原型、用户反馈报告\"]}","tools":"Figma、Axure、Sketch、纸面原型、墨刀","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"原型法,原型设计,需求验证,用户测试,快速迭代","sort_order":3,"_created_at":"2026-09-15T18:34:13.718+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.874+08:00","_updated_by":"()","code":"PROD-RES-003","aliases":"原型,Prototype,原型设计","summary":"通过制作产品原型快速验证需求和获取用户反馈的方法","problem_statement":"需求靠文字和脑补，开发出来才发现不是用户想要的，返工成本高、沟通效率低，需求反复变更；原型法通过可视化的产品原型快速验证需求，让用户在开发前就能看到摸到，大幅降低理解偏差和返工风险。","triggers":"原型,原型设计,验证,用户测试,快速迭代","applicable":"新产品设计、功能迭代、需求验证、用户测试、设计评审","not_applicable":"需求非常明确的简单功能、纯后台逻辑功能","related_frameworks":"MVP 最小可行产品,设计思维,用户故事","templates":"原型评审检查表","limitations":"原型和真实产品有差距；过度追求高保真会浪费时间；需要避免用户只评价外观","mastery_level":"L3","last_used_date":null,"domain_code":"PROD"},{"id":"12b3a19d-ffe2-4d10-a756-725d8177ea3b","name":"钻石模型","category":"科研写作","scene":"国家/区域竞争力研究、产业集群研究、国际比较研究、产业政策论文","core_logic":"波特的钻石模型解释一个国家/地区为什么能在某个产业取得国际竞争优势。核心是四大要素（生产要素、需求条件、相关支持产业、企业战略与竞争）形成钻石体系，加上政府和机遇两个辅助因素，共同决定产业的国家竞争优势。","steps":"[]","itto":"{\"tools\": [\"钻石模型分析\", \"产业集群研究\", \"国际比较\"], \"inputs\": [\"国家/地区产业数据\", \"政策环境\", \"市场信息\"], \"outputs\": [\"国家竞争优势分析\", \"产业升级路径\"]}","tools":"钻石模型框架、产业集群测度（区位熵）、DEA效率分析、国际比较研究","cases":"为什么深圳的电子信息产业有国际竞争力？用钻石模型分析：生产要素（人才聚集+资本充足）、需求条件（庞大的国内市场+挑剔消费者）、相关产业（完善的电子供应链+产业集群）、企业战略竞争（激烈的市场竞争+民营企业活力）、政府（政策支持+自贸区）、机遇（移动互联网浪潮）","viz_type":"matrix","viz_config":"{\"quadrants\": [{\"name\": \"生产要素\", \"items\": [\"自然资源\", \"人力资源\", \"知识资源\", \"资本资源\", \"基础设施\"], \"description\": \"一个国家/地区的生产要素禀赋\"}, {\"name\": \"需求条件\", \"items\": [\"国内市场规模\", \"需求增长速度\", \"需求 sophistication\", \"挑剔型客户\"], \"description\": \"国内市场需求的质量和特性\"}, {\"name\": \"相关与支持性产业\", \"items\": [\"上游供应商\", \"下游产业\", \"配套产业\", \"产业集群效应\"], \"description\": \"相关产业和支持产业的竞争力\"}, {\"name\": \"企业战略结构竞争\", \"items\": [\"企业管理模式\", \"竞争激烈程度\", \"创新氛围\", \"创业环境\"], \"description\": \"企业的组织管理形态和国内竞争强度\"}, {\"name\": \"政府\", \"items\": [\"产业政策\", \"教育投入\", \"基础设施\", \"监管环境\"], \"description\": \"政府的作用（辅助因素）\"}, {\"name\": \"机遇\", \"items\": [\"技术突破\", \"金融危机\", \"突发事件\", \"政策窗口\"], \"description\": \"偶然事件和机遇（辅助因素）\"}], \"xAxisLabel\": \"四大核心要素 + 两大辅助因素\", \"yAxisLabel\": \"\"}","keywords":"钻石模型,波特,国家竞争优势,产业集群,国际竞争力,战略产业","sort_order":124,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.882+08:00","_updated_by":"()","code":"DEC-IND-003","aliases":"钻石模型","summary":"波特的钻石模型解释一个国家/地区为什么能在某个产业取得国际竞争优势。核心是四大要素（生产要素、需求条件、相关支持产业、企业战略与竞争）形成钻石体系，加上政府和机","problem_statement":"研究产业竞争力不知道从哪里切入，分析维度零散不系统，说不清为什么某个国家/地区的某个产业能领先；钻石模型从生产要素、需求条件、相关支持产业、企业战略四大要素构建分析体系，系统解释产业竞争优势来源。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"国家/区域竞争力研究、产业集群研究、国际比较研究、产业政策论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"为什么深圳的电子信息产业有国际竞争力？用钻石模型分析：生产要素（人才聚集+资本充足）、需求条件（庞大的国内市场+挑剔消费者）、相关产业（完善的电子供应链+产业集群）、企业战略竞争（激烈的市场竞争+民营","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"13c5c588-3a26-413f-8a1c-6ba34a087285","name":"风险应对四大策略","category":"风险分析","scene":"项目风险管理、企业危机应对、投资决策、产品迭代风险评估、应急预案制定。","core_logic":"根据风险的性质和影响程度，选择四种应对策略之一：规避（消除风险源）、转移（将后果转嫁给第三方）、减轻（降低概率或影响）、接受（主动建立储备或被动承受）。选择的核心依据是风险发生概率、影响程度以及应对成本。","steps":"[]","itto":"{\"tools\": [\"决策树\", \"蒙特卡洛\", \"专家判断\"], \"inputs\": [\"风险登记册\", \"风险评估结果\"], \"outputs\": [\"风险应对计划\", \"风险责任人\"]}","tools":"风险矩阵、决策树分析、蒙特卡洛模拟、EMV 预期货币价值","cases":"某软件项目识别出「核心技术人员离职」风险：采用减轻策略（建立知识文档库、代码评审制度、关键岗位备份）+ 接受策略（预留 10% 应急时间），最终在一名核心开发离职时，项目仅延期 2 天，远低于预期的 2 周影响。","viz_type":"matrix","viz_config":"{\"quadrants\": [{\"name\": \"规避 Avoid\", \"items\": [\"取消高风险活动\", \"改变策略\", \"缩小范围\", \"增加资源\"], \"description\": \"改变计划消除风险或保护目标免受影响\"}, {\"name\": \"转移 Transfer\", \"items\": [\"购买保险\", \"外包\", \"签订固定价合同\", \"设立担保\"], \"description\": \"将风险后果转移给第三方，财务风险常见\"}, {\"name\": \"减轻 Mitigate\", \"items\": [\"增加测试\", \"原型验证\", \"选用稳定技术\", \"冗余设计\"], \"description\": \"降低风险发生概率或影响到可接受阈值\"}, {\"name\": \"接受 Accept\", \"items\": [\"建立应急储备\", \"分配应急时间\", \"接受现状\", \"定期监控\"], \"description\": \"不改变计划，主动建立应急储备或被动应对\"}], \"xAxisLabel\": \"主动应对 → 被动接受\", \"yAxisLabel\": \"概率高 → 概率低\"}","keywords":"风险应对,风险管理,PMP,四大策略","sort_order":9,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.889+08:00","_updated_by":"()","code":"PM-RSK-001","aliases":"风险应对","summary":"根据风险的性质和影响程度，选择四种应对策略之一：规避（消除风险源）、转移（将后果转嫁给第三方）、减轻（降低概率或影响）、接受（主动建立储备或被动承受）。选择的核","problem_statement":"面对风险只会一味回避或者硬扛，不知道不同风险该用不同策略，资源浪费在不该花的地方；风险应对四大策略根据风险的性质和影响程度，选择规避、转移、减轻、接受中最适合的策略，让风险管理精准高效。","triggers":"风险不明、决策犹豫、不确定性高","applicable":"项目风险管理、企业危机应对、投资决策、产品迭代风险评估、应急预案制定。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某软件项目识别出「核心技术人员离职」风险：采用减轻策略（建立知识文档库、代码评审制度、关键岗位备份）+ 接受策略（预留 10% 应急时间），最终在一名核心开发离职时，项目仅延期 2 天，远低于预期的 ","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"14cf3d5a-9a53-45e2-a15b-6c8f79960a87","name":"MECE 原则","category":"思维方法","scene":"问题拆解、信息分类、方案设计时需要结构化梳理的场景","core_logic":"将一个整体问题按维度逐层拆解，保证各子集之间相互独立（Mutually Exclusive）、所有子集合起来完全穷尽（Collectively Exhaustive），从而实现完整、清晰的结构化分析。","steps":"[{\"name\": \"明确分析范围和目标\", \"description\": \"\"}, {\"name\": \"选择第一维度拆解\", \"description\": \"\"}, {\"name\": \"检查各子集是否相互独立\", \"description\": \"\"}, {\"name\": \"检查所有子集是否覆盖全部范围\", \"description\": \"\"}, {\"name\": \"继续下一层拆解直到足够细\", \"description\": \"\"}]","itto":"{\"tools\": [\"逻辑树、矩阵图\"], \"inputs\": [\"待分析的问题/主题\"], \"outputs\": [\"结构化的分析框架\"]}","tools":"逻辑树、思维导图、矩阵图、二分法","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"MECE,结构化,分类,穷尽,独立","sort_order":10,"_created_at":"2026-09-15T18:34:03.085+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.897+08:00","_updated_by":"()","code":"META-THK-002","aliases":"MECE,相互独立完全穷尽","summary":"确保分类不重叠、不遗漏的结构化思维原则","problem_statement":"分析问题时分类要么重叠要么遗漏，维度混乱、逻辑不清，分析结果要么重复劳动要么有重大盲区，越分析越乱；MECE原则确保分类相互独立、完全穷尽，让你的分析不重不漏、逻辑严谨，是结构化思维的基石。","triggers":"分类,拆解,结构化,穷尽,独立","applicable":"问题分解、信息整理、方案对比、报告撰写等需要结构化思考的场景","not_applicable":"艺术创作、灵感发散等不需要严格结构化的场景","related_frameworks":"金字塔原理,逻辑树分析,第一性原理","templates":"二分法分类模板、矩阵分类模板","limitations":"现实中很多问题边界模糊，难以做到绝对 MECE；过度追求穷尽可能导致分析效率低下","mastery_level":"L3","last_used_date":null,"domain_code":"META"},{"id":"162d6bd5-e54d-43ad-b44c-e80c768a2252","name":"总分总写作框架","category":"写作表达","scene":"商务邮件、汇报材料、议论文、演讲稿、产品文档等需要清晰表达观点的写作场景。","core_logic":"遵循「结论先行—分层论证—总结升华」的三段式结构：开头亮出核心观点让读者一目了然，中间从多个维度展开论述提供论据支撑，结尾总结重申观点并升华主题，确保表达既有力又完整。","steps":"[{\"name\": \"总-开头点题\", \"description\": \"开门见山提出核心观点或结论，统领全文，让读者一目了然\"}, {\"name\": \"分-分层论述\", \"description\": \"从多个角度、分多个段落展开论证，每个段落有明确的主题句和论据支撑\"}, {\"name\": \"总-结尾升华\", \"description\": \"总结全文要点，重申核心观点，并可适当升华主题或发出号召\"}]","itto":"{\"tools\": [\"大纲法\", \"思维导图\", \"MECE原则\"], \"inputs\": [\"写作主题\", \"素材资料\", \"写作目标\"], \"outputs\": [\"完整文章\", \"结构化表达\"]}","tools":"Xmind 大纲、石墨文档协作、Markdown 写作、金字塔原理","cases":"某产品经理用总分总结构撰写季度汇报：开头直接抛出「Q3 营收同比增长 35%」的结论，中间从产品、运营、市场三个维度展开数据论证，结尾提出 Q4 增长目标和战略重点，汇报一次性通过。","viz_type":"process","viz_config":"{}","keywords":"写作,总分总,结构化表达","sort_order":3,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.904+08:00","_updated_by":"()","code":"RES-WRI-001","aliases":"写作","summary":"遵循「结论先行—分层论证—总结升华」的三段式结构：开头亮出核心观点让读者一目了然，中间从多个维度展开论述提供论据支撑，结尾总结重申观点并升华主题，确保表达既有力","problem_statement":"写文章想到哪写到哪，开头铺垫太长、中间散乱、结尾仓促，读者读完全文不知核心观点为何；总分总结构遵循结论先行-分层论证-总结升华的三段式，开头亮观点、中间给支撑、结尾再强化，让表达既清晰又有力。","triggers":"表达混乱、逻辑不清、说服力不足","applicable":"商务邮件、汇报材料、议论文、演讲稿、产品文档等需要清晰表达观点的写作场景。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某产品经理用总分总结构撰写季度汇报：开头直接抛出「Q3 营收同比增长 35%」的结论，中间从产品、运营、市场三个维度展开数据论证，结尾提出 Q4 增长目标和战略重点，汇报一次性通过。","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"RES"},{"id":"1669f8a9-8015-4bce-9594-cf795dcd4f2e","name":"访谈法","category":"需求管理","scene":"产品需求探索、用户研究、问题定义的定性研究阶段","core_logic":"通过结构化或半结构化的一对一对话，深入了解用户的行为、动机、痛点和期望，获取问卷调查无法触及的深层信息，为产品设计和需求定义提供真实依据。","steps":"[{\"name\": \"明确访谈目标和假设\", \"description\": \"\"}, {\"name\": \"设计访谈提纲\", \"description\": \"\"}, {\"name\": \"招募目标用户\", \"description\": \"\"}, {\"name\": \"执行访谈（倾听为主）\", \"description\": \"\"}, {\"name\": \"整理访谈记录并编码分析\", \"description\": \"\"}, {\"name\": \"提炼洞察和需求\", \"description\": \"\"}]","itto":"{\"tools\": [\"访谈提纲、录音设备\"], \"inputs\": [\"研究目标、目标用户画像\"], \"outputs\": [\"用户洞察报告、需求列表\"]}","tools":"访谈提纲、录音笔、亲和图法、编码分析","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"用户访谈,定性研究,需求调研,用户洞察,深度访谈","sort_order":1,"_created_at":"2026-09-15T18:34:13.697+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.912+08:00","_updated_by":"()","code":"PROD-RES-001","aliases":"用户访谈,深度访谈,User Interview","summary":"通过与用户一对一深入对话获取真实需求和洞察的定性研究方法","problem_statement":"关起门来想需求，想当然地替用户做决定，产品上线后才发现用户根本不需要，投入打了水漂；访谈法通过与用户一对一深入对话，挖掘真实使用场景和潜在需求，让需求建立在真实用户声音之上。","triggers":"用户访谈,需求调研,定性研究,用户洞察,访谈","applicable":"产品需求探索、用户研究、市场调研、问题定义","not_applicable":"需要统计显著性的大规模验证、已有明确需求的执行阶段","related_frameworks":"问卷调查,原型法,JTBD 理论","templates":"用户访谈提纲模板、访谈记录模板","limitations":"样本量小不具备统计意义；访谈结果受访谈者技巧影响大；用户说的和做的可能不一致","mastery_level":"L3","last_used_date":null,"domain_code":"PROD"},{"id":"1c64d623-8f0d-4f34-aef9-a2a2a74809f8","name":"黄金圈法则","category":"决策思维","scene":"品牌建设、领导力沟通、产品定位、创业方向、演讲表达的场景","core_logic":"黄金圈法则由西蒙·斯涅克提出，将思维和沟通分为三个层次：最外层What（做什么）、中间层How（怎么做）、最内层Why（为什么做）。普通人和组织从外而内思考（先讲做什么再说怎么做最后讲为什么），而伟大的领导者和品牌由内而外沟通（先讲为什么，再讲怎么做，最后讲做什么）。因为人们购买的不是你的产品，而是你的信念。","steps":"[{\"name\": \"探索Why（为什么）\", \"description\": \"深入思考：我们为什么存在？我们的信念是什么？我们做这件事的初心是什么？\"}, {\"name\": \"明确How（怎么做）\", \"description\": \"我们独特的做事方式是什么？我们的核心能力和差异化方法是什么？\"}, {\"name\": \"梳理What（做什么）\", \"description\": \"我们具体提供什么产品或服务？我们做的事情是什么？\"}, {\"name\": \"验证一致性\", \"description\": \"检查Why-How-What是否一致，What是否真正体现了Why和How\"}, {\"name\": \"由内而外重构沟通\", \"description\": \"将所有对外和对内沟通从Why开始，再讲How，最后才是What\"}, {\"name\": \"应用到品牌和产品\", \"description\": \"在品牌定位、产品设计、用户体验中贯穿Why的理念\"}, {\"name\": \"培养领导者思维\", \"description\": \"管理层带头践行黄金圈思维，决策从Why出发\"}, {\"name\": \"持续检验和强化\", \"description\": \"定期回顾，确保行动不偏离初心，持续强化品牌信念\"}]","itto":"{\"tools\": [\"黄金圈模型、品牌工作坊、用户调研、使命愿景价值观梳理\"], \"inputs\": [\"品牌历史、创始人故事、核心价值观、产品信息、目标用户洞察\"], \"outputs\": [\"品牌核心宣言(Why)、品牌沟通框架、产品价值主张、演讲/营销内容结构\"]}","tools":"品牌工作坊、使命愿景梳理、用户调研、故事叙述技巧","cases":"苹果公司(Think Different)、特斯拉、华为(以客户为中心)、西蒙斯涅克TED演讲","viz_type":"hierarchy","viz_config":"{}","keywords":"黄金圈,Why-How-What,为什么,初心,品牌,领导力,西蒙斯涅克","sort_order":75,"_created_at":"2026-09-16T16:20:50.871+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.92+08:00","_updated_by":"()","code":"DECIDE-GOLDEN-001","aliases":"黄金圈,为什么-怎么做-是什么,Why-How-What,西蒙·斯涅克,Start with Why","summary":"由内而外的思维与表达框架，从Why出发激励人心，而不是从What开始描述","problem_statement":"沟通和营销从'做什么'开始描述，听众和客户没感觉、不认同，沟通效果差、说服不了人；黄金圈法则由内而外思考和表达，从Why出发激励人心，先讲为什么再讲怎么做和做什么。","triggers":"黄金圈,Why-How-What,为什么,Start with Why,西蒙斯涅克,品牌理念,初心","applicable":"品牌建设、领导力沟通、产品定位、创业使命定义、演讲表达、团队激励、营销传播","not_applicable":"纯技术性沟通、紧急事务处理、完全理性的决策场景","related_frameworks":"品牌定位,商业模式画布,电梯演讲,STAR法则,PREP表达法","templates":"黄金圈分析模板、品牌宣言工作坊指南、Why Statement模板","limitations":"可能过度强调情感而忽视产品质量；Why的提炼需要深度思考不是口号；对B2B等理性决策场景效果可能有限","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"1d4e7353-dd5f-4bac-90e2-2ab2efc88454","name":"产品路线图","category":"需求管理","scene":"产品战略规划、跨部门对齐、利益相关者沟通的场景","core_logic":"产品路线图是产品战略的可视化表达，展示产品在未来一段时间内的方向、主要功能里程碑和时间规划，帮助团队和利益相关者对齐目标、理解优先级、做出决策。","steps":"[{\"name\": \"明确产品愿景和战略目标\", \"description\": \"\"}, {\"name\": \"识别关键主题和里程碑\", \"description\": \"\"}, {\"name\": \"按优先级和时间规划排列\", \"description\": \"\"}, {\"name\": \"定义每个阶段的目标和成果\", \"description\": \"\"}, {\"name\": \"与利益相关者沟通对齐\", \"description\": \"\"}, {\"name\": \"定期回顾和更新\", \"description\": \"\"}]","itto":"{\"tools\": [\"优先级排序、路线图工具\"], \"inputs\": [\"产品愿景、市场数据、战略目标\"], \"outputs\": [\"产品路线图、战略沟通材料\"]}","tools":"路线图工具、优先级框架、OKR","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"产品路线图,产品规划,战略,产品愿景,里程碑","sort_order":11,"_created_at":"2026-09-15T18:34:20.027+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.928+08:00","_updated_by":"()","code":"PROD-RD-001","aliases":"产品路线图,Product Roadmap,产品规划","summary":"展示产品愿景、方向、优先级和时间规划的战略沟通工具","problem_statement":"产品做什么全靠临时拍板，团队对未来方向没有共识， stakeholders 各有各的期待，沟通成本极高；产品路线图清晰展示产品愿景、优先级和时间规划，是团队内外对齐方向、管理预期的战略沟通工具。","triggers":"路线图,产品规划,战略,里程碑,愿景","applicable":"产品战略规划、跨部门沟通、产品汇报、投资决策","not_applicable":"探索期产品（方向不确定）、简单功能迭代","related_frameworks":"MoSCoW 优先级,KANO 模型,用户故事","templates":"产品路线图模板","limitations":"需要根据市场变化定期更新；过度精确可能束缚团队；需要平衡战略稳定与敏捷响应","mastery_level":"L2","last_used_date":null,"domain_code":"PROD"},{"id":"1f66c64b-7c9e-4e69-a4af-d43187b3f325","name":"非暴力沟通","category":"团队管理","scene":"冲突调解、绩效反馈、难搞对话、关系改善的场景","core_logic":"非暴力沟通(NVC)由马歇尔·卢森堡提出，核心是四个要素：观察（说出事实而非评判）、感受（表达情绪而非想法）、需要（感受背后的需要）、请求（具体可执行的请求而非命令）。通过同理心地倾听和表达，建立连接并解决冲突。","steps":"[{\"name\": \"观察：描述具体事实，不加评判\", \"description\": \"\"}, {\"name\": \"感受：表达自己的情绪感受\", \"description\": \"\"}, {\"name\": \"需要：说出感受背后的需要\", \"description\": \"\"}, {\"name\": \"请求：提出具体可执行的请求\", \"description\": \"\"}, {\"name\": \"同理倾听对方的四要素\", \"description\": \"\"}]","itto":"{\"tools\": [\"倾听、共情\"], \"inputs\": [\"冲突/对话场景\"], \"outputs\": [\"理解连接、协作解决方案\"]}","tools":"积极倾听、共情、自我觉察","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"非暴力沟通,NVC,冲突调解,共情沟通,关系改善","sort_order":5,"_created_at":"2026-09-15T18:34:20.076+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.936+08:00","_updated_by":"()","code":"TEAM-COM-001","aliases":"NVC,非暴力沟通,Nonviolent Communication","summary":"通过观察—感受—需要—请求四要素实现共情沟通的方法","problem_statement":"沟通中充满评判、指责和情绪，话说出口就伤人，本意是解决问题结果变成吵架，关系越来越僵、矛盾越来越深；非暴力沟通通过观察-感受-需要-请求四要素，剥离评判和情绪，聚焦需求和请求，实现共情沟通、化解冲突。","triggers":"非暴力沟通,NVC,冲突,共情,沟通技巧","applicable":"冲突调解、绩效沟通、亲密关系、团队协作、客户沟通","not_applicable":"紧急命令场景、需要强制执行的场合","related_frameworks":"托马斯-基尔曼冲突模型,GROW 教练模型,情境领导模型","templates":"NVC四要素练习卡","limitations":"需要大量练习才能掌握；在极端情绪下难以应用；不是所有文化都适应这种表达方式","mastery_level":"L3","last_used_date":null,"domain_code":"TEAM"},{"id":"20572b7c-4ed9-45f2-97d4-e9ec5de27698","name":"KPT 复盘法","category":"知识管理","scene":"敏捷迭代回顾、团队短周期复盘、项目快速复盘的场景","core_logic":"KPT是一种简单高效的复盘框架：Keep（做得好的，保持继续）→Problem（遇到的问题，需要改进）→Try（下次尝试的新做法）。简单易学，适合敏捷团队和短周期复盘。","steps":"[{\"name\": \"K 保持：哪些做得好的要继续\", \"description\": \"\"}, {\"name\": \"P 问题：遇到了什么问题和阻碍\", \"description\": \"\"}, {\"name\": \"T 尝试：下次要尝试什么新做法\", \"description\": \"\"}, {\"name\": \"排序优先级\", \"description\": \"\"}, {\"name\": \"确定具体行动责任人\", \"description\": \"\"}]","itto":"{\"tools\": [\"便签、白板\"], \"inputs\": [\"迭代/项目经历\"], \"outputs\": [\"复盘结论、行动计划\"]}","tools":"便签纸、白板、在线协作工具","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"KPT,复盘,敏捷回顾,Keep Problem Try,团队改进","sort_order":7,"_created_at":"2026-09-15T18:34:26.629+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.944+08:00","_updated_by":"()","code":"KNOW-RVW-002","aliases":"KPT,Keep-Problem-Try,复盘","summary":"保持—问题—尝试的简单高效复盘方法","problem_statement":"做完项目不总结，经验留不住、教训记不住，同样的坑反复踩，团队和个人都在原地踏步；KPT复盘法通过保持-问题-尝试三个简单问题，快速回顾项目得失，让每一次经历都转化为成长。","triggers":"KPT,复盘,敏捷回顾,Keep Problem Try","applicable":"敏捷迭代回顾、小团队复盘、短周期项目复盘、个人周复盘","not_applicable":"需要深度根因分析的重大问题、跨部门复杂项目","related_frameworks":"GRAI 复盘法,PDCA 循环,看板","templates":"KPT复盘模板","limitations":"过于简单，深度有限；问题分析可能不够深入；适合高频短周期而非重大复盘","mastery_level":"L2","last_used_date":null,"domain_code":"KNOW"},{"id":"20cc3da6-7933-4439-90f1-fcccf4621efb","name":"动态能力理论","category":"科研写作","scene":"战略管理研究、企业转型研究、创新管理、动态环境下的竞争优势论文","core_logic":"Teece 等人提出的动态能力理论是 RBV 的延伸和发展。RBV 解释了静态环境下的竞争优势，而在快速变化的环境中，企业需要\"动态能力\"——感知机会、抓住机会、持续重构资源的能力，才能不断更新竞争优势。是解释企业在动荡环境中持续成功的核心理论。","steps":"[{\"name\": \"感知能力 Sensing\", \"description\": \"感知和发现外部环境中的机会与威胁，扫描、搜索、学习和解读环境变化\"}, {\"name\": \"抓住能力 Seizing\", \"description\": \"抓住感知到的机会，调动资源开发新产品、新服务、新业务模式\"}, {\"name\": \"重构能力 Transforming\", \"description\": \"根据环境变化持续重构和调整企业的资源结构和组织形态\"}, {\"name\": \"动态能力 = 感知+抓住+重构\", \"description\": \"在快速变化的环境中，企业整合、构建和重构内外部资源/能力以适应变化的能力\"}]","itto":"{\"tools\": [\"动态能力理论\", \"案例研究\", \"问卷调研\", \"多案例比较\"], \"inputs\": [\"企业能力数据\", \"环境变化信息\", \"资源配置情况\"], \"outputs\": [\"动态能力评估报告\", \"能力提升路径\"]}","tools":"动态能力量表、案例研究、纵向案例研究、多案例比较","cases":"诺基亚为什么衰落而苹果为什么崛起？诺基亚在功能机时代有强大的资源和能力，但在智能手机变革来临时，缺乏感知（低估iPhone的革命性）、抓住（转型太慢）和重构（组织僵化）的动态能力；而苹果有极强的动态能力，从电脑→iPod→iPhone→服务，不断自我颠覆。","viz_type":"process","viz_config":"{}","keywords":"动态能力,Dynamic Capabilities,Teece,环境变化,战略更新,管理社科","sort_order":136,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.951+08:00","_updated_by":"()","code":"RES-THY-004","aliases":"动态能力","summary":"Teece 等人提出的动态能力理论是 RBV 的延伸和发展。RBV 解释了静态环境下的竞争优势，而在快速变化的环境中，企业需要\"动态能力\"——感知机会、抓住机会","problem_statement":"用静态资源观看待企业竞争优势，解释不了为什么有些企业在快速变化的环境中持续领先而有些则衰落失败；动态能力理论强调企业在动态环境中感知机会、抓住机会、重构资源的能力，解释了竞争优势的动态来源。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"战略管理研究、企业转型研究、创新管理、动态环境下的竞争优势论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"诺基亚为什么衰落而苹果为什么崛起？诺基亚在功能机时代有强大的资源和能力，但在智能手机变革来临时，缺乏感知（低估iPhone的革命性）、抓住（转型太慢）和重构（组织僵化）的动态能力；而苹果有极强的动态能","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"23a57c98-0a76-4e85-89df-ff379bb4300d","name":"SCP 范式：结构—行为—绩效","category":"科研写作","scene":"产业经济学研究、反垄断分析、市场规制研究、行业竞争力分析论文","core_logic":"SCP 是产业组织理论哈佛学派的经典分析范式：市场结构（Structure）决定企业行为（Conduct），企业行为决定市场绩效（Performance）。结构→行为→绩效是单向因果链，但后来的芝加哥学派等也强调绩效对结构的反向影响。是分析产业组织问题的基础框架。","steps":"[{\"name\": \"S - Structure 市场结构\", \"description\": \"产业的市场结构特征：市场集中度、产品差异化、进入退出壁垒、纵向一体化程度等\"}, {\"name\": \"C - Conduct 企业行为\", \"description\": \"企业在特定市场结构下的行为策略：定价策略、产品策略、研发投入、并购行为、合谋等\"}, {\"name\": \"P - Performance 市场绩效\", \"description\": \"市场运行的最终效果：资源配置效率、技术进步效率、利润率、产品质量、社会福利等\"}, {\"name\": \"反馈关系\", \"description\": \"绩效反过来影响结构和行为，形成动态演化；政府政策可介入任一环节\"}]","itto":"{\"tools\": [\"SCP分析范式\", \"产业组织理论\", \"集中度测量\", \"效率分析\"], \"inputs\": [\"行业数据\", \"企业行为数据\", \"绩效指标\"], \"outputs\": [\"产业组织分析报告\", \"政策建议\"]}","tools":"市场集中度（CRn、HHI）、勒纳指数、DEA效率分析、利润率分析","cases":"中国银行业SCP分析：结构（国有大行垄断，但中小银行数量增加，集中度下降）→ 行为（利率市场化后定价更市场化，差异化竞争增多，金融创新加速）→ 绩效（整体利润率高但增速放缓，服务实体经济能力提升）→ 政策建议（继续放宽准入、鼓励竞争）","viz_type":"process","viz_config":"{}","keywords":"SCP,结构行为绩效,产业组织理论,哈佛学派,产业经济学,战略产业","sort_order":125,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.959+08:00","_updated_by":"()","code":"DEC-IND-004","aliases":"SCP","summary":"SCP 是产业组织理论哈佛学派的经典分析范式：市场结构（Structure）决定企业行为（Conduct），企业行为决定市场绩效（Performance）。结构","problem_statement":"研究产业问题只看企业行为或只看市场绩效，看不到三者之间的因果关系，分析浮于表面、政策建议无依据；SCP范式建立了市场结构决定企业行为、企业行为决定市场绩效的完整分析链条，为产业研究提供清晰逻辑。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"产业经济学研究、反垄断分析、市场规制研究、行业竞争力分析论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"中国银行业SCP分析：结构（国有大行垄断，但中小银行数量增加，集中度下降）→ 行为（利率市场化后定价更市场化，差异化竞争增多，金融创新加速）→ 绩效（整体利润率高但增速放缓，服务实体经济能力提升）→ ","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"2557168e-7449-457d-9585-305cbce6f342","name":"设计思维","category":"思维方法","scene":"产品设计、服务创新、社会问题解决等以人为中心的场景","core_logic":"以用户需求为出发点，通过共情深入理解用户真实需求，定义核心问题，发散构思多种解决方案，快速制作原型并迭代测试，在不断试错中逼近最优解。","steps":"[{\"name\": \"共情(Empathize): 深入理解用户\", \"description\": \"\"}, {\"name\": \"定义(Define): 明确核心问题\", \"description\": \"\"}, {\"name\": \"构思(Ideate): 发散创意\", \"description\": \"\"}, {\"name\": \"原型(Prototype): 制作可交互原型\", \"description\": \"\"}, {\"name\": \"测试(Test): 验证并迭代\", \"description\": \"\"}]","itto":"{\"tools\": [\"用户访谈、原型工具、头脑风暴\"], \"inputs\": [\"用户洞察、问题场景\"], \"outputs\": [\"用户验证的解决方案\"]}","tools":"用户访谈、同理心地图、头脑风暴、原型设计、用户测试","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"设计思维,用户中心,创新,原型,共情","sort_order":17,"_created_at":"2026-09-15T18:34:03.176+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.967+08:00","_updated_by":"()","code":"META-THK-009","aliases":"Design Thinking,设计思维","summary":"以人为本的创新方法论，通过共情—定义—构思—原型—测试解决复杂问题","problem_statement":"创新以技术和方案为中心，做出来的东西用户不需要，投入大量资源却没人买单，创新失败率高；设计思维以人为本，通过共情-定义-构思-原型-测试五步，从用户真实需求出发创造有价值的解决方案。","triggers":"设计思维,用户中心,创新,原型,共情","applicable":"产品设计、服务创新、教育、医疗、社会创新","not_applicable":"纯技术优化问题、已有明确方案的问题","related_frameworks":"MVP 最小可行产品,JTBD 理论,价值主张画布","templates":"同理心地图、设计思维工作坊手册","limitations":"实施周期较长；需要跨职能团队配合；容易停留在流程形式而忽略本质","mastery_level":"L3","last_used_date":null,"domain_code":"META"},{"id":"2a11a9b7-4fbb-42f1-926d-094397504d1b","name":"MVP 最小可行产品","category":"需求管理","scene":"新产品验证、创业项目、功能探索等需要快速验证假设的场景","core_logic":"MVP（最小可行产品）是指用最少的功能实现，快速推向市场收集用户反馈，验证核心价值假设，而不是一开始就做完整功能的产品。目标是用最小成本验证产品是否有价值。","steps":"[{\"name\": \"识别最核心的价值假设\", \"description\": \"\"}, {\"name\": \"定义MVP需要验证的问题\", \"description\": \"\"}, {\"name\": \"设计最小功能集合\", \"description\": \"\"}, {\"name\": \"快速开发/制作MVP\", \"description\": \"\"}, {\"name\": \"推向目标用户收集反馈\", \"description\": \"\"}, {\"name\": \"根据反馈决定坚持/转型/放弃\", \"description\": \"\"}]","itto":"{\"tools\": [\"快速开发、原型工具\"], \"inputs\": [\"产品假设、目标用户\"], \"outputs\": [\"MVP产品、用户反馈、验证结论\"]}","tools":"原型设计、低代码工具、精益创业方法论","cases":"需补充","viz_type":"cycle","viz_config":"{}","keywords":"MVP,最小可行产品,精益创业,验证假设,快速迭代","sort_order":9,"_created_at":"2026-09-15T18:34:20.011+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.974+08:00","_updated_by":"()","code":"PROD-MVP-001","aliases":"MVP,最小可行产品,Minimum Viable Product","summary":"用最小的功能集合快速验证核心假设的产品开发方法","problem_statement":"闭门造车憋大招，花了大量时间做了一堆功能，上线后发现用户根本不需要，浪费了宝贵的时间和资源；MVP用最小的功能集合快速验证核心假设，用最少的投入获取最大的认知，避免在错误的方向上走太远。","triggers":"MVP,最小可行产品,精益创业,验证,快速迭代","applicable":"创业项目、新产品探索、功能创新、市场验证","not_applicable":"需求非常明确的内部系统、监管要求完整功能的产品","related_frameworks":"假设驱动开发,原型法,设计思维","templates":"MVP设计画布","limitations":"MVP不等于低劣产品；可能需要多次迭代才能验证；需要快速迭代能力","mastery_level":"L3","last_used_date":null,"domain_code":"PROD"},{"id":"2a892889-6a17-45aa-ab42-10f160faa44c","name":"卡片盒笔记法（Zettelkasten）","category":"知识管理","scene":"学术研究、知识工作、写作、深度学习的场景","core_logic":"Zettelkasten卡片盒笔记法由社会学家卢曼发明并实践，核心是：每张卡片记录一个原子化的想法，用自己的话写；卡片之间通过双向链接建立关联；知识以网络形式生长而非树形结构存储。帮助产生洞见和写作素材。","steps":"[{\"name\": \"阅读/思考时记录闪念笔记\", \"description\": \"\"}, {\"name\": \"整理为永久卡片（一个想法一张）\", \"description\": \"\"}, {\"name\": \"用自己的话重写，确保理解\", \"description\": \"\"}, {\"name\": \"添加与已有卡片的双向链接\", \"description\": \"\"}, {\"name\": \"定期浏览发现新联系\", \"description\": \"\"}, {\"name\": \"写作时从卡片网络中提取素材\", \"description\": \"\"}]","itto":"{\"tools\": [\"卡片笔记工具、双向链接\"], \"inputs\": [\"阅读/思考素材\"], \"outputs\": [\"知识网络、写作素材、洞见\"]}","tools":"Obsidian、Roam Research、Logseq、卡片软件","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"Zettelkasten,卡片盒笔记,双向链接,知识网络,卢曼","sort_order":8,"_created_at":"2026-09-15T18:34:26.637+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.982+08:00","_updated_by":"()","code":"KNOW-ZET-001","aliases":"Zettelkasten,卡片盒,卢曼卡片盒,卡片笔记","summary":"通过原子化卡片和双向链接构建知识网络的笔记方法","problem_statement":"笔记记了一大堆但互不关联，想用的时候找不到，知识是零散的孤岛，无法产生新想法；卡片盒笔记法通过原子化卡片和双向链接构建知识网络，让笔记之间相互关联、碰撞产生新洞见。","triggers":"Zettelkasten,卡片盒,双向链接,知识网络,卢曼","applicable":"学术研究、写作、知识工作、深度学习、内容创作","not_applicable":"简单信息记录、临时待办、不需要深度思考的场景","related_frameworks":"渐进式总结,CODE 知识加工,PARA 分类法","templates":"Zettelkasten卡片模板","limitations":"需要长期积累才有价值；原子化把握需要练习；工具选择和配置有门槛","mastery_level":"L3","last_used_date":null,"domain_code":"KNOW"},{"id":"2b12ad10-f5df-4332-9b42-44faedf8fe1b","name":"5W2H 分析法","category":"思维方法","scene":"问题全面分析、项目启动前调研、方案设计评审、新产品功能定义、故障根因排查。","core_logic":"通过连续追问七个问题（What/Why/Who/When/Where/How/How much），从不同维度系统地拆解一个问题或任务，避免遗漏关键信息，确保分析的全面性和逻辑性，是最简单有效的结构化思维工具之一。","steps":"[{\"name\": \"What - 是什么\", \"description\": \"做什么？目的是什么？要解决什么问题？\"}, {\"name\": \"Why - 为什么\", \"description\": \"为什么要做？原因是什么？为什么这样做？\"}, {\"name\": \"Who - 谁来做\", \"description\": \"谁负责？谁参与？谁是受众？\"}, {\"name\": \"When - 何时做\", \"description\": \"什么时候开始？什么时候完成？什么时机最合适？\"}, {\"name\": \"Where - 在哪里\", \"description\": \"在哪里做？从哪里入手？范围是什么？\"}, {\"name\": \"How - 怎么做\", \"description\": \"用什么方法？步骤是什么？路径如何？\"}, {\"name\": \"How much - 多少成本\", \"description\": \"花费多少？投入产出比如何？预算多少？\"}]","itto":"{\"tools\": [\"提问法\", \"思维导图\"], \"inputs\": [\"待分析问题\", \"背景信息\"], \"outputs\": [\"全面分析报告\", \"行动方案\"]}","tools":"思维导图、白板讨论、结构化笔记","cases":"某创业团队在产品立项时用 5W2H 梳理：What（做一款职场人学习 App）、Why（职场人碎片化学习需求未被满足）、Who（25-35 岁白领）、When（6 个月 MVP 上线）、Where（移动端为主）、How（短视频+知识卡片形式）、How much（预算 200 万），为后续产品规划提供了清晰的框架。","viz_type":"process","viz_config":"{}","keywords":"5W2H,七何分析法,问题分析","sort_order":6,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.989+08:00","_updated_by":"()","code":"SOL-ANA-001","aliases":"5W2H","summary":"通过连续追问七个问题（What/Why/Who/When/Where/How/How much），从不同维度系统地拆解一个问题或任务，避免遗漏关键信息，确保分析","problem_statement":"分析问题遗漏关键信息，考虑不周全，要么漏了成本要么忘了责任人，执行时才发现一堆没想清楚的问题；5W2H通过What/Why/Who/When/Where/How/How much七个问题，从所有维度系统拆解问题，确保不遗漏。","triggers":"思路卡壳、分析不透彻、缺乏框架","applicable":"问题全面分析、项目启动前调研、方案设计评审、新产品功能定义、故障根因排查。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某创业团队在产品立项时用 5W2H 梳理：What（做一款职场人学习 App）、Why（职场人碎片化学习需求未被满足）、Who（25-35 岁白领）、When（6 个月 MVP 上线）、Where（移","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"SOLVE"},{"id":"2ddcca63-7909-45d3-869c-b2c76c2288f4","name":"问题域—解空间","category":"思维方法","scene":"产品设计、问题诊断、方案设计、论文选题等场景","core_logic":"问题域关注「真正的问题是什么」，解空间关注「如何解决」。大多数人急于跳到解空间而忽略了问题定义。正确的做法是先充分探索和定义问题域，再进入解空间寻找方案。","steps":"[{\"name\": \"进入问题域：收集事实和现象\", \"description\": \"\"}, {\"name\": \"定义真正的问题（而非症状）\", \"description\": \"\"}, {\"name\": \"验证问题定义的准确性\", \"description\": \"\"}, {\"name\": \"进入解空间：生成多种解决方案\", \"description\": \"\"}, {\"name\": \"评估并选择最优方案\", \"description\": \"\"}]","itto":"{\"tools\": [\"用户访谈、观察法、根因分析\"], \"inputs\": [\"现象/症状描述\"], \"outputs\": [\"问题定义、解决方案\"]}","tools":"用户访谈、5Why、现状分析、竞品分析","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"问题域,解空间,问题定义,需求分析,方案设计","sort_order":7,"_created_at":"2026-09-15T18:34:03.242+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:49.997+08:00","_updated_by":"()","code":"SOL-THK-003","aliases":"问题域解空间,Problem-Solution Space","summary":"区分问题定义与解决方案，先正确定义问题再寻找解法的思维框架","problem_statement":"遇到问题还没弄清楚是什么就急着给方案，解决方案一大堆但问题没定义准，越努力离目标越远；问题域-解空间框架提醒你先正确定义问题、再寻找解决方案，避免在错误的问题上浪费时间。","triggers":"问题定义,解空间,问题域,需求分析,方向","applicable":"产品设计、咨询诊断、学术研究、创新项目","not_applicable":"问题已明确定义的执行性任务","related_frameworks":"5Why,逻辑树分析,设计思维","templates":"问题定义画布","limitations":"问题域和解空间的边界有时不清晰；需要平衡探索深度与效率","mastery_level":"L3","last_used_date":null,"domain_code":"SOLVE"},{"id":"3006c4a7-bfd0-4765-bc4b-e0166e61eabc","name":"十大知识领域","category":"项目管理","scene":"系统化学习和应用项目管理知识体系的场景","core_logic":"PMBOK定义了项目管理的十大知识领域：整合、范围、进度、成本、质量、资源、沟通、风险、采购、相关方。每个知识领域包含特定的过程和工具，覆盖项目管理的各个专业维度。","steps":"[{\"name\": \"整合管理：全局协调\", \"description\": \"\"}, {\"name\": \"范围管理：做什么\", \"description\": \"\"}, {\"name\": \"进度管理：什么时候做\", \"description\": \"\"}, {\"name\": \"成本管理：花多少钱\", \"description\": \"\"}, {\"name\": \"质量管理：达到什么标准\", \"description\": \"\"}, {\"name\": \"资源管理：用什么人/资源\", \"description\": \"\"}, {\"name\": \"沟通管理：怎么沟通\", \"description\": \"\"}, {\"name\": \"风险管理：有什么风险\", \"description\": \"\"}, {\"name\": \"采购管理：买什么\", \"description\": \"\"}, {\"name\": \"相关方管理：涉及哪些人\", \"description\": \"\"}]","itto":"{\"tools\": [\"各领域工具技术\"], \"inputs\": [\"项目章程、项目管理计划\"], \"outputs\": [\"各领域交付物\"]}","tools":"WBS、甘特图、EVM、RACI、风险登记册等","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"十大知识领域,PMBOK,项目管理知识体系,范围进度成本","sort_order":11,"_created_at":"2026-09-15T18:34:13.588+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.005+08:00","_updated_by":"()","code":"PM-KNW-002","aliases":"PMBOK十大知识领域,项目管理知识领域","summary":"PMBOK定义的项目管理十大知识模块","problem_statement":"项目管理只盯进度和成本，忽视风险、质量、沟通等维度，出了问题才救火，项目顾此失彼；PMBOK十大知识领域从范围、进度、成本、质量、风险等十个维度系统覆盖项目管理全貌，避免管理盲区。","triggers":"知识领域,PMBOK,项目管理,范围进度成本质量","applicable":"项目管理体系建设、项目经理培养、项目诊断","not_applicable":"简单小型项目（可裁剪）、个人日常任务","related_frameworks":"PMBOK 五大过程组,ITTO,EVM 挣值管理","templates":"十大知识领域检查表","limitations":"体系庞大需要裁剪使用；不同项目类型侧重点不同","mastery_level":"L2","last_used_date":null,"domain_code":"PM"},{"id":"3126031e-f3f8-4532-9d20-e2114ff0abb3","name":"创新生态系统","category":"科研写作","scene":"区域创新系统研究、创新政策研究、科技园区研究、创新生态评估论文","core_logic":"借鉴生态学的概念研究创新活动，将创新视为一个由多元主体（企业、大学、政府、中介、金融等）相互作用、与环境共同演化的生态系统。强调主体多样性、关系网络、协同进化和环境支撑，而不只是单一主体的创新能力。","steps":"[]","itto":"{\"tools\": [\"生态系统理论\", \"社会网络分析\", \"案例研究\", \"专利分析\"], \"inputs\": [\"创新主体数据\", \"环境信息\", \"政策资料\"], \"outputs\": [\"创新生态系统评估报告\", \"优化路径\"]}","tools":"社会网络分析（SNA）、专利合作网络分析、DEA创新效率、案例研究","cases":"中关村创新生态系统研究：核心物种（大量科技企业）+ 知识源头（清华北大等高校）+ 政府（中关村管委会、政策支持）+ 中介（孵化器、律所、会计师事务所）+ 金融（创投机构聚集）+ 环境（人才高地、创业文化）→ 形成具有自组织能力的创新生态","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"核心物种：企业/研究机构\", \"description\": \"创新的主体，产生创新成果的核心行动者\"}, {\"name\": \"关键种群\", \"items\": [\"企业（创新主体）\", \"大学/科研院所（知识源头）\", \"政府（制度供给）\", \"中介服务机构（桥梁纽带）\", \"金融机构（资本支持）\"]}, {\"name\": \"生态环境\", \"items\": [\"政策环境\", \"文化氛围\", \"人才环境\", \"基础设施\", \"市场环境\"]}, {\"name\": \"生态机制\", \"items\": [\"知识流动机制\", \"利益分配机制\", \"协同进化机制\", \"自我调节机制\"]}]}","keywords":"创新生态系统,创新驱动,区域创新,协同创新,战略产业","sort_order":128,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.013+08:00","_updated_by":"()","code":"DEC-IND-007","aliases":"创新生态系统","summary":"借鉴生态学的概念研究创新活动，将创新视为一个由多元主体（企业、大学、政府、中介、金融等）相互作用、与环境共同演化的生态系统。强调主体多样性、关系网络、协同进化和","problem_statement":"研究创新只关注单个企业或单一因素，忽视创新是多主体相互作用的系统现象，解释不了产业集群和创新高地的形成机制；创新生态系统借鉴生态学视角，将创新视为多元主体与环境共同演化的生态系统。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"区域创新系统研究、创新政策研究、科技园区研究、创新生态评估论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"中关村创新生态系统研究：核心物种（大量科技企业）+ 知识源头（清华北大等高校）+ 政府（中关村管委会、政策支持）+ 中介（孵化器、律所、会计师事务所）+ 金融（创投机构聚集）+ 环境（人才高地、创业文","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"312b78e4-f7fc-4a22-ad0c-440490315c7c","name":"PDCA 循环","category":"项目管理","scene":"质量管理体系建立、流程改进、项目复盘与迭代、团队绩效提升、产品持续优化。","core_logic":"戴明环的核心是「持续改进」：通过 Plan（计划）→ Do（执行）→ Check（检查）→ Act（处理）四个阶段的循环往复，每一轮都总结经验、标准化成功做法、改进不足，逐步逼近目标，实现螺旋式上升。","steps":"[{\"name\": \"P - Plan 计划\", \"description\": \"确定目标和制定行动方案，明确方向和路径\"}, {\"name\": \"D - Do 执行\", \"description\": \"按照计划实施，执行具体任务和措施\"}, {\"name\": \"C - Check 检查\", \"description\": \"对照计划检查执行结果，找出偏差和问题\"}, {\"name\": \"A - Act 处理\", \"description\": \"总结经验教训，标准化成功做法，改进不足，进入下一轮循环\"}]","itto":"{\"tools\": [\"5W2H\", \"鱼骨图\", \"根本原因分析\"], \"inputs\": [\"现状分析\", \"目标设定\"], \"outputs\": [\"改进方案\", \"标准化流程\"]}","tools":"流程图、甘特图、SOP 标准化文档、A3 报告","cases":"某制造企业引入 PDCA 改善产品质量：P 阶段设定次品率从 5% 降到 2% 的目标，D 阶段试点新工艺流程，C 阶段检查发现次品率降至 3.2%，A 阶段将有效措施标准化并启动下一轮改进，持续 3 个循环后次品率稳定在 1.8%。","viz_type":"cycle","viz_config":"{}","keywords":"PDCA,戴明环,持续改进,循环","sort_order":4,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.021+08:00","_updated_by":"()","code":"PM-QA-001","aliases":"PDCA","summary":"戴明环的核心是「持续改进」：通过 Plan（计划）→ Do（执行）→ Check（检查）→ Act（处理）四个阶段的循环往复，每一轮都总结经验、标准化成功做法、","problem_statement":"做事做一步算一步，做完不总结，同样的错反复犯，能力和质量都上不去，长期在低水平重复；PDCA通过计划-执行-检查-处理的闭环，让每一轮都沉淀经验、标准化成功做法，实现持续改进。","triggers":"项目延期、进度失控、范围蔓延、资源不足","applicable":"质量管理体系建立、流程改进、项目复盘与迭代、团队绩效提升、产品持续优化。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某制造企业引入 PDCA 改善产品质量：P 阶段设定次品率从 5% 降到 2% 的目标，D 阶段试点新工艺流程，C 阶段检查发现次品率降至 3.2%，A 阶段将有效措施标准化并启动下一轮改进，持续 3","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"3195c922-e7bb-467a-be61-ca891d57f509","name":"STP 市场细分定位","category":"产品营销","scene":"产品定位、市场进入、品牌建设、目标用户选择、竞争差异化的场景","core_logic":"STP理论由营销大师菲利普·科特勒（Philip Kotler）系统阐述并推广，是现代营销战略的核心三部曲：S（Segmentation 市场细分）——按照一定标准将整个市场划分为若干个细分市场；T（Targeting 目标市场选择）——评估各细分市场的吸引力，选择一个或几个作为目标市场；P（Positioning 市场定位）——在目标用户心智中建立独特的认知和形象。STP帮助企业从「满足所有人」转向「聚焦目标用户、建立差异化优势」，是营销战略的起点。","steps":"[{\"name\": \"市场调研与数据收集\", \"description\": \"收集市场、用户、竞争等各方面数据，为细分提供依据\"}, {\"name\": \"市场细分(Segmentation)\", \"description\": \"选择细分维度（地理/人口/心理/行为等），将市场划分为不同的细分市场\"}, {\"name\": \"描述各细分市场\", \"description\": \"详细描述每个细分市场的特征、规模、需求、行为模式等\"}, {\"name\": \"评估细分市场吸引力\", \"description\": \"从规模、增长性、盈利性、竞争强度等方面评估各细分市场的吸引力\"}, {\"name\": \"选择目标市场(Targeting)\", \"description\": \"结合自身能力和资源，选择一个或几个最有吸引力的细分市场作为目标\"}, {\"name\": \"分析竞争格局\", \"description\": \"分析目标市场中现有竞争者的定位和优劣势，找到差异化空间\"}, {\"name\": \"市场定位(Positioning)\", \"description\": \"确定你在目标用户心智中的独特位置——你是谁、为谁解决什么问题、和别人有什么不同\"}, {\"name\": \"制定定位传播策略\", \"description\": \"围绕定位设计产品、价格、渠道、传播等所有营销组合，将定位植入用户心智\"}]","itto":"{\"tools\": [\"市场调研、聚类分析、用户画像、竞品分析、定位图、品牌工作坊\"], \"inputs\": [\"市场数据、用户调研、竞争分析、企业能力评估\"], \"outputs\": [\"市场细分报告、目标市场选择、定位声明、差异化策略、营销战略方案\"]}","tools":"市场调研、聚类分析、用户画像、竞品分析、定位地图、品牌工作坊","cases":"宝洁多品牌战略、农夫山泉定位、王老吉定位（怕上火喝王老吉）、特斯拉定位","viz_type":"process","viz_config":"{}","keywords":"STP,市场细分,目标市场,市场定位,差异化,Segmentation,Targeting,Positioning","sort_order":103,"_created_at":"2026-09-16T16:20:51.086+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.029+08:00","_updated_by":"()","code":"PROD-STP-001","aliases":"STP,市场细分,目标市场选择,市场定位,Segmentation Targeting Positioning","summary":"市场细分-目标市场选择-市场定位三步曲，系统化找到最佳目标客群并建立差异化认知","problem_statement":"产品定位模糊，想讨好所有人结果谁都不买账，营销投入打了水漂，品牌没有差异化认知；STP通过市场细分-目标市场选择-市场定位三步，系统化找到最佳目标客群并建立差异化认知。","triggers":"STP,市场细分,目标市场,市场定位,Segmentation,Targeting,Positioning,差异化","applicable":"新产品定位、品牌战略制定、市场进入策略、用户增长、竞争差异化、营销规划","not_applicable":"完全垄断无竞争的市场、标准化的公共产品、纯技术驱动无需定位的产品","related_frameworks":"4P营销组合,蓝海战略ERRC框架,PMF产品市场契合,用户画像,品牌定位","templates":"STP分析模板、市场细分表、定位声明模板、竞品定位地图","limitations":"市场细分的标准选择很关键，分错了后续都错；数据收集和分析成本较高；定位一旦形成很难改变；过度细分可能导致市场规模太小","mastery_level":"L2","last_used_date":null,"domain_code":"PROD"},{"id":"3327fd60-0e0c-4c40-a682-11ca8d5859a7","name":"需求—功能—架构—实现—验证","category":"科研写作","scene":"软件工程论文、系统设计类研究、工程技术类论文、产品开发研究","core_logic":"经典的系统工程和软件开发生命周期模型，从需求出发，经过功能设计、架构设计、编码实现到测试验证，形成完整的开发闭环。体现了工程化思维：先想清楚做什么（需求），再想怎么做（设计），然后动手做（实现），最后检查对不对（验证）。","steps":"[{\"name\": \"需求分析 Requirements\", \"description\": \"系统全面地收集、分析和确认系统需求，包括功能需求和非功能需求\"}, {\"name\": \"功能设计 Functions\", \"description\": \"基于需求设计系统的功能模块和功能结构，明确各功能的输入输出\"}, {\"name\": \"架构设计 Architecture\", \"description\": \"设计系统的整体架构，包括模块划分、接口设计、技术选型和部署方案\"}, {\"name\": \"编码实现 Implementation\", \"description\": \"按照设计方案进行编码开发，实现各模块功能，完成系统集成\"}, {\"name\": \"测试验证 Verification\", \"description\": \"通过单元测试、集成测试、系统测试、验收测试等验证系统是否满足需求\"}]","itto":"{\"tools\": [\"需求工程\", \"系统架构设计\", \"软件工程\", \"测试方法\"], \"inputs\": [\"用户需求\", \"技术条件\", \"资源投入\"], \"outputs\": [\"系统设计方案\", \"软件/系统产品\", \"测试报告\"]}","tools":"UML建模、需求规格说明书、架构图、敏捷开发、DevOps","cases":"某智慧校园信息系统开发论文：需求分析（学生、教师、管理者的各类需求）→ 功能设计（教务、学工、科研、人事等模块）→ 架构设计（微服务架构、前后端分离、云部署）→ 实现（技术栈选型、编码、集成）→ 验证（功能测试、性能测试、用户验收测试）","viz_type":"process","viz_config":"{}","keywords":"软件工程,系统工程,需求分析,架构设计,软件生命周期,工程系统","sort_order":161,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.036+08:00","_updated_by":"()","code":"RES-WRI-012","aliases":"软件工程","summary":"经典的系统工程和软件开发生命周期模型，从需求出发，经过功能设计、架构设计、编码实现到测试验证，形成完整的开发闭环。体现了工程化思维：先想清楚做什么（需求），再想","problem_statement":"工程类论文写作逻辑混乱，需求没说清就讲实现，架构没论证就写细节，评审一看就觉得不严谨、不系统；需求-功能-架构-实现-验证遵循工程化思维，从需求出发层层递进，让论文逻辑严密、结构完整。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"软件工程论文、系统设计类研究、工程技术类论文、产品开发研究","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某智慧校园信息系统开发论文：需求分析（学生、教师、管理者的各类需求）→ 功能设计（教务、学工、科研、人事等模块）→ 架构设计（微服务架构、前后端分离、云部署）→ 实现（技术栈选型、编码、集成）→ 验证","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"3604bcc3-4f4d-48c5-a2ec-651bfa5d9d20","name":"翻转课堂","category":"教学科研","scene":"课堂教学改革、线上线下混合式教学、提升课堂参与度的场景","core_logic":"翻转课堂将传统的课堂讲授+课后作业的顺序颠倒过来：学生课前通过视频等材料自主学习知识，课堂时间用于讨论、练习、答疑、项目等深度互动活动。这样可以提高课堂参与度和学习深度。","steps":"[{\"name\": \"制作课前学习材料（视频/阅读）\", \"description\": \"\"}, {\"name\": \"设计课前学习任务和检测\", \"description\": \"\"}, {\"name\": \"设计课堂互动活动（讨论/练习/项目）\", \"description\": \"\"}, {\"name\": \"学生课前自主学习\", \"description\": \"\"}, {\"name\": \"课堂互动深化理解\", \"description\": \"\"}, {\"name\": \"课后巩固和延伸\", \"description\": \"\"}]","itto":"{\"tools\": [\"视频制作、互动教学设计\"], \"inputs\": [\"教学内容、学习平台\"], \"outputs\": [\"翻转课程方案、混合学习资源\"]}","tools":"在线学习平台、视频录制工具、互动工具、学习管理系统","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"翻转课堂,混合式教学,Flipped Classroom,在线学习,教学改革","sort_order":8,"_created_at":"2026-09-15T18:34:26.544+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.044+08:00","_updated_by":"()","code":"TEACH-FLIP-001","aliases":"翻转课堂,Flipped Classroom,颠倒课堂","summary":"将知识传授放在课前、课堂用于互动练习的教学模式","problem_statement":"传统课堂老师讲学生听，知识传授占满课堂时间，学生被动接收，课后做作业又没人指导，学习效果差；翻转课堂将知识传授放在课前、课堂用于互动练习和答疑，让学生在最需要老师帮助的时候得到支持。","triggers":"翻转课堂,混合式教学,Flipped Classroom,在线学习,互动","applicable":"高校教学、职业教育、企业培训、K12教育","not_applicable":"纯理论性的讲座、学生自学能力差的低龄阶段、没有线上学习条件的场景","related_frameworks":"BOPPPS 课堂模型,形成性评价与终结性评价,布鲁姆认知分类法","templates":"翻转课堂教学设计模板","limitations":"需要学生较强的自主学习能力；课前材料制作成本高；不认真预习会影响课堂效果","mastery_level":"L2","last_used_date":null,"domain_code":"TEACH"},{"id":"3662e674-614d-4aa8-8c84-db5d0ad993be","name":"问题根因分析 RCA","category":"客户交付","scene":"重大客户投诉、系统故障、服务质量问题的深度分析场景","core_logic":"针对客户重大问题，不仅要解决当前问题，更要通过系统化的根因分析找到问题根源，制定纠正和预防措施，防止类似问题再次发生，持续提升客户满意度。","steps":"[{\"name\": \"确认问题事实和影响\", \"description\": \"\"}, {\"name\": \"收集数据和时间线\", \"description\": \"\"}, {\"name\": \"用5Why/鱼骨图找根因\", \"description\": \"\"}, {\"name\": \"制定纠正措施和预防措施\", \"description\": \"\"}, {\"name\": \"跟踪措施落地效果\", \"description\": \"\"}, {\"name\": \"向客户反馈和致歉\", \"description\": \"\"}]","itto":"{\"tools\": [\"5Why、鱼骨图、故障树\"], \"inputs\": [\"客户问题事件\"], \"outputs\": [\"根因报告、改进措施\"]}","tools":"5Why、鱼骨图、故障树分析、时间线还原","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"RCA,根因分析,客户问题,投诉处理,持续改进","sort_order":7,"_created_at":"2026-09-15T18:34:20.161+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.052+08:00","_updated_by":"()","code":"CUST-RCA-001","aliases":"RCA,根因分析,客户问题根因","summary":"对客户投诉和重大问题进行系统性根因分析并制定改进措施的方法","problem_statement":"客户问题解决了又复发，每次只处理表面症状不深挖根因，客户满意度持续下降，团队疲于奔命救火；RCA对客户投诉和重大问题进行系统性根因分析，找到问题根源并制定预防措施，防止同类问题反复发生。","triggers":"RCA,根因分析,客户投诉,问题改进,预防","applicable":"客户投诉处理、重大故障复盘、服务质量改进、客户成功管理","not_applicable":"小问题常规处理、一次性偶发事件","related_frameworks":"8D 问题解决法,客户升级机制,客户满意度管理","templates":"客户问题RCA报告模板","limitations":"需要跨部门协作和数据支持；分析质量依赖团队能力；改进措施落地需要推动","mastery_level":"L2","last_used_date":null,"domain_code":"CUST"},{"id":"36713803-4229-426b-82ec-4ca9977b473e","name":"客户旅程图","category":"客户交付","scene":"客户体验优化、服务设计、客户痛点识别的场景","core_logic":"客户旅程图从客户视角出发，按阶段描绘客户与企业的所有接触点、客户行为、想法、情绪、痛点和机会点，帮助团队全面理解客户体验，找到改进机会。","steps":"[{\"name\": \"明确目标客户和场景\", \"description\": \"\"}, {\"name\": \"划分客户旅程阶段\", \"description\": \"\"}, {\"name\": \"梳理各阶段的客户行为和触点\", \"description\": \"\"}, {\"name\": \"标注客户的想法和情绪曲线\", \"description\": \"\"}, {\"name\": \"识别痛点和机会点\", \"description\": \"\"}, {\"name\": \"制定改进计划\", \"description\": \"\"}]","itto":"{\"tools\": [\"用户访谈、数据分\"], \"inputs\": [\"用户研究数据、客户反馈\"], \"outputs\": [\"客户旅程图、改进机会清单\"]}","tools":"用户访谈、数据分析、服务设计工具、便签工作坊","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"客户旅程图,客户体验,触点,服务设计,痛点","sort_order":4,"_created_at":"2026-09-15T18:34:20.136+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.06+08:00","_updated_by":"()","code":"CUST-JNY-001","aliases":"客户旅程,Customer Journey,用户旅程地图","summary":"端到端可视化客户与企业交互的全流程体验工具","problem_statement":"只站在企业视角看服务流程，不了解客户端到端的体验和痛点，哪里体验差不知道，改进找不到方向；客户旅程图可视化客户与企业交互的全流程，精准识别体验痛点和改进机会，让优化有的放矢。","triggers":"客户旅程,体验地图,客户体验,触点,痛点","applicable":"客户体验优化、服务设计、产品设计、客户成功、营销设计","not_applicable":"极简单的交易型服务、内部流程优化（应使用流程图）","related_frameworks":"NPS 净推荐值,客户满意度管理,价值主张画布","templates":"客户旅程图模板","limitations":"绘制需要充分的用户研究；容易变成静态墙贴而不落地；需要跨部门协作推动改进","mastery_level":"L3","last_used_date":null,"domain_code":"CUST"},{"id":"373655b7-ae04-4e04-82f9-a57ae39a0f37","name":"现状—问题—原因—对策","category":"科研写作","scene":"政策调研报告、咨询报告、对策研究论文、政府决策参考","core_logic":"最经典的问题导向型研究框架：先把现状说清楚，再从中找问题，然后深挖原因，最后对症下药提出解决方案。逻辑链条清晰：是什么→哪里不好→为什么不好→怎么办。是政策研究和应用类论文最常用的结构。","steps":"[{\"name\": \"现状分析\", \"description\": \"全面描绘研究对象的当前状态、发展水平、主要特征和基本事实\"}, {\"name\": \"问题识别\", \"description\": \"从现状中提炼出存在的主要问题、矛盾和困境，明确问题表现\"}, {\"name\": \"原因剖析\", \"description\": \"深入分析问题产生的深层原因，区分直接原因和根本原因\"}, {\"name\": \"对策建议\", \"description\": \"针对问题和原因，提出系统性、可操作的解决方案和政策建议\"}]","itto":"{\"tools\": [\"实地调研\", \"访谈法\", \"统计分析\", \"SWOT分析\"], \"inputs\": [\"调研数据\", \"现状材料\", \"问题清单\"], \"outputs\": [\"政策调研报告\", \"对策建议方案\"]}","tools":"实地调研法、深度访谈、问卷调查、统计分析、鱼骨图根因分析","cases":"某市养老服务发展研究：现状（机构数量、床位数、服务能力）→ 问题（供给不足、质量不高、人才短缺）→ 原因（财政投入不足、薪酬待遇低、培训体系缺失）→ 对策（加大财政支持、提高从业人员待遇、建立培训体系）","viz_type":"process","viz_config":"{}","keywords":"现状问题原因对策,问题导向,政策研究,调研报告,政策调研","sort_order":110,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.067+08:00","_updated_by":"()","code":"RES-WRI-005","aliases":"现状问题原因对策","summary":"最经典的问题导向型研究框架：先把现状说清楚，再从中找问题，然后深挖原因，最后对症下药提出解决方案。逻辑链条清晰：是什么→哪里不好→为什么不好→怎么办。是政策研究","problem_statement":"问题导向型论文找不到清晰的写作逻辑，要么现状和问题混为一谈，要么原因分析不深入、对策空泛无物；现状-问题-原因-对策遵循是什么→哪里不好→为什么不好→怎么办的经典逻辑链条，层层递进。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"政策调研报告、咨询报告、对策研究论文、政府决策参考","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某市养老服务发展研究：现状（机构数量、床位数、服务能力）→ 问题（供给不足、质量不高、人才短缺）→ 原因（财政投入不足、薪酬待遇低、培训体系缺失）→ 对策（加大财政支持、提高从业人员待遇、建立培训体系","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"38bec9ea-7938-4928-9d7a-1919ea04beba","name":"飞轮效应","category":"思维模型","scene":"企业增长战略、产品运营、个人习惯养成、组织能力建设的场景","core_logic":"飞轮效应源自吉姆·柯林斯的《从优秀到卓越》：一个公司从优秀到卓越的转变不是一蹴而就的，而是像推动一个巨大的飞轮——一开始很费力，但一圈一圈持续推动，飞轮越转越快，到某个临界点后，飞轮自身的重量和惯性会成为推动力的一部分，加速运转。飞轮的核心是找到各环节之间的正反馈循环，让每一步的成果成为下一步的动力，形成自我增强的良性循环。","steps":"[{\"name\": \"理解你的业务本质\", \"description\": \"深入理解你的业务是靠什么驱动增长的——用户、内容、数据还是品牌？\"}, {\"name\": \"识别关键驱动因素\", \"description\": \"找出影响增长的3-6个关键环节或要素\"}, {\"name\": \"设计正反馈循环\", \"description\": \"设计各环节之间的因果关系，让A带来B，B又强化A，形成闭环\"}, {\"name\": \"画出飞轮示意图\", \"description\": \"用图示清晰表达飞轮的各环节和它们之间的增强关系\"}, {\"name\": \"集中力量推第一圈\", \"description\": \"在飞轮转动初期，集中所有资源推动，克服初始静摩擦\"}, {\"name\": \"持续推动积累动能\", \"description\": \"不要停下来，一圈接一圈持续推动，让飞轮逐渐加速\"}, {\"name\": \"观察临界点\", \"description\": \"注意观察飞轮什么时候开始「自己转」——增长开始自驱动\"}, {\"name\": \"持续优化飞轮\", \"description\": \"飞轮转起来后不断优化各环节效率，让飞轮转得更快更稳\"}]","itto":"{\"tools\": [\"正反馈设计、系统思考、增长模型、数据驱动、持续优化\"], \"inputs\": [\"初始资源、战略聚焦、持续投入、各环节协同、时间耐心\"], \"outputs\": [\"自我增强的增长循环、加速增长曲线、品牌势能、竞争壁垒\"]}","tools":"系统动力学、增长黑客、A/B测试、数据驱动运营、正反馈设计","cases":"亚马逊飞轮(更低价格→更多用户→更多卖家→更丰富选品→更低价格)、抖音算法推荐、微信社交网络、苹果生态系统","viz_type":"cycle","viz_config":"{}","keywords":"飞轮效应,增长飞轮,正反馈,良性循环,增长引擎,复利","sort_order":87,"_created_at":"2026-09-16T16:20:50.984+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.075+08:00","_updated_by":"()","code":"META-FLYWHEEL-001","aliases":"飞轮模型,增长飞轮,Flywheel Effect,正反馈循环,良性循环","summary":"让各环节相互增强形成增长飞轮，前期推动费力，转速起来后靠惯性自动加速","problem_statement":"增长靠持续的外力推动，一停就下滑，每个环节各自为战，前期投入大、增长慢且难以持续；飞轮效应让各环节相互增强形成正反馈循环，前期推动费力，转速起来后靠惯性自动加速，实现自驱增长。","triggers":"飞轮效应,增长飞轮,正反馈,良性循环,复利效应,飞轮模型,Flywheel","applicable":"企业增长战略、产品运营、用户增长、品牌建设、个人习惯养成、组织能力构建","not_applicable":"一次性项目、线性增长业务、外部环境剧烈变化的领域、无法形成正反馈的系统","related_frameworks":"复利思维,网络效应,正反馈,系统思维,精益创业","templates":"飞轮模型设计模板、增长飞轮诊断表、飞轮优化路线图","limitations":"飞轮启动需要很长时间和大量资源；飞轮设计需要深刻的业务洞察；飞轮可能因外部冲击停转；过度依赖飞轮可能忽视创新和新机会","mastery_level":"L2","last_used_date":null,"domain_code":"META"},{"id":"394b522c-0947-4923-ad2a-90c06d9819c9","name":"客户满意度管理","category":"客户交付","scene":"客户服务质量提升、客户体验优化、服务团队管理的场景","core_logic":"客户满意度管理是一个闭环体系：通过多种方式测量满意度（CSAT/NPS/CES等）→ 分析痛点和原因 → 制定改进措施 → 跟踪改进效果 → 持续优化。目标是通过提升满意度来提高客户留存和口碑。","steps":"[{\"name\": \"选择满意度指标和测量方式\", \"description\": \"\"}, {\"name\": \"定期收集客户反馈\", \"description\": \"\"}, {\"name\": \"分析数据找到关键痛点\", \"description\": \"\"}, {\"name\": \"制定优先级和改进计划\", \"description\": \"\"}, {\"name\": \"推动改进落地\", \"description\": \"\"}, {\"name\": \"持续追踪满意度变化\", \"description\": \"\"}]","itto":"{\"tools\": [\"调研工具、数据分析\"], \"inputs\": [\"客户反馈、服务数据\"], \"outputs\": [\"满意度报告、改进方案\"]}","tools":"CSAT问卷、NPS、客户旅程图、数据分析","cases":"需补充","viz_type":"cycle","viz_config":"{}","keywords":"客户满意度,CSAT,客户体验,服务质量,客户成功","sort_order":8,"_created_at":"2026-09-15T18:34:26.406+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.082+08:00","_updated_by":"()","code":"CUST-CSAT-001","aliases":"CSAT,客户满意度,客户体验管理","summary":"系统性测量、分析和改进客户满意度的管理体系","problem_statement":"客户满意度只靠偶尔的问卷调研，没有系统性管理，满意度低了不知道原因、提升了也不知道为什么，改进盲目；客户满意度管理体系通过测量-分析-改进的闭环，系统管理和持续提升客户满意度。","triggers":"客户满意度,CSAT,客户体验,服务质量,留存","applicable":"客户服务、SaaS产品、零售、服务行业、客户成功","not_applicable":"完全无交互的标准化产品、客户极少的业务","related_frameworks":"NPS 净推荐值,客户旅程图,QBR 季度业务回顾","templates":"客户满意度管理体系模板","limitations":"满意度不等于忠诚度；容易被刷分操纵；改进需要跨部门协作推动","mastery_level":"L2","last_used_date":null,"domain_code":"CUST"},{"id":"3966a570-4e78-4f0c-9672-985ece0c76fa","name":"单案例研究","category":"科研写作","scene":"探索性研究、新现象研究、典型实践剖析、管理学研究、教学案例开发","core_logic":"单案例研究是案例研究的基本形态，通过对一个典型案例进行深入细致的剖析，揭示复杂现象背后的机制和规律。单案例不是\"样本少\"的缺陷，而是\"深入\"的优势——可以挖掘多维度、全过程、多层次的信息，回答\"怎么样\"和\"为什么\"的问题。代表人物：罗伯特·殷（Robert Yin）。","steps":"[{\"name\": \"案例选择\", \"description\": \"按理论抽样选择典型案例（极端案例、关键案例、 revelatory 案例等），而非随机抽样\"}, {\"name\": \"资料收集\", \"description\": \"多源证据收集：访谈、观察、档案、实物等，三角验证提高效度\"}, {\"name\": \"案例深描\", \"description\": \"详尽描述案例的背景、过程、关键事件和结果，呈现丰富的情境信息\"}, {\"name\": \"分析与理论化\", \"description\": \"在案例数据基础上进行分析，提炼概念、构建命题、发展理论\"}, {\"name\": \"理论贡献\", \"description\": \"讨论案例发现的理论意义和实践价值，说明研究贡献\"}]","itto":"{\"tools\": [\"单案例研究法\", \"三角验证\", \"案例深描\", \"模式匹配\"], \"inputs\": [\"研究问题\", \"典型案例\", \"多源数据\"], \"outputs\": [\"单案例研究论文\", \"理论命题\", \"深度发现\"]}","tools":"案例研究方法、三角验证、模式匹配、解释性分析、时间序列分析","cases":"华为公司国际化战略研究：选择华为作为单案例（代表性+极端成功案例），通过公开资料、内部访谈、行业报告等多源数据，深入剖析华为国际化的历程、模式、关键能力和成功逻辑，提炼中国企业国际化的一般规律。","viz_type":"process","viz_config":"{}","keywords":"单案例研究,案例研究,深度案例,典型案例,殷一丁,案例比较","sort_order":151,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.09+08:00","_updated_by":"()","code":"RES-032","aliases":"单案例研究","summary":"单案例研究是案例研究的基本形态，通过对一个典型案例进行深入细致的剖析，揭示复杂现象背后的机制和规律。单案例不是\"样本少\"的缺陷，而是\"深入\"的优势——可以挖掘多","problem_statement":"案例研究被质疑样本太少不科学，不知道单案例研究的价值在哪，写成了案例描述而非学术研究；单案例研究的核心价值在于深入剖析典型案例、揭示复杂现象背后的机制，单案例不是缺陷而是深度优势。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"探索性研究、新现象研究、典型实践剖析、管理学研究、教学案例开发","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"华为公司国际化战略研究：选择华为作为单案例（代表性+极端成功案例），通过公开资料、内部访谈、行业报告等多源数据，深入剖析华为国际化的历程、模式、关键能力和成功逻辑，提炼中国企业国际化的一般规律。","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"39680f4a-a4d7-4564-896f-5dbeeb97ea9f","name":"DDD 领域驱动设计","category":"系统架构","scene":"复杂业务系统设计、微服务划分、系统重构的场景","core_logic":"DDD（领域驱动设计）主张以业务领域为核心驱动软件设计，通过建立统一语言（Ubiquitous Language）、限界上下文（Bounded Context）、聚合（Aggregate）、领域事件（Domain Event）等模式，使软件设计反映业务本质，降低复杂度。","steps":"[{\"name\": \"领域建模：与领域专家协作建立领域模型\", \"description\": \"\"}, {\"name\": \"定义限界上下文\", \"description\": \"\"}, {\"name\": \"设计聚合和实体\", \"description\": \"\"}, {\"name\": \"建立统一语言\", \"description\": \"\"}, {\"name\": \"实现领域层+应用层+基础设施层\", \"description\": \"\"}, {\"name\": \"通过领域事件解耦\", \"description\": \"\"}]","itto":"{\"tools\": [\"事件风暴、领域建模\"], \"inputs\": [\"业务领域知识、需求\"], \"outputs\": [\"领域模型、限界上下文、代码结构\"]}","tools":"事件风暴、UML、领域建模工具、CQRS/ES","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"DDD,领域驱动设计,领域模型,限界上下文,聚合","sort_order":4,"_created_at":"2026-09-15T18:34:26.443+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.098+08:00","_updated_by":"()","code":"ARCH-DDD-001","aliases":"DDD,领域驱动设计,Domain-Driven Design","summary":"以业务领域为核心的软件设计方法论，强调领域模型和统一语言","problem_statement":"软件设计以技术为中心，业务概念被打散到代码各处，业务和技术各说各话，系统越做越复杂、越改越难改；DDD以业务领域为核心，通过领域模型和统一语言让业务与技术对齐，构建可维护的复杂软件系统。","triggers":"DDD,领域驱动设计,领域模型,限界上下文,聚合","applicable":"复杂业务系统、微服务架构、大型系统重构、产品演进","not_applicable":"简单CRUD系统、技术驱动的基础设施项目、快速验证的MVP","related_frameworks":"微服务架构,分层架构,4+1 视图模型","templates":"DDD模式速查卡、事件风暴工作坊指南","limitations":"学习曲线陡峭；需要领域专家深度参与；前期投入较大；不适合所有项目","mastery_level":"L3","last_used_date":null,"domain_code":"ARCH"},{"id":"39d48f23-6eef-4d9b-aa51-d33fbb63903b","name":"麦肯锡 7S 模型","category":"组织发展","scene":"组织诊断、组织变革、战略落地、企业文化建设、组织设计的场景","core_logic":"麦肯锡7S模型由麦肯锡顾问理查德·帕斯卡尔（Richard Pascale）和安东尼·阿索斯（Anthony Athos）提出，后经汤姆·彼得斯（Tom Peters）和罗伯特·沃特曼（Robert Waterman）在《追求卓越》一书中推广而广为人知。该模型认为一个组织的有效性取决于七个要素的协同配合：三个硬S（战略Strategy、结构Structure、制度Systems）和四个软S（共同价值观Shared Values、风格Style、人员Staff、技能Skills）。七个要素相互关联、相互影响，任何一个要素的改变都需要其他要素的配合。组织发展和变革需要七个要素协同推进，只改战略不改人和文化是行不通的。","steps":"[{\"name\": \"明确分析目的\", \"description\": \"明确是做组织诊断、变革规划还是效能评估\"}, {\"name\": \"评估战略(Strategy)\", \"description\": \"组织的战略是什么？是否清晰？是否被理解和认同？\"}, {\"name\": \"评估结构(Structure)\", \"description\": \"组织结构如何？层级关系？部门划分？是否支持战略？\"}, {\"name\": \"评估制度(Systems)\", \"description\": \"关键流程和制度是什么？是否高效？是否支撑战略执行？\"}, {\"name\": \"评估共同价值观(Shared Values)\", \"description\": \"组织的核心价值观和文化是什么？是否深入人心？是否支持战略？\"}, {\"name\": \"评估风格(Style)\", \"description\": \"领导风格是什么？管理风格如何？组织氛围怎样？\"}, {\"name\": \"评估人员(Staff)\", \"description\": \"员工队伍的数量、质量、结构如何？是否满足战略需要？\"}, {\"name\": \"评估技能(Skills)\", \"description\": \"组织和员工的核心能力是什么？是否有竞争优势？\"}, {\"name\": \"分析协同性与差距\", \"description\": \"七个要素之间是否协同？哪些要素存在差距需要调整？\"}, {\"name\": \"制定改进方案\", \"description\": \"针对不协同的要素制定改进措施，确保七个要素联动调整\"}]","itto":"{\"tools\": [\"7S诊断框架、组织调研、访谈法、问卷法、标杆分析\"], \"inputs\": [\"组织现状信息、战略方向、访谈调研数据、行业标杆\"], \"outputs\": [\"组织诊断报告、7S评估结果、组织变革方案、改进路线图\"]}","tools":"组织诊断工具、员工调研、访谈提纲、标杆研究、工作坊","cases":"麦肯锡咨询项目、企业组织变革诊断、并购后组织整合、创业公司规模化组织设计","viz_type":"hierarchy","viz_config":"{}","keywords":"7S模型,麦肯锡7S,组织诊断,组织变革,七要素,企业文化,组织结构","sort_order":94,"_created_at":"2026-09-16T16:20:51.029+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.106+08:00","_updated_by":"()","code":"PM-7S-001","aliases":"7S模型,麦肯锡7S,McKinsey 7S Model,组织七要素,7S框架","summary":"战略、结构、制度、共同价值观、风格、人员、技能七要素协同决定组织效能","problem_statement":"组织变革只调结构或只换战略，忽视其他要素的协同，改了结构效率也没提升、战略换了也落不了地，改革屡屡失败；7S模型从战略、结构、制度、共同价值观、风格、人员、技能七要素协同诊断组织，确保变革系统推进、全面落地。","triggers":"7S模型,麦肯锡7S,组织诊断,组织变革,七大要素,组织设计,企业文化","applicable":"组织诊断、组织变革与重组、战略落地、企业文化建设、并购后整合、组织效能评估","not_applicable":"个人层面的问题分析、小型团队问题诊断、纯技术问题、与组织结构无关的业务问题","related_frameworks":"组织发展理论,平衡计分卡BSC,变革管理,企业文化建设,精益管理","templates":"7S诊断模板、组织调研问卷、7S分析报告模板、变革路线图模板","limitations":"模型较为宏观，提供方向但不提供具体操作方法；软S（文化、风格等）评估主观性强；七个要素的因果关系不清晰；对小型组织可能过于复杂","mastery_level":"L2","last_used_date":null,"domain_code":"PM"},{"id":"3a8cd2c8-22e6-499c-a7c5-da94cd02d790","name":"跨案例比较研究","category":"科研写作","scene":"比较政治经济学、比较公共政策、管理研究、不同地区/国家/企业的比较研究论文","core_logic":"跨案例比较研究强调通过系统的横向比较来识别模式、发现规律、检验理论。核心是比较维度的设计——选对维度才能看出有意义的异同。可以是小样本深度比较（4-10个案例），也可以是中等样本的定性比较分析（10-50个，用QCA方法）。","steps":"[{\"name\": \"比较维度设计\", \"description\": \"设计清晰的比较维度和分析框架，这是跨案例比较的研究设计核心\"}, {\"name\": \"案例资料整理\", \"description\": \"将各案例资料按统一维度和格式整理，形成标准化案例数据库\"}, {\"name\": \"横向比较分析\", \"description\": \"沿每个维度对各案例逐一比较，识别相同点和差异点\"}, {\"name\": \"模式识别与分类\", \"description\": \"基于比较结果识别典型模式，对案例进行类型学分类\"}, {\"name\": \"机制解释\", \"description\": \"解释为什么存在差异、为什么形成这些模式，提炼因果机制\"}]","itto":"{\"tools\": [\"比较研究法\", \"类型学分析\", \"定性比较分析QCA\", \"机制解释\"], \"inputs\": [\"多案例资料\", \"比较分析框架\", \"理论视角\"], \"outputs\": [\"跨案例比较研究\", \"类型学分类\", \"比较分析报告\"]}","tools":"比较方法（最相似/最不同系统设计）、定性比较分析（fsQCA/csQCA/mvQCA）、类型学分析、配置比较","cases":"中国不同城市住房政策比较研究：选取10个城市，设计比较维度（供应体系、保障方式、调控手段、土地政策、金融支持），整理各城市的政策实践数据，通过跨案例比较和QCA分析，找出不同城市政策模式的差异及其影响因素。","viz_type":"process","viz_config":"{}","keywords":"跨案例比较,比较研究,类型学,QCA,比较分析,案例比较","sort_order":153,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.114+08:00","_updated_by":"()","code":"RES-034","aliases":"跨案例比较","summary":"跨案例比较研究强调通过系统的横向比较来识别模式、发现规律、检验理论。核心是比较维度的设计——选对维度才能看出有意义的异同。可以是小样本深度比较（4-10个案例）","problem_statement":"做了多个案例但只是简单罗列，没有系统比较就下结论，研究结论说服力弱、外部效度低，研究价值不足；跨案例比较研究通过精心设计比较维度，用逐项复制和差别复制逻辑提升结论的稳健性和理论建构力。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"比较政治经济学、比较公共政策、管理研究、不同地区/国家/企业的比较研究论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"中国不同城市住房政策比较研究：选取10个城市，设计比较维度（供应体系、保障方式、调控手段、土地政策、金融支持），整理各城市的政策实践数据，通过跨案例比较和QCA分析，找出不同城市政策模式的差异及其影响","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"3adf5f9f-3ea2-439d-b064-1a03458ab559","name":"贝叶斯思维","category":"决策思维","scene":"概率判断、信息更新、诊断推理、投资决策、学习与认知升级的场景","core_logic":"贝叶斯思维源自贝叶斯定理：P(A|B) = P(B|A) × P(A) / P(B)。核心思想是「更新信念」——你对某件事先有一个初始判断（先验概率），当获得新证据时，根据证据的强度和相关性调整你的判断，得到更准确的后验概率。贝叶斯思维强调概率是主观信念的度量，应该随新信息不断更新，而不是固定不变的。","steps":"[{\"name\": \"明确要判断的假设\", \"description\": \"清晰定义你要评估的假设或命题是什么\"}, {\"name\": \"确定先验概率\", \"description\": \"基于已有知识和经验，给出假设成立的初始概率估计\"}, {\"name\": \"收集新证据\", \"description\": \"获取与假设相关的新信息、新数据或新观察\"}, {\"name\": \"评估证据的似然度\", \"description\": \"如果假设成立，观察到这个证据的概率有多大？如果假设不成立呢？\"}, {\"name\": \"计算后验概率\", \"description\": \"用贝叶斯公式更新信念：后验 = 先验 × 似然比 / 归一化因子\"}, {\"name\": \"调整判断和决策\", \"description\": \"根据更新后的概率调整你的判断和行动方案\"}, {\"name\": \"持续收集证据迭代\", \"description\": \"继续收集新信息，不断更新和校准你的信念\"}, {\"name\": \"反思和校准\", \"description\": \"定期回顾你的预测和实际结果，校准你的先验判断能力\"}]","itto":"{\"tools\": [\"贝叶斯公式、贝叶斯网络、概率计算工具、A/B测试、历史数据库\"], \"inputs\": [\"先验知识、新证据/数据、背景信息、领域经验\"], \"outputs\": [\"后验概率、更新后的信念、决策建议、置信度评估\"]}","tools":"贝叶斯公式、A/B测试、概率统计、贝叶斯网络、Python/PyMC3","cases":"医疗疾病诊断、垃圾邮件过滤、投资决策调整、机器学习分类器、情报分析","viz_type":"process","viz_config":"{}","keywords":"贝叶斯,贝叶斯定理,条件概率,后验概率,概率更新,证据推理","sort_order":77,"_created_at":"2026-09-16T16:20:50.894+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.122+08:00","_updated_by":"()","code":"DECIDE-BAYES-001","aliases":"贝叶斯定理,贝叶斯推理,Bayesian Thinking,条件概率,后验概率","summary":"基于新证据不断更新先验概率的迭代决策思维，从「我相信什么」到「根据新信息我该调整多少」","problem_statement":"决策一旦形成就不肯改变，固守先入为主的判断，新信息来了也不调整，导致决策失误和认知僵化；贝叶斯思维基于新证据不断更新先验概率，从'我相信什么'到'根据新信息我该调整多少'，迭代逼近真相。","triggers":"贝叶斯,贝叶斯定理,条件概率,后验概率,概率更新,证据推理,贝叶斯思维","applicable":"医疗诊断、投资决策、信息评估、假设检验、学习认知、风险判断、人工智能","not_applicable":"完全确定性的问题、需要即时反应没有思考时间的场景、涉及价值判断而非事实判断的问题","related_frameworks":"概率思维,期望值决策,蒙特卡洛模拟,第一性原理,批判性思维","templates":"贝叶斯更新工作表、概率判断记录模板、先验-后验对比表","limitations":"先验概率的设定有主观性；计算可能复杂普通人难直接应用；需要持续收集高质量数据；容易误用或过度自信","mastery_level":"L1","last_used_date":null,"domain_code":"DECIDE"},{"id":"3cf9d3e4-eb39-4eed-9a68-786016b755c3","name":"波特五力模型","category":"科研写作","scene":"产业分析、战略研究、行业进入决策、竞争战略制定、产业经济学论文","core_logic":"迈克尔·波特提出的经典产业分析框架，认为一个行业的竞争强度和盈利能力由五种力量共同决定：现有竞争者的竞争、潜在进入者威胁、替代品威胁、供应商议价能力、购买者议价能力。五力越强行业越难做，五力越弱行业利润越丰厚。","steps":"[]","itto":"{\"tools\": [\"五力分析模型\", \"行业集中度CRn\", \"进入壁垒分析\", \"议价能力评估\"], \"inputs\": [\"行业数据\", \"企业信息\", \"市场结构\"], \"outputs\": [\"行业竞争分析报告\", \"产业吸引力评估\"]}","tools":"行业集中度（CR4/CR8/HHI）、进入壁垒分析、价值链分析、议价能力评估矩阵","cases":"中国快递行业五力分析：现有竞争者竞争激烈（价格战）、潜在进入者威胁中等（京东等跨界进入）、替代品威胁较低（时效性不可替代）、供应商议价能力弱（车辆/包装供应充足）、购买者议价能力强（消费者价格敏感）→ 结论：行业竞争激烈，利润薄","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"行业竞争强度\", \"description\": \"决定行业盈利能力的核心是五种竞争力量的共同作用\"}, {\"name\": \"五大竞争力量\", \"items\": [\"现有竞争者之间的竞争程度\", \"潜在进入者的威胁\", \"替代品的威胁\", \"供应商的议价能力\", \"购买者的议价能力\"]}, {\"name\": \"战略含义\", \"items\": [\"竞争激烈→利润稀薄\", \"进入壁垒高→利润丰厚\", \"替代品少→定价权强\", \"供应商强→成本压力大\", \"购买者强→营收压力大\"]}]}","keywords":"五力模型,波特,产业分析,竞争战略,行业吸引力,战略产业","sort_order":122,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.13+08:00","_updated_by":"()","code":"DEC-IND-001","aliases":"五力模型","summary":"迈克尔·波特提出的经典产业分析框架，认为一个行业的竞争强度和盈利能力由五种力量共同决定：现有竞争者的竞争、潜在进入者威胁、替代品威胁、供应商议价能力、购买者议价","problem_statement":"分析行业竞争只盯着直接竞争对手，忽视替代品威胁、供应商和客户议价能力等间接竞争力量，战略判断片面；波特五力模型从现有竞争者、潜在进入者、替代品、供应商、购买者五个维度全面评估行业竞争强度。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"产业分析、战略研究、行业进入决策、竞争战略制定、产业经济学论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"中国快递行业五力分析：现有竞争者竞争激烈（价格战）、潜在进入者威胁中等（京东等跨界进入）、替代品威胁较低（时效性不可替代）、供应商议价能力弱（车辆/包装供应充足）、购买者议价能力强（消费者价格敏感）→","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"3eb18dfb-7977-4120-ac00-24a071efe95e","name":"灰度决策","category":"决策思维","scene":"信息不完备决策、两难困境、复杂人事问题、快速变化环境中的决策场景","core_logic":"灰度决策是一种务实的决策思维：承认现实世界不是非黑即白的，很多决策面临信息不完整、价值冲突、结果不确定的灰色地带。灰度决策不是和稀泥，而是在无法求得最优解时，采取「边走边看、小步快跑、及时调整」的策略，先做试探性决策，根据反馈再迭代优化，既不犹豫不前也不鲁莽蛮干。","steps":"[{\"name\": \"识别灰色地带\", \"description\": \"承认问题处于灰色地带，没有唯一正确答案，放下对完美答案的执念\"}, {\"name\": \"明确底线和边界\", \"description\": \"明确哪些是绝对不能碰的红线，哪些是可以灵活调整的范围\"}, {\"name\": \"收集尽可能多的信息\", \"description\": \"在时间允许的范围内尽可能收集信息，减少灰度但不追求完备\"}, {\"name\": \"分析各方利益诉求\", \"description\": \"理解决策涉及的各方利益和立场，寻找可能的平衡点\"}, {\"name\": \"设计渐进式方案\", \"description\": \"不追求一步到位，设计可分阶段实施、可调整的方案\"}, {\"name\": \"设定检查点和退出条件\", \"description\": \"明确在什么情况下需要调整方向，什么情况下应该及时止损\"}, {\"name\": \"小范围试错验证\", \"description\": \"先在小范围内试点，观察效果收集反馈\"}, {\"name\": \"根据反馈迭代调整\", \"description\": \"根据试点结果扩大、调整或终止决策，持续优化\"}]","itto":"{\"tools\": [\"底线思维、试点验证、利益相关方分析、反馈循环、PDCA\"], \"inputs\": [\"问题背景、利益相关方分析、可用信息、时间和资源约束\"], \"outputs\": [\"灰度决策方案、试点计划、监控指标、调整机制\"]}","tools":"底线思维、试点验证法、利益相关方分析、PDCA循环、反馈闭环","cases":"企业管理中的人事决策、政策制定的试点推广、初创公司方向调整、复杂谈判策略","viz_type":"process","viz_config":"{}","keywords":"灰度决策,灰度思维,两难,信息不全,渐进决策,试点,反馈","sort_order":78,"_created_at":"2026-09-16T16:20:50.905+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.138+08:00","_updated_by":"()","code":"DECIDE-GRAY-001","aliases":"灰度思维,灰度决策,灰色决策,非黑即白,渐进决策,灰度管理","summary":"在信息不完备、两难情境下接受不确定性，不追求完美答案，做渐进式、可调整的决策","problem_statement":"面对信息不完备的两难情境非要追求完美答案，犹豫不决错失机会，或者强行拍板事后后悔；灰度决策接受不确定性，不追求完美答案，做渐进式、可调整的决策，在信息有限时也能向前推进。","triggers":"灰度决策,灰度思维,灰色地带,两难困境,信息不全,渐进决策,边走边看","applicable":"信息不完备的复杂决策、价值冲突的两难问题、快速变化的商业环境、人事管理决策、创新探索型项目","not_applicable":"有明确正确答案的技术性问题、法律法规明确禁止的事项、安全人命关天的领域、信息充分可以精确计算的问题","related_frameworks":"贝叶斯思维,精益创业,情景规划法,逆向思维,底线思维","templates":"灰度决策检查表、试点方案模板、决策回顾清单","limitations":"容易被滥用为不负责任的借口；需要决策者有良好的判断力和底线意识；可能延长决策时间；不适合需要明确立场的场合","mastery_level":"L1","last_used_date":null,"domain_code":"DECIDE"},{"id":"3f34d590-97be-486b-87a0-25fd0314fc8a","name":"敏感性分析","category":"问题解决","scene":"投资决策、项目评估、财务模型、风险识别、关键变量确认的场景","core_logic":"敏感性分析是一种量化分析方法：保持其他变量不变，每次只改变一个关键变量的取值，观察结果随之变化的幅度，从而找出哪些变量对结果影响最大（最敏感）。敏感性分析能帮助决策者把注意力聚焦在最关键的变量上，也能评估决策的稳健性。","steps":"[{\"name\": \"确定基准模型和输出指标\", \"description\": \"建立基础计算模型，明确要分析的输出结果是什么\"}, {\"name\": \"识别关键输入变量\", \"description\": \"列出所有可能影响结果的输入变量\"}, {\"name\": \"确定各变量的变动范围\", \"description\": \"设定每个变量可能的变动幅度或范围（如±10%、±20%）\"}, {\"name\": \"逐个变动变量并计算结果\", \"description\": \"保持其他变量为基准值，每次变动一个变量，计算对应的输出结果\"}, {\"name\": \"计算敏感度\", \"description\": \"计算每个变量变动引起的结果变动幅度，用百分比或绝对值表示\"}, {\"name\": \"排序和可视化\", \"description\": \"按敏感度从大到小排序，用龙卷风图等方式直观展示\"}, {\"name\": \"分析关键变量\", \"description\": \"重点关注最敏感的变量，评估其不确定性和可控性\"}, {\"name\": \"制定应对策略\", \"description\": \"对高敏感变量加强监控、制定预案或寻找替代方案\"}]","itto":"{\"tools\": [\"Excel数据表(DTABLE)、Python、龙卷风图、盈亏平衡分析、情景分析\"], \"inputs\": [\"基础模型、变量清单、历史数据、专家判断\"], \"outputs\": [\"敏感性分析报告、龙卷风图、关键变量排序、风险优先级、决策建议\"]}","tools":"Excel数据表、Python、龙卷风图、盈亏平衡分析、SPSS/统计软件","cases":"房地产投资可行性分析、产品定价敏感性、项目NPV敏感性、贷款利率变动影响分析","viz_type":"chart","viz_config":"{}","keywords":"敏感性分析,灵敏度分析,What-if,龙卷风图,风险分析,关键变量","sort_order":68,"_created_at":"2026-09-16T16:20:50.813+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.145+08:00","_updated_by":"()","code":"SOLVE-SENSITIVITY-001","aliases":"灵敏度分析,Sensitivity Analysis,敏感性测试,单因素分析,What-if分析","summary":"逐个变动关键假设，观察结果变化幅度，找出对结果影响最大的敏感变量","problem_statement":"决策依赖关键假设，但假设变动对结果影响有多大不知道，一旦假设不成立结果完全失效；敏感性分析逐个变动关键假设观察结果变化幅度，找出对结果影响最大的敏感变量，让决策更稳健。","triggers":"敏感性分析,灵敏度分析,What-if,假设分析,关键变量,风险因子,龙卷风图","applicable":"投资可行性分析、财务模型验证、项目评估、定价决策、关键风险识别、设计优化","not_applicable":"变量之间高度相关无法单独变动的场景、完全定性无法量化的问题、简单决策不需要深度分析","related_frameworks":"蒙特卡洛模拟,风险矩阵,期望值决策,盈亏平衡分析,情景规划法","templates":"敏感性分析Excel模板、龙卷风图模板、单因素分析表","limitations":"单因素分析忽略变量间交互作用；假设变量独立可能与实际不符；需要有量化模型作为基础","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"3fe1daae-dbd9-40d8-9b87-ba7131882a37","name":"文献综述—理论框架—实证分析—讨论—结论","category":"科研写作","scene":"硕博学位论文、深度研究论文、需要构建理论框架的研究","core_logic":"经典的学术研究五段式结构，强调从文献到理论、再到实证的完整研究链条。文献综述是研究的起点和地基，理论框架是研究的骨架，实证分析是研究的血肉，讨论是研究的灵魂，结论是研究的归宿。","steps":"[{\"name\": \"文献综述\", \"description\": \"系统梳理和评价已有研究，识别研究空白、争议点和理论演进脉络\"}, {\"name\": \"理论框架\", \"description\": \"构建本研究的理论分析框架，明确核心概念、研究变量和逻辑关系\"}, {\"name\": \"实证分析\", \"description\": \"用定量或定性方法进行数据分析，验证理论框架提出的命题\"}, {\"name\": \"结果讨论\", \"description\": \"将实证结果与理论对话，解释结果背后的机制和意义\"}, {\"name\": \"研究结论\", \"description\": \"总结研究发现，指出贡献和局限，提出未来方向\"}]","itto":"{\"tools\": [\"系统文献综述\", \"内容分析\", \"回归分析\", \"案例研究\"], \"inputs\": [\"文献资料\", \"研究问题\", \"理论视角\"], \"outputs\": [\"研究论文\", \"理论贡献\", \"实证发现\"]}","tools":"文献计量学（CiteSpace/VOSviewer）、NVivo 质性分析、Stata/R、案例研究法","cases":"某博士论文结构：第1章绪论 → 第2章文献综述与理论基础 → 第3章研究设计与理论框架 → 第4-6章实证分析/案例研究 → 第7章结论与展望","viz_type":"process","viz_config":"{}","keywords":"文献综述,理论框架,实证分析,研究范式,学术通用","sort_order":103,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.153+08:00","_updated_by":"()","code":"RES-WRI-003","aliases":"文献综述","summary":"经典的学术研究五段式结构，强调从文献到理论、再到实证的完整研究链条。文献综述是研究的起点和地基，理论框架是研究的骨架，实证分析是研究的血肉，讨论是研究的灵魂，结","problem_statement":"学术论文写作东拼西凑，没有清晰的研究逻辑，文献与理论脱节、实证与讨论脱节，论文像一盘散沙；五段式结构从文献筑基到理论架骨、实证填充、讨论升华、结论收尾，构建完整严谨的研究链条。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"硕博学位论文、深度研究论文、需要构建理论框架的研究","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某博士论文结构：第1章绪论 → 第2章文献综述与理论基础 → 第3章研究设计与理论框架 → 第4-6章实证分析/案例研究 → 第7章结论与展望","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"4062b606-18ff-4ed0-a857-d1addfda9794","name":"波士顿矩阵 BCG","category":"战略决策","scene":"业务组合分析、资源分配决策、产品组合管理、投资优先级的场景","core_logic":"波士顿矩阵由BCG（波士顿咨询集团）创立，用市场增长率（纵坐标）和相对市场份额（横坐标）两个维度，将业务/产品划分为四个象限：明星业务（高增长高份额）、金牛业务（低增长高份额）、问号业务（高增长低份额）、瘦狗业务（低增长低份额），针对不同类型采取不同策略：投资明星、收割金牛、评估问号、退出瘦狗。","steps":"[{\"name\": \"界定分析范围\", \"description\": \"明确要分析的业务单元或产品集合，确定分析周期\"}, {\"name\": \"计算市场增长率\", \"description\": \"计算每个业务所在市场的年增长率，通常以10%为高低分界\"}, {\"name\": \"计算相对市场份额\", \"description\": \"计算本企业市场份额与最大竞争对手的比值，通常以1.0为分界\"}, {\"name\": \"绘制矩阵定位\", \"description\": \"将每个业务按两个维度定位到BCG矩阵的对应象限\"}, {\"name\": \"确定业务类型\", \"description\": \"明星/金牛/问号/瘦狗，并确认各业务的现金流特征\"}, {\"name\": \"制定各业务策略\", \"description\": \"明星→加大投入；金牛→收割维持；问号→评估投入或放弃；瘦狗→收缩退出\"}, {\"name\": \"优化业务组合平衡\", \"description\": \"确保业务组合健康平衡，有足够金牛支撑明星和问号的发展\"}, {\"name\": \"制定资源分配方案\", \"description\": \"根据策略将资金、人才等资源在各业务间合理分配\"}]","itto":"{\"tools\": [\"BCG矩阵图、市场份额计算、增长率分析、财务分析工具\"], \"inputs\": [\"各业务市场数据、竞争格局、财务数据、市场增长率数据\"], \"outputs\": [\"BCG矩阵分析图、业务组合诊断报告、资源分配建议、战略调整方案\"]}","tools":"BCG矩阵图、市场调研数据、财务报表分析、竞争分析工具","cases":"通用电气业务组合分析、宝洁产品组合管理、多元化集团战略规划","viz_type":"matrix","viz_config":"{}","keywords":"BCG,波士顿矩阵,业务组合,明星,金牛,问号,瘦狗,资源配置","sort_order":71,"_created_at":"2026-09-16T16:20:50.824+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.177+08:00","_updated_by":"()","code":"DECIDE-BCG-001","aliases":"BCG矩阵,波士顿咨询矩阵,市场增长率-相对市场份额矩阵,BCG Matrix","summary":"以市场增长率和相对市场份额划分明星/金牛/问号/瘦狗四类业务组合，优化资源配置","problem_statement":"业务组合不知道该怎么分配资源，每个业务都喊缺钱，撒胡椒面式投资导致好业务没吃饱、差业务浪费资源；BCG矩阵以市场增长率和相对市场份额划分明星/金牛/问号/瘦狗四类业务，优化资源配置策略。","triggers":"BCG,波士顿矩阵,业务组合,产品组合,资源分配,明星,金牛,问号,瘦狗","applicable":"多元化企业业务组合管理、产品线规划、投资组合分析、战略资源配置","not_applicable":"单一业务企业、新兴行业无市场份额概念、服务业等难以定义市场份额的场景","related_frameworks":"安索夫矩阵,GE-McKinsey九宫格,SWOT分析,蓝海战略ERRC框架,价值链分析","templates":"BCG矩阵模板、业务组合分析表","limitations":"仅用两个维度过于简化；市场定义困难时计算不准；忽视业务间协同效应；静态分析缺少动态视角","mastery_level":"L3","last_used_date":null,"domain_code":"DECIDE"},{"id":"445753b6-020a-42ff-ac81-fd9d49add4f8","name":"STAR 法则","category":"表达与写作","scene":"面试回答、简历撰写、绩效汇报、案例分享、经验复盘的场景","core_logic":"STAR法则是结构化描述经历和成果的经典框架：S(Situation)——事情发生的背景和情境是什么？T(Task)——你面临的任务和目标是什么？A(Action)——你具体采取了什么行动？R(Result)——行动带来了什么结果和影响？STAR结构让表达逻辑清晰、重点突出、有说服力，特别适合用具体案例证明自己的能力和成就。","steps":"[{\"name\": \"明确要证明的能力\", \"description\": \"先想清楚你想用这个案例证明哪项能力或特质\"}, {\"name\": \"选择合适的案例\", \"description\": \"选择最能体现该项能力的一个具体案例，最好是近期且结果明确的\"}, {\"name\": \"描述情境(S)\", \"description\": \"简要说明事情发生的背景：时间、地点、环境、面临的挑战，1-2句话交代清楚\"}, {\"name\": \"明确任务(T)\", \"description\": \"你需要完成什么任务？目标是什么？难点在哪里？你的角色是什么？\"}, {\"name\": \"详述行动(A)\", \"description\": \"这是STAR的核心，详细说明你具体做了什么、怎么做的、用了什么方法、克服了什么困难，用「我」做主语\"}, {\"name\": \"量化结果(R)\", \"description\": \"行动带来了什么结果？尽可能用数字量化，说明影响和价值，突出你的贡献\"}, {\"name\": \"提炼反思(可选)\", \"description\": \"从这件事中你学到了什么？如果再做一次你会怎么改进？\"}, {\"name\": \"检查匹配度\", \"description\": \"回头检查：这个STAR是否清晰地证明了你想展示的能力？结果是否足够有分量？\"}]","itto":"{\"tools\": [\"STAR模板、量化思维、故事叙述技巧、行为面试法\"], \"inputs\": [\"个人经历、项目案例、数据和结果、能力自评\"], \"outputs\": [\"结构化的案例陈述、有说服力的面试回答、优化后的简历内容、清晰的成果展示\"]}","tools":"STAR模板、行为面试法、量化表达、故事结构、金字塔原理","cases":"面试行为问题回答、简历业绩描述、晋升答辩、销售案例分享、年度绩效总结","viz_type":"process","viz_config":"{}","keywords":"STAR,STAR法则,情境任务行动结果,面试,简历,案例陈述,故事表达","sort_order":121,"_created_at":"2026-09-16T16:20:51.119+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.185+08:00","_updated_by":"()","code":"RES-STAR-001","aliases":"STAR法则,STAR,情境-任务-行动-结果,Situation Task Action Result,面试法则","summary":"结构化描述经历与成果的黄金法则，情境-任务-行动-结果，让表达清晰有说服力","problem_statement":"描述经历和成果时流水账式罗列，重点不突出，面试官或听众听完不知道你到底做了什么、贡献在哪；STAR法则按情境-任务-行动-结果的结构组织表达，让成果和能力一目了然、说服力倍增。","triggers":"STAR,STAR法则,情境任务行动结果,面试回答,简历撰写,案例陈述,故事表达","applicable":"求职面试、简历优化、绩效面谈、案例分享、项目汇报、晋升答辩、讲故事","not_applicable":"纯观点表达、情绪化沟通、闲聊社交、完全没有结果的失败经历","related_frameworks":"PREP表达法,金字塔原理,电梯演讲,黄金圈法则,故事思维","templates":"STAR回答模板、简历STAR描述模板、面试准备清单、案例陈述框架","limitations":"过于结构化可能显得生硬和模板化；需要真实的经历和数据支撑；不适合所有类型的问题（如观点类问题）；准备多个STAR案例需要时间","mastery_level":"L3","last_used_date":null,"domain_code":"RES"},{"id":"45b210c8-56ca-4fea-9255-d1812e61d49a","name":"安索夫矩阵","category":"战略决策","scene":"增长战略规划、市场进入决策、产品路线规划、业务拓展的场景","core_logic":"安索夫矩阵由伊戈尔·安索夫提出，用「现有/新产品」和「现有/新市场」两个维度，将增长战略分为四种类型：市场渗透（现有产品+现有市场）、产品开发（新产品+现有市场）、市场开发（现有产品+新市场）、多元化（新产品+新市场）。风险从市场渗透到多元化逐步递增，企业应根据自身资源和能力选择合适的增长路径。","steps":"[{\"name\": \"明确增长目标\", \"description\": \"确定增长目标（收入、用户、市场份额等）和时间期限\"}, {\"name\": \"梳理现有产品和市场\", \"description\": \"盘点当前的产品/服务以及所服务的市场/客户群\"}, {\"name\": \"评估市场渗透机会\", \"description\": \"现有产品在现有市场还能增长多少？需要什么策略？\"}, {\"name\": \"评估产品开发机会\", \"description\": \"为现有客户开发新产品/服务的可能性和可行性\"}, {\"name\": \"评估市场开发机会\", \"description\": \"现有产品进入新市场（新区域、新客群）的机会和风险\"}, {\"name\": \"评估多元化机会\", \"description\": \"新产品+新市场的多元化机会，相关还是无关多元化？\"}, {\"name\": \"比较四种策略的风险收益\", \"description\": \"评估每种策略的投入、风险、预期收益和匹配度\"}, {\"name\": \"选择增长路径并制定计划\", \"description\": \"选择1-2种主要增长路径，制定详细执行计划\"}]","itto":"{\"tools\": [\"安索夫矩阵、市场调研、竞争分析、SWOT分析、财务可行性评估\"], \"inputs\": [\"市场数据、产品信息、竞争格局、资源能力评估、客户调研\"], \"outputs\": [\"增长战略分析报告、增长路径选择、实施路线图、资源需求清单\"]}","tools":"安索夫矩阵、市场调研、SWOT分析、PESTEL分析、财务模型","cases":"苹果从电脑到iPod到iPhone的产品开发+市场开发、可口可乐全球市场开发、互联网企业多元化扩张","viz_type":"matrix","viz_config":"{}","keywords":"安索夫矩阵,增长策略,市场渗透,产品开发,市场开发,多元化","sort_order":72,"_created_at":"2026-09-16T16:20:50.835+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.193+08:00","_updated_by":"()","code":"DECIDE-ANSOFF-001","aliases":"安索夫矩阵,产品-市场拓展矩阵,Ansoff Matrix,增长策略矩阵","summary":"市场渗透/市场开发/产品开发/多元化四种增长战略组合，系统思考增长路径","problem_statement":"增长路径拍脑袋选，不知道有哪些增长方向可选，每种方向的风险和回报有什么不同，战略盲目；安索夫矩阵从市场渗透/市场开发/产品开发/多元化四个象限系统思考增长路径，匹配不同风险偏好和资源能力。","triggers":"安索夫矩阵,增长策略,市场渗透,产品开发,市场开发,多元化,增长路径","applicable":"企业增长战略制定、市场进入决策、产品规划、业务扩张路径选择、创业方向选择","not_applicable":"非营利组织目标不是增长、业务收缩而非扩张阶段、完全垄断无增长空间的市场","related_frameworks":"波士顿矩阵BCG,蓝海战略ERRC框架,SWOT分析,PMF产品市场契合,精益创业","templates":"安索夫矩阵分析模板、增长策略评估表","limitations":"仅提供战略框架不提供执行细节；四种策略边界可能模糊；忽略竞争反应和外部环境变化","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"45b74d6f-49ab-49a7-acd6-a3af42d69c55","name":"MBO 目标管理","category":"目标管理","scene":"企业绩效管理、团队目标设定、员工激励、部门协作的场景","core_logic":"MBO（Management by Objectives）由管理大师彼得·德鲁克在《管理的实践》中提出，核心思想是：企业的使命和任务必须转化为目标，管理者应该通过目标对下级进行管理。MBO强调员工参与目标制定、上下级共同商定目标、目标分解到个人、以完成目标的程度作为考核依据，让员工实现自我控制和自我激励，而不是被监督和控制。","steps":"[{\"name\": \"制定组织整体目标\", \"description\": \"最高管理层制定组织的整体战略目标和年度目标\"}, {\"name\": \"目标分解与商定\", \"description\": \"上下级共同商定各部门和各岗位的目标，上级提出方向下级提出方案，充分讨论达成一致\"}, {\"name\": \"明确目标标准\", \"description\": \"每个目标都要有明确的衡量标准、完成期限和资源支持\"}, {\"name\": \"授权与自主执行\", \"description\": \"管理者充分授权，员工自主决定完成目标的方法和路径，实现自我控制\"}, {\"name\": \"定期检查与反馈\", \"description\": \"定期检查目标进度，及时反馈和调整，但不干预具体执行方式\"}, {\"name\": \"期末评估\", \"description\": \"期末对照目标评估完成情况，以成果为标准评价绩效\"}, {\"name\": \"绩效奖励与发展\", \"description\": \"根据目标完成情况给予相应的奖惩和发展机会\"}, {\"name\": \"新周期目标设定\", \"description\": \"总结经验，进入下一个目标管理周期，持续提升\"}]","itto":"{\"tools\": [\"目标设定方法、绩效评估体系、沟通反馈机制、激励机制\"], \"inputs\": [\"组织战略、管理者能力、员工参与意愿、绩效管理体系\"], \"outputs\": [\"各层级目标体系、绩效评估结果、员工自我管理能力、组织目标达成\"]}","tools":"目标设定SMART、绩效面谈、PDCA循环、KPI、激励机制设计","cases":"德鲁克提出后在美国企业广泛应用、惠普的HPWay、日本企业的经营理念","viz_type":"hierarchy","viz_config":"{}","keywords":"MBO,目标管理,德鲁克,自我控制,目标导向,绩效管理","sort_order":92,"_created_at":"2026-09-16T16:20:51.007+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.201+08:00","_updated_by":"()","code":"PM-MBO-001","aliases":"MBO,目标管理,Management by Objectives,德鲁克目标管理,目标导向管理","summary":"德鲁克提出的目标管理方法，以目标为导向、以人为中心、以成果为标准，让员工自我控制","problem_statement":"员工不知道为什么而干，管理者事事盯着干，团队没有自主性也没有责任感，组织效率低；MBO以目标为导向、以人为中心、以成果为标准，让员工参与目标制定、自我控制、自我管理，激发主动性。","triggers":"MBO,目标管理,德鲁克,目标导向,自我控制,Management by Objectives","applicable":"知识型企业、中高层管理、创意型团队、需要激发主动性的组织、结果导向的工作","not_applicable":"重复性流水线工作、需要严格控制的生产环节、新员工缺乏自我管理能力、目标难以量化的工作","related_frameworks":"OKR目标与关键结果,SMART目标设定,KPI,平衡计分卡BSC,OGSM","templates":"MBO目标管理卡、目标制定工作表、绩效面谈模板、目标承诺书","limitations":"目标难以量化时效果差；容易导致短期目标导向忽视长期发展；各部门目标可能难以协调；需要管理者有较高的沟通和辅导能力；环境变化快时目标可能很快过时","mastery_level":"L2","last_used_date":null,"domain_code":"PM"},{"id":"4619af3a-0e5e-4615-b23c-ab89995f8207","name":"逆向规划法","category":"问题解决","scene":"目标设定、项目规划、个人发展、战略落地的场景","core_logic":"逆向规划法是一种以终为始的规划方法：先清晰定义最终想要达成的结果，再从终点一步一步往回推导，每一步需要完成什么、需要什么资源、由谁负责，直到推到当下该做的第一件事。这种方法能确保所有行动都指向最终目标，避免跑偏和无效努力。","steps":"[{\"name\": \"定义最终目标\", \"description\": \"清晰、具体地描述最终想要达到的状态，符合SMART原则\"}, {\"name\": \"明确成功标准\", \"description\": \"如何判断目标已经达成，量化指标和定性标准\"}, {\"name\": \"倒推关键里程碑\", \"description\": \"从终点往回推，达成目标前需要完成哪些关键里程碑\"}, {\"name\": \"分解每阶段任务\", \"description\": \"每个里程碑需要完成哪些具体任务和交付物\"}, {\"name\": \"识别所需资源\", \"description\": \"每个步骤需要什么人、财、物、时间资源\"}, {\"name\": \"识别前置依赖\", \"description\": \"各步骤之间的依赖关系，哪些必须先完成\"}, {\"name\": \"确定第一步行动\", \"description\": \"明确当下立即可以开始做的第一件事\"}, {\"name\": \"制定检查点\", \"description\": \"设置过程中的检查节点，及时调整偏差\"}]","itto":"{\"tools\": [\"SMART原则、甘特图、WBS、里程碑图、关键路径法\"], \"inputs\": [\"目标愿景、资源约束、环境条件、时间期限\"], \"outputs\": [\"逆向规划路线图、行动计划、资源清单、里程碑表\"]}","tools":"SMART原则、WBS工作分解、甘特图、关键路径法、里程碑计划","cases":"项目管理计划制定、职业发展规划、产品上市规划、年度目标分解","viz_type":"process","viz_config":"{}","keywords":"逆向规划,以终为始,倒推法,目标导向,反向规划","sort_order":66,"_created_at":"2026-09-16T16:20:50.789+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.208+08:00","_updated_by":"()","code":"SOLVE-BACKWARD-001","aliases":"逆向规划,以终为始,倒推法,反向规划,Backward Planning,结果导向规划","summary":"从期望的最终结果倒推所需步骤和资源，确保行动与目标一致","problem_statement":"做事从当前出发走一步看一步，方向感不强、容易走偏，做了很多无用功，最终也达不到想要的结果；逆向规划法从期望的最终结果倒推所需步骤和资源，确保每一步行动都与最终目标精准对齐、不跑偏。","triggers":"逆向规划,以终为始,倒推法,目标导向,反向规划,结果思维","applicable":"目标制定、项目规划、个人职业发展、战略落地、产品路线图规划","not_applicable":"探索性研究项目、完全无法预知终点的创新项目、日常例行事务","related_frameworks":"SMART目标设定,OKR目标与关键结果,WBS工作分解结构,PDCA循环,精益创业","templates":"逆向规划模板、目标倒推工作表、里程碑规划表","limitations":"要求对目标有清晰认知，目标模糊时难以使用；对不确定性高的项目可能反复调整；可能忽略沿途出现的新机会","mastery_level":"L1","last_used_date":null,"domain_code":"SOLVE"},{"id":"4697e3b3-fd4f-4b15-a343-29ab159a57fa","name":"背景—目标—任务—措施—保障","category":"科研写作","scene":"政策文件起草、发展规划编制、专项方案设计、行动计划制定","core_logic":"标准的政策文件和规划编制结构，遵循\"为什么做→做成什么样→做什么→怎么做→怎么保证落地\"的逻辑链条，从宏观背景到微观措施层层递进，是政府和机构编制政策文件的经典范式。","steps":"[{\"name\": \"背景分析\", \"description\": \"阐述政策出台的时代背景、现实需求和政策环境，说明为什么要做\"}, {\"name\": \"目标设定\", \"description\": \"明确政策要达到的总体目标和具体目标，可用 SMART 原则设定\"}, {\"name\": \"主要任务\", \"description\": \"为实现目标需要完成的重点任务和关键工作，通常分解为几项\"}, {\"name\": \"政策措施\", \"description\": \"具体的政策工具和实施手段，包括财政、金融、人才、土地等\"}, {\"name\": \"保障机制\", \"description\": \"确保政策落地的组织保障、制度保障、资金保障和监督评估机制\"}]","itto":"{\"tools\": [\"目标管理\", \"政策工具分析\", \"规划编制方法\"], \"inputs\": [\"政策需求\", \"上级精神\", \"现状评估\"], \"outputs\": [\"政策文件\", \"规划方案\", \"实施方案\"]}","tools":"政策工具理论、规划评估法、SMART目标设定、成本收益分析","cases":"某省数字经济发展三年行动计划：背景（数字经济浪潮+省情需要）→ 目标（GDP占比达50%）→ 任务（数字产业化、产业数字化、数字化治理）→ 措施（财政补贴、人才引进、基础设施建设）→ 保障（领导小组、考核机制、资金保障）","viz_type":"process","viz_config":"{}","keywords":"政策框架,规划编制,背景目标任务措施保障,实施方案,政策调研","sort_order":111,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.216+08:00","_updated_by":"()","code":"RES-WRI-006","aliases":"政策框架","summary":"标准的政策文件和规划编制结构，遵循\"为什么做→做成什么样→做什么→怎么做→怎么保证落地\"的逻辑链条，从宏观背景到微观措施层层递进，是政府和机构编制政策文件的经典","problem_statement":"政策文件和规划写作逻辑散乱，背景和目标对不上、措施和保障分不清，读起来像政策拼盘没有主线；背景-目标-任务-措施-保障遵循为什么做→做成什么样→做什么→怎么做→怎么保证的逻辑，层层递进。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"政策文件起草、发展规划编制、专项方案设计、行动计划制定","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某省数字经济发展三年行动计划：背景（数字经济浪潮+省情需要）→ 目标（GDP占比达50%）→ 任务（数字产业化、产业数字化、数字化治理）→ 措施（财政补贴、人才引进、基础设施建设）→ 保障（领导小组、","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"4a648e98-361a-4e44-bbbf-89154186ada6","name":"名义小组技术","category":"思维方法","scene":"需要集思广益但又担心群体思维或沉默螺旋的决策场景","core_logic":"名义小组技术结合了个人独立思考和集体讨论的优点：先让成员独立写下想法，再轮流分享并记录，然后群体讨论澄清，最后独立投票排序。避免了强势成员主导和从众心理。","steps":"[{\"name\": \"每位成员独立写下想法\", \"description\": \"\"}, {\"name\": \"轮流分享并逐一记录\", \"description\": \"\"}, {\"name\": \"群体讨论澄清每个想法\", \"description\": \"\"}, {\"name\": \"成员独立投票排序\", \"description\": \"\"}, {\"name\": \"汇总结果得出优先顺序\", \"description\": \"\"}]","itto":"{\"tools\": [\"投票、排序工具\"], \"inputs\": [\"决策议题\"], \"outputs\": [\"排序结果、共识决策\"]}","tools":"投票卡片、点投法、匿名投票","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"名义小组技术,NGT,群体决策,结构化投票,共识","sort_order":13,"_created_at":"2026-09-15T18:34:03.319+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.224+08:00","_updated_by":"()","code":"SOL-THK-009","aliases":"名义小组技术,NGT,Nominal Group Technique","summary":"通过结构化群体决策过程，平衡个体独立思考与集体智慧的方法","problem_statement":"群体决策要么被权威和多数人意见主导，要么争论不休达不成共识，好想法被埋没、决策质量低；名义小组技术通过结构化流程平衡个体独立思考与集体智慧，让每个声音都被听到、决策更科学。","triggers":"名义小组,群体决策,NGT,投票,结构化讨论","applicable":"团队决策、优先级排序、需求评审、问题解决方案选择","not_applicable":"简单问题快速决策、需要充分自由讨论的创意阶段","related_frameworks":"头脑风暴法,决策矩阵,德尔菲法","templates":"名义小组技术流程卡","limitations":"流程较耗时；需要主持人引导；想法数量可能不如头脑风暴多","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"4b05096a-e7ae-4863-b2e1-28eb2d44ada0","name":"理论—假设—数据—检验—结论","category":"科研写作","scene":"社会科学实证研究论文、量化研究学位论文、需要验证假设的研究","core_logic":"遵循假设演绎法（Hypothetico-Deductive Method）的研究路径：从理论出发推导出可检验的假设，然后收集数据用实证方法检验假设是否成立，最后根据检验结果修正理论或得出结论。是最经典的实证研究范式。","steps":"[{\"name\": \"理论基础\", \"description\": \"梳理相关理论，明确研究的理论视角和分析框架，为假设提出提供理论依据\"}, {\"name\": \"研究假设\", \"description\": \"基于理论推导和已有研究，提出可检验的具体研究假设（H0/H1 等）\"}, {\"name\": \"数据收集\", \"description\": \"确定数据来源、样本范围、变量测量方式，构建研究数据集\"}, {\"name\": \"假设检验\", \"description\": \"运用统计方法或计量模型对假设进行检验，验证或证伪研究假设\"}, {\"name\": \"结论讨论\", \"description\": \"总结检验结果，讨论其理论意义和实践价值，指出研究局限\"}]","itto":"{\"tools\": [\"理论分析\", \"假设演绎法\", \"统计检验\", \"回归分析\"], \"inputs\": [\"理论文献\", \"研究问题\", \"数据资源\"], \"outputs\": [\"实证研究论文\", \"假设验证结论\"]}","tools":"文献综述法、理论演绎、SPSS/Stata/R/Python、结构方程模型（SEM）","cases":"组织行为学研究：基于社会认知理论提出\"自我效能感正向影响工作绩效\"的假设，通过问卷调查收集200名员工数据，用回归分析验证假设成立。","viz_type":"process","viz_config":"{}","keywords":"假设检验,实证研究,理论框架,假设演绎,学术通用","sort_order":102,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.231+08:00","_updated_by":"()","code":"RES-WRI-002","aliases":"假设检验","summary":"遵循假设演绎法（Hypothetico-Deductive Method）的研究路径：从理论出发推导出可检验的假设，然后收集数据用实证方法检验假设是否成立，最后","problem_statement":"实证研究不知道该遵循什么研究范式，拍脑袋提假设、凑数据做检验，研究过程不规范、结论不可靠；理论-假设-数据-检验-结论遵循假设演绎法，从理论推导假设、用数据检验假设，研究过程科学严谨。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"社会科学实证研究论文、量化研究学位论文、需要验证假设的研究","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"组织行为学研究：基于社会认知理论提出\"自我效能感正向影响工作绩效\"的假设，通过问卷调查收集200名员工数据，用回归分析验证假设成立。","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"4bcd7924-15b9-4f53-aff5-ad2ecd1076df","name":"关键路径法","category":"项目管理","scene":"项目进度计划制定、最短工期计算、活动优先级排序、资源调配优化、工期压缩决策。","core_logic":"CPM（Critical Path Method）通过分析项目活动的依赖关系和工期，计算出每条路径的总时长，其中最长的路径即为关键路径——关键路径上任何活动的延期都会直接导致整个项目延期。关键路径上活动的总时差为零，是项目管理的重点关注对象。","steps":"[{\"name\": \"第一步：列出活动\", \"description\": \"将项目分解为具体活动，确定每项活动的工期\"}, {\"name\": \"第二步：确定依赖关系\", \"description\": \"明确活动之间的先后顺序和逻辑依赖关系\"}, {\"name\": \"第三步：绘制网络图\", \"description\": \"按逻辑关系绘制项目网络图（节点图或箭线图）\"}, {\"name\": \"第四步：正推计算最早时间\", \"description\": \"从前往后计算各活动的最早开始和最早完成时间\"}, {\"name\": \"第五步：逆推计算最晚时间\", \"description\": \"从后往前计算各活动的最晚开始和最晚完成时间\"}, {\"name\": \"第六步：确定关键路径\", \"description\": \"总时差为零的活动组成的路径就是关键路径，决定项目最短工期\"}]","itto":"{\"tools\": [\"网络图\", \"甘特图\", \"PERT估算\"], \"inputs\": [\"WBS工作分解\", \"活动工期估算\"], \"outputs\": [\"关键路径\", \"项目工期\", \"总时差\"]}","tools":"MS Project、飞书项目、甘特图、PERT 三点估算","cases":"某建筑项目用 CPM 分析后发现：原计划 180 天的项目，关键路径实际只需 156 天。通过识别关键路径上的 7 项活动，项目经理将非关键路径上的部分资源（2 名工程师）调配到关键路径活动，最终项目提前 18 天完工，节省成本 12%。","viz_type":"process","viz_config":"{}","keywords":"关键路径,CPM,进度管理,网络图","sort_order":13,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.239+08:00","_updated_by":"()","code":"PM-TIM-001","aliases":"关键路径","summary":"CPM（Critical Path Method）通过分析项目活动的依赖关系和工期，计算出每条路径的总时长，其中最长的路径即为关键路径——关键路径上任何活动的延","problem_statement":"项目任务一堆，不知道哪些是关键、哪些可以缓一缓，资源乱配，进度失控还找不到根源；CPM通过分析活动依赖关系和工期计算出关键路径，让你精准抓住决定项目总工期的核心任务。","triggers":"项目延期、进度失控、范围蔓延、资源不足","applicable":"项目进度计划制定、最短工期计算、活动优先级排序、资源调配优化、工期压缩决策。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某建筑项目用 CPM 分析后发现：原计划 180 天的项目，关键路径实际只需 156 天。通过识别关键路径上的 7 项活动，项目经理将非关键路径上的部分资源（2 名工程师）调配到关键路径活动，最终项目","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"4c9ba940-b5cd-4a3a-85a3-61704c8bd0e0","name":"PREP 表达法","category":"表达与写作","scene":"观点表达、演讲发言、写作结构、会议发言、快速表达的场景","core_logic":"PREP是一种简洁有力的表达结构：P(Point)——先开门见山亮出你的观点/结论；R(Reason)——说明支持这个观点的理由/原因；E(Example)——用具体例子、数据或故事来证明和支撑；P(Point)——最后再次重申和强调观点，加深印象。PREP结构符合「结论先行」的原则，让听者第一时间get到你的核心信息，理由和例子让观点有说服力，最后的重申强化记忆。","steps":"[{\"name\": \"明确核心观点\", \"description\": \"想清楚你最想让对方记住的那一句话是什么，用一句话概括你的核心观点\"}, {\"name\": \"亮明观点(Point)\", \"description\": \"开口第一句话就直接说出你的结论/观点/答案，不要铺垫和绕弯子\"}, {\"name\": \"说明理由(Reason)\", \"description\": \"给出支撑你观点的2-3个核心理由，逻辑清晰，从最重要的开始说\"}, {\"name\": \"举出例子(Example)\", \"description\": \"用具体的例子、数据、故事或案例来证明你的理由，让观点更有说服力和画面感\"}, {\"name\": \"重申观点(Point)\", \"description\": \"最后再次总结和强调你的核心观点，与开头呼应，加深对方印象\"}, {\"name\": \"控制时长和篇幅\", \"description\": \"根据场景调整详细程度，30秒到3分钟都可以用PREP结构\"}, {\"name\": \"根据反馈调整\", \"description\": \"观察对方反应，如果对方有疑问，补充解释或调整表达重点\"}, {\"name\": \"刻意练习\", \"description\": \"日常沟通中有意识地使用PREP结构，养成结论先行的表达习惯\"}]","itto":"{\"tools\": [\"PREP模板、金字塔原理、电梯演讲、结构化思维、故事举例\"], \"inputs\": [\"观点/想法、理由、例子和数据、表达场景\"], \"outputs\": [\"清晰有力的表达、被理解和接受的观点、高效的沟通、专业形象\"]}","tools":"金字塔原理、结构化思维、故事叙述、数据支撑、电梯演讲","cases":"商务汇报、面试回答、演讲开场、公众号文章结构、会议发言","viz_type":"process","viz_config":"{}","keywords":"PREP,PREP表达法,结论先行,观点表达,演讲结构,写作结构,沟通","sort_order":122,"_created_at":"2026-09-16T16:20:51.13+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.247+08:00","_updated_by":"()","code":"RES-PREP-001","aliases":"PREP表达法,PREP法,观点-理由-例子-重申观点,Point Reason Example Point","summary":"先亮明观点再讲理由和例子最后重申观点，简洁有力的表达结构","problem_statement":"表达观点时绕来绕去，铺垫半天还没说到重点，听众耐心耗尽也抓不住核心意思，沟通效率低下；PREP法先亮明观点、再讲理由和例子、最后重申观点，结构紧凑直击要点，让表达简洁有力。","triggers":"PREP,PREP表达法,结论先行,观点表达,演讲结构,写作结构,表达逻辑","applicable":"会议发言、演讲表达、短文写作、面试问答、日常沟通、观点陈述、方案汇报","not_applicable":"需要循序渐进铺垫的长篇演说、情感类表达、悬疑故事类表达、需要引导听众自己得出结论的场景","related_frameworks":"STAR法则,电梯演讲,金字塔原理,黄金圈法则,结构化思考","templates":"PREP表达模板、演讲大纲模板、短文写作模板、发言准备清单","limitations":"过于直接可能显得突兀，不够委婉；不适合复杂或有争议的观点；对情感类沟通可能过于理性；多次使用会显得模式化","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"4d28c59e-d1f1-4eba-b484-439823af0d4f","name":"建构对齐","category":"教学科研","scene":"课程设计、教学改革、教学质量提升的场景","core_logic":"建构对齐（Constructive Alignment）由John Biggs提出，核心理念是：学生通过主动建构知识来学习（建构主义），教师要确保学习目标、教学活动和评估任务三者对齐。学生学到什么取决于他们做了什么，而不是老师教了什么。","steps":"[{\"name\": \"用布鲁姆等分类定义学习目标\", \"description\": \"\"}, {\"name\": \"设计与目标对齐的教学活动\", \"description\": \"\"}, {\"name\": \"设计与目标对齐的评估任务\", \"description\": \"\"}, {\"name\": \"检查三者的对齐程度\", \"description\": \"\"}, {\"name\": \"实施后收集反馈调整\", \"description\": \"\"}]","itto":"{\"tools\": [\"布鲁姆分类、教学设计\"], \"inputs\": [\"课程目标、教学内容\"], \"outputs\": [\"对齐的课程设计方案\"]}","tools":"布鲁姆分类、课程矩阵、教学评估","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"教学活动\", \"y_label\": \"学习目标\", \"quadrants\": {\"q1\": \"评估任务对齐关系\"}}","keywords":"建构对齐,Biggs,教学设计一致性,学习目标,教学质量","sort_order":5,"_created_at":"2026-09-15T18:34:26.52+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.255+08:00","_updated_by":"()","code":"TEACH-CON-001","aliases":"建构对齐,Constructive Alignment,Biggs","summary":"学习目标、教学活动和评估三者一致对齐的教学设计原则","problem_statement":"教学设计中目标、活动、评估三者脱节，教的和考的对不上，学的和目标没关系，教学效果差、学生抱怨多；建构对齐原则要求学习目标、教学活动和评估方式三者高度一致，确保教什么就考什么、怎么教就怎么学。","triggers":"建构对齐,Constructive Alignment,Biggs,教学一致性","applicable":"课程设计、教学改革、教师培训、教学质量提升","not_applicable":"简单知识传递、无评估要求的讲座","related_frameworks":"布鲁姆认知分类法,OBE 成果导向教育,评价量规 Rubric","templates":"建构对齐课程矩阵模板","limitations":"理念层面多操作层面少；需要教师主动改变教学方式；对齐度评估有主观性","mastery_level":"L2","last_used_date":null,"domain_code":"TEACH"},{"id":"50947b5e-ee56-4dc6-8430-b3b0f48fb8dc","name":"价值链分析","category":"科研写作","scene":"企业战略分析、产业链研究、竞争力分析、产业升级研究论文","core_logic":"波特价值链理论将企业活动分为基本活动（直接创造价值）和支持活动（辅助支撑）两大类共九个环节。企业的竞争优势来源于价值链上一个或多个环节的优势。通过分析价值链可以找到价值创造的关键环节和优化空间。","steps":"[{\"name\": \"基本活动 Primary Activities\", \"description\": \"直接创造价值的活动：内部物流→生产运营→外部物流→市场销售→服务\"}, {\"name\": \"支持活动 Support Activities\", \"description\": \"支撑基本活动的辅助活动：企业基础设施→人力资源管理→技术开发→采购\"}, {\"name\": \"价值识别\", \"description\": \"分析每个环节创造了多少价值、消耗了多少成本，识别高价值环节\"}, {\"name\": \"竞争优势来源\", \"description\": \"判断企业竞争优势来源于哪些价值链环节，是成本优势还是差异化优势\"}, {\"name\": \"价值链优化\", \"description\": \"通过优化价值链环节、外包非核心环节、整合上下游提升竞争力\"}]","itto":"{\"tools\": [\"价值链分析\", \"作业成本法\", \"对标分析\", \"外包决策\"], \"inputs\": [\"企业业务流程\", \"成本数据\", \"行业对标\"], \"outputs\": [\"价值链分析报告\", \"优化建议\"]}","tools":"价值链图、作业成本法（ABC）、标杆管理、微笑曲线分析","cases":"手机产业价值链分析：芯片设计（高通，高利润）→ 操作系统（Google/苹果，高利润）→ 整机制造（富士康，低利润）→ 品牌营销（苹果，最高利润）→ 应用生态（App Store，高利润），用微笑曲线解释产业利润分布","viz_type":"process","viz_config":"{}","keywords":"价值链,波特,价值创造,竞争优势,产业链,战略产业","sort_order":123,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.263+08:00","_updated_by":"()","code":"DEC-IND-002","aliases":"价值链","summary":"波特价值链理论将企业活动分为基本活动（直接创造价值）和支持活动（辅助支撑）两大类共九个环节。企业的竞争优势来源于价值链上一个或多个环节的优势。通过分析价值链可以","problem_statement":"研究企业竞争优势只看整体不看环节，找不到优势的具体来源，战略建议空泛不落地，企业不知道该从哪发力；价值链分析将企业活动拆解为九大环节，精准识别价值创造和竞争优势的具体来源。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"企业战略分析、产业链研究、竞争力分析、产业升级研究论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"手机产业价值链分析：芯片设计（高通，高利润）→ 操作系统（Google/苹果，高利润）→ 整机制造（富士康，低利润）→ 品牌营销（苹果，最高利润）→ 应用生态（App Store，高利润），用微笑曲线","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"5324c54e-2c9c-4c1e-9ee7-6e8bb594e31d","name":"情景规划法","category":"问题解决","scene":"战略规划、高不确定性环境、长期决策、风险预警的场景","core_logic":"情景规划法由壳牌石油首创，是一种应对高度不确定性的战略思维工具：识别关键不确定性→构建多种不同的未来情景→分析每种情景下的影响→制定应对策略→建立预警信号。不同于预测，情景规划是准备多种可能的未来，让组织在任何情景发生时都能快速响应。","steps":"[{\"name\": \"明确决策焦点\", \"description\": \"确定要做的决策是什么，时间范围和空间范围\"}, {\"name\": \"识别关键因素\", \"description\": \"列出影响决策结果的所有内部和外部关键因素\"}, {\"name\": \"识别关键不确定性\", \"description\": \"从关键因素中筛选出最不确定且影响最大的2-3个维度\"}, {\"name\": \"构建情景矩阵\", \"description\": \"将关键不确定性的不同取值组合，形成3-4种典型情景\"}, {\"name\": \"丰富情景细节\", \"description\": \"为每种情景填充具体细节，使情景栩栩如生、逻辑自洽\"}, {\"name\": \"分析各情景影响\", \"description\": \"评估每种情景对组织/项目的影响和含义\"}, {\"name\": \"制定应对策略\", \"description\": \"为每种情景制定应对方案，同时寻找稳健策略（多情景都适用）\"}, {\"name\": \"建立预警信号\", \"description\": \"识别早期信号，监控现实向哪种情景演变，及时调整策略\"}]","itto":"{\"tools\": [\"情景矩阵、不确定性矩阵、PESTEL分析、专家研讨、德尔菲法\"], \"inputs\": [\"行业趋势数据、专家访谈、PEST分析、历史案例\"], \"outputs\": [\"情景分析报告、应对策略集、预警指标体系、战略弹性方案\"]}","tools":"情景矩阵、PESTEL分析、专家研讨工作坊、德尔菲法、时间轴分析","cases":"壳牌石油应对石油危机、荷兰政府应对气候变化、企业数字化转型战略、军事战略推演","viz_type":"matrix","viz_config":"{}","keywords":"情景规划,不确定性,战略规划,情景分析,壳牌,未来思考","sort_order":65,"_created_at":"2026-09-16T16:20:50.778+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.271+08:00","_updated_by":"()","code":"SOLVE-SCENARIO-001","aliases":"情景规划,场景规划,Scenario Planning,壳牌情景规划,未来情景分析","summary":"壳牌首创，针对不确定性构建多种未来情景并制定对应策略，提升组织适应力","problem_statement":"面对高度不确定性只做单一方案，一旦未来不如预期就措手不及，组织适应能力差、抗风险能力弱；情景规划法针对不确定性构建多种未来情景并制定对应策略，提升组织的适应力和战略韧性。","triggers":"情景规划,场景规划,不确定性,战略规划,未来分析,壳牌,情景分析","applicable":"长期战略规划、高不确定性行业、重大投资决策、危机管理预案、政策制定","not_applicable":"短期运营决策、确定性较高的问题、资源极度有限的小型项目","related_frameworks":"PESTEL分析,SWOT分析,蒙特卡洛模拟,风险矩阵,德尔菲法","templates":"情景规划工作坊指南、情景矩阵模板、预警信号监控表","limitations":"不是预测工具，不能预知未来；需要投入大量时间和资源；实施需要高层支持和跨部门参与","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"548d7a5e-cad8-4012-9acc-ea89119f8287","name":"资源基础观 RBV","category":"科研写作","scene":"战略管理研究、企业竞争力研究、核心能力分析、创新管理论文","core_logic":"资源基础观（Resource-Based View）是战略管理的主流理论，认为企业竞争优势的根源不在外部市场定位，而在企业内部拥有的异质性资源。满足VRIO四个条件（有价值、稀缺、不可模仿、组织化）的资源才能带来持续竞争优势。代表人物：Wernerfelt、Barney。","steps":"[]","itto":"{\"tools\": [\"RBV理论\", \"VRIO分析\", \"资源识别与评估\", \"案例研究\"], \"inputs\": [\"企业资源清单\", \"竞争对手对比\", \"能力评估\"], \"outputs\": [\"竞争优势分析报告\", \"资源建设建议\"]}","tools":"VRIO框架、核心能力识别、价值链分析、标杆对比","cases":"华为为什么能持续领先？用RBV分析：有形资源（充足的现金流、全球布局）、无形资源（5G技术专利、强大的研发能力、品牌声誉）、能力资源（高效的研发流程、艰苦奋斗的企业文化、以客户为中心的组织能力）→ 这些资源具有VRIO属性，构成了华为的持续竞争优势","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"企业竞争优势来源：内部资源\", \"description\": \"企业是资源的集合体，竞争优势来源于企业内部的异质性资源\"}, {\"name\": \"VRIO 框架\", \"items\": [\"Value 有价值：能创造价值或降低成本\", \"Rarity 稀缺性：只有少数企业拥有\", \"Inimitable 不可模仿：难以被竞争对手复制\", \"Organization 组织化：企业有能力组织和利用\"]}, {\"name\": \"资源类型\", \"items\": [\"有形资源：实物、财务、人力\", \"无形资源：技术、品牌、声誉、文化\", \"能力资源：流程、 routines、动态能力\"]}]}","keywords":"资源基础观,RBV,VRIO,竞争优势,战略管理,核心能力,管理社科","sort_order":135,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.279+08:00","_updated_by":"()","code":"RES-THY-003","aliases":"资源基础观","summary":"资源基础观（Resource-Based View）是战略管理的主流理论，认为企业竞争优势的根源不在外部市场定位，而在企业内部拥有的异质性资源。满足VRIO四个","problem_statement":"研究企业竞争优势只从外部市场找原因，忽视企业内部资源差异，解释不了同一行业内企业表现为何差异巨大；资源基础观从企业内部异质性资源出发，用VRIO框架识别持续竞争优势的内部来源。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"战略管理研究、企业竞争力研究、核心能力分析、创新管理论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"华为为什么能持续领先？用RBV分析：有形资源（充足的现金流、全球布局）、无形资源（5G技术专利、强大的研发能力、品牌声誉）、能力资源（高效的研发流程、艰苦奋斗的企业文化、以客户为中心的组织能力）→ 这","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"55f1de12-c02e-453b-8e46-8a9e2565d718","name":"RACI 职责矩阵","category":"团队管理","scene":"团队分工、流程职责划分、跨部门协作的场景","core_logic":"RACI矩阵将任务与角色交叉，明确每个任务中谁负责执行(R)、谁最终负责(A)、谁需要被咨询(C)、谁需要被告知(I)，避免职责不清、推诿扯皮和多头指挥。","steps":"[{\"name\": \"列出关键任务/活动\", \"description\": \"\"}, {\"name\": \"列出相关角色\", \"description\": \"\"}, {\"name\": \"分配R/A/C/I\", \"description\": \"\"}, {\"name\": \"确保每个任务一个A\", \"description\": \"\"}, {\"name\": \"沟通确认\", \"description\": \"\"}]","itto":"{\"tools\": [\"团队研讨\"], \"inputs\": [\"任务清单、角色清单\"], \"outputs\": [\"RACI职责矩阵\"]}","tools":"团队工作坊、Excel矩阵","cases":"某10人教学团队用RACI梳理课程建设任务：课程负责人(Accountable)对整体质量负责，主讲老师(Responsible)完成教学设计，助教(Consulted)参与作业设计，教学秘书(Informed)同步行政流程。明确了分工，减少了推诿。","viz_type":"matrix","viz_config":"{\"x_label\": \"角色\", \"y_label\": \"任务\", \"quadrants\": {\"q1\": \"R/A/C/I\"}}","keywords":"RACI,职责矩阵,团队分工,角色职责","sort_order":4,"_created_at":"2026-09-15T18:34:20.068+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.287+08:00","_updated_by":"()","code":"TEAM-RACI-001","aliases":"RACI,职责矩阵","summary":"明确团队角色职责分配的工具（执行/审批/咨询/知情）","problem_statement":"团队职责不清，任务来了没人接或多人抢着做，出了问题互相甩锅，协作效率低下内耗严重；RACI矩阵明确每个任务的执行者、审批者、咨询者和知情者，消除职责重叠和责任真空，让协作清晰高效。","triggers":"RACI,职责,分工,角色,团队管理","applicable":"团队分工、流程优化、组织调整、跨部门协作","not_applicable":"小型紧密团队、职责天然清晰的简单任务","related_frameworks":"贝尔宾团队角色,授权与分工,情境领导模型","templates":"RACI矩阵模板","limitations":"是静态工具需要定期更新；任务太多时矩阵过于复杂","mastery_level":"L3","last_used_date":null,"domain_code":"TEAM"},{"id":"5a9999d8-cf42-4907-8937-4308218b1f39","name":"系统动力学","category":"科研写作","scene":"复杂系统研究、社会经济系统仿真、生态环境系统、政策仿真、管理学论文","core_logic":"系统动力学（System Dynamics）由 Jay Forrester 创立，用于研究复杂反馈系统的动态行为。核心思想是：系统的行为模式由系统内部的反馈结构（正反馈环和负反馈环）决定。通过建立存量流量模型和仿真，可以观察系统随时间的演化，找到\"政策杠杆点\"——对系统影响最大的参数。","steps":"[{\"name\": \"问题界定与系统边界\", \"description\": \"明确要研究的动态问题，划定系统边界，确定内生变量和外生变量\"}, {\"name\": \"因果关系图 Causal Loop\", \"description\": \"绘制系统中各变量之间的因果关系图，识别正反馈环和负反馈环\"}, {\"name\": \"存量流量图 Stock & Flow\", \"description\": \"将因果关系图转化为存量流量图，明确积累效应和速率变量\"}, {\"name\": \"模型构建与仿真\", \"description\": \"建立系统动力学方程，运行仿真模拟，得到系统行为随时间变化的轨迹\"}, {\"name\": \"政策分析与优化\", \"description\": \"测试不同政策参数的效果，寻找系统优化的政策杠杆点\"}]","itto":"{\"tools\": [\"Vensim\", \"系统动力学\", \"因果回路图\", \"存量流量图\", \"仿真模拟\"], \"inputs\": [\"系统问题\", \"变量关系数据\", \"时间序列数据\"], \"outputs\": [\"系统动力学模型\", \"仿真结果\", \"政策建议\"]}","tools":"Vensim、Stella/iThink、AnyLogic、因果回路图（CLD）、存量流量图（SFD）","cases":"城市住房市场系统动力学研究：构建包含人口、经济、土地供应、住房需求、房价等变量的SD模型，识别关键反馈环（房价上涨→预期→更多需求→房价继续上涨的正反馈环），仿真模拟不同调控政策（限购、限价、增加土地供应）对房价的长期影响。","viz_type":"cycle","viz_config":"{}","keywords":"系统动力学,System Dynamics,反馈环,仿真建模,Vensim,福瑞斯特,工程系统","sort_order":163,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.295+08:00","_updated_by":"()","code":"SOL-SYS-001","aliases":"系统动力学","summary":"系统动力学（System Dynamics）由 Jay Forrester 创立，用于研究复杂反馈系统的动态行为。核心思想是：系统的行为模式由系统内部的反馈结构","problem_statement":"研究复杂社会经济问题只看静态快照，忽视系统内部反馈机制和动态变化趋势，预测和政策建议经常失灵；系统动力学通过构建因果反馈环和存量流量模型，研究复杂系统的动态行为和长期演化趋势。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"复杂系统研究、社会经济系统仿真、生态环境系统、政策仿真、管理学论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"城市住房市场系统动力学研究：构建包含人口、经济、土地供应、住房需求、房价等变量的SD模型，识别关键反馈环（房价上涨→预期→更多需求→房价继续上涨的正反馈环），仿真模拟不同调控政策（限购、限价、增加土地","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"5b06fe46-f4b1-4aa3-944b-a17d56683662","name":"托马斯-基尔曼冲突模型","category":"团队管理","scene":"冲突诊断、冲突管理培训、团队建设的场景","core_logic":"托马斯-基尔曼冲突模型从「坚持己见」和「合作满足对方」两个维度，将冲突应对方式分为五类：竞争(高坚持低合作)、协作(高坚持高合作)、妥协(中等坚持中等合作)、回避(低坚持低合作)、迁就(低坚持高合作)。不同情境适合不同方式。","steps":"[{\"name\": \"识别当前的冲突情境\", \"description\": \"\"}, {\"name\": \"评估问题的重要性和紧迫性\", \"description\": \"\"}, {\"name\": \"评估关系的重要性\", \"description\": \"\"}, {\"name\": \"选择合适的冲突应对方式\", \"description\": \"\"}, {\"name\": \"事后复盘调整\", \"description\": \"\"}]","itto":"{\"tools\": [\"TKI测评、冲突分析\"], \"inputs\": [\"冲突场景\"], \"outputs\": [\"冲突解决策略\"]}","tools":"TKI测评、非暴力沟通、谈判技巧","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"合作性（满足对方）\", \"y_label\": \"坚持性（满足自己）\", \"quadrants\": {\"q1\": \"竞争型\", \"q2\": \"协作型\", \"q3\": \"回避型\", \"q4\": \"迁就型\", \"center\": \"妥协型\"}}","keywords":"托马斯基尔曼,冲突模型,TKI,冲突管理,五种应对方式","sort_order":6,"_created_at":"2026-09-15T18:34:20.084+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.302+08:00","_updated_by":"()","code":"TEAM-CON-001","aliases":"TKI,冲突模式,Thomas-Kilmann","summary":"将冲突应对方式分为五类的冲突管理模型","problem_statement":"团队冲突处理方式单一，要么一味回避让问题发酵、要么强硬压制导致对立，团队氛围差、内耗严重；托马斯-基尔曼模型将冲突应对分为竞争、合作、妥协、回避、迁就五类，帮你根据情境选择最合适的处理方式。","triggers":"冲突,TKI,冲突管理,竞争协作妥协回避迁就","applicable":"冲突管理、团队建设、领导力发展、谈判技巧","not_applicable":"完全没有冲突的和谐场景","related_frameworks":"非暴力沟通,情境领导模型,力场分析","templates":"TKI冲突模式评估表","limitations":"是行为风格描述而非操作方法；实际冲突中需要灵活切换；测试结果受自评偏差影响","mastery_level":"L2","last_used_date":null,"domain_code":"TEAM"},{"id":"5b448e56-2d61-40e6-be60-0645e67762b0","name":"ATAM 架构权衡分析","category":"系统架构","scene":"架构评审、架构选型、关键设计决策评估的场景","core_logic":"ATAM是SEI提出的架构权衡分析方法，通过识别业务驱动→确定质量属性目标→梳理架构方法→分析敏感点和权衡点的过程，系统性评估架构在性能、可用性、安全性、可修改性等质量属性间的权衡，帮助做出更好的架构决策。","steps":"[{\"name\": \"明确业务驱动和质量属性目标\", \"description\": \"\"}, {\"name\": \"梳理架构设计决策\", \"description\": \"\"}, {\"name\": \"识别质量属性场景\", \"description\": \"\"}, {\"name\": \"分析敏感点和权衡点\", \"description\": \"\"}, {\"name\": \"生成风险和非风险点\", \"description\": \"\"}, {\"name\": \"形成架构评估报告\", \"description\": \"\"}]","itto":"{\"tools\": [\"ATAM方法、质量属性场景\"], \"inputs\": [\"架构设计方案、质量属性需求\"], \"outputs\": [\"架构评估报告、风险清单\"]}","tools":"质量属性场景、效用树、架构评审会议","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"架构决策\", \"y_label\": \"质量属性\", \"quadrants\": {\"q1\": \"权衡分析\"}}","keywords":"ATAM,架构权衡,质量属性,架构评估,架构评审","sort_order":7,"_created_at":"2026-09-15T18:34:26.469+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.31+08:00","_updated_by":"()","code":"ARCH-ATAM-001","aliases":"ATAM,架构权衡分析方法,Architecture Tradeoff Analysis Method","summary":"系统性评估架构设计在质量属性间权衡优劣的分析方法","problem_statement":"架构设计只看功能不看质量属性，系统上线后才发现性能差、可用性低、扩展性差，但已经很难改了；ATAM系统性评估架构在性能、可用性、安全性等质量属性间的权衡优劣，提前发现架构风险。","triggers":"ATAM,架构权衡,质量属性,架构评审,架构评估","applicable":"架构评审、架构选型、关键技术决策、重大系统重构","not_applicable":"小型简单系统、架构无争议的标准方案","related_frameworks":"4+1 视图模型,高可用架构设计,微服务架构","templates":"ATAM评估模板","limitations":"实施门槛较高；需要有经验的架构师引导；耗时较长需要多方参与","mastery_level":"L2","last_used_date":null,"domain_code":"ARCH"},{"id":"5db4a434-58ae-41db-9a2f-95f4c8a48399","name":"电梯演讲","category":"表达与写作","scene":"路演、商务介绍、面试自我介绍、创业融资、社交场合自我介绍的场景","core_logic":"电梯演讲（Elevator Pitch）源自麦肯锡：假设你在电梯里遇到了关键决策者，只有30秒到2分钟的时间，你能否用这段时间把你的想法/产品/自己讲清楚并打动对方？好的电梯演讲应该包含：钩子（吸引注意力）→ 问题（痛点是什么）→ 解决方案（你怎么解决）→ 价值主张（有什么独特价值）→ 行动呼吁（你希望对方做什么）。核心是简洁、有力、留有余味。","steps":"[{\"name\": \"明确目标听众\", \"description\": \"清楚你在跟谁说话，他们关心什么、痛点是什么、有什么背景\"}, {\"name\": \"设定演讲目标\", \"description\": \"明确你希望通过这次演讲达到什么效果——获得一次会议？拿到投资？被记住？\"}, {\"name\": \"设计钩子(Hook)\", \"description\": \"用一个有趣的问题、惊人的数据或引人深思的场景开头，抓住注意力\"}, {\"name\": \"点明问题(Problem)\", \"description\": \"快速说明你在解决什么问题/满足什么需求/面对什么挑战，让对方产生共鸣\"}, {\"name\": \"给出解决方案(Solution)\", \"description\": \"简明扼要地说明你的方案/产品/你自己如何解决这个问题，独特之处在哪里\"}, {\"name\": \"展示价值(Value)\", \"description\": \"量化或具象化说明能带来什么价值/好处/成果，最好用数字说话\"}, {\"name\": \"行动呼吁(CTA)\", \"description\": \"明确告诉对方你希望他下一步做什么——约个时间详谈？安排演示？交换联系方式？\"}, {\"name\": \"反复打磨和练习\", \"description\": \"反复精简语言，控制在规定时间内，对着镜子或朋友练习，直到自然流畅\"}]","itto":"{\"tools\": [\"钩子设计、价值主张画布、讲故事技巧、30秒计时器\"], \"inputs\": [\"你的想法/产品/简历、听众画像、目标设定\"], \"outputs\": [\"精炼的自我介绍/产品介绍、对方的兴趣和关注、下一步行动机会、个人品牌印象\"]}","tools":"价值主张画布、故事叙述、钩子技巧、价值量化、听众分析","cases":"创业融资路演、TED演讲开场、求职自我介绍、销售初次见面、行业社交场合","viz_type":"process","viz_config":"{}","keywords":"电梯演讲,Elevator Pitch,30秒陈述,自我介绍,路演,pitch,价值主张","sort_order":123,"_created_at":"2026-09-16T16:20:51.141+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.317+08:00","_updated_by":"()","code":"RES-ELEVATOR-001","aliases":"电梯演讲,电梯 pitch,30秒陈述,Elevator Pitch,电梯游说,电梯陈述","summary":"在极短时间内（30秒-2分钟）讲清价值主张，吸引对方兴趣并争取进一步沟通的机会","problem_statement":"遇到关键人物却三言两语说不清楚价值，错失展示和沟通机会，好想法因为表达不精炼而被忽略；电梯演讲训练你在30秒到2分钟内讲清核心价值，快速抓住对方兴趣并争取深入沟通的机会。","triggers":"电梯演讲,Elevator Pitch,30秒陈述,电梯游说,自我介绍,路演,pitch","applicable":"创业融资路演、商务洽谈、面试自我介绍、社交场合自我介绍、产品介绍、求职/销售","not_applicable":"需要深入讨论的技术细节、完全陌生的领域（需要更多背景铺垫）、非正式社交场合","related_frameworks":"PREP表达法,STAR法则,黄金圈法则,价值主张,电梯测试","templates":"电梯演讲模板、自我介绍模板、30秒pitch脚本、路演开场模板","limitations":"准备需要时间和反复打磨；过于精简可能丢失重要信息；需要根据不同听众调整版本；紧张时容易大脑空白","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"5de875b7-9734-4870-8c20-bf77c5fef4d7","name":"KJ 法（亲和图法）","category":"问题解决","scene":"信息杂乱无章、需要从混沌中提炼结构、创意收敛、问题定义的场景","core_logic":"KJ法由人类学家川喜田二郎创立，是一种从大量混乱信息中发现内在关联、形成结构化认知的方法：收集信息卡片→分组归类→为每组命名→形成层级结构→发现整体模式。通过亲和分组让隐性的关联浮现出来，特别适合处理模糊、复杂、涉及人的因素的问题。","steps":"[{\"name\": \"确定主题\", \"description\": \"明确要研究的问题或主题，设定讨论范围\"}, {\"name\": \"收集信息并制作卡片\", \"description\": \"收集所有相关信息、想法、观点，每条写在一张卡片上\"}, {\"name\": \"分组归类（亲和分组）\", \"description\": \"将相似的卡片放在一起，凭直觉和感觉分组，不急于分类\"}, {\"name\": \"为每组命名\", \"description\": \"为每组卡片起一个能代表该组本质的标题，形成亲和卡\"}, {\"name\": \"形成层级结构\", \"description\": \"将小组再归为大组，逐步建立层次结构\"}, {\"name\": \"发现整体模式\", \"description\": \"观察整体结构，发现关键洞察和内在关系\"}, {\"name\": \"总结与行动\", \"description\": \"将发现转化为结论和行动计划\"}]","itto":"{\"tools\": [\"便签纸、白板、亲和图模板、思维导图工具\"], \"inputs\": [\"原始信息、用户反馈、创意想法、调研数据\"], \"outputs\": [\"亲和图、结构化洞察、问题定义、行动方向\"]}","tools":"便签纸、白板、Miro/Mural、思维导图工具","cases":"用户研究数据分析、质量管理问题归类、产品需求整理、组织问题诊断","viz_type":"hierarchy","viz_config":"{}","keywords":"KJ法,亲和图,信息归类,结构化,川喜田二郎,收敛","sort_order":63,"_created_at":"2026-09-16T16:20:50.756+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.325+08:00","_updated_by":"()","code":"SOLVE-KJ-001","aliases":"亲和图法,川喜田二郎,KJ Method,Affinity Diagram,亲和图","summary":"把零散混乱的信息按内在关联归类分组，从混乱中提炼结构化洞察","problem_statement":"面对大量零散混乱的信息不知道如何整理，越理越乱，提炼不出有价值的洞察，决策没有条理；KJ法把零散信息按内在关联归类分组，从混乱中发现结构、提炼洞察，让信息从无序变有序。","triggers":"KJ法,亲和图,信息归类,混乱信息,结构化整理,创意收敛","applicable":"信息整理与归纳、问题定义阶段、用户研究分析、创意收敛、团队共识建立","not_applicable":"数据已结构化的问题、需要精确量化分析的场景、时间紧迫需要快速决策","related_frameworks":"名义小组技术,头脑风暴法,思维导图,用户旅程图,卡片分类法","templates":"KJ法工作指引、亲和图模板","limitations":"主观性较强，结果依赖参与者水平；耗时较长，不适合紧急问题；需要有经验的引导者","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"5f887173-4e59-4f52-be4f-3f3abb0b67b7","name":"DIKW 模型","category":"知识管理","scene":"知识管理体系设计、信息素养提升、知识产品设计的场景","core_logic":"DIKW模型将人类认知分为四个层级：Data（数据，原始符号）→Information（信息，有意义的数据）→Knowledge（知识，可应用的信息）→Wisdom（智慧，能做出正确判断的知识）。每层都增加了价值和上下文。","steps":"[{\"name\": \"收集原始数据\", \"description\": \"\"}, {\"name\": \"整理加工为有意义的信息\", \"description\": \"\"}, {\"name\": \"提炼总结为可应用的知识\", \"description\": \"\"}, {\"name\": \"实践内化形成智慧洞察\", \"description\": \"\"}, {\"name\": \"持续迭代升级\", \"description\": \"\"}]","itto":"{\"tools\": [\"信息加工、知识提炼\"], \"inputs\": [\"原始数据/素材\"], \"outputs\": [\"知识资产、智慧洞察\"]}","tools":"数据分析、知识管理系统、个人知识管理","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"DIKW,数据信息知识智慧,知识层级,知识管理","sort_order":1,"_created_at":"2026-09-15T18:34:26.578+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.333+08:00","_updated_by":"()","code":"KNOW-DIKW-001","aliases":"DIKW,数据信息知识智慧,知识层级模型","summary":"描述从数据到信息到知识到智慧的四个层级的经典模型","problem_statement":"数据信息不分、知识智慧混淆，收集了海量信息却不会提炼为知识，更无法上升为智慧做决策；DIKW模型清晰划分数据-信息-知识-智慧四个层级，帮你理解从原始数据到决策智慧的转化路径。","triggers":"DIKW,数据信息知识智慧,知识层级,知识管理","applicable":"知识管理、信息架构、教育设计、知识产品设计","not_applicable":"纯数据处理、无认知提升需求的场景","related_frameworks":"SECI 模型,CODE 知识加工,渐进式总结","templates":"DIKW知识转化模板","limitations":"层级边界有时模糊；是概念模型不是操作方法；智慧层的达成没有标准路径","mastery_level":"L2","last_used_date":null,"domain_code":"KNOW"},{"id":"62da94e6-0d31-41be-8291-480d213ab7c3","name":"权力/利益矩阵","category":"项目管理","scene":"项目启动阶段的干系人识别和管理策略制定","core_logic":"将所有干系人按权力大小（纵轴）和利益相关程度（横轴）分为四类：高权高利（重点管理）、高权低利（保持满意）、低权高利（保持知情）、低权低利（花最少精力），对不同类别采取不同的管理策略。","steps":"[{\"name\": \"识别所有项目干系人\", \"description\": \"\"}, {\"name\": \"评估每个干系人的权力大小\", \"description\": \"\"}, {\"name\": \"评估每个干系人的利益相关程度\", \"description\": \"\"}, {\"name\": \"将干系人放入矩阵四象限\", \"description\": \"\"}, {\"name\": \"制定差异化的沟通和管理策略\", \"description\": \"\"}]","itto":"{\"tools\": [\"权力利益评估\"], \"inputs\": [\"干系人清单\"], \"outputs\": [\"干系人分类、管理策略\"]}","tools":"头脑风暴、干系人访谈、项目文件分析","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"利益相关程度\", \"y_label\": \"权力大小\", \"quadrants\": {\"q1\": \"重点管理\", \"q2\": \"保持满意\", \"q3\": \"花最少精力\", \"q4\": \"保持知情\"}}","keywords":"权力利益矩阵,干系人管理,干系人分类,项目管理","sort_order":15,"_created_at":"2026-09-15T18:34:13.653+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.341+08:00","_updated_by":"()","code":"PM-STK-001","aliases":"权力利益矩阵,干系人矩阵,Power-Interest Grid","summary":"按权力和利益两个维度分类干系人，制定差异化管理策略的工具","problem_statement":"项目干系人多且杂，不知道该重点关注谁、该怎么沟通，要么得罪了关键人要么精力错配；权力/利益矩阵按权力和利益两个维度对干系人分类，为不同类型的干系人制定差异化的管理策略。","triggers":"权力利益,干系人,干系人管理,矩阵,分类","applicable":"项目干系人管理、政策推动、变革管理、客户关系管理","not_applicable":"简单的个人任务、干系人很少的小型项目","related_frameworks":"干系人参与计划,RACI 矩阵,客户旅程图","templates":"权力利益矩阵模板","limitations":"权力和利益的评估有主观性；干系人地位可能随项目进展变化；二维分析可能简化过度","mastery_level":"L2","last_used_date":null,"domain_code":"PM"},{"id":"638f170d-7dcb-4e3d-8013-724043f235d9","name":"TOE 框架：技术—组织—环境","category":"科研写作","scene":"技术采纳与扩散研究、信息化/数字化转型研究、创新管理、信息系统领域论文","core_logic":"TOE 框架从技术情境（技术本身的特性）、组织情境（采用技术的组织特征）、环境情境（组织所处的外部环境）三个维度分析技术创新在组织中的采纳和扩散。是信息系统领域最经典的分析框架之一，Tornatzky & Fleischer 提出。","steps":"[]","itto":"{\"tools\": [\"TOE框架\", \"问卷调研\", \"结构方程模型\", \"案例研究\"], \"inputs\": [\"技术特征信息\", \"组织特征数据\", \"环境因素\"], \"outputs\": [\"技术采纳影响因素分析\", \"推广策略建议\"]}","tools":"问卷调研、结构方程模型（SEM）、多案例研究、回归分析","cases":"企业数字化转型影响因素研究：T（数字技术成熟度、相对优势、与现有系统兼容性）、O（企业规模、CEO支持、IT能力、组织文化）、E（行业竞争压力、政策支持、同行示范效应）→ 用SEM验证各因素对数字化转型程度的影响","viz_type":"matrix","viz_config":"{\"quadrants\": [{\"name\": \"T 技术情境 Technological\", \"items\": [\"技术成熟度\", \"技术兼容性\", \"相对优势\", \"复杂性\", \"可试性\"], \"description\": \"与技术本身特性相关的因素\"}, {\"name\": \"O 组织情境 Organizational\", \"items\": [\"组织规模\", \"组织结构\", \"高层支持\", \"资源充足度\", \"员工素质\"], \"description\": \"与组织内部特征相关的因素\"}, {\"name\": \"E 环境情境 Environmental\", \"items\": [\"行业竞争\", \"政府政策\", \"合作伙伴\", \"基础设施\", \"外部压力\"], \"description\": \"与外部环境相关的因素\"}], \"xAxisLabel\": \"三大情境维度\", \"yAxisLabel\": \"\"}","keywords":"TOE,技术采纳,技术扩散,创新扩散,信息系统,战略产业","sort_order":126,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.349+08:00","_updated_by":"()","code":"DEC-IND-005","aliases":"TOE","summary":"TOE 框架从技术情境（技术本身的特性）、组织情境（采用技术的组织特征）、环境情境（组织所处的外部环境）三个维度分析技术创新在组织中的采纳和扩散。是信息系统领域","problem_statement":"研究技术采纳只看技术本身，忽视组织特征和外部环境的影响，解释不了同样的技术在不同组织效果天差地别；TOE框架从技术情境、组织情境、环境情境三个维度系统分析技术创新的采纳和扩散。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"技术采纳与扩散研究、信息化/数字化转型研究、创新管理、信息系统领域论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"企业数字化转型影响因素研究：T（数字技术成熟度、相对优势、与现有系统兼容性）、O（企业规模、CEO支持、IT能力、组织文化）、E（行业竞争压力、政策支持、同行示范效应）→ 用SEM验证各因素对数字化转","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"64cb651a-d748-45f0-a6ac-6e40e18f1e07","name":"客户升级机制","category":"客户交付","scene":"客户支持、运维服务、项目交付等需要分级处理客户问题的场景","core_logic":"客户升级机制定义了问题的分级标准（一般按影响范围和紧急程度分为P0-P3）、每级的响应时间和解决时间、升级路径和上报对象，确保重大问题能快速得到高层关注和资源支持。","steps":"[{\"name\": \"定义问题分级标准(P0-P3)\", \"description\": \"\"}, {\"name\": \"设定各级响应和解决时效\", \"description\": \"\"}, {\"name\": \"明确升级路径和责任人\", \"description\": \"\"}, {\"name\": \"建立升级触发机制\", \"description\": \"\"}, {\"name\": \"培训团队执行\", \"description\": \"\"}, {\"name\": \"定期复盘优化\", \"description\": \"\"}]","itto":"{\"tools\": [\"工单系统、值班制度\"], \"inputs\": [\"客户问题/故障\"], \"outputs\": [\"问题分级处理、客户满意度\"]}","tools":"工单系统、值班制度、故障管理流程","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"升级机制,问题分级,客户支持,SLA,故障处理","sort_order":6,"_created_at":"2026-09-15T18:34:20.153+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.356+08:00","_updated_by":"()","code":"CUST-ESC-001","aliases":"升级机制,问题升级,Escalation","summary":"按问题严重程度和处理时效逐级升级的客户问题处理机制","problem_statement":"客户问题处理时该升级的不升级、不该升级的乱升级，小问题拖成大投诉，大问题又处理不及时，客户体验差；客户升级机制按问题严重程度和处理时效明确升级标准和路径，确保问题在合适层级得到及时解决。","triggers":"升级机制,问题分级,响应时效,客户支持,故障处理","applicable":"客户支持团队、IT运维服务、SaaS产品、项目交付","not_applicable":"简单标准化产品、客户量极少的业务","related_frameworks":"SLA 服务级别协议,8D 问题解决法,客户满意度管理","templates":"问题升级矩阵模板","limitations":"分级标准制定有难度；升级过多会导致高层疲劳；需要文化配合避免不敢升级","mastery_level":"L2","last_used_date":null,"domain_code":"CUST"},{"id":"6cb9e8da-f352-4c98-96b1-c90a84d575e1","name":"PESTEL 分析","category":"科研写作","scene":"产业研究、战略规划、市场分析、企业外部环境分析、课题研究的宏观背景分析","core_logic":"PESTEL 是从政治(Political)、经济(Economic)、社会(Social)、技术(Technological)、环境(Environmental)、法律(Legal)六个维度系统扫描宏观环境的经典框架。帮助研究者全面识别外部环境中的机会和威胁，避免遗漏重要的环境因素。","steps":"[]","itto":"{\"tools\": [\"PESTEL分析框架\", \"文献研究\", \"专家访谈\", \"情景分析\"], \"inputs\": [\"宏观环境信息\", \"行业数据\", \"政策文件\"], \"outputs\": [\"宏观环境分析报告\", \"战略机遇与威胁清单\"]}","tools":"情景分析、德尔菲法、文献计量、行业报告分析","cases":"新能源汽车产业宏观环境分析：P（双碳政策、补贴退坡）、E（经济复苏、消费升级）、S（环保意识提升）、T（电池技术突破）、E（碳中和目标）、L（新能源汽车产业发展规划）","viz_type":"matrix","viz_config":"{\"quadrants\": [{\"name\": \"P 政治 Political\", \"items\": [\"政府政策\", \"政治稳定性\", \"监管环境\", \"国际关系\", \"产业政策\"], \"description\": \"政治和政策因素对产业/企业的影响\"}, {\"name\": \"E 经济 Economic\", \"items\": [\"经济增长\", \"利率汇率\", \"通胀水平\", \"消费能力\", \"产业结构\"], \"description\": \"经济环境和趋势的影响\"}, {\"name\": \"S 社会 Social\", \"items\": [\"人口结构\", \"文化观念\", \"消费习惯\", \"教育水平\", \"生活方式\"], \"description\": \"社会文化因素的影响\"}, {\"name\": \"T 技术 Technological\", \"items\": [\"技术突破\", \"创新能力\", \"数字化水平\", \"研发投入\", \"技术标准\"], \"description\": \"技术变革和创新的影响\"}, {\"name\": \"E 环境 Environmental\", \"items\": [\"环保要求\", \"气候变化\", \"资源约束\", \"可持续发展\", \"绿色政策\"], \"description\": \"生态环境因素的影响\"}, {\"name\": \"L 法律 Legal\", \"items\": [\"法律法规\", \"知识产权\", \"劳动法规\", \"反垄断\", \"行业标准\"], \"description\": \"法律和监管因素的影响\"}], \"xAxisLabel\": \"宏观环境六大维度\", \"yAxisLabel\": \"\"}","keywords":"PESTEL,宏观环境,战略分析,产业研究,战略产业","sort_order":121,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.365+08:00","_updated_by":"()","code":"DEC-MAC-001","aliases":"PESTEL","summary":"PESTEL 是从政治(Political)、经济(Economic)、社会(Social)、技术(Technological)、环境(Environmenta","problem_statement":"分析宏观环境只看经济或政策单一维度，忽略社会、技术、环境等因素，战略分析不全面，错失机会或低估风险；PESTEL从政治、经济、社会、技术、环境、法律六个维度全面扫描宏观环境。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"产业研究、战略规划、市场分析、企业外部环境分析、课题研究的宏观背景分析","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"新能源汽车产业宏观环境分析：P（双碳政策、补贴退坡）、E（经济复苏、消费升级）、S（环保意识提升）、T（电池技术突破）、E（碳中和目标）、L（新能源汽车产业发展规划）","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"DECIDE"},{"id":"6cc204e4-74b1-4bcb-bd30-779546f567f3","name":"费曼学习法","category":"学习方法","scene":"深度学习新知识、准备面试/考试、技术分享准备、知识体系构建、概念理解验证。","core_logic":"诺贝尔物理学奖得主理查德·费曼的学习方法，核心是「以教代学」：如果你不能用简单的语言把一个概念讲清楚让小白也听懂，说明你还没有真正理解。通过「选择概念→教授他人→找出缺口→简化类比」四步循环，倒逼自己深度学习，消除知识盲区。","steps":"[{\"name\": \"第一步：选择概念\", \"description\": \"选择一个你想理解的概念或知识点，明确学习目标\"}, {\"name\": \"第二步：教授他人\", \"description\": \"用简单的语言向别人（或假想对象）讲解这个概念，就像教一个新手一样\"}, {\"name\": \"第三步：找出缺口\", \"description\": \"发现自己讲不清楚、理解不深的地方，回到原始材料重新学习\"}, {\"name\": \"第四步：简化与类比\", \"description\": \"用更简洁的语言和类比来解释，真正做到深入浅出\"}]","itto":"{\"tools\": [\"思维导图\", \"笔记法\", \"类比思维\"], \"inputs\": [\"学习主题\", \"参考资料\"], \"outputs\": [\"深度理解\", \"可传授知识\"]}","tools":"康奈尔笔记法、思维导图、写博客/公众号、给同事做技术分享","cases":"某工程师用费曼法学机器学习：先尝试给产品经理讲清楚「什么是神经网络」，发现自己讲不清反向传播原理，回去重学数学基础和推导过程，再讲第二遍，直到能用「就像人脑中神经元传递信号，通过不断调整连接权重来学习规律」这样的类比让文科生也听懂。","viz_type":"cycle","viz_config":"{}","keywords":"费曼,学习法,深度学习,以教代学","sort_order":10,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.373+08:00","_updated_by":"()","code":"LRN-STU-001","aliases":"费曼","summary":"诺贝尔物理学奖得主理查德·费曼的学习方法，核心是「以教代学」：如果你不能用简单的语言把一个概念讲清楚让小白也听懂，说明你还没有真正理解。通过「选择概念→教授他人","problem_statement":"看书觉得都懂了，一到要用就卡壳，能听懂但说不出来，知识停留在被动接收的浅层；费曼学习法核心是以教代学——如果你不能用简单语言把概念讲清楚让小白听懂，说明你还没有真正理解。","triggers":"学不会、记不住、效率低","applicable":"深度学习新知识、准备面试/考试、技术分享准备、知识体系构建、概念理解验证。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某工程师用费曼法学机器学习：先尝试给产品经理讲清楚「什么是神经网络」，发现自己讲不清反向传播原理，回去重学数学基础和推导过程，再讲第二遍，直到能用「就像人脑中神经元传递信号，通过不断调整连接权重来学习","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"LEARN"},{"id":"6f589bc6-ee00-47a1-bef3-498c5da0607c","name":"行动研究","category":"科研写作","scene":"教育研究、管理实践改进、社会工作、社区发展、组织变革研究论文","core_logic":"行动研究（Action Research）由勒温提出，核心是\"研究行动、在行动中研究、为行动而研究\"。研究者不是站在外面观察，而是深入实践与实践者合作，通过\"计划→行动→观察→反思\"的多轮循环，既解决实践问题又生产知识。是连接理论与实践的重要研究范式。","steps":"[{\"name\": \"计划 Plan\", \"description\": \"明确研究问题、制定行动计划，研究者与实践者共同参与计划制定\"}, {\"name\": \"行动 Act\", \"description\": \"按照计划实施干预或变革行动，研究者深入实践现场参与行动\"}, {\"name\": \"观察 Observe\", \"description\": \"系统观察和记录行动的过程和结果，收集多方面的数据和反馈\"}, {\"name\": \"反思 Reflect\", \"description\": \"对行动结果进行反思和讨论，总结经验教训，发现新问题\"}, {\"name\": \"下一轮循环\", \"description\": \"基于反思调整计划，进入下一轮计划→行动→观察→反思的循环\"}]","itto":"{\"tools\": [\"行动研究法\", \"参与式观察\", \"访谈\", \"反思日志\"], \"inputs\": [\"实践问题\", \"研究者+实践者团队\", \"行动方案\"], \"outputs\": [\"实践改进方案\", \"行动研究报告\", \"实践理论\"]}","tools":"参与式观察、深度访谈、行动日志、反思日记、焦点小组","cases":"高校教学改革行动研究：教师（同时也是研究者）在自己的课堂上实施教学改革——计划（翻转课堂设计）→ 行动（实际授课）→ 观察（学生反馈、成绩变化、课堂记录）→ 反思（哪些有效、哪些需要调整）→ 下一轮改进。几个循环后既改善了教学效果，又产出了教学研究成果。","viz_type":"cycle","viz_config":"{}","keywords":"行动研究,Action Research,参与式研究,实践改进,勒温,管理社科","sort_order":140,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.38+08:00","_updated_by":"()","code":"RES-029","aliases":"行动研究","summary":"行动研究（Action Research）由勒温提出，核心是\"研究行动、在行动中研究、为行动而研究\"。研究者不是站在外面观察，而是深入实践与实践者合作，通过\"计","problem_statement":"学术研究与实践脱节，研究者站在外面观察，研究成果对实践者没有指导价值，研究问题也不接地气；行动研究强调研究者深入实践与实践者合作，通过计划-行动-观察-反思的循环，在行动中研究、为行动而研究。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"教育研究、管理实践改进、社会工作、社区发展、组织变革研究论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"高校教学改革行动研究：教师（同时也是研究者）在自己的课堂上实施教学改革——计划（翻转课堂设计）→ 行动（实际授课）→ 观察（学生反馈、成绩变化、课堂记录）→ 反思（哪些有效、哪些需要调整）→ 下一轮改","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"71aeda3a-f4d3-467d-b7c4-05658159dfcf","name":"问题—目标—方案—评估—决策","category":"科研写作","scene":"工程管理研究、决策分析论文、方案比选研究、项目可行性研究","core_logic":"标准的工程决策和管理问题分析框架：从明确问题开始，到设定目标、设计方案、评估比较，最终做出决策。强调多个备选方案的比较而非单一方案的论证，用科学的评估方法支撑决策，避免拍脑袋决策。","steps":"[{\"name\": \"问题界定\", \"description\": \"清晰定义工程/管理问题，明确问题边界、约束条件和评价标准\"}, {\"name\": \"目标设定\", \"description\": \"设定解决问题要达到的目标，包括总目标和分目标，量化目标指标\"}, {\"name\": \"方案设计\", \"description\": \"设计多种备选方案，每个方案都有完整的技术路线和资源需求\"}, {\"name\": \"方案评估\", \"description\": \"用多准则决策方法对各方案进行综合评估，比较优劣\"}, {\"name\": \"决策选择\", \"description\": \"基于评估结果和风险分析，选择最优方案或满意方案\"}]","itto":"{\"tools\": [\"多准则决策\", \"层次分析法AHP\", \"模糊综合评价\", \"方案比选\"], \"inputs\": [\"工程问题\", \"约束条件\", \"评估标准\"], \"outputs\": [\"决策分析报告\", \"最优方案选择\"]}","tools":"AHP层次分析法、TOPSIS、模糊综合评价、成本效益分析、风险分析","cases":"城市地铁线路选型决策研究：问题（老城区交通拥堵需要轨道交通）→ 目标（缓解拥堵、投资可控、工期合理）→ 方案（A方案走主干道、B方案走次干道、C方案绕行开发区）→ 评估（用AHP从造价、工期、客流、环境影响等多维度评估）→ 决策（选择综合最优的B方案）","viz_type":"process","viz_config":"{}","keywords":"决策分析,方案比选,多准则决策,工程管理,系统分析,工程系统","sort_order":162,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.388+08:00","_updated_by":"()","code":"RES-WRI-013","aliases":"决策分析","summary":"标准的工程决策和管理问题分析框架：从明确问题开始，到设定目标、设计方案、评估比较，最终做出决策。强调多个备选方案的比较而非单一方案的论证，用科学的评估方法支撑决","problem_statement":"工程和管理类论文分析问题只给一个方案自说自话，没有比较和评估，决策过程不科学、说服力弱；问题-目标-方案-评估-决策框架强调多方案比较和科学评估，用系统化方法支撑决策。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"工程管理研究、决策分析论文、方案比选研究、项目可行性研究","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"城市地铁线路选型决策研究：问题（老城区交通拥堵需要轨道交通）→ 目标（缓解拥堵、投资可控、工期合理）→ 方案（A方案走主干道、B方案走次干道、C方案绕行开发区）→ 评估（用AHP从造价、工期、客流、环","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"72bf495d-9b0b-4d89-8f55-51cbc50593f3","name":"问卷调查","category":"需求管理","scene":"验证需求普遍性、测量用户满意度、大规模市场调研的场景","core_logic":"通过设计标准化的问卷，向大量目标用户发放收集数据，用统计方法分析用户行为、态度和需求，验证定性研究发现的普遍性，为产品决策提供数据支撑。","steps":"[{\"name\": \"明确调查目标和研究问题\", \"description\": \"\"}, {\"name\": \"设计问卷（题目类型/逻辑）\", \"description\": \"\"}, {\"name\": \"小规模预测试\", \"description\": \"\"}, {\"name\": \"大规模发放回收\", \"description\": \"\"}, {\"name\": \"数据清洗和统计分析\", \"description\": \"\"}, {\"name\": \"输出分析报告\", \"description\": \"\"}]","itto":"{\"tools\": [\"问卷设计、统计分析软件\"], \"inputs\": [\"调研目标、目标人群\"], \"outputs\": [\"调查报告、统计数据\"]}","tools":"问卷星、金数据、SurveyMonkey、SPSS、Excel","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"问卷调查,定量研究,用户调研,统计分析,需求验证","sort_order":2,"_created_at":"2026-09-15T18:34:13.707+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.396+08:00","_updated_by":"()","code":"PROD-RES-002","aliases":"问卷,调查问卷,User Survey","summary":"通过标准化问卷大规模收集用户数据的定量研究方法","problem_statement":"只靠少量访谈做需求，样本太少结论不可靠，不知道用户真实分布和优先级，决策凭感觉；问卷调查通过标准化问题大规模收集用户数据，用量化数据支撑需求决策，让结论有据可依。","triggers":"问卷,调研,定量,统计,用户研究","applicable":"需求普遍性验证、满意度调查、市场规模评估、产品使用行为统计","not_applicable":"探索性需求发现、深层动机和原因探究","related_frameworks":"访谈法,KANO 模型,问卷调查","templates":"调查问卷设计模板","limitations":"问卷设计不当会导致偏差；回收率低可能影响代表性；只能回答是什么不能回答为什么","mastery_level":"L2","last_used_date":null,"domain_code":"PROD"},{"id":"73abf55f-8abf-4475-b984-8adf23c60756","name":"根本原因分析 RCA","category":"思维方法","scene":"事故调查、质量问题、系统故障、运营问题的深层分析","core_logic":"RCA是一套系统化的根因分析方法论，通过定义问题、收集数据、识别直接原因、追溯根本原因、制定并实施改进措施五个步骤，结合5Why、鱼骨图、故障树等多种工具，确保问题从根源上解决。","steps":"[{\"name\": \"定义问题：清楚描述发生了什么\", \"description\": \"\"}, {\"name\": \"收集数据：时间、地点、人员、影响\", \"description\": \"\"}, {\"name\": \"识别可能的原因：鱼骨图等工具\", \"description\": \"\"}, {\"name\": \"追溯根本原因：5Why或故障树\", \"description\": \"\"}, {\"name\": \"制定改进措施并验证效果\", \"description\": \"\"}]","itto":"{\"tools\": [\"鱼骨图、5Why、故障树\"], \"inputs\": [\"问题事件\"], \"outputs\": [\"根因报告、纠正预防措施\"]}","tools":"5Why、鱼骨图、故障树分析FTA、失效模式FMEA、帕累托分析","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"RCA,根本原因分析,根因,事故调查,预防措施","sort_order":10,"_created_at":"2026-09-15T18:34:03.28+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.404+08:00","_updated_by":"()","code":"SOL-THK-006","aliases":"RCA,Root Cause Analysis,根因分析","summary":"系统性识别问题根本原因并制定预防措施的分析方法体系","problem_statement":"出了问题只处理表面症状，头痛医头脚痛医脚，同样的问题反复发生，永远在救火从不防火；根本原因分析通过系统化方法深挖问题背后的根本原因，制定预防措施，从根源上解决问题。","triggers":"RCA,根因分析,事故调查,根本原因,预防","applicable":"事故调查、医疗差错分析、IT故障、质量问题、安全事件","not_applicable":"简单明了的小问题、一次性偶发事件","related_frameworks":"5Why 分析法,鱼骨图,8D 问题解决法","templates":"RCA分析报告模板","limitations":"需要跨部门协作和数据支撑；对分析者能力要求较高；可能找到多个根因","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"757ccae3-6ee1-465f-a9dd-b6ef546b5f89","name":"IMRaD 结构","category":"科研写作","scene":"实证研究类期刊论文、学位论文、会议论文的标准写作结构，尤其适用于理工科和社会科学实证研究","core_logic":"IMRaD 是国际学术期刊最通用的论文结构：先说为什么做（引言），再说怎么做（方法），然后说发现了什么（结果），最后解释这些发现意味着什么（讨论）。结构清晰、逻辑严密，让读者和审稿人能快速定位关键信息。","steps":"[{\"name\": \"I - Introduction 引言\", \"description\": \"介绍研究背景、问题提出、研究意义、研究目标和论文结构安排\"}, {\"name\": \"M - Methods 方法\", \"description\": \"详细描述研究设计、数据来源、样本选择、分析方法和研究工具的选择依据\"}, {\"name\": \"R - Results 结果\", \"description\": \"客观呈现研究发现和数据分析结果，用图表配合文字说明，不加入主观解释\"}, {\"name\": \"D - Discussion 讨论\", \"description\": \"对结果进行解释和讨论，与已有文献对比，分析研究的理论和实践意义\"}, {\"name\": \"Conclusion 结论\", \"description\": \"总结核心发现、指出研究局限、提出未来研究方向和政策建议\"}]","itto":"{\"tools\": [\"文献检索工具\", \"统计分析软件\", \"论文写作规范\"], \"inputs\": [\"研究选题\", \"文献资料\", \"研究数据\", \"分析结果\"], \"outputs\": [\"完整学术论文\", \"期刊投稿\"]}","tools":"EndNote/Zotero 文献管理、SPSS/Stata/R 统计分析、Origin/Matplotlib 绘图、Grammarly 英文润色","cases":"经济学实证论文标准结构：引言（研究问题与贡献）→ 研究设计（模型设定+数据来源）→ 实证结果（基准回归+稳健性检验）→ 进一步讨论（机制分析+异质性分析）→ 结论与政策建议","viz_type":"process","viz_config":"{}","keywords":"IMRaD,学术论文,论文结构,引言方法结果讨论,学术通用","sort_order":101,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.411+08:00","_updated_by":"()","code":"RES-IMRAD-001","aliases":"IMRaD","summary":"IMRaD 是国际学术期刊最通用的论文结构：先说为什么做（引言），再说怎么做（方法），然后说发现了什么（结果），最后解释这些发现意味着什么（讨论）。结构清晰、逻","problem_statement":"论文写作不知如何组织结构，想到哪写到哪，逻辑混乱、读者读不懂，投稿被审稿人批评结构不清；IMRaD提供国际通用的四段式结构（引言-方法-结果-讨论），让研究故事按读者期待的顺序展开。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"实证研究类期刊论文、学位论文、会议论文的标准写作结构，尤其适用于理工科和社会科学实证研究","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"经济学实证论文标准结构：引言（研究问题与贡献）→ 研究设计（模型设定+数据来源）→ 实证结果（基准回归+稳健性检验）→ 进一步讨论（机制分析+异质性分析）→ 结论与政策建议","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"75f1cf49-8594-49c0-872f-0b1f310101b7","name":"ADDIE 教学设计模型","category":"教学科研","scene":"课程开发、培训设计、教育产品开发的场景","core_logic":"ADDIE是最经典的教学设计模型，包含五个阶段：分析(Analysis)学习需求和受众→设计(Design)课程目标和架构→开发(Development)教学内容和材料→实施(Implementation)开展教学→评估(Evaluation)效果并改进。是一个迭代循环的过程。","steps":"[{\"name\": \"分析：学习需求、受众、约束条件\", \"description\": \"\"}, {\"name\": \"设计：学习目标、课程结构、评估方式\", \"description\": \"\"}, {\"name\": \"开发：教学材料、活动、资源\", \"description\": \"\"}, {\"name\": \"实施：开展教学/培训\", \"description\": \"\"}, {\"name\": \"评估：效果评估与迭代改进\", \"description\": \"\"}]","itto":"{\"tools\": [\"教学设计方法、课程开发工具\"], \"inputs\": [\"培训需求、目标受众\"], \"outputs\": [\"课程产品、教学材料\"]}","tools":"教学设计、课程开发工具、学习管理系统LMS","cases":"分析→设计→开发→实施→评估。案例：开发了一门《软考高项冲刺》在线课程。","viz_type":"cycle","viz_config":"{}","keywords":"ADDIE,教学设计,课程开发,教学系统设计,培训开发","sort_order":1,"_created_at":"2026-09-15T18:34:26.486+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.419+08:00","_updated_by":"()","code":"TEACH-ADDIE-001","aliases":"ADDIE,教学设计,课程开发","summary":"分析—设计—开发—实施—评估的系统化教学设计模型","problem_statement":"教学设计凭经验拍脑袋，想到什么教什么，没有系统流程，教学质量不稳定、培训效果差；ADDIE通过分析-设计-开发-实施-评估五步系统化设计教学，让每一步都有依据、教学效果可衡量。","triggers":"ADDIE,教学设计,课程开发,教学系统设计","applicable":"课程开发、企业培训、在线教育、教学设计","not_applicable":"即兴分享、简单的知识传递","related_frameworks":"BOPPPS 课堂模型,OBE 成果导向教育,布鲁姆认知分类法","templates":"ADDIE课程开发模板","limitations":"线性模型不适合快速迭代；过程较复杂需要专业能力；耗时较长","mastery_level":"L3","last_used_date":null,"domain_code":"TEACH"},{"id":"768ac537-1613-45eb-8446-cc79a2c923a2","name":"力场分析","category":"思维方法","scene":"变革管理、决策评估、方案可行性分析的场景","core_logic":"勒温提出的力场分析认为，任何现状都是驱动力（推动变革的力量）和制约力（阻碍变革的力量）的平衡结果。通过识别和分析这两类力量，可以评估变革的可行性并找到增强驱动力或减弱制约力的杠杆点。","steps":"[{\"name\": \"明确变革目标和现状\", \"description\": \"\"}, {\"name\": \"列出所有驱动力（推动因素）\", \"description\": \"\"}, {\"name\": \"列出所有制约力（阻碍因素）\", \"description\": \"\"}, {\"name\": \"评估各力量的强弱\", \"description\": \"\"}, {\"name\": \"寻找增强驱动力或减弱制约力的策略\", \"description\": \"\"}]","itto":"{\"tools\": [\"头脑风暴、专家访谈\"], \"inputs\": [\"变革议题\"], \"outputs\": [\"力场图、变革策略\"]}","tools":"头脑风暴、鱼骨图、力场图","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"力场分析,变革管理,驱动力,制约力,勒温","sort_order":8,"_created_at":"2026-09-15T18:34:13.555+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.427+08:00","_updated_by":"()","code":"DEC-FRC-001","aliases":"力场分析,Force Field Analysis,勒温力场","summary":"分析推动和阻碍变革的力量，评估变革可行性的工具","problem_statement":"推动变革时只看动力不看阻力，或者只看到阻力不知道从哪突破，变革推动困难、成功率低；力场分析系统识别推动和阻碍变革的各种力量，评估变革可行性，找到突破阻力的关键着力点。","triggers":"力场分析,变革,驱动力,阻力,勒温","applicable":"组织变革、项目推动、流程改进、个人转变","not_applicable":"已经决定必须执行的事项、简单决策","related_frameworks":"系统思考,塔克曼团队发展模型,情境领导模型","templates":"力场分析图模板","limitations":"力量识别依赖参与者认知；力量强度评估有主观性；忽略力量间的相互作用","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"780073d5-4e42-4ec5-9d63-4a8c8d84a525","name":"康奈尔笔记法","category":"学习方法","scene":"课堂学习、培训听讲、读书学习、会议记录、知识内化的场景","core_logic":"康奈尔笔记法由康奈尔大学沃尔特·波克教授发明，将笔记本分为三个区域：右侧「笔记栏」（占2/3，上课/阅读时记录要点）、左侧「线索栏」（占1/3，课后提炼关键词、问题、要点）、底部「总结栏」（用一两句话概括整页内容）。配合5R步骤：记录(Record)→简化(Reduce)→背诵(Recite)→思考(Reflect)→复习(Review)，让笔记从单纯的记录变成主动学习和深度内化的工具。","steps":"[{\"name\": \"准备笔记纸\", \"description\": \"将页面分为三个区域：右侧70%为笔记栏、左侧30%为线索栏、底部约5-7行为总结栏\"}, {\"name\": \"记录(Record)\", \"description\": \"在笔记栏中尽可能详细地记录关键概念、要点、公式、例子等，使用自己的话\"}, {\"name\": \"简化(Reduce)\", \"description\": \"课后尽快将笔记栏中的要点提炼成关键词、问题或标题，写在左侧线索栏\"}, {\"name\": \"背诵(Recite)\", \"description\": \"遮住笔记栏，只看线索栏的关键词/问题，尝试用自己的话复述完整内容\"}, {\"name\": \"思考(Reflect)\", \"description\": \"在底部总结栏用自己的话概括整页内容的核心思想，思考「这对我意味着什么」\"}, {\"name\": \"复习(Review)\", \"description\": \"定期（先密后疏）复习笔记，每次花10-15分钟快速浏览并回忆\"}, {\"name\": \"补充和完善\", \"description\": \"复习时如有新的理解或疑问，补充到笔记中\"}, {\"name\": \"建立知识关联\", \"description\": \"将不同笔记之间建立联系，形成知识网络\"}]","itto":"{\"tools\": [\"康奈尔笔记模板、笔记本/GoodNotes/Notion、复习计划、主动回忆\"], \"inputs\": [\"学习内容、课堂/书籍/讲座信息、笔记本/电子笔记工具\"], \"outputs\": [\"结构化的笔记、深度理解的知识、长期记忆、学习效率提升\"]}","tools":"康奈尔笔记纸、GoodNotes/Notability、Notion、Anki(配合间隔重复)","cases":"康奈尔大学学生广泛使用、美国高中和大学推荐学习方法、高效学习法标配","viz_type":"hierarchy","viz_config":"{}","keywords":"康奈尔笔记,Cornell Notes,5R笔记法,学习方法,笔记方法,知识内化","sort_order":112,"_created_at":"2026-09-16T16:20:51.108+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.434+08:00","_updated_by":"()","code":"LEARN-CORNELL-001","aliases":"康奈尔笔记,Cornell Notes,5R笔记法,康奈尔大学笔记法","summary":"记录-简化-背诵-思考-复习五步笔记法，左右分区+底部总结，结构化吸收知识","problem_statement":"做笔记就是抄书划线，事后看不懂也不会用，笔记记了一大堆但没转化为自己的知识；康奈尔笔记法通过左右分区+底部总结的结构，配合记录-简化-背诵-思考-复习五步，让知识结构化、记得牢、用得上。","triggers":"康奈尔笔记,Cornell Notes,5R笔记法,笔记方法,学习方法,知识内化","applicable":"学生课堂学习、职业培训、读书学习、会议记录、讲座/演讲笔记、系统性知识学习","not_applicable":"创意发散类笔记（思维导图更适合）、简单速记场景、图解类内容","related_frameworks":"费曼学习法,间隔重复,主动回忆,思维导图,PQ4R学习法","templates":"康奈尔笔记模板(打印版/电子版)、5R笔记步骤卡、复习计划表","limitations":"准备笔记格式需要时间；不适合需要画图或复杂结构的内容；需要课后投入时间整理和复习；对纯创意类内容可能过于结构化","mastery_level":"L2","last_used_date":null,"domain_code":"LEARN"},{"id":"78842b72-6afd-49c2-90f7-4eafdddc0581","name":"三螺旋模型","category":"科研写作","scene":"产学研合作研究、协同创新研究、科技政策研究、区域创新系统论文","core_logic":"亨利·埃茨科威茨提出的三螺旋（Triple Helix）理论认为，在知识经济时代，大学、产业、政府三者不再是各自独立的线性关系，而是形成相互缠绕、边界渗透、协同演化的三重螺旋关系。大学不只做研究、产业不只做产品、政府不只做管理，三者在创新中互相交叉融合。","steps":"[{\"name\": \"大学 University\", \"description\": \"知识生产和人才培养的主体，提供基础研究成果和高素质人力资源\"}, {\"name\": \"产业 Industry\", \"description\": \"技术创新和市场应用的主体，将知识转化为产品和服务，创造经济价值\"}, {\"name\": \"政府 Government\", \"description\": \"制度设计和公共服务的主体，提供政策支持、基础设施和制度环境\"}, {\"name\": \"三重螺旋互动\", \"description\": \"三者边界模糊化，相互渗透、协同创新，形成螺旋上升的动态关系\"}, {\"name\": \"混合型组织\", \"description\": \"互动中产生的新型组织形态，如大学科技园、企业研究院、官产学研联盟等\"}]","itto":"{\"tools\": [\"三螺旋理论\", \"协同创新分析\", \"案例研究\", \"专利合作分析\"], \"inputs\": [\"大学研究成果\", \"产业创新需求\", \"政府政策资源\"], \"outputs\": [\"产学研协同创新研究报告\", \"政策建议\"]}","tools":"三螺旋测度（三螺旋算法、专利共类）、社会网络分析、案例研究、产学研合作强度","cases":"硅谷的成功是三螺旋的典范：斯坦福大学（知识源头+技术转化）+ 科技企业（惠普、英特尔、Google等产业创新）+ 美国政府（DARPA/NSF科研资助+移民政策+反垄断），三者互动形成充满活力的创新生态。","viz_type":"cycle","viz_config":"{}","keywords":"三螺旋,产学研,协同创新,大学产业政府,Etzkowitz,战略产业","sort_order":129,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.442+08:00","_updated_by":"()","code":"DEC-IND-008","aliases":"三螺旋","summary":"亨利·埃茨科威茨提出的三螺旋（Triple Helix）理论认为，在知识经济时代，大学、产业、政府三者不再是各自独立的线性关系，而是形成相互缠绕、边界渗透、协同","problem_statement":"研究创新只看企业或大学单一主体，解释不了为什么有些区域产学研协同效果好而有些则各自为政、创新效率低；三螺旋模型揭示大学、产业、政府三者相互缠绕、边界渗透、协同创新的互动机制。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"产学研合作研究、协同创新研究、科技政策研究、区域创新系统论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"硅谷的成功是三螺旋的典范：斯坦福大学（知识源头+技术转化）+ 科技企业（惠普、英特尔、Google等产业创新）+ 美国政府（DARPA/NSF科研资助+移民政策+反垄断），三者互动形成充满活力的创新生","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"7a5fa233-9681-4fbf-a1ce-457fd8070efe","name":"概率思维","category":"思维模型","scene":"不确定性决策、风险评估、投资判断、预测未来、生活各领域的场景","core_logic":"概率思维是应对不确定性的核心思维方式：世界上绝大多数事情都不是确定的，而是以某种概率发生。概率思维要求我们放弃非黑即白的二元思维，学会用「可能性程度」来思考——给不同结果赋予不同的概率权重，根据期望值做决策，并根据新信息不断更新概率判断。拥有概率思维的人不会追求绝对正确，而是追求长期胜率。","steps":"[{\"name\": \"识别不确定性\", \"description\": \"意识到问题存在多种可能的结果，放弃确定性幻想\"}, {\"name\": \"列出可能的结果\", \"description\": \"尽可能完整地列出所有可能的结果和场景\"}, {\"name\": \"估计各结果的概率\", \"description\": \"基于历史数据、逻辑分析或经验，给每种结果赋予概率\"}, {\"name\": \"评估各结果的影响\", \"description\": \"每种结果发生的话，收益或损失有多大？\"}, {\"name\": \"计算期望值\", \"description\": \"用概率×收益计算期望值，作为决策依据\"}, {\"name\": \"考虑极端情况\", \"description\": \"特别关注小概率但影响极大的黑天鹅事件\"}, {\"name\": \"做出概率化决策\", \"description\": \"根据概率和期望值选择方案，接受可能出错的可能性\"}, {\"name\": \"根据新信息更新概率\", \"description\": \"持续收集信息，用贝叶斯思维调整概率判断\"}]","itto":"{\"tools\": [\"概率论、贝叶斯定理、期望值计算、蒙特卡洛模拟、决策树\"], \"inputs\": [\"历史数据、相关信息、领域知识、逻辑分析能力\"], \"outputs\": [\"概率化判断、期望值决策、风险评估、置信度区间\"]}","tools":"概率论、贝叶斯定理、期望值法、蒙特卡洛模拟、决策树分析","cases":"扑克牌决策、投资组合管理、保险精算、天气预报、医疗诊断概率","viz_type":"chart","viz_config":"{}","keywords":"概率思维,不确定性,赔率,期望值,风险,贝叶斯","sort_order":82,"_created_at":"2026-09-16T16:20:50.928+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.45+08:00","_updated_by":"()","code":"META-PROBABILITY-001","aliases":"概率思考,概率思维,Probabilistic Thinking,不确定思维,赔率思维","summary":"用概率而非确定性的方式思考问题和机会，始终考虑多种可能性及其权重","problem_statement":"思考问题非黑即白，总想要确定性答案，遇到不确定性就焦虑，决策容易走极端、承受不了波动；概率思维用概率而非确定性的方式思考，始终考虑多种可能性及其权重，理性面对不确定性。","triggers":"概率思维,不确定性,赔率,胜率,可能,风险,概率,贝叶斯","applicable":"投资决策、风险管理、人生选择、商业判断、体育博彩、天气预报、医疗决策","not_applicable":"完全确定性的问题、纯逻辑推导、道德原则判断、紧急情况下的直觉决策","related_frameworks":"贝叶斯思维,期望值决策,蒙特卡洛模拟,风险矩阵,凯利公式","templates":"概率判断记录模板、期望值计算表、决策复盘表","limitations":"概率估计常受认知偏差影响；需要较好的数学和统计基础；过度依赖概率可能忽视质变和极端事件；人的直觉概率判断经常出错","mastery_level":"L2","last_used_date":null,"domain_code":"META"},{"id":"7b4a2600-53ac-4082-bfe1-5ded64718909","name":"WBS 工作分解结构","category":"项目管理","scene":"项目范围管理、任务拆解与分配、进度计划制定、成本估算、项目风险管理。","core_logic":"将项目总目标逐层向下分解：从项目最终交付物分解为阶段/可交付成果，再分解为工作包，最后到具体活动。分解遵循「100% 原则」（全部工作都要被分解到）和「80 小时法则」（每个工作包不超过 80 小时工作量），确保项目没有遗漏的工作。","steps":"[]","itto":"{\"tools\": [\"头脑风暴\", \"类比法\", \"自上而下分解\"], \"inputs\": [\"项目范围说明书\", \"项目章程\"], \"outputs\": [\"WBS字典\", \"范围基准\"]}","tools":"Project/飞书项目、Xmind 分解、Trello 看板、甘特图","cases":"某 SaaS 产品开发项目用 WBS 分解：将「上线客户管理系统」分解为需求调研、系统设计、前后端开发、测试、上线 5 大阶段，每个阶段再拆 5-8 个工作包，共 37 个工作包，每个工作包不超过 5 天，确保项目范围 100% 覆盖、进度可追踪。","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"项目总目标\", \"description\": \"项目最终交付成果和目标\"}, {\"name\": \"阶段/可交付成果\", \"items\": [\"阶段一：需求分析与设计\", \"阶段二：开发与实现\", \"阶段三：测试与验收\"]}, {\"name\": \"工作包\", \"items\": [\"需求调研\", \"系统设计\", \"数据库设计\", \"前端开发\", \"后端开发\", \"单元测试\", \"集成测试\", \"UAT测试\"]}, {\"name\": \"具体活动\", \"items\": [\"访谈用户\", \"撰写需求文档\", \"评审\", \"编码\", \"调试\", \"...\"]}]}","keywords":"WBS,工作分解,范围管理","sort_order":8,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.457+08:00","_updated_by":"()","code":"PM-SCP-001","aliases":"WBS","summary":"将项目总目标逐层向下分解：从项目最终交付物分解为阶段/可交付成果，再分解为工作包，最后到具体活动。分解遵循「100% 原则」（全部工作都要被分解到）和「80 小","problem_statement":"项目目标大而空，不知道从何下手，任务边界模糊，责任不清，最后交付物漏东漏西；WBS将项目逐层分解到可管理的工作包，遵循100%原则确保不重不漏，让每个任务都有明确的交付物和负责人。","triggers":"项目延期、进度失控、范围蔓延、资源不足","applicable":"项目范围管理、任务拆解与分配、进度计划制定、成本估算、项目风险管理。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某 SaaS 产品开发项目用 WBS 分解：将「上线客户管理系统」分解为需求调研、系统设计、前后端开发、测试、上线 5 大阶段，每个阶段再拆 5-8 个工作包，共 37 个工作包，每个工作包不超过 5","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"81604019-5e55-4a31-b79c-798eaf365486","name":"QBR 季度业务回顾","category":"客户交付","scene":"大客户管理、客户成功、长期合作关系维护的场景","core_logic":"QBR是客户成功管理的核心机制，每季度与客户关键决策层进行业务回顾会议，汇报过去一季度的交付成果、业务价值和数据指标，讨论下季度目标和计划，建立战略层面的信任和合作关系。","steps":"[{\"name\": \"收集本季度交付数据和成果\", \"description\": \"\"}, {\"name\": \"梳理业务价值和ROI\", \"description\": \"\"}, {\"name\": \"准备QBR汇报材料\", \"description\": \"\"}, {\"name\": \"与客户召开季度回顾会\", \"description\": \"\"}, {\"name\": \"记录行动计划和下季度目标\", \"description\": \"\"}, {\"name\": \"跟踪落地执行\", \"description\": \"\"}]","itto":"{\"tools\": [\"数据分析、汇报材料\"], \"inputs\": [\"客户数据、交付成果\"], \"outputs\": [\"QBR报告、行动计划、客户关系强化\"]}","tools":"数据分析、PPT、客户成功平台、CRM","cases":"需补充","viz_type":"cycle","viz_config":"{}","keywords":"QBR,季度业务回顾,客户成功,战略沟通,客户价值","sort_order":3,"_created_at":"2026-09-15T18:34:20.128+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.465+08:00","_updated_by":"()","code":"CUST-QBR-001","aliases":"QBR,季度业务回顾,Quarterly Business Review","summary":"每季度与客户回顾业务价值、对齐目标的战略沟通机制","problem_statement":"与客户合作只有项目执行没有战略对齐，客户只看单价不看价值，合作关系停留在买卖层面难以深化；QBR每季度与客户回顾业务价值、对齐未来目标，将合作从执行层面提升到战略层面，深化客户关系。","triggers":"QBR,季度回顾,客户成功,战略沟通,客户价值","applicable":"大客户管理、SaaS客户成功、长期服务合作、战略客户维护","not_applicable":"一次性交易客户、小客户","related_frameworks":"SLA 服务级别协议,客户满意度管理,NPS 净推荐值","templates":"QBR汇报模板","limitations":"需要客户高层参与配合；准备工作耗时；没有实质价值会变成走过场","mastery_level":"L3","last_used_date":null,"domain_code":"CUST"},{"id":"833dfe72-2a5e-45af-b71f-9c0f1dc235e4","name":"利益相关者分析","category":"科研写作","scene":"公共政策分析、项目评估、社区治理、企业社会责任、参与式研究","core_logic":"利益相关者分析（Stakeholder Analysis）系统识别和分析所有受项目/政策影响或能影响项目/政策的个人和群体，评估他们的利益、权力、态度和相互关系，据此制定差异化的参与和沟通策略。是应用研究和政策研究中不可或缺的分析工具。","steps":"[]","itto":"{\"tools\": [\"利益相关者地图\", \"权力利益矩阵\", \"米切尔评分法\", \"访谈法\"], \"inputs\": [\"利益相关者名单\", \"项目/政策信息\", \"权力利益评估\"], \"outputs\": [\"利益相关者分析报告\", \"参与策略\"]}","tools":"利益相关者地图、权力/利益矩阵、米切尔评分法（权力+合法性+紧迫性）、利益相关者访谈","cases":"城市更新项目利益相关者分析：识别出政府、开发商、原居民、商户、周边社区等10类利益相关者，用权力-利益矩阵分类，对高权高益的（政府、开发商、原居民）重点参与协商，对低权高益的（商户、周边社区）及时告知。","viz_type":"matrix","viz_config":"{\"quadrants\": [{\"name\": \"关键利益相关者\", \"items\": [\"决策者\", \"主要受益者\", \"核心执行者\"], \"description\": \"权力高+利益高，重点关注和参与\"}, {\"name\": \"利益相关者角色\", \"items\": [\"支持者\", \"反对者\", \"中立者\", \"关键盟友\"], \"description\": \"区分不同利益相关者的态度和立场\"}, {\"name\": \"权力/利益矩阵\", \"items\": [\"高权力高利益：密切参与\", \"高权力低利益：保持满意\", \"低权力高利益：及时告知\", \"低权力低利益：最小关注\"], \"description\": \"米切尔评分法和权力/利益矩阵\"}], \"xAxisLabel\": \"利益相关者分类与管理策略\", \"yAxisLabel\": \"\"}","keywords":"利益相关者,stakeholder,米切尔,权力利益矩阵,参与式治理,管理社科","sort_order":132,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.473+08:00","_updated_by":"()","code":"DEC-STA-001","aliases":"利益相关者","summary":"利益相关者分析（Stakeholder Analysis）系统识别和分析所有受项目/政策影响或能影响项目/政策的个人和群体，评估他们的利益、权力、态度和相互关系","problem_statement":"做项目或政策只考虑主要决策者，忽视其他受影响群体的利益和诉求，实施阻力大、社会接受度低、容易失败；利益相关者分析系统识别所有受影响和能施加影响的个人与群体，评估其利益、权力和态度。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"公共政策分析、项目评估、社区治理、企业社会责任、参与式研究","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"城市更新项目利益相关者分析：识别出政府、开发商、原居民、商户、周边社区等10类利益相关者，用权力-利益矩阵分类，对高权高益的（政府、开发商、原居民）重点参与协商，对低权高益的（商户、周边社区）及时告知","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"83f6b210-f162-4a63-8be3-bbb6c0d2ec1a","name":"授权与分工","category":"团队管理","scene":"管理者能力提升、团队扩张、员工发展的场景","core_logic":"授权不是简单的分派任务，而是根据任务性质和员工能力，赋予相应的决策权和资源，同时保持适度的支持和监督。有效授权能解放管理者、发展员工、提升团队整体能力。","steps":"[{\"name\": \"评估任务的性质和风险\", \"description\": \"\"}, {\"name\": \"评估员工的能力和意愿\", \"description\": \"\"}, {\"name\": \"选择合适的授权程度\", \"description\": \"\"}, {\"name\": \"明确任务目标和边界\", \"description\": \"\"}, {\"name\": \"提供支持和资源\", \"description\": \"\"}, {\"name\": \"建立反馈和监督机制\", \"description\": \"\"}]","itto":"{\"tools\": [\"情境领导、GROW教练\"], \"inputs\": [\"任务清单、团队成员能力评估\"], \"outputs\": [\"授权清单、员工成长\"]}","tools":"情境领导、RACI、GROW教练、反馈技巧","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"授权,分工,赋能,员工发展,团队管理","sort_order":8,"_created_at":"2026-09-15T18:34:20.101+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.481+08:00","_updated_by":"()","code":"TEAM-EMP-001","aliases":"授权,分工,Empowerment,Delegation","summary":"通过合理授权和分工激发团队能力、提升整体效能的管理实践","problem_statement":"管理者事必躬亲累死自己，团队成员没事干也没成长，组织能力全靠个人撑着，规模一大就崩溃、效率低下；合理授权与分工通过科学分配任务和权力，激发团队潜能、培养下属能力，让组织效能规模化提升。","triggers":"授权,分工,赋能,员工发展,管理者","applicable":"管理者能力提升、团队扩张、员工发展、组织规模化","not_applicable":"极高风险的决策、必须管理者亲自做的事项","related_frameworks":"情境领导模型,RACI 职责矩阵,GROW 教练模型","templates":"授权程度评估表","limitations":"授权不当会失控；需要管理者的信任和放手意愿；需要过程中的支持和纠偏","mastery_level":"L2","last_used_date":null,"domain_code":"TEAM"},{"id":"840cf74f-26fe-41b0-810f-8280163f61c0","name":"风险矩阵","category":"风险分析","scene":"项目风险评估、企业风险管理、安全风险评估等场景","core_logic":"将每个风险事件按发生概率（横轴）和影响程度（纵轴）放入二维矩阵中，形成不同等级的风险区域（红黄绿区），帮助快速识别高优先级风险并制定相应的应对策略。","steps":"[{\"name\": \"识别所有潜在风险\", \"description\": \"\"}, {\"name\": \"评估每个风险的发生概率\", \"description\": \"\"}, {\"name\": \"评估每个风险的影响程度\", \"description\": \"\"}, {\"name\": \"将风险定位到矩阵中\", \"description\": \"\"}, {\"name\": \"按优先级制定应对措施\", \"description\": \"\"}]","itto":"{\"tools\": [\"概率影响评估表\"], \"inputs\": [\"风险清单\"], \"outputs\": [\"风险等级排序、应对策略\"]}","tools":"风险登记册、德尔菲法、历史数据分析","cases":"某客户交付项目用风险矩阵评估15个风险：按发生概率(高/中/低)和影响程度(高/中/低)定位到4个高风险(关键人员离职、需求变更、技术难点、供应商延期)，针对性制定应对策略。","viz_type":"matrix","viz_config":"{\"x_label\": \"发生概率\", \"y_label\": \"影响程度\", \"quadrants\": {\"q1\": \"高概率高影响（红区）\", \"q2\": \"低概率高影响（黄区）\", \"q3\": \"低概率低影响（绿区）\", \"q4\": \"高概率低影响（黄区）\"}}","keywords":"风险矩阵,风险评估,概率影响,风险分级,风险管理","sort_order":7,"_created_at":"2026-09-15T18:34:13.545+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.489+08:00","_updated_by":"()","code":"DEC-RSK-001","aliases":"风险矩阵,风险评估矩阵,Probability-Impact Matrix","summary":"按概率和影响两个维度评估风险等级的可视化工具","problem_statement":"风险识别了一大堆但不知道哪个最该优先处理，眉毛胡子一把抓，资源分散、重大风险没管好；风险矩阵按概率和影响两个维度评估风险等级，让你快速识别高优先级风险、集中资源处理最重要的。","triggers":"风险矩阵,风险评估,概率,影响,优先级","applicable":"项目风险管理、企业运营风险、信息安全、职业健康安全","not_applicable":"单一重大风险的深度分析、无法估计概率的全新风险","related_frameworks":"风险登记册,风险应对四大策略,决策树","templates":"风险矩阵评估模板","limitations":"概率和影响评估有主观性；二维简化可能忽略风险间的关联性；适合初步评估","mastery_level":"L3","last_used_date":null,"domain_code":"DECIDE"},{"id":"858ea065-68b7-40a8-bb2c-9648b1e6bb71","name":"AHP 层次分析法","category":"思维方法","scene":"复杂多准则决策、战略选择、资源分配等重大决策场景","core_logic":"将决策问题分解为目标层、准则层、方案层的递阶层次结构，通过两两比较确定各要素的相对权重，计算一致性比率检验判断是否合理，最终得出方案排序。","steps":"[{\"name\": \"建立递阶层次结构模型\", \"description\": \"\"}, {\"name\": \"构造两两比较判断矩阵\", \"description\": \"\"}, {\"name\": \"计算各层要素权重\", \"description\": \"\"}, {\"name\": \"一致性检验\", \"description\": \"\"}, {\"name\": \"计算方案层总排序\", \"description\": \"\"}]","itto":"{\"tools\": [\"判断矩阵、特征向量计算\"], \"inputs\": [\"决策问题、备选方案\"], \"outputs\": [\"权重排序、决策建议\"]}","tools":"判断矩阵、特征值法、Expert Choice软件","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"AHP,层次分析法,多准则决策,权重,两两比较","sort_order":19,"_created_at":"2026-09-15T18:34:03.204+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.497+08:00","_updated_by":"()","code":"META-THK-011","aliases":"AHP,层次分析法,Analytic Hierarchy Process","summary":"将复杂决策分解为层次结构，通过两两比较确定权重的决策方法","problem_statement":"复杂决策因素太多、权重难定，拍脑袋又怕不准，决策过程说不清楚、说服不了别人；AHP将复杂决策分解为层次结构，通过两两比较科学确定各因素权重，让决策过程透明、结果可靠。","triggers":"AHP,层次分析,权重,决策,多准则","applicable":"战略决策、项目优先级排序、供应商评估、资源分配","not_applicable":"简单快速决策、要素无法明确分层的场景","related_frameworks":"决策矩阵,多准则决策 MCDA,成本效益分析","templates":"AHP层次分析模板","limitations":"两两比较工作量大；判断矩阵主观性强；层级数量受限","mastery_level":"L2","last_used_date":null,"domain_code":"META"},{"id":"85b0a05b-47a2-468a-9bdc-f8dd52ee5fee","name":"多案例研究","category":"科研写作","scene":"理论建构型研究、管理研究、比较研究、需要提高外部效度的质性研究论文","core_logic":"多案例研究通过对多个案例的比较分析，提高研究结论的外部效度和理论稳健性。与单案例的探索性不同，多案例研究更适合理论建构——通过\"逐项复制\"（得到相同结果）和\"差别复制\"（得到可预测的不同结果）的逻辑，在反复验证中打磨理论。Eisenhardt 方法是经典的多案例研究范式。","steps":"[{\"name\": \"案例选择\", \"description\": \"按复制逻辑（replication logic）选择4-6个案例，包括正面案例和反面案例，而非统计抽样\"}, {\"name\": \"单案例内分析\", \"description\": \"对每个案例分别进行深入分析，写出单案例报告，形成各自的发现\"}, {\"name\": \"跨案例分析\", \"description\": \"将各案例进行横向比较，寻找共性模式和差异原因，验证或修正理论命题\"}, {\"name\": \"理论建构\", \"description\": \"基于跨案例比较结果，归纳构建理论框架，确保理论与数据契合\"}, {\"name\": \"结论与边界\", \"description\": \"总结研究结论，明确理论适用范围和边界条件\"}]","itto":"{\"tools\": [\"多案例研究法\", \"复制逻辑\", \"跨案例分析\", \"Eisenhardt方法\"], \"inputs\": [\"研究问题\", \"多案例样本\", \"多源数据\"], \"outputs\": [\"多案例研究论文\", \"理论框架\", \"可推广发现\"]}","tools":"Eisenhardt多案例方法、复制逻辑、跨案例比较表格、模式匹配","cases":"企业数字化转型路径研究：选择4-6个不同行业、不同规模的企业作为多案例样本，逐个分析它们的数字化转型路径，然后通过跨案例比较归纳出\"技术驱动型\"\"业务牵引型\"\"平台生态型\"等典型转型模式。","viz_type":"process","viz_config":"{}","keywords":"多案例研究,跨案例比较,复制逻辑,Eisenhardt,案例研究,案例比较","sort_order":152,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.505+08:00","_updated_by":"()","code":"RES-033","aliases":"多案例研究","summary":"多案例研究通过对多个案例的比较分析，提高研究结论的外部效度和理论稳健性。与单案例的探索性不同，多案例研究更适合理论建构——通过\"逐项复制\"（得到相同结果）和\"差","problem_statement":"单案例研究结论推广性有限，想提升研究的外部效度和理论稳健性但不知道多案例该怎么设计和分析；多案例研究通过逐项复制和差别复制的逻辑，系统比较多个案例以提升结论的稳健性和理论建构力。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"理论建构型研究、管理研究、比较研究、需要提高外部效度的质性研究论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"企业数字化转型路径研究：选择4-6个不同行业、不同规模的企业作为多案例样本，逐个分析它们的数字化转型路径，然后通过跨案例比较归纳出\"技术驱动型\"\"业务牵引型\"\"平台生态型\"等典型转型模式。","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"8a0a4cdb-9509-4b27-bcc0-7d375829681d","name":"混合方法研究","category":"科研写作","scene":"复杂社会科学研究、教育研究、管理研究、需要深入且系统验证的研究论文","core_logic":"混合方法研究（Mixed Methods Research）是继定量研究、质性研究之后的\"第三种研究范式\"。它不是简单地把两种方法堆在一起，而是有系统的设计逻辑（序列/并行、主次关系），核心是\"三角验证\"——用不同方法研究同一个问题，结果互相印证或互补，从而获得更全面、更可靠的结论。","steps":"[]","itto":"{\"tools\": [\"混合方法研究设计\", \"问卷+访谈\", \"量化+质性分析\", \"三角验证\"], \"inputs\": [\"研究问题\", \"混合方法设计\", \"数据收集资源\"], \"outputs\": [\"混合方法研究论文\", \"多层次证据\"]}","tools":"解释性/探索性/收敛设计、QUAN/qual或QUAL/quan的主次标注、联合展示（joint display）","cases":"企业数字化转型影响因素研究：先用大样本问卷做量化分析（找到主要影响因素），再选取典型企业做深度案例访谈（解释为什么这些因素重要、具体机制是什么），这是解释性序列混合方法设计——先量后质，用量化结果指导质性深化。","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"定性 + 定量 结合\", \"description\": \"混合方法（Mixed Methods）同时使用质性和定量方法，发挥各自优势，互相补充验证\"}, {\"name\": \"三大设计类型\", \"items\": [\"解释性序列设计（Explanatory）：先定量后定性，用量化结果指导质性深入\", \"探索性序列设计（Exploratory）：先定性后定量，从质性发现发展量化工具\", \"收敛并行设计（Convergent）：定量和定性同时进行，结果互相对照验证\"]}, {\"name\": \"优势\", \"items\": [\"三角验证，提高效度\", \"更全面深入地回答研究问题\", \"适合复杂研究问题\", \"可探索也可验证\"]}]}","keywords":"混合方法,Mixed Methods,三角验证,质性+定量,研究方法,管理社科","sort_order":142,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.513+08:00","_updated_by":"()","code":"RES-031","aliases":"混合方法","summary":"混合方法研究（Mixed Methods Research）是继定量研究、质性研究之后的\"第三种研究范式\"。它不是简单地把两种方法堆在一起，而是有系统的设计逻辑","problem_statement":"定量研究和质性研究各走各的，要么只做量化缺深度、要么只做质性缺广度，研究方法单一、结论片面不可靠；混合方法研究系统整合定量和质性两种方法的优势，用设计逻辑确保两种方法真正互补，提升研究的全面性和说服力。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"复杂社会科学研究、教育研究、管理研究、需要深入且系统验证的研究论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"企业数字化转型影响因素研究：先用大样本问卷做量化分析（找到主要影响因素），再选取典型企业做深度案例访谈（解释为什么这些因素重要、具体机制是什么），这是解释性序列混合方法设计——先量后质，用量化结果指导","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"8ab0f3f6-47e7-4225-8744-8c15a06d18e6","name":"SCAMPER 法","category":"思维方法","scene":"产品改进、服务创新、流程优化的创意激发场景","core_logic":"从替代(Substitute)、组合(Combine)、调整(Adapt)、修改(Modify)、其他用途(Put to other uses)、消除(Eliminate)、反向/重排(Reverse/Rearrange)七个维度对现有事物进行系统性提问，激发改进和创新的思路。","steps":"[{\"name\": \"明确要改进的对象\", \"description\": \"\"}, {\"name\": \"按S-C-A-M-P-E-R顺序逐维提问\", \"description\": \"\"}, {\"name\": \"记录每个维度的创意想法\", \"description\": \"\"}, {\"name\": \"筛选有价值的想法\", \"description\": \"\"}, {\"name\": \"组合并完善方案\", \"description\": \"\"}]","itto":"{\"tools\": [\"SCAMPER提问清单\"], \"inputs\": [\"待改进的产品/服务/流程\"], \"outputs\": [\"创意方案清单\"]}","tools":"头脑风暴、思维导图、SCAMPER检查清单","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"SCAMPER,奔驰法,创意激发,创新,头脑风暴","sort_order":16,"_created_at":"2026-09-15T18:34:03.163+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.52+08:00","_updated_by":"()","code":"META-THK-008","aliases":"SCAMPER,奔驰法","summary":"通过7个维度的提问激发创意的结构化创新工具","problem_statement":"想创意全靠灵光一现，没有方法可循，想不出来就干着急，创新效率低、质量不稳定；SCAMPER通过替代、组合、调整、修改、其他用途、消除、重组七个维度的结构化提问，系统激发创意。","triggers":"创意,创新,改进,发散,头脑风暴","applicable":"产品迭代、服务设计、流程优化、商业模式创新","not_applicable":"需要深度分析的复杂战略问题","related_frameworks":"头脑风暴法,设计思维,TRIZ 理论","templates":"SCAMPER创意激发表","limitations":"生成的创意较为发散，需要后续筛选和深化；适合创意激发而非深度分析","mastery_level":"L2","last_used_date":null,"domain_code":"META"},{"id":"8b6c1399-9733-440d-b597-70cb4f180b29","name":"风险登记册","category":"项目管理","scene":"项目风险管理全流程的记录和跟踪工具","core_logic":"风险登记册是风险管理的核心工具，系统记录每个风险的编号、描述、类别、概率、影响、等级、责任人、应对措施、状态等信息，实现风险的全生命周期管理。","steps":"[{\"name\": \"识别风险并录入登记册\", \"description\": \"\"}, {\"name\": \"分析风险的概率和影响\", \"description\": \"\"}, {\"name\": \"确定风险等级和优先级\", \"description\": \"\"}, {\"name\": \"制定应对措施和责任人\", \"description\": \"\"}, {\"name\": \"定期跟踪风险状态\", \"description\": \"\"}, {\"name\": \"关闭已解决的风险\", \"description\": \"\"}]","itto":"{\"tools\": [\"风险矩阵、专家判断\"], \"inputs\": [\"风险识别清单\"], \"outputs\": [\"风险清单、应对计划、状态报告\"]}","tools":"风险矩阵、概率影响评估、SWOT分析、专家判断","cases":"某客户交付项目，识别出\"关键人员离职\"风险，提前做了备份。","viz_type":"process","viz_config":"{}","keywords":"风险登记册,风险管理,风险跟踪,风险应对,项目风险","sort_order":13,"_created_at":"2026-09-15T18:34:13.608+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.528+08:00","_updated_by":"()","code":"PM-RSK-002","aliases":"风险登记册,风险注册表,Risk Register","summary":"记录所有项目风险及其分析、应对和监控信息的核心文档","problem_statement":"项目风险想到哪算哪，出了事才临时抱佛脚，风险没有记录、没有责任人、没有应对措施；风险登记册系统记录所有风险及其概率、影响、应对策略和责任人，让风险管理有据可依、有迹可循。","triggers":"风险登记册,风险管理,风险跟踪,风险应对","applicable":"各类项目风险管理、企业风险管理体系建设","not_applicable":"简单低风险的小型项目","related_frameworks":"风险矩阵,风险应对四大策略,风险意识","templates":"风险登记册模板（Excel）","limitations":"需要定期维护更新；风险描述的质量决定效果；容易变成形式主义","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"8b92269e-912d-407d-aeba-51ce0c0e115a","name":"渐进式总结","category":"知识管理","scene":"读书笔记、文章笔记、知识提炼的场景","core_logic":"渐进式总结由Tiago Forte提出，核心是分层加工笔记：第0层原文→第1层高亮重点→第2层加粗精华→第3层写摘要→第4层 Remix 重组应用。每一层都是在前一层基础上的浓缩，时间投入与价值成正比。","steps":"[{\"name\": \"第0层：保存原文/原始笔记\", \"description\": \"\"}, {\"name\": \"第1层：高亮重要段落\", \"description\": \"\"}, {\"name\": \"第2层：在高亮中加粗精华句\", \"description\": \"\"}, {\"name\": \"第3层：在顶部写自己的摘要\", \"description\": \"\"}, {\"name\": \"第4层：Remix，应用到自己的项目中\", \"description\": \"\"}]","itto":"{\"tools\": [\"高亮、加粗、摘要\"], \"inputs\": [\"原始笔记/文章\"], \"outputs\": [\"多层浓缩的精华笔记\"]}","tools":"笔记软件、高亮工具、反向链接","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"渐进式总结,分层笔记,知识提炼,Progressive Summarization","sort_order":5,"_created_at":"2026-09-15T18:34:26.611+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.536+08:00","_updated_by":"()","code":"KNOW-PRGS-001","aliases":"渐进式总结,Progressive Summarization,分层笔记","summary":"通过多层加粗逐步浓缩笔记精华的加工方法","problem_statement":"笔记越积越多，回头看还要重新读一遍，时间成本极高，精华内容淹没在大量文字里；渐进式总结通过多层加粗逐步浓缩笔记精华，让你从摘要到原文按需取用，大幅提升笔记复用效率。","triggers":"渐进式总结,分层笔记,笔记提炼,Progressive Summarization","applicable":"读书笔记、文章笔记、知识管理、学习加工","not_applicable":"结构化数据、不需要重读的临时笔记","related_frameworks":"CODE 知识加工,卡片盒笔记法（Zettelkasten）,PARA 分类法","templates":"渐进式总结示例模板","limitations":"需要多次阅读加工；需要工具支持多层标记；加工程度把握需要经验","mastery_level":"L2","last_used_date":null,"domain_code":"KNOW"},{"id":"8c4377d9-fb8f-471c-b486-7faf891cf399","name":"TOGAF 企业架构","category":"系统架构","scene":"企业级架构规划、数字化转型、IT战略对齐的场景","core_logic":"TOGAF是The Open Group推出的企业架构框架，核心是ADM（架构开发方法）：通过预备阶段→业务架构→信息系统架构→技术架构→机会解决方案→迁移规划→实施治理→架构变更管理的循环过程，系统化建设企业架构。","steps":"[{\"name\": \"预备阶段：建立架构能力\", \"description\": \"\"}, {\"name\": \"A 愿景阶段：定义架构愿景\", \"description\": \"\"}, {\"name\": \"B 业务架构\", \"description\": \"\"}, {\"name\": \"C 信息系统架构(数据+应用)\", \"description\": \"\"}, {\"name\": \"D 技术架构\", \"description\": \"\"}, {\"name\": \"E 机会与解决方案\", \"description\": \"\"}, {\"name\": \"F 迁移规划\", \"description\": \"\"}, {\"name\": \"G 实施治理\", \"description\": \"\"}, {\"name\": \"H 架构变更管理\", \"description\": \"\"}]","itto":"{\"tools\": [\"ADM方法、架构框架\"], \"inputs\": [\"企业战略、业务需求\"], \"outputs\": [\"企业架构蓝图、实施路线图\"]}","tools":"Archimate、EA工具、架构仓库、业务流程建模","cases":"需补充","viz_type":"cycle","viz_config":"{}","keywords":"TOGAF,企业架构,ADM,架构规划,数字化转型","sort_order":1,"_created_at":"2026-09-15T18:34:26.416+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.544+08:00","_updated_by":"()","code":"ARCH-EA-001","aliases":"TOGAF,企业架构,The Open Group Architecture Framework","summary":"业界最主流的企业架构方法论框架，包含ADM架构开发方法","problem_statement":"企业IT建设各做各的，系统孤岛严重、重复建设多，业务战略与IT能力脱节，IT投入产出比低；TOGAF通过ADM架构开发方法和企业架构框架，系统性规划企业架构，让IT与业务对齐、避免重复建设。","triggers":"TOGAF,企业架构,ADM,架构规划,数字化转型","applicable":"大型企业架构规划、数字化转型、IT战略制定、组织级架构治理","not_applicable":"小型企业、单一产品公司、创业公司","related_frameworks":"Zachman 框架,4+1 视图模型,DDD 领域驱动设计","templates":"TOGAF ADM交付物模板集","limitations":"体系庞大实施门槛高；周期长见效慢；需要高层支持和组织配合","mastery_level":"L2","last_used_date":null,"domain_code":"ARCH"},{"id":"8c8535e0-f326-4150-abed-7062aba16aae","name":"番茄工作法","category":"效率工具","scene":"深度工作、学习备考、写作编程、远程办公自律、专注力训练、拖延症改善。","core_logic":"由弗朗西斯科·西里洛创立的时间管理方法：将工作时间划分为 25 分钟的专注时段（番茄钟）和 5 分钟的短休息交替进行，每完成 4 个番茄钟后进行 15-30 分钟长休息。核心是通过时间盒（Timeboxing）强制专注+定期休息，保持高效而不 burnout。","steps":"[{\"name\": \"第一步：选择任务\", \"description\": \"确定当前要完成的任务，明确目标\"}, {\"name\": \"第二步：专注25分钟\", \"description\": \"设置25分钟倒计时，全神贯注工作，不被干扰打断\"}, {\"name\": \"第三步：短休息5分钟\", \"description\": \"番茄钟结束后短暂休息，放松大脑和眼睛\"}, {\"name\": \"第四步：每4个番茄钟长休息\", \"description\": \"完成4个番茄钟后休息15-30分钟，恢复精力\"}]","itto":"{\"tools\": [\"番茄钟APP\", \"待办清单\", \"专注力训练\"], \"inputs\": [\"任务清单\", \"计时器\"], \"outputs\": [\"高效产出\", \"时间感知提升\"]}","tools":"Forest App、番茄 ToDo、手机专注模式、物理计时器","cases":"一位自由职业者用番茄工作法改善拖延：过去每天有效工作约 3 小时且经常分心，实施番茄工作法后，每天稳定完成 8-10 个番茄钟（约 4-5 小时纯专注时间），产出提升 60%，同时因为有规律休息，下午不再昏昏欲睡。","viz_type":"cycle","viz_config":"{}","keywords":"番茄工作法,时间管理,专注,效率","sort_order":14,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.552+08:00","_updated_by":"()","code":"LRN-EFF-001","aliases":"番茄工作法","summary":"由弗朗西斯科·西里洛创立的时间管理方法：将工作时间划分为 25 分钟的专注时段（番茄钟）和 5 分钟的短休息交替进行，每完成 4 个番茄钟后进行 15-30 分","problem_statement":"工作时注意力分散，刷手机、走神频繁，一天下来没做多少事，效率低、拖延严重、疲惫不堪；番茄工作法将工作划分为25分钟专注时段和5分钟休息交替进行，通过节奏化管理大幅提升专注度和工作效率。","triggers":"时间不够、注意力分散、产出低下","applicable":"深度工作、学习备考、写作编程、远程办公自律、专注力训练、拖延症改善。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"一位自由职业者用番茄工作法改善拖延：过去每天有效工作约 3 小时且经常分心，实施番茄工作法后，每天稳定完成 8-10 个番茄钟（约 4-5 小时纯专注时间），产出提升 60%，同时因为有规律休息，下午","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"LEARN"},{"id":"8ec3df52-54bd-4b41-868f-c8312379644d","name":"分层架构","category":"系统架构","scene":"企业应用、Web系统、业务系统等需要清晰职责划分的场景","core_logic":"分层架构是最经典的软件架构模式，将系统按职责划分为表现层（UI/API）、业务逻辑层、数据访问层等，每一层只依赖其下层。优点是职责清晰、易于理解和维护，是大多数应用的基础架构。","steps":"[{\"name\": \"确定分层数量和职责\", \"description\": \"\"}, {\"name\": \"定义各层之间的接口\", \"description\": \"\"}, {\"name\": \"表现层：处理用户交互/API\", \"description\": \"\"}, {\"name\": \"业务层：核心业务逻辑\", \"description\": \"\"}, {\"name\": \"数据层：数据持久化和访问\", \"description\": \"\"}, {\"name\": \"确保依赖方向正确\", \"description\": \"\"}]","itto":"{\"tools\": [\"架构设计、框架选型\"], \"inputs\": [\"需求规格、技术选型\"], \"outputs\": [\"分层架构设计文档、代码结构\"]}","tools":"MVC框架、ORM框架、依赖注入","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"分层架构,三层架构,软件架构,设计模式,职责分离","sort_order":6,"_created_at":"2026-09-15T18:34:26.459+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.559+08:00","_updated_by":"()","code":"ARCH-LYR-001","aliases":"分层架构,Layered Architecture,三层架构","summary":"按职责将软件划分为多层，层间通过接口调用的经典架构模式","problem_statement":"软件代码混在一起，职责不清、耦合严重，改一个地方牵连一堆，维护困难、团队协作效率低；分层架构按职责将软件划分为多层，层间通过接口调用，实现关注点分离、降低耦合、提升可维护性。","triggers":"分层架构,三层架构,表现层业务层数据层,架构模式","applicable":"企业应用、Web系统、业务系统、中小型项目","not_applicable":"超高性能实时系统、简单脚本工具、需要极低延迟的场景","related_frameworks":"DDD 领域驱动设计,微服务架构,4+1 视图模型","templates":"分层架构设计模板","limitations":"扩展性有限；容易形成「下沉式」调用导致底层膨胀；不适合复杂的跨领域业务","mastery_level":"L2","last_used_date":null,"domain_code":"ARCH"},{"id":"8ec737ac-48c6-47da-8be0-c373f5117ebb","name":"制度分析与发展框架 IAD","category":"科研写作","scene":"公共管理研究、制度分析、公共事务治理（资源/环境/社区）、新制度主义论文","core_logic":"埃莉诺·奥斯特罗姆提出的 IAD（Institutional Analysis and Development）框架是制度分析的通用元框架。核心概念是\"行动舞台\"——行动者在特定的自然条件、共同体属性和规则体系约束下互动，产生特定结果。规则分为7类（边界、职位、范围、权威、聚合、信息、报酬），是制度分析的核心变量。","steps":"[]","itto":"{\"tools\": [\"IAD框架\", \"制度分析\", \"案例研究\", \"博弈论\"], \"inputs\": [\"制度环境信息\", \"行动者特征\", \"规则体系\"], \"outputs\": [\"制度分析报告\", \"制度设计/改进建议\"]}","tools":"IAD框架、博弈论、案例研究法、比较制度分析","cases":"农村灌溉系统治理研究：用IAD分析——自然条件（水资源禀赋）+ 共同体（村庄社会资本）+ 规则（取水规则、维护规则、监督规则）→ 行动舞台（村民取水互动）→ 结果（灌溉系统是否可持续）→ 评估（效率+公平+可持续）","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"行动舞台 Action Arena\", \"description\": \"行动者在特定情境下互动的场所，是IAD的核心分析单元\"}, {\"name\": \"外生变量\", \"items\": [\"自然物质条件\", \"共同体属性\", \"现行规则（7类规则）\"]}, {\"name\": \"行动舞台组成\", \"items\": [\"行动者（个体/群体）\", \"行动情境（信息、成本收益、控制等7个要素）\"]}, {\"name\": \"结果与评估\", \"items\": [\"互动模式（个体选择→结果）\", \"评估标准（效率、公平、可持续等）\"]}]}","keywords":"IAD,制度分析与发展,奥斯特罗姆,公共事务治理,制度经济学,管理社科","sort_order":131,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.567+08:00","_updated_by":"()","code":"DEC-IND-009","aliases":"IAD","summary":"埃莉诺·奥斯特罗姆提出的 IAD（Institutional Analysis and Development）框架是制度分析的通用元框架。核心概念是\"行动舞台","problem_statement":"制度分析缺乏通用框架，不同研究各说各话，研究成果难以对话和积累，制度影响机制说不清道不明；IAD框架作为制度分析的通用元框架，通过行动舞台等核心概念构建可对话、可积累的制度分析体系。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"公共管理研究、制度分析、公共事务治理（资源/环境/社区）、新制度主义论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"农村灌溉系统治理研究：用IAD分析——自然条件（水资源禀赋）+ 共同体（村庄社会资本）+ 规则（取水规则、维护规则、监督规则）→ 行动舞台（村民取水互动）→ 结果（灌溉系统是否可持续）→ 评估（效率+","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"8fac6307-1d3f-43cd-a304-d733d488598f","name":"SECI 模型","category":"知识管理","scene":"组织知识管理、经验沉淀、团队知识分享的场景","core_logic":"SECI模型描述了知识在隐性和显性之间转化、不断升级的四个过程：Socialization（社会化，隐性→隐性，如师徒制）→Externalization（外化，隐性→显性，如写文档）→Combination（组合化，显性→显性，如整合资料）→Internalization（内化，显性→隐性，如实践应用）。四者形成螺旋上升。","steps":"[{\"name\": \"S 社会化：分享经验，传递隐性知识\", \"description\": \"\"}, {\"name\": \"E 外化：将隐性知识显性化表达\", \"description\": \"\"}, {\"name\": \"C 组合化：整合显性知识形成体系\", \"description\": \"\"}, {\"name\": \"I 内化：通过实践内化为隐性知识\", \"description\": \"\"}, {\"name\": \"螺旋上升，持续创造新知识\", \"description\": \"\"}]","itto":"{\"tools\": [\"知识管理工具、实践社区\"], \"inputs\": [\"组织内的隐性/显性知识\"], \"outputs\": [\"组织知识资产、知识创新\"]}","tools":"知识管理系统、wiki、实践社区、复盘会","cases":"需补充","viz_type":"cycle","viz_config":"{}","keywords":"SECI,知识创造,隐性知识,知识螺旋,野中郁次郎","sort_order":2,"_created_at":"2026-09-15T18:34:26.586+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.575+08:00","_updated_by":"()","code":"KNOW-SECI-001","aliases":"SECI,知识创造螺旋,隐性知识显性化","summary":"野中郁次郎提出的组织知识创造螺旋模型","problem_statement":"组织知识只存在于个人脑子里，人一走知识就流失，隐性经验无法传递和沉淀为组织能力；SECI模型通过社会化-外部化-组合化-内部化的知识螺旋，实现隐性知识与显性知识的相互转化和组织化沉淀。","triggers":"SECI,知识创造,隐性知识,知识管理,知识螺旋","applicable":"组织知识管理、经验沉淀、团队学习、企业大学建设","not_applicable":"个人知识管理（部分适用）、完全标准化的工作","related_frameworks":"DIKW 模型,GRAI 复盘法,卡片盒笔记法（Zettelkasten）","templates":"SECI知识转化矩阵模板","limitations":"需要组织文化配合；隐性知识外化难度大；实施周期较长","mastery_level":"L2","last_used_date":null,"domain_code":"KNOW"},{"id":"9436806c-b733-45d2-864d-7d47072a3bf7","name":"长尾理论","category":"思维模型","scene":"互联网产品、电商选品、内容运营、利基市场战略、个性化推荐的场景","core_logic":"长尾理论由克里斯·安德森提出：在传统物理约束下（货架空间有限、渠道成本高），只能集中销售少数热门产品（头部），而大量小众产品（尾部）因为销量低不值得做。但互联网降低了库存和分发成本，让尾部产品的集合（长尾）也能产生可观的销量和利润，甚至总和超过头部。核心洞见是：文化和经济的重心正在从需求曲线头部的少数热门产品转向尾部的大量小众产品。","steps":"[{\"name\": \"分析品类分布\", \"description\": \"分析你的产品/内容的销量分布，是集中在头部还是有很长的尾部\"}, {\"name\": \"降低获取成本\", \"description\": \"找到降低长尾产品获取（生产/采购）成本的方式\"}, {\"name\": \"降低库存成本\", \"description\": \"利用数字化、按需生产、预售等方式降低库存压力\"}, {\"name\": \"降低分发成本\", \"description\": \"利用互联网渠道、算法推荐等方式低成本触达小众用户\"}, {\"name\": \"建立连接机制\", \"description\": \"通过搜索、推荐、分类、社区等机制，让小众用户找到对应的小众产品\"}, {\"name\": \"扩大长尾广度\", \"description\": \"不断增加SKU/内容数量，让尾巴更长更丰富\"}, {\"name\": \"优化推荐算法\", \"description\": \"通过个性化推荐提高长尾产品的发现率和转化率\"}, {\"name\": \"衡量总体贡献\", \"description\": \"统计长尾整体的销售额和利润贡献，而不是只看单品排名\"}]","itto":"{\"tools\": [\"推荐算法、用户画像、大数据分析、电商平台、内容平台、按需生产\"], \"inputs\": [\"大量小众产品/内容、低成本分发渠道、用户行为数据、推荐算法\"], \"outputs\": [\"长尾产品矩阵、个性化推荐系统、小众用户群体、总销量增长\"]}","tools":"推荐算法、大数据分析、用户画像、电商平台、内容管理系统","cases":"亚马逊图书、Netflix影库、淘宝/拼多多、苹果App Store、Spotify音乐、抖音短视频","viz_type":"chart","viz_config":"{}","keywords":"长尾理论,Long Tail,利基市场,小众市场,个性化,推荐算法","sort_order":86,"_created_at":"2026-09-16T16:20:50.972+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.583+08:00","_updated_by":"()","code":"META-LONGTAIL-001","aliases":"长尾理论,长尾巴,Long Tail,利基市场,小众市场聚合","summary":"小众需求的集合可以匹敌甚至超越头部市场，互联网降低了库存和分发成本让长尾成为可能","problem_statement":"只盯着头部市场和主流需求，忽略小众需求，错失巨大的市场机会，业务增长遇到瓶颈；长尾理论指出小众需求的集合可以匹敌甚至超越头部市场，互联网让长尾的供给和匹配成本大幅降低。","triggers":"长尾理论,长尾,Long Tail,利基市场,小众市场,个性化推荐,长尾巴","applicable":"电商平台、数字内容、SaaS产品、流媒体、出版社、在线教育、任何库存和分发成本极低的行业","not_applicable":"高库存成本的实体零售、服务成本无法摊薄的行业、品牌驱动的奢侈品市场、监管严格的行业","related_frameworks":"帕累托法则(80/20),蓝海战略ERRC框架,STP市场细分定位,4P营销组合,PMF产品市场契合","templates":"长尾产品矩阵规划表、品类拓展路线图、推荐策略优化方案","limitations":"不是所有行业都适用（长尾需要极低的边际成本）；长尾管理复杂度高；质量控制难度大；过度追求长尾可能稀释品牌定位；赢家通吃的平台效应反而可能加剧头部集中","mastery_level":"L2","last_used_date":null,"domain_code":"META"},{"id":"94f36f38-eedf-4e8d-ad8c-df91b80e553f","name":"期望值决策","category":"决策思维","scene":"风险决策、投资分析、项目评估、多方案选择的场景","core_logic":"期望值决策是一种量化决策方法：当存在多种可能结果且每种结果有一定概率时，计算每个方案的期望值（各结果的收益×概率之和），选择期望值最大的方案。它将不确定性纳入决策考量，比凭感觉拍板更理性，特别适合有历史数据或概率可估计的决策场景。","steps":"[{\"name\": \"明确决策问题和备选方案\", \"description\": \"列出所有可选方案，确保方案互斥且完整\"}, {\"name\": \"识别可能的自然状态\", \"description\": \"列出影响结果的不确定性因素及其可能状态\"}, {\"name\": \"估计各状态发生概率\", \"description\": \"基于历史数据或专家判断，为每种自然状态赋予概率，概率之和为1\"}, {\"name\": \"构建收益矩阵\", \"description\": \"计算每个方案在每种自然状态下的收益/损失值\"}, {\"name\": \"计算各方案期望值\", \"description\": \"EV = Σ(收益i × 概率i)，计算每个方案的期望值\"}, {\"name\": \"比较期望值并选择\", \"description\": \"选择期望值最大（或损失最小）的方案\"}, {\"name\": \"考虑风险因素\", \"description\": \"除了期望值，还要考虑方差/波动、最坏情况等风险因素\"}, {\"name\": \"敏感性检验\", \"description\": \"测试概率或收益估计变化时，决策结论是否稳健\"}]","itto":"{\"tools\": [\"收益矩阵、概率计算、决策树、Excel模型、敏感性分析\"], \"inputs\": [\"备选方案清单、收益数据、概率估计、历史数据、专家判断\"], \"outputs\": [\"收益矩阵、各方案期望值、最优方案建议、风险分析\"]}","tools":"决策矩阵、Excel、决策树、敏感性分析、概率统计","cases":"投资项目选择、新产品上市决策、保险定价、赌博/彩票理性分析、库存决策","viz_type":"matrix","viz_config":"{}","keywords":"期望值,收益矩阵,概率决策,风险决策,Expected Value,决策矩阵","sort_order":76,"_created_at":"2026-09-16T16:20:50.882+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.59+08:00","_updated_by":"()","code":"DECIDE-EV-001","aliases":"期望价值决策,收益矩阵,期望值法,Expected Value,期望效用","summary":"用概率×收益计算各方案期望值，理性选择期望值最大的方案","problem_statement":"做决策凭感觉选看起来好的，不量化概率和收益，选完了才发现实际收益远不如预期，决策质量差、容易后悔；期望值决策用概率乘以收益计算各方案期望值，理性选择期望值最大的方案，让决策有据可依。","triggers":"期望值,期望价值,收益矩阵,概率决策,风险决策,Expected Value,决策矩阵","applicable":"投资决策、项目选择、风险评估、商业决策、有概率信息的多方案选择","not_applicable":"完全无法估计概率的场景、涉及重大不可量化价值（如生命、名誉）的决策、一次性不可重复的重大决策","related_frameworks":"决策树,敏感性分析,蒙特卡洛模拟,贝叶斯思维,风险矩阵","templates":"期望值决策模板、收益矩阵模板、决策树模板","limitations":"概率估计可能不准；忽略了风险偏好（期望效用更准确）；不适合小概率大影响的极端事件；人的实际决策常偏离期望值理论（展望理论）","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"95734cd9-aa51-485f-8698-c952fe350bfd","name":"复利思维","category":"思维模型","scene":"长期投资、个人成长、学习积累、职业发展、能力建设的场景","core_logic":"复利思维源于金融学中的复利概念：本金产生利息，利息加入本金继续产生利息，形成指数式增长。复利的核心是「时间」和「持续」——早期增长缓慢甚至看不见，但越过临界点后会加速爆发。复利思维不仅适用于金钱，也适用于知识、技能、人脉、健康等领域：每天进步一点点，长期积累下来的差距是惊人的。","steps":"[{\"name\": \"识别可复利的领域\", \"description\": \"找出哪些事情是可以持续积累、越久越有价值的\"}, {\"name\": \"确定核心本金\", \"description\": \"明确你的「本金」是什么——时间、精力、金钱、技能还是人脉？\"}, {\"name\": \"设定长期目标\", \"description\": \"以年甚至十年为单位设定目标，拉长时间维度思考\"}, {\"name\": \"建立正反馈循环\", \"description\": \"设计让收益再投入的机制，形成增长飞轮\"}, {\"name\": \"保持持续投入\", \"description\": \"每天/每周持续投入，哪怕量不大，关键是不间断\"}, {\"name\": \"忍受前期缓慢\", \"description\": \"接受早期增长不明显的阶段，不急于求成不轻易放弃\"}, {\"name\": \"关注长期而非短期波动\", \"description\": \"不过度关注短期起伏，着眼长期趋势\"}, {\"name\": \"定期复盘和再投资\", \"description\": \"定期回顾积累成果，将收益再次投入扩大本金\"}]","itto":"{\"tools\": [\"长期目标设定、习惯养成、定投策略、费曼学习法、复盘反思\"], \"inputs\": [\"时间、精力、资金、初始能力、持续投入的决心\"], \"outputs\": [\"指数增长曲线、长期积累的能力/财富/人脉、跨越临界点后的爆发\"]}","tools":"定投策略、习惯养成、目标管理、复盘方法、长期主义","cases":"巴菲特投资、个人知识积累、语言学习、健身、阅读量与认知提升","viz_type":"chart","viz_config":"{}","keywords":"复利,指数增长,长期主义,积累,滚雪球,延迟满足","sort_order":81,"_created_at":"2026-09-16T16:20:50.917+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.598+08:00","_updated_by":"()","code":"META-COMPOUND-001","aliases":"复利效应,复利,Compound Interest,指数增长,长期主义,滚雪球效应","summary":"重视长期积累的指数增长效应，前期慢后期爆发，适用于学习、投资、人脉、能力","problem_statement":"只看短期收益、急功近利，忽视长期积累的价值，什么来钱快做什么，最终碌碌无为、增长停滞；复利思维重视长期指数增长效应，前期慢后期爆发，适用于学习、投资、能力等所有可积累的领域。","triggers":"复利,指数增长,长期主义,滚雪球,积累效应,Compound Interest,延迟满足","applicable":"投资理财、个人成长、学习教育、职业发展、健康管理、人脉经营、企业长期战略","not_applicable":"需要快速见效的紧急事务、生命周期很短的事物、无法积累的一次性活动","related_frameworks":"飞轮效应,长期主义,精益创业,刻意练习,破窗效应","templates":"复利计算表、年度目标与复盘模板、定投计划表","limitations":"需要很长时间才能看到效果，容易半途而废；需要方向正确，错误方向复利越久损失越大；复利也有天花板和边界，不可能无限增长","mastery_level":"L2","last_used_date":null,"domain_code":"META"},{"id":"95b77d90-48e4-4cdb-821c-aefa8501768a","name":"SWOT 分析矩阵","category":"风险分析","scene":"企业战略规划、产品定位分析、竞品分析、项目立项可行性评估、个人职业发展规划。","core_logic":"从内部（优势/劣势）和外部（机会/威胁）两个维度、正面和负面两个方向进行四象限交叉分析，帮助决策者全面认清形势，从而制定 SO（增长）、WO（扭转）、ST（多元化）、WT（防御）四种战略组合。","steps":"[{\"name\": \"明确分析目标与范围\", \"description\": \"确定分析的对象（企业/产品/项目/个人）和分析目的\"}, {\"name\": \"收集内部信息，识别优势（S）\", \"description\": \"盘点组织内部的资源、能力、优势，列出核心Strengths\"}, {\"name\": \"收集内部信息，识别劣势（W）\", \"description\": \"诚实地分析内部不足和短板，列出Weaknesses\"}, {\"name\": \"分析外部环境，识别机会（O）\", \"description\": \"研究外部趋势、市场变化，识别有利的Opportunities\"}, {\"name\": \"分析外部环境，识别威胁（T）\", \"description\": \"识别外部风险、竞争压力等不利因素，列出Threats\"}, {\"name\": \"构建SWOT矩阵\", \"description\": \"将S/W/O/T分别填入四个象限，形成分析矩阵\"}, {\"name\": \"制定SO战略（增长型）\", \"description\": \"利用优势抓住机会——内部优势+外部机会的最大化组合\"}, {\"name\": \"制定WO战略（扭转型）\", \"description\": \"利用机会弥补劣势——通过外部机会改进内部不足\"}, {\"name\": \"制定ST战略（多元化/多种经营）\", \"description\": \"利用优势规避威胁——用内部优势应对外部挑战\"}, {\"name\": \"制定WT战略（防御型）\", \"description\": \"减少劣势规避威胁——收缩防守，降低风险\"}, {\"name\": \"评估与优先级排序\", \"description\": \"评估各战略组合的可行性和优先级，确定行动重点\"}, {\"name\": \"制定行动计划\", \"description\": \"将选定的战略转化为具体的行动计划和时间表\"}]","itto":"{\"tools\": [\"头脑风暴\", \"专家访谈\", \"PEST分析\", \"波特五力\"], \"inputs\": [\"内部环境分析\", \"外部环境分析\", \"行业报告\"], \"outputs\": [\"SWOT分析矩阵\", \"战略方向建议\"]}","tools":"头脑风暴法、PEST 宏观分析、波特五力模型、专家德尔菲法","cases":"某电商平台年度战略复盘：通过 SWOT 分析识别出供应链优势+直播电商机会的 SO 战略组合，投入资源打造自营直播业务，首年 GMV 突破 10 亿。","viz_type":"matrix","viz_config":"{\"quadrants\": [{\"name\": \"优势 Strengths\", \"items\": [\"技术优势\", \"品牌影响力\", \"资源充足\", \"团队能力强\"], \"description\": \"组织内部的积极因素\"}, {\"name\": \"劣势 Weaknesses\", \"items\": [\"资金不足\", \"技术落后\", \"管理混乱\", \"人才短缺\"], \"description\": \"组织内部的消极因素\"}, {\"name\": \"机会 Opportunities\", \"items\": [\"市场增长\", \"政策支持\", \"技术变革\", \"合作伙伴\"], \"description\": \"外部环境的有利因素\"}, {\"name\": \"威胁 Threats\", \"items\": [\"竞争加剧\", \"政策变化\", \"经济下行\", \"技术替代\"], \"description\": \"外部环境的不利因素\"}], \"xAxisLabel\": \"内部因素 → 外部因素\", \"yAxisLabel\": \"正面影响 → 负面影响\"}","keywords":"SWOT,风险分析,战略分析,矩阵","sort_order":2,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.606+08:00","_updated_by":"()","code":"DEC-STR-001","aliases":"SWOT","summary":"从内部（优势/劣势）和外部（机会/威胁）两个维度进行四象限交叉分析，制定SO增长、WO扭转、ST多元化、WT防御四种战略组合","problem_statement":"做战略分析只看单一维度，要么只看优势忽略风险，要么只看外部机会没考虑自身能力，战略判断片面误判；SWOT从内部优劣势和外部机会威胁四个维度交叉分析，制定SO/WO/ST/WT四种匹配策略。","triggers":"风险不明、决策犹豫、不确定性高","applicable":"企业战略规划、产品定位分析、竞品分析、项目立项可行性评估、个人职业发展规划。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某电商平台年度战略复盘：通过 SWOT 分析识别出供应链优势+直播电商机会的 SO 战略组合，投入资源打造自营直播业务，首年 GMV 突破 10 亿。","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"DECIDE"},{"id":"98f87606-45d0-44e6-a121-5b815c7baa4b","name":"需求管理 ITTO","category":"需求管理","scene":"项目启动阶段收集、分析和管理干系人需求；产品需求文档（PRD）编写；需求评审与基线化。","core_logic":"以输入-工具-输出（ITTO）的结构化方式梳理需求管理全过程：从项目章程和干系人登记册出发，通过访谈、原型法、标杆对照等十大工具技术，最终产出需求文件、需求跟踪矩阵和需求管理计划三大核心交付物。","steps":"[{\"name\": \"输入(Inputs)\", \"description\": \"项目章程、干系人登记册、事业环境因素、组织过程资产\"}, {\"name\": \"工具与技术(Tools)\", \"description\": \"访谈、焦点小组、引导式研讨会、群体创新技术、问卷调查、观察、原型法、标杆对照、系统交互图、文件分析\"}, {\"name\": \"输出(Outputs)\", \"description\": \"需求文件、需求跟踪矩阵、需求管理计划\"}]","itto":"{\"tools\": [\"访谈\", \"焦点小组\", \"引导式研讨会\", \"群体创新技术\", \"问卷调查\", \"观察\", \"原型法\", \"标杆对照\", \"系统交互图\", \"文件分析\"], \"inputs\": [\"项目章程\", \"干系人登记册\", \"事业环境因素\", \"组织过程资产\"], \"outputs\": [\"需求文件\", \"需求跟踪矩阵\", \"需求管理计划\"]}","tools":"Jira/Confluence 需求管理、Axure 原型设计、Xmind 思维导图、Excel 需求跟踪矩阵","cases":"某互联网产品从 0 到 1 搭建需求体系：通过访谈+焦点小组收集 50+ 用户需求，用原型法快速验证 MVP，最终输出 200 条需求的跟踪矩阵，覆盖率达 95%。","viz_type":"process","viz_config":"{}","keywords":"需求,ITTO,输入输出,PMP","sort_order":1,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.614+08:00","_updated_by":"()","code":"PM-REQ-001","aliases":"需求","summary":"以输入-工具-输出（ITTO）的结构化方式梳理需求管理全过程：从项目章程和干系人登记册出发，通过访谈、原型法、标杆对照等十大工具技术，最终产出需求文件、需求跟踪","problem_statement":"需求管理过程混乱，输入不清、工具随意、输出不规范，需求从哪来、怎么管、交付什么都一笔糊涂账；需求管理ITTO以输入-工具-输出的结构化方式梳理全过程，让需求管理有章可循、有标准可依。","triggers":"需求变更频繁、需求不清晰、干系人期望不一致","applicable":"项目启动阶段收集、分析和管理干系人需求；产品需求文档（PRD）编写；需求评审与基线化。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某互联网产品从 0 到 1 搭建需求体系：通过访谈+焦点小组收集 50+ 用户需求，用原型法快速验证 MVP，最终输出 200 条需求的跟踪矩阵，覆盖率达 95%。","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"98ff3d87-671b-4f66-afdf-31affe100141","name":"FMEA 失效模式与影响分析","category":"问题解决","scene":"产品设计评审、流程风险识别、质量预防、系统安全分析的场景","core_logic":"FMEA是一种预防性的风险分析方法，通过系统地分析产品或流程中每一个可能的失效模式，评估其严重度(S)、发生频度(O)和探测度(D)，计算风险优先数(RPN=S×O×D)，对高风险项优先采取改进措施，将风险消除或控制在可接受范围内。","steps":"[{\"name\": \"确定分析范围和对象\", \"description\": \"明确要分析的产品/流程/系统，划定分析边界\"}, {\"name\": \"列出所有潜在失效模式\", \"description\": \"系统梳理每个环节可能的失效方式和表现\"}, {\"name\": \"分析失效影响\", \"description\": \"评估每种失效对用户、下道工序、系统的影响\"}, {\"name\": \"确定严重度(S)评分\", \"description\": \"按影响严重程度1-10分打分\"}, {\"name\": \"分析失效原因与发生频度(O)\", \"description\": \"找出失效的根本原因，评估发生频率1-10分\"}, {\"name\": \"评估当前控制与探测度(D)\", \"description\": \"现有控制措施能否及时发现失效，1-10分\"}, {\"name\": \"计算RPN并排序\", \"description\": \"RPN=S×O×D，按风险优先数从高到低排序\"}, {\"name\": \"制定改进措施并跟踪\", \"description\": \"对高风险项制定预防/探测改进措施，跟踪效果并重新评分\"}]","itto":"{\"tools\": [\"FMEA表格、严重度/频度/探测度评分标准、历史失效数据库、专家经验\"], \"inputs\": [\"产品/流程设计信息、历史失效数据、类似产品经验、客户需求\"], \"outputs\": [\"FMEA分析报告、风险优先级清单、改进措施计划、设计/工艺变更建议\"]}","tools":"FMEA表格、AIAG-VDA FMEA标准、风险矩阵、历史失效数据库","cases":"汽车行业DFMEA/PFMEA、航空航天可靠性分析、医疗器械安全评估、电子制造业质量控制","viz_type":"matrix","viz_config":"{}","keywords":"FMEA,失效模式,风险分析,质量预防,RPN,可靠性","sort_order":64,"_created_at":"2026-09-16T16:20:50.766+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.621+08:00","_updated_by":"()","code":"SOLVE-FMEA-001","aliases":"FMEA,失效模式分析,潜在失效模式与后果分析,Failure Mode and Effects Analysis","summary":"预防性风险分析工具，系统识别潜在失效模式、影响与严重度，提前制定改进措施","problem_statement":"产品或流程出了问题才补救，事前不知道哪里可能出问题、影响有多大，风险没有提前预防；FMEA系统性识别潜在失效模式、影响和严重度，按优先级提前制定改进措施，将风险消灭在萌芽状态。","triggers":"FMEA,失效模式,风险分析,质量预防,可靠性分析,DFMEA,PFMEA","applicable":"新产品设计开发、制造工艺设计、服务流程设计、安全关键系统、质量改进","not_applicable":"极其简单的产品/流程、完全创新性无法预判的场景、时间极短的临时项目","related_frameworks":"FTA故障树分析,风险矩阵,8D问题解决法,A3问题解决法,HAZOP危险与可操作性分析","templates":"FMEA分析模板、DFMEA模板、PFMEA模板、RPN评分标准","limitations":"实施耗时耗力；评分有主观性；需要跨部门协作；对全新产品缺乏历史数据支撑","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"993dc03c-0758-47bf-a92a-d51fa2b8e09a","name":"MoSCoW 优先级","category":"需求管理","scene":"迭代规划、发布范围确定、项目范围管理的场景","core_logic":"MoSCoW将需求分为四个优先级：Must have（必须有，否则不可交付）、Should have（应该有，重要但非必须）、Could have（可以有，有了更好）、Won't have（本次不会做）。帮助团队在资源有限时聚焦最重要的需求。","steps":"[{\"name\": \"列出所有候选需求\", \"description\": \"\"}, {\"name\": \"逐个评估并归类到M/S/C/W\", \"description\": \"\"}, {\"name\": \"与干系人达成共识\", \"description\": \"\"}, {\"name\": \"确认Must have的交付可行性\", \"description\": \"\"}, {\"name\": \"规划S/C的迭代安排\", \"description\": \"\"}, {\"name\": \"定期回顾调整\", \"description\": \"\"}]","itto":"{\"tools\": [\"干系人研讨\"], \"inputs\": [\"需求列表、资源约束\"], \"outputs\": [\"优先级分类、发布计划\"]}","tools":"需求卡片、优先级排序工作坊、KANO模型","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"MoSCoW,优先级,需求排序,迭代规划,Must have","sort_order":5,"_created_at":"2026-09-15T18:34:13.74+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.63+08:00","_updated_by":"()","code":"PROD-PRI-001","aliases":"MoSCoW,莫斯科法,需求优先级","summary":"将需求分为必须有/应该有/可以有/不会有四级的优先级方法","problem_statement":"需求不分轻重缓急全做，资源分散、重点不突出，核心功能被不重要的需求挤占时间，交付质量差且延期；MoSCoW将需求分为必须有/应该有/可以有/不会有四级，确保资源聚焦在最核心的需求上。","triggers":"MoSCoW,优先级,需求排序,迭代规划,范围","applicable":"敏捷迭代规划、产品版本规划、项目范围管理、需求筛选","not_applicable":"需求很少的简单项目、所有需求同等重要的场景","related_frameworks":"KANO 模型,需求跟踪矩阵 RTM,用户故事","templates":"MoSCoW需求优先级模板","limitations":"四级划分可能过于粗糙；分级标准有主观性；需要干系人共识","mastery_level":"L3","last_used_date":null,"domain_code":"PROD"},{"id":"9996ad17-8207-4acb-a362-5a9da48b98e9","name":"需求跟踪矩阵 RTM","category":"需求管理","scene":"复杂项目的需求管理、变更影响分析、合规性要求的场景","core_logic":"需求跟踪矩阵记录每个需求的来源、描述、优先级、对应的设计、开发、测试用例和交付物，建立需求到交付物的双向追溯关系，确保每个需求都被实现，每个变更都能评估影响。","steps":"[{\"name\": \"收集并编号所有需求\", \"description\": \"\"}, {\"name\": \"识别需求来源和依据\", \"description\": \"\"}, {\"name\": \"映射需求到设计文档\", \"description\": \"\"}, {\"name\": \"映射需求到开发任务\", \"description\": \"\"}, {\"name\": \"映射需求到测试用例\", \"description\": \"\"}, {\"name\": \"建立矩阵并定期更新\", \"description\": \"\"}]","itto":"{\"tools\": [\"需求管理工具\"], \"inputs\": [\"需求文档、设计文档、测试用例\"], \"outputs\": [\"需求跟踪矩阵、变更影响分析\"]}","tools":"需求管理软件、Excel、Jira、TestLink","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"交付物\", \"y_label\": \"需求\", \"quadrants\": {\"q1\": \"追溯关系\"}}","keywords":"RTM,需求跟踪矩阵,需求追溯,变更影响,需求管理","sort_order":6,"_created_at":"2026-09-15T18:34:13.751+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.638+08:00","_updated_by":"()","code":"PROD-RTM-001","aliases":"RTM,需求跟踪矩阵,Requirements Traceability Matrix","summary":"建立需求从来源到交付物全链路可追溯关系的管理工具","problem_statement":"需求从提出到交付全链路脱节，改了需求忘了改代码，测试了功能不知道对应哪条需求，追溯困难；RTM建立需求从来源到设计、编码、测试、交付的全链路追溯关系，确保每条需求都有始有终、变更影响清晰。","triggers":"RTM,需求跟踪,追溯,需求管理,影响分析","applicable":"中大型项目、外包项目、合规性要求高的项目、需求变更频繁的项目","not_applicable":"小型敏捷项目（用故事卡片和验收标准替代）","related_frameworks":"变更控制（CCB）,KANO 模型,MoSCoW 优先级","templates":"需求跟踪矩阵RTM模板","limitations":"维护成本较高；需要流程配合；工具选择影响效率","mastery_level":"L3","last_used_date":null,"domain_code":"PROD"},{"id":"9bafef9e-318e-4312-83c7-828854dc846b","name":"贝尔宾团队角色","category":"团队管理","scene":"团队组建、团队诊断、人才招聘、团队配置优化的场景","core_logic":"贝尔宾通过研究发现高效团队通常由九种不同角色类型的人组成：执行者、完成者、塑造者、创新者、资源调查者、协调者、监督者、凝聚者、专家。一个人可以扮演多种角色，团队需要角色平衡才能高效。","steps":"[{\"name\": \"评估现有成员的团队角色\", \"description\": \"\"}, {\"name\": \"识别缺失或薄弱的角色\", \"description\": \"\"}, {\"name\": \"通过招聘或培养补充角色\", \"description\": \"\"}, {\"name\": \"根据任务调整角色分工\", \"description\": \"\"}, {\"name\": \"定期评估团队角色平衡\", \"description\": \"\"}]","itto":"{\"tools\": [\"贝尔宾测评、访谈\"], \"inputs\": [\"团队成员名单\"], \"outputs\": [\"团队角色分析报告、配置建议\"]}","tools":"贝尔宾团队角色测评、MBTI、StrengthsFinder","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"贝尔宾,团队角色,Belbin,团队配置,角色平衡","sort_order":7,"_created_at":"2026-09-15T18:34:20.093+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.646+08:00","_updated_by":"()","code":"TEAM-ROLE-001","aliases":"贝尔宾,Belbin,团队角色理论","summary":"描述高效团队需要的九种角色类型及其贡献的团队配置理论","problem_statement":"团队招人只看技能不看角色互补，一堆同类人聚在一起思维趋同，关键角色缺位导致协作不畅；贝尔宾团队角色理论描述了高效团队需要的九种角色类型，帮你识别角色缺口、优化团队配置。","triggers":"贝尔宾,团队角色,Belbin,团队配置,角色平衡","applicable":"团队组建、人才招聘、团队诊断、团队建设","not_applicable":"极小型团队（一人多角不可避免）、极简单任务","related_frameworks":"RACI 职责矩阵,塔克曼团队发展模型,授权与分工","templates":"贝尔宾团队角色评估表","limitations":"测评有一定主观性；团队角色不是固定不变的；九种角色不是所有团队都需要","mastery_level":"L2","last_used_date":null,"domain_code":"TEAM"},{"id":"9c337488-97ea-433e-bf40-6cfbef71f102","name":"第一性原理","category":"思维方法","scene":"颠覆性创新、复杂问题求解、破除思维定式的场景","core_logic":"将问题拆解到最根本的、不可再分的事实单元（第一性原理），然后从这些基本事实出发，通过逻辑推理重新构建解决方案，而不是依赖类比思维和约定俗成的做法。","steps":"[{\"name\": \"识别当前问题的既有假设\", \"description\": \"\"}, {\"name\": \"将问题拆解到最基本的事实要素\", \"description\": \"\"}, {\"name\": \"验证每个要素是否为不可再分的真理\", \"description\": \"\"}, {\"name\": \"从第一性原理出发重新构建解决方案\", \"description\": \"\"}, {\"name\": \"验证新方案的可行性\", \"description\": \"\"}]","itto":"{\"tools\": [\"追问法、拆解法\"], \"inputs\": [\"问题/现象、已有方案\"], \"outputs\": [\"创新方案、本质洞察\"]}","tools":"苏格拉底提问法、5Why、拆解法","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"第一性原理,本质思维,创新,拆解,底层逻辑","sort_order":11,"_created_at":"2026-09-15T18:34:03.099+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.654+08:00","_updated_by":"()","code":"META-THK-003","aliases":"第一性原理,First Principles","summary":"从最基本的事实出发，重新推导结论的思维方式","problem_statement":"思考问题总是基于类比和经验，被固有认知束缚，跳不出思维框框，做不出颠覆性创新，只能跟在别人后面；第一性原理从最基本的事实和原理出发重新推导结论，打破思维定势，实现真正的颠覆性创新。","triggers":"创新,颠覆,本质,原理,重新思考","applicable":"技术创新、商业模式创新、复杂问题根源求解、产品设计突破","not_applicable":"日常事务处理、需要快速决策的场景、已有成熟方案的常规问题","related_frameworks":"5Why,TRIZ 理论,逆向思维","templates":"第一性原理追问清单","limitations":"思考成本高，耗时；需要较深的领域知识；不适合所有问题类型","mastery_level":"L3","last_used_date":null,"domain_code":"META"},{"id":"9f2bfdcf-1142-4ecb-a0f8-8d0b91f91eb3","name":"艾宾浩斯遗忘曲线","category":"学习方法","scene":"语言学习、考试备考、知识记忆、技能巩固、长期记忆建立","core_logic":"艾宾浩斯遗忘曲线由德国心理学家赫尔曼·艾宾浩斯（Hermann Ebbinghaus）于1885年在《论记忆》一书中提出，描述了人类记忆随时间衰减的规律：学习后遗忘立即开始，且先快后慢。通过在遗忘临界点（20分钟、1小时、9小时、1天、2天、6天、31天）进行有计划的复习，可以有效延缓遗忘，将短期记忆转化为长期记忆。","steps":"[{\"name\": \"初次学习\", \"description\": \"认真学习新知识，建立初步理解和记忆\"}, {\"name\": \"第一次复习（20分钟后）\", \"description\": \"学习后约20分钟进行第一次快速回顾，巩固短期记忆\"}, {\"name\": \"第二次复习（1小时后）\", \"description\": \"约1小时后进行第二次复习，强化记忆痕迹\"}, {\"name\": \"第三次复习（9小时后）\", \"description\": \"约9小时后进行第三次复习，延缓快速遗忘\"}, {\"name\": \"第四次复习（1天后）\", \"description\": \"1天后复习，将记忆向中期转化\"}, {\"name\": \"第五次复习（2天后）\", \"description\": \"2天后复习，进一步巩固记忆\"}, {\"name\": \"第六次复习（6天后）\", \"description\": \"6天后复习，向长期记忆转化\"}, {\"name\": \"第七次复习（31天后）\", \"description\": \"约一个月后复习，巩固为长期记忆\"}]","itto":"{\"tools\": [\"间隔重复软件Anki、复习计划表、闪卡、番茄工作法\"], \"inputs\": [\"待学习的知识内容、学习计划、记忆材料\"], \"outputs\": [\"长期记忆效果、复习计划表、知识掌握度提升\"]}","tools":"Anki间隔重复软件、闪卡、复习计划表、番茄工作法、费曼学习法","cases":"英语单词背诵、考试备考、医学知识记忆、法律条文记忆、语言学习","viz_type":"process","viz_config":"{}","keywords":"艾宾浩斯,遗忘曲线,记忆,间隔重复,复习,学习","sort_order":503,"_created_at":"2026-09-16T16:20:51.164+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.661+08:00","_updated_by":"()","code":"LEARN-EBB-001","aliases":"遗忘曲线,艾宾浩斯记忆法,间隔重复记忆,Ebbinghaus Forgetting Curve","summary":"按遗忘规律安排复习间隔，科学提升记忆效率的学习方法","problem_statement":"学完不复习，几天后几乎全忘，之前花的时间全白费，学习效率极低，总在重复学同样的内容；艾宾浩斯遗忘曲线揭示了记忆的衰退规律，按科学间隔安排复习，让记忆从短期转化为长期。","triggers":"艾宾浩斯,遗忘曲线,记忆,复习,间隔重复,背单词,备考","applicable":"语言学习、考试备考、知识点记忆、技能训练、需要长期记忆的知识学习","not_applicable":"理解性学习、技能实操（主要靠肌肉记忆）、纯逻辑性内容","related_frameworks":"费曼学习法,番茄工作法,间隔重复,刻意练习,SQ3R阅读法","templates":"艾宾浩斯复习计划表、间隔重复学习时间表","limitations":"需要长期坚持才能见效；复习间隔需要根据内容难度调整；纯机械记忆效果有限需配合理解","mastery_level":"L2","last_used_date":null,"domain_code":"LEARN"},{"id":"a0d12379-4cd4-4574-8d94-fde94abfff9f","name":"高可用架构设计","category":"系统架构","scene":"核心业务系统、互联网产品、金融系统等对可用性要求高的场景","core_logic":"高可用架构通过消除单点故障、冗余设计、故障自动检测和转移、降级熔断等手段，确保系统在硬件故障、软件bug、流量突增等异常情况下仍能持续提供服务。常用策略包括：主备、集群、负载均衡、熔断、限流、降级。","steps":"[{\"name\": \"确定可用性目标(SLA)\", \"description\": \"\"}, {\"name\": \"识别单点故障和风险点\", \"description\": \"\"}, {\"name\": \"设计冗余和故障转移方案\", \"description\": \"\"}, {\"name\": \"设计限流/熔断/降级机制\", \"description\": \"\"}, {\"name\": \"建设监控和告警体系\", \"description\": \"\"}, {\"name\": \"定期容灾演练\", \"description\": \"\"}]","itto":"{\"tools\": [\"负载均衡、集群、容灾技术\"], \"inputs\": [\"系统架构、可用性目标\"], \"outputs\": [\"高可用架构方案、容灾预案\"]}","tools":"负载均衡、集群、容器编排、熔断框架、监控告警","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"高可用,HA,故障转移,冗余设计,容灾","sort_order":8,"_created_at":"2026-09-15T18:34:26.477+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.669+08:00","_updated_by":"()","code":"ARCH-HA-001","aliases":"高可用,HA,High Availability,高可用架构","summary":"通过冗余、故障转移等手段确保系统持续可用的架构设计原则","problem_statement":"系统单点故障频繁，一有问题就全线瘫痪，业务中断造成巨大损失，用户体验差、信任度下降风险高；高可用架构通过冗余设计、故障转移、限流降级等手段，确保系统在故障情况下仍能持续提供服务。","triggers":"高可用,HA,故障转移,冗余,容灾","applicable":"核心业务系统、互联网产品、金融系统、电商平台、SaaS服务","not_applicable":"内部工具、非核心系统、低可用要求的简单应用","related_frameworks":"微服务架构,ATAM 架构权衡分析,4+1 视图模型","templates":"高可用架构设计清单","limitations":"高可用需要成本投入；追求过高可用性可能过度设计；需要持续运营和演练","mastery_level":"L2","last_used_date":null,"domain_code":"ARCH"},{"id":"a253c01c-a104-400e-84a8-83bcd2f0dbfa","name":"4P 营销组合","category":"产品营销","scene":"营销策略制定、产品上市、品牌推广、市场进入的场景","core_logic":"4P营销组合理论由杰罗姆·麦卡锡提出，是市场营销的经典框架，将营销活动归纳为四个核心要素：①产品(Product)——功能、特性、质量、品牌、包装、服务等；②价格(Price)——定价策略、价格体系、折扣、付款方式等；③渠道(Place)——分销渠道、覆盖范围、物流、终端等；④促销(Promotion)——广告、公关、销售促进、人员推销等。四个要素必须协调配合，形成合力，才能有效触达目标用户并实现营销目标。","steps":"[{\"name\": \"明确目标和定位\", \"description\": \"明确营销目标和产品定位，确定目标用户群\"}, {\"name\": \"产品策略(Product)\", \"description\": \"规划产品：功能特性、质量水平、品牌命名、包装设计、售后服务、产品线组合\"}, {\"name\": \"价格策略(Price)\", \"description\": \"制定价格：定价目标、定价方法、价格体系、折扣政策、付款条件、价格调整机制\"}, {\"name\": \"渠道策略(Place)\", \"description\": \"设计渠道：渠道类型、渠道层级、覆盖范围、分销方式、物流配送、终端管理\"}, {\"name\": \"促销策略(Promotion)\", \"description\": \"规划促销：广告投放、公关传播、销售促进、人员推销、内容营销、数字营销\"}, {\"name\": \"整合4P形成合力\", \"description\": \"确保四个P相互配合、方向一致、形成协同效应，而不是各自为政\"}, {\"name\": \"制定执行计划\", \"description\": \"将营销策略转化为具体的执行计划、预算和时间表\"}, {\"name\": \"执行、监控与调整\", \"description\": \"执行营销计划，监控关键指标，根据效果及时调整策略\"}]","itto":"{\"tools\": [\"市场调研、竞品分析、用户画像、STP定位、品牌定位、营销数据监控\"], \"inputs\": [\"产品信息、市场调研数据、目标用户画像、竞争分析、营销预算\"], \"outputs\": [\"营销组合策略、营销执行计划、营销预算、品牌推广方案、市场进入策略\"]}","tools":"市场调研、竞品分析、用户画像、品牌定位、STP、营销数据看板","cases":"消费品公司营销策划、互联网产品增长营销、新产品上市推广、品牌全案策划","viz_type":"matrix","viz_config":"{}","keywords":"4P营销,营销组合,产品,价格,渠道,促销,市场营销","sort_order":102,"_created_at":"2026-09-16T16:20:51.075+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.677+08:00","_updated_by":"()","code":"PROD-4P-001","aliases":"4P营销,营销组合,4P理论,Product Price Place Promotion,市场营销组合","summary":"产品、价格、渠道、促销四要素构成的营销框架，系统规划营销策略","problem_statement":"营销只靠打广告或拼价格，要素之间不协同，营销策略零散不系统，投入不少但效果不佳；4P营销组合从产品、价格、渠道、促销四个维度系统规划营销策略，让各要素协同发力。","triggers":"4P营销,营销组合,4P理论,产品价格渠道促销,市场营销,营销策略","applicable":"产品上市营销、品牌推广、市场进入策略、营销规划、营销策略制定","not_applicable":"纯技术驱动无营销需求的产品、完全to政府的关系型销售、非商业性产品","related_frameworks":"STP市场细分定位,品牌定位,AARRR海盗模型,PMF产品市场契合,蓝海战略ERRC框架","templates":"4P营销分析模板、产品上市营销计划、营销预算模板、营销策略矩阵","limitations":"4P是从企业视角出发的，后来发展出4C等从用户视角的框架；偏战术层面，对战略层面关注不足；数字时代营销手段更加丰富，4P需要扩展；服务行业还需增加人员、过程、有形展示（7P）","mastery_level":"L2","last_used_date":null,"domain_code":"PROD"},{"id":"a5d132a8-ec24-4310-b8ef-209b7048f8d5","name":"六顶思考帽","category":"思维方法","scene":"团队会议决策、产品方案评审、创新头脑风暴、问题分析讨论、战略规划会议。","core_logic":"爱德华·德博诺博士提出的平行思维工具：用六种颜色的帽子代表六种不同的思维模式（白-事实、红-情感、黑-风险、黄-价值、绿-创意、蓝-控制），让团队在同一时间只戴同一顶帽子，避免争吵和混乱，确保全面思考每一个议题，提高会议效率和决策质量。","steps":"[{\"name\": \"白帽-事实与信息\", \"description\": \"中立客观，只关注事实和数据，不掺入主观判断\"}, {\"name\": \"红帽-情感与直觉\", \"description\": \"表达感受、直觉和情绪，不需要理由和逻辑\"}, {\"name\": \"黑帽-谨慎与风险\", \"description\": \"批判思维，指出风险、困难和潜在问题，保守谨慎\"}, {\"name\": \"黄帽-积极与乐观\", \"description\": \"正向思维，关注价值、利益和可行性，积极寻找机会\"}, {\"name\": \"绿帽-创意与创新\", \"description\": \"发散思维，提出新想法、新方案、新思路，鼓励创新\"}, {\"name\": \"蓝帽-控制与组织\", \"description\": \"管理思维过程，控制讨论节奏，总结归纳，指挥方向\"}]","itto":"{\"tools\": [\"团队讨论\", \"角色扮演\", \"会议引导\"], \"inputs\": [\"讨论议题\", \"团队成员\"], \"outputs\": [\"全面决策\", \"团队共识\", \"创新方案\"]}","tools":"会议引导、卡片法、投票表决、行动事项跟踪","cases":"某产品团队评审新功能方案时引入六帽法：蓝帽主持定议程→白帽出示用户数据→红帽大家说直觉感受→黑帽指出风险和困难→黄帽讨论价值和收益→绿帽头脑风暴改进方案→蓝帽总结决策。原本 2 小时吵不出结论的会议，1 小时就达成共识并明确了行动项。","viz_type":"process","viz_config":"{}","keywords":"六顶思考帽,德博诺,思维工具,团队决策","sort_order":15,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.685+08:00","_updated_by":"()","code":"DEC-THK-001","aliases":"六顶思考帽","summary":"爱德华·德博诺博士提出的平行思维工具：用六种颜色的帽子代表六种不同的思维模式（白-事实、红-情感、黑-风险、黄-价值、绿-创意、蓝-控制），让团队在同一时间只戴","problem_statement":"团队讨论混乱不堪，同时在说事实、说感受、说风险、说创意，各说各话、效率极低，还容易变成争吵；六顶思考帽用六种颜色代表六种思维模式，让团队同一时间只戴一顶帽子、同一维度思考，提升思考效率和质量。","triggers":"思路卡壳、分析不透彻、缺乏框架","applicable":"团队会议决策、产品方案评审、创新头脑风暴、问题分析讨论、战略规划会议。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某产品团队评审新功能方案时引入六帽法：蓝帽主持定议程→白帽出示用户数据→红帽大家说直觉感受→黑帽指出风险和困难→黄帽讨论价值和收益→绿帽头脑风暴改进方案→蓝帽总结决策。原本 2 小时吵不出结论的会议，","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"DECIDE"},{"id":"a7e07854-7d26-4914-8492-5eade4d2f583","name":"GTD 时间管理","category":"时间管理","scene":"任务管理、时间管理、效率提升、工作生活平衡、信息过载的场景","core_logic":"GTD（Getting Things Done）由戴维·艾伦提出，是一套任务管理和时间管理系统。核心思想是：把所有待办事项从大脑中「收集」到外部系统中，通过「整理-组织-回顾-执行」的流程，让大脑从记忆和焦虑中解放出来，专注于当下的执行。GTD的五大步骤：收集（Capture）→ 厘清（Clarify）→ 组织（Organize）→ 反思（Reflect）→ 执行（Engage）。它不仅是效率工具，更是一种让生活井然有序的生活方式。","steps":"[{\"name\": \"收集(Capture)\", \"description\": \"将所有想法、任务、待办、邮件、信息全部收集到「收件箱」中，大脑只用来思考不用来记忆\"}, {\"name\": \"厘清(Clarify)\", \"description\": \"逐一处理收件箱中的事项：这是什么？需要行动吗？是一件事还是多个？下一步行动是什么？\"}, {\"name\": \"组织(Organize)\", \"description\": \"将厘清后的事项分类放入不同的清单：下一步行动、等待中、项目、 someday/maybe、参考资料等\"}, {\"name\": \"反思(Reflect)\", \"description\": \"定期（每日/每周）回顾清单，更新状态，清理垃圾，规划新一周，确保系统不过期\"}, {\"name\": \"执行(Engage)\", \"description\": \"根据情境、时间、精力、优先级从清单中选择合适的任务执行\"}, {\"name\": \"管理项目(Projects)\", \"description\": \"对于需要多步完成的项目，维护项目清单，确保每个项目都有下一步行动\"}, {\"name\": \"情境化执行\", \"description\": \"根据地点、工具、时间、精力等情境因素，选择最合适的任务来做\"}, {\"name\": \"每周回顾\", \"description\": \"每周进行一次全面回顾：清空收件箱、更新各清单、回顾日程、展望未来\"}]","itto":"{\"tools\": [\"GTD工具(OmniFocus/Things/Todoist/Notion)、收集箱、项目清单、每周回顾模板\"], \"inputs\": [\"各种待办事项、信息、想法、邮件、任务\"], \"outputs\": [\"清空的大脑、井然有序的任务系统、高效执行、掌控感、心流状态\"]}","tools":"Todoist/Things/OmniFocus、Notion、滴答清单、日历、周回顾模板","cases":"全球数百万知识工作者实践、企业效率培训、个人生产力提升","viz_type":"process","viz_config":"{}","keywords":"GTD,Getting Things Done,时间管理,任务管理,效率提升,戴维艾伦,搞定","sort_order":111,"_created_at":"2026-09-16T16:20:51.097+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.693+08:00","_updated_by":"()","code":"LEARN-GTD-001","aliases":"GTD,Getting Things Done,搞定,戴维艾伦,时间管理,任务管理","summary":"收集-整理-组织-回顾-执行五步清空大脑，让事情有条不紊地推进","problem_statement":"脑子里装了一堆待办事项，焦虑不堪又忘东忘西，事情越多越乱，不知道从哪里下手，效率低下；GTD通过收集-整理-组织-回顾-执行五步清空大脑，将所有待办系统化管理，让事情有条不紊地推进。","triggers":"GTD,Getting Things Done,时间管理,任务管理,效率,戴维艾伦,搞定","applicable":"知识工作者、管理者、多任务处理者、需要高效管理事务的人、信息过载人群","not_applicable":"工作内容单一重复性强的岗位、不需要管理复杂事务的学生党、极度自律且事务简单的人","related_frameworks":"番茄工作法,艾森豪威尔矩阵,帕累托法则,OKR目标与关键结果,深度工作","templates":"GTD清单模板、每周回顾模板、项目规划模板、情境清单模板","limitations":"系统维护需要时间和纪律；工具选择和搭建有学习成本；对执行层面关注多对战略层面关注少；收集过度可能导致系统臃肿","mastery_level":"L2","last_used_date":null,"domain_code":"LEARN"},{"id":"a99d3e22-f09d-4a0f-9a44-0eb3884fd243","name":"塔克曼团队发展模型","category":"团队管理","scene":"团队建设、团队诊断、新团队辅导的场景","core_logic":"塔克曼模型描述了团队发展的五个阶段：形成期（成员试探了解）、震荡期（冲突分歧出现）、规范期（建立规则协作）、执行期（高效产出）、解散期（任务结束告别）。不同阶段需要不同的领导风格。","steps":"[{\"name\": \"形成期：建立目标，互相认识\", \"description\": \"\"}, {\"name\": \"震荡期：管理冲突，建立信任\", \"description\": \"\"}, {\"name\": \"规范期：明确规则，形成共识\", \"description\": \"\"}, {\"name\": \"执行期：授权赋能，高效产出\", \"description\": \"\"}, {\"name\": \"解散期：总结庆祝，知识沉淀\", \"description\": \"\"}]","itto":"{\"tools\": [\"团队引导、冲突管理\"], \"inputs\": [\"新组建的团队\"], \"outputs\": [\"高效团队、绩效成果\"]}","tools":"团队建设活动、冲突管理、教练技术、复盘","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"塔克曼,团队发展,五阶段模型,团队建设,团队成熟度","sort_order":1,"_created_at":"2026-09-15T18:34:20.044+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.701+08:00","_updated_by":"()","code":"TEAM-DEV-001","aliases":"塔克曼模型,团队发展五阶段,Tuckman","summary":"团队从组建到高效协作的五个发展阶段：形成—震荡—规范—执行—解散","problem_statement":"新组建的团队问题频出，不知道是正常现象还是管理出了问题，一味施压反而适得其反，团队迟迟进入不了状态；塔克曼模型揭示团队从形成-震荡-规范-执行-解散的五阶段发展规律，让管理者对症施策。","triggers":"塔克曼,团队发展,五阶段,团队建设,团队成熟度","applicable":"新团队组建、团队绩效提升、团队诊断、团队领导培养","not_applicable":"个人工作、极短期临时团队","related_frameworks":"情境领导模型,GROW 教练模型,贝尔宾团队角色","templates":"团队发展阶段诊断表","limitations":"模型是理想化的线性过程，实际团队可能在阶段间来回；忽略了任务性质等其他因素","mastery_level":"L3","last_used_date":null,"domain_code":"TEAM"},{"id":"a9f4049f-21f1-4494-a28b-a7524710b1d4","name":"过程追踪法","category":"科研写作","scene":"因果机制研究、单一案例深度分析、政策过程研究、历史事件分析、质性研究方法论文","core_logic":"过程追踪（Process Tracing）是质性研究中用于检验和发现因果机制的核心方法。它不满足于\"X导致Y\"的相关性结论，而是要打开黑箱，详细追踪从X到Y之间每一步的因果链条，用实证证据检验因果机制的每一环是否真实存在。是提高质性研究内部效度的利器。","steps":"[{\"name\": \"理论化因果机制\", \"description\": \"先明确要检验或发现的因果机制，将X→Y之间的过程分解为若干步骤\"}, {\"name\": \"收集过程证据\", \"description\": \"系统收集关于过程每一步的实证证据，包括事件顺序、行动者决策、中间结果等\"}, {\"name\": \"检验因果步骤\", \"description\": \"逐环节检验机制是否按理论预期运行，用证据确认或否定每个步骤\"}, {\"name\": \"排除替代解释\", \"description\": \"检验并排除其他可能的因果机制和解释，提高内部效度\"}, {\"name\": \"得出因果结论\", \"description\": \"基于证据检验结果，判断因果机制是否成立，并讨论理论意义\"}]","itto":"{\"tools\": [\"过程追踪法\", \"因果机制分析\", \"贝叶斯过程追踪\", \"证据检验\"], \"inputs\": [\"因果机制假设\", \"过程性数据\", \"案例资料\"], \"outputs\": [\"过程追踪研究\", \"因果机制验证\"]}","tools":"过程追踪四步法、贝叶斯过程追踪、箍测试（hoop test）、烟枪测试（smoking gun test）","cases":"研究\"为什么某项政策成功落地\"：不是简单看政策输入和结果输出，而是用过程追踪法详细追踪政策从制定到执行到见效的全过程——每一步发生了什么、谁做了什么决策、遇到了什么障碍、如何克服的，完整重建因果链条，解释成功的真正机制。","viz_type":"process","viz_config":"{}","keywords":"过程追踪,因果机制,过程追踪法,贝叶斯,内部效度,案例比较","sort_order":155,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.708+08:00","_updated_by":"()","code":"RES-036","aliases":"过程追踪","summary":"过程追踪（Process Tracing）是质性研究中用于检验和发现因果机制的核心方法。它不满足于\"X导致Y\"的相关性结论，而是要打开黑箱，详细追踪从X到Y之间","problem_statement":"质性研究只停留在相关性描述，打不开因果机制的黑箱，说不清X到底是怎么导致Y的，研究深度不足；过程追踪法通过详细追踪从原因到结果之间的因果链条和机制过程，打开黑箱检验因果机制。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"因果机制研究、单一案例深度分析、政策过程研究、历史事件分析、质性研究方法论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"研究\"为什么某项政策成功落地\"：不是简单看政策输入和结果输出，而是用过程追踪法详细追踪政策从制定到执行到见效的全过程——每一步发生了什么、谁做了什么决策、遇到了什么障碍、如何克服的，完整重建因果链条，","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"aa3ac3df-93c2-43aa-bdff-05f2a1c61d45","name":"SQ3R 阅读法","category":"学习方法","scene":"教科书阅读、学术文献研读、深度阅读、知识学习的场景","core_logic":"SQ3R是由Francis Robinson提出的经典阅读方法，包含五个步骤：Survey(浏览概览)→Question(提出问题)→Read(主动阅读)→Recite(复述回忆)→Review(复习巩固)。通过主动阅读和回忆，大幅提升阅读理解和记忆效果。","steps":"[{\"name\": \"S 浏览：快速通读，了解结构和重点\", \"description\": \"\"}, {\"name\": \"Q 提问：将标题转化为问题\", \"description\": \"\"}, {\"name\": \"R 阅读：带着问题主动阅读\", \"description\": \"\"}, {\"name\": \"R 复述：合上书用自己的话复述\", \"description\": \"\"}, {\"name\": \"R 复习：复习笔记，巩固记忆\", \"description\": \"\"}]","itto":"{\"tools\": [\"笔记工具、思维导图\"], \"inputs\": [\"待阅读的书籍/文献\"], \"outputs\": [\"读书笔记、深度理解\"]}","tools":"笔记、思维导图、康奈尔笔记法、高亮标注","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"SQ3R,阅读法,高效阅读,主动阅读,深度学习","sort_order":5,"_created_at":"2026-09-15T18:34:26.569+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.716+08:00","_updated_by":"()","code":"LRN-STU-004","aliases":"SQ3R,高效阅读,浏览提问阅读复述复习","summary":"浏览—提问—阅读—复述—复习的高效阅读理解五步阅读法","problem_statement":"读书从头到尾一字不漏地读，读完就忘，抓不住重点，花了大量时间却收获甚微，阅读效率极其低下；SQ3R通过浏览-提问-阅读-复述-复习五步，带着问题主动阅读、主动输出，阅读理解和记忆效率大幅提升。","triggers":"SQ3R,阅读法,高效阅读,主动阅读,阅读理解","applicable":"教科书学习、学术阅读、专业书籍研读、考试备考","not_applicable":"休闲阅读、快速浏览类阅读、小说文学类","related_frameworks":"费曼学习法,间隔重复,卡片盒笔记法（Zettelkasten）","templates":"SQ3R阅读笔记模板","limitations":"阅读速度较慢；需要主动投入精力；不适合浅阅读场景","mastery_level":"L2","last_used_date":null,"domain_code":"LEARN"},{"id":"ab1b113b-7db1-4663-976b-f292f5b040ed","name":"CODE 知识加工","category":"知识管理","scene":"个人知识管理、内容创作、学习输出的场景","core_logic":"CODE是Tiago Forte在Building a Second Brain中提出的知识加工四步法：Capture（捕获，收集有价值的信息）→Organize（组织，按PARA等方式整理）→Distill（提炼，逐步浓缩为精华）→Express（表达，输出为作品或应用于生活）。强调知识的使用价值。","steps":"[{\"name\": \"C 捕获：收集触动你的信息\", \"description\": \"\"}, {\"name\": \"O 组织：按PARA等方式归类\", \"description\": \"\"}, {\"name\": \"D 提炼：用渐进式总结浓缩精华\", \"description\": \"\"}, {\"name\": \"E 表达：将知识应用或输出为作品\", \"description\": \"\"}, {\"name\": \"迭代：根据反馈继续优化\", \"description\": \"\"}]","itto":"{\"tools\": [\"笔记工具、加工方法\"], \"inputs\": [\"信息输入、学习资源\"], \"outputs\": [\"知识作品、知识应用\"]}","tools":"笔记软件、PARA、渐进式总结、输出工具","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"CODE,知识加工,第二大脑,知识输出,Tiago Forte","sort_order":4,"_created_at":"2026-09-15T18:34:26.603+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.724+08:00","_updated_by":"()","code":"KNOW-CODE-001","aliases":"CODE,知识加工,捕获组织提炼表达","summary":"Tiago Forte提出的四步知识创造方法论","problem_statement":"收集了大量资料但没有加工，知识只进不出不成体系，学了很多但用不出来，囤积焦虑严重；CODE方法论通过捕捉-组织-提炼-表达四步，将原始信息加工为可用的知识资产并输出创造价值。","triggers":"CODE,知识加工,第二大脑,知识输出,Tiago Forte","applicable":"个人知识管理、内容创作、学习产出、知识工作者","not_applicable":"纯娱乐性信息消费、不需要知识产出的人群","related_frameworks":"PARA 分类法,渐进式总结,卡片盒笔记法（Zettelkasten）","templates":"CODE知识加工流程图","limitations":"需要持续投入时间；提炼环节需要判断力；输出质量需要练习","mastery_level":"L2","last_used_date":null,"domain_code":"KNOW"},{"id":"ada2baab-6541-4272-bbe6-42a13eb2a3e1","name":"平衡计分卡 BSC","category":"战略执行","scene":"战略落地、绩效管理、组织诊断、战略地图制定的场景","core_logic":"平衡计分卡（BSC）由卡普兰和诺顿提出，是一种战略绩效管理工具，它打破了传统只关注财务指标的做法，从四个维度平衡地衡量组织绩效：①财务维度（股东如何看待我们？）②客户维度（客户如何看待我们？）③内部流程维度（我们必须擅长什么？）④学习与成长维度（我们能否持续创造价值？）。四个维度之间存在因果关系，形成战略地图，帮助组织把战略转化为可执行的行动。","steps":"[{\"name\": \"明确组织战略\", \"description\": \"梳理和明确组织的战略目标和发展方向\"}, {\"name\": \"绘制战略地图\", \"description\": \"用因果关系链描述四个维度的目标如何相互作用，最终实现战略\"}, {\"name\": \"设定财务维度目标和指标\", \"description\": \"确定财务层面的关键目标和衡量指标（如营收增长、利润率、ROI等）\"}, {\"name\": \"设定客户维度目标和指标\", \"description\": \"确定客户层面的关键目标和衡量指标（如满意度、留存率、市场份额等）\"}, {\"name\": \"设定内部流程维度目标和指标\", \"description\": \"确定内部核心流程的关键目标和衡量指标（如质量、效率、周期等）\"}, {\"name\": \"设定学习与成长维度目标和指标\", \"description\": \"确定组织能力建设的关键目标和衡量指标（如员工能力、系统、文化等）\"}, {\"name\": \"分解到部门和个人\", \"description\": \"将公司级BSC分解到各部门和岗位，形成纵向一致的指标体系\"}, {\"name\": \"定期回顾与调整\", \"description\": \"定期（月度/季度）回顾指标完成情况，分析偏差，调整策略和行动\"}]","itto":"{\"tools\": [\"战略地图、BSC四维度框架、KPI指标库、数据仪表盘、战略回顾会\"], \"inputs\": [\"组织战略、行业标杆、历史数据、各部门参与\"], \"outputs\": [\"战略地图、平衡计分卡指标体系、部门/个人考核指标、战略执行监控报告\"]}","tools":"战略地图、KPI指标设计、数据仪表盘、战略执行会议、标杆管理","cases":"美孚石油、可口可乐、西门子、华润集团、大量世界500强企业","viz_type":"hierarchy","viz_config":"{}","keywords":"BSC,平衡计分卡,战略地图,卡普兰诺顿,绩效管理,战略执行,四个维度","sort_order":93,"_created_at":"2026-09-16T16:20:51.018+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.732+08:00","_updated_by":"()","code":"PM-BSC-001","aliases":"BSC,平衡计分卡,Balanced Scorecard,卡普兰诺顿,战略绩效管理","summary":"从财务、客户、内部流程、学习成长四个维度平衡地衡量组织绩效和战略落地","problem_statement":"绩效考核只看财务指标，短视行为严重，客户、流程、人才这些长期价值没人管，战略落不了地；BSC从财务、客户、内部流程、学习成长四个维度平衡地衡量绩效，确保短期结果与长期战略一致。","triggers":"BSC,平衡计分卡,战略地图,卡普兰,绩效考核,四个维度,战略执行","applicable":"中大型企业战略管理、集团公司绩效管理、非营利组织、需要战略落地的组织、政府机构","not_applicable":"初创公司方向未定、小型团队、快速变化的行业、难以量化指标的创意型组织","related_frameworks":"OKR目标与关键结果,KPI,OGSM,战略地图,PDCA循环","templates":"BSC平衡计分卡模板、战略地图模板、部门级BSC模板、指标分解表","limitations":"实施复杂耗时耗力；指标设计难度大，容易指标过多或指标偏离战略；数据收集成本高；需要高层持续推动；对中小企业可能过于复杂","mastery_level":"L2","last_used_date":null,"domain_code":"PM"},{"id":"adff961b-e6a5-4bc9-863c-117208bd0e86","name":"交易成本理论","category":"科研写作","scene":"组织经济学研究、企业边界分析、供应链治理、制度分析、公共服务外包研究","core_logic":"科斯开创、威廉姆森发展的交易成本经济学认为，市场和企业是两种可以相互替代的治理方式，选择哪种取决于交易成本的大小。交易的三个关键维度（资产专用性、交易频率、不确定性）决定了交易成本，进而决定了最优的治理结构（市场/混合/企业）。","steps":"[{\"name\": \"交易的三个维度\", \"description\": \"资产专用性、交易频率、不确定性——这三个维度决定了交易成本的高低\"}, {\"name\": \"交易成本类型\", \"description\": \"事前成本（搜寻、谈判、签约成本）和事后成本（监督、执行、调整成本）\"}, {\"name\": \"治理结构选择\", \"description\": \"市场（低资产专用性）→ 混合/关系契约（中等）→ 企业层级（高资产专用性）\"}, {\"name\": \"比较制度分析\", \"description\": \"不同治理结构在节约交易成本上的比较优势，决定了组织边界\"}]","itto":"{\"tools\": [\"交易成本经济学\", \"比较制度分析\", \"案例研究\", \"计量检验\"], \"inputs\": [\"交易特征信息\", \"治理方式选择\", \"制度环境\"], \"outputs\": [\"交易成本分析报告\", \"治理结构选择建议\"]}","tools":"交易成本测度、案例研究、比较制度分析、计量经济学","cases":"企业自制还是外包？用交易成本理论分析：如果零部件的资产专用性高（需要专用设备和模具）、交易频率高、不确定性大，则自制（企业内治理）更节约交易成本；如果是标准化产品、资产专用性低，则市场采购更高效。","viz_type":"process","viz_config":"{}","keywords":"交易成本,科斯,威廉姆森,治理结构,资产专用性,企业边界,管理社科","sort_order":134,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.739+08:00","_updated_by":"()","code":"RES-THY-002","aliases":"交易成本","summary":"科斯开创、威廉姆森发展的交易成本经济学认为，市场和企业是两种可以相互替代的治理方式，选择哪种取决于交易成本的大小。交易的三个关键维度（资产专用性、交易频率、不确","problem_statement":"研究企业和市场的关系只看生产成本，忽视交易成本的影响，解释不了为什么有些活动在企业内做而有些在市场上做；交易成本理论从资产专用性、交易频率、不确定性三个维度解释治理方式的选择。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"组织经济学研究、企业边界分析、供应链治理、制度分析、公共服务外包研究","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"企业自制还是外包？用交易成本理论分析：如果零部件的资产专用性高（需要专用设备和模具）、交易频率高、不确定性大，则自制（企业内治理）更节约交易成本；如果是标准化产品、资产专用性低，则市场采购更高效。","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"af11c604-cc43-48bb-a35d-f80f4c4ca59f","name":"OKR 目标与关键结果","category":"目标管理","scene":"企业目标管理、团队对齐、个人绩效管理、季度规划的场景","core_logic":"OKR（Objectives and Key Results）是一套目标管理框架，由英特尔的安迪·格鲁夫（Andy Grove）创立，后经约翰·杜尔（John Doerr）引入谷歌并推广至全球。核心要素：O（目标）——明确我们要做什么，要有挑战性且鼓舞人心，是定性的；KR（关键结果）——如何衡量目标是否达成，必须是可量化的。OKR强调：公开透明、上下对齐、挑战性目标（70%完成度即优秀）、不与绩效直接挂钩、聚焦少数关键目标。","steps":"[{\"name\": \"明确使命与战略\", \"description\": \"从公司使命和战略出发，确定本周期的战略优先级\"}, {\"name\": \"制定公司级OKR\", \"description\": \"管理层制定公司层面的3-5个目标(O)和对应的关键结果(KR)\"}, {\"name\": \"部门/团队对齐OKR\", \"description\": \"各部门基于公司OKR制定自己的OKR，确保对齐和支撑\"}, {\"name\": \"个人OKR制定\", \"description\": \"员工基于团队OKR和个人职责制定个人OKR\"}, {\"name\": \"公开公示\", \"description\": \"所有OKR全公司公开透明，任何人都能看到其他人的OKR\"}, {\"name\": \"季度中检查\", \"description\": \"季度中期检查进度，识别风险，必要时调整KR的优先级\"}, {\"name\": \"季度末评分\", \"description\": \"季度末对每个KR打分（0-1.0），评估目标完成度\"}, {\"name\": \"复盘与迭代\", \"description\": \"复盘本周期OKR的经验教训，为下一个周期做准备\"}]","itto":"{\"tools\": [\"OKR模板、OKR软件(Gtmhub/Worktile/飞书OKR)、对齐会议、复盘会\"], \"inputs\": [\"战略方向、业务优先级、团队能力、历史数据\"], \"outputs\": [\"公司/团队/个人OKR、季度进度报告、复盘总结、目标对齐共识\"]}","tools":"OKR工具软件、季度规划会议、复盘方法论、绩效沟通","cases":"谷歌、英特尔、字节跳动、领英、亚马逊、Spotify","viz_type":"hierarchy","viz_config":"{}","keywords":"OKR,目标与关键结果,目标管理,谷歌,对齐,聚焦,挑战性目标","sort_order":91,"_created_at":"2026-09-16T16:20:50.996+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.747+08:00","_updated_by":"()","code":"PM-OKR-001","aliases":"OKR,目标与关键成果,Objectives and Key Results,谷歌OKR,英特尔OKR","summary":"英特尔首创、谷歌推广的目标管理方法，目标对齐与结果量化驱动组织聚焦和突破","problem_statement":"目标和执行脱节，员工不知道自己的工作和公司战略有什么关系，目标模糊无法衡量，年底不知道做得好不好；OKR通过目标对齐和关键结果量化，让组织聚焦最重要的事，从上到下对齐、从下到上支撑。","triggers":"OKR,目标管理,关键结果,Objectives,Key Results,谷歌,目标对齐,季度目标","applicable":"科技公司、创新型组织、知识密集型团队、需要快速迭代的业务、跨部门协作项目","not_applicable":"重复性强的流水线工作、严格的传统制造业、需要精确考核的销售团队、执行力文化弱的组织","related_frameworks":"SMART目标设定,MBO目标管理,平衡计分卡BSC,OGSM,KPI","templates":"OKR模板、OKR设定指南、季度OKR复盘模板、OKR评分标准","limitations":"不是绩效考核工具（与绩效挂钩会扭曲行为）；需要文化配合和持续投入；设定有挑战性的O不容易；过度量化可能忽视质的方面；实施初期容易做成KPI","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"b061bf80-e2e2-48de-b637-457e25ddb894","name":"逆向思维","category":"思维方法","scene":"风险规避、方案校验、创新思考的场景","core_logic":"与其思考如何成功，不如先思考如何失败，然后避免那些导致失败的因素。通过逆向推导识别隐藏的风险和错误，提高决策的稳健性。","steps":"[{\"name\": \"明确正向目标\", \"description\": \"\"}, {\"name\": \"反过来想：如何会失败/搞砸\", \"description\": \"\"}, {\"name\": \"列出所有导致失败的因素\", \"description\": \"\"}, {\"name\": \"制定避免这些失败的措施\", \"description\": \"\"}, {\"name\": \"将反向洞察融入正向方案\", \"description\": \"\"}]","itto":"{\"tools\": [\"逆向提问法\"], \"inputs\": [\"目标/方案\"], \"outputs\": [\"风险清单、改进方案\"]}","tools":"逆向提问清单、事前验尸法、魔鬼代言人","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"逆向思维,反向思考,风险规避,失败分析,决策校验","sort_order":13,"_created_at":"2026-09-15T18:34:03.124+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.755+08:00","_updated_by":"()","code":"META-THK-005","aliases":"逆向思维,反向思维,Inversion","summary":"从反面思考问题，避免失败比追求成功更重要","problem_statement":"总是正向思考如何成功，忽略了哪些因素会导致失败，结果踩坑不断、事与愿违，努力越多损失越大；逆向思维从反面思考问题——先想清楚怎样会失败，然后主动避免那些失败因素，反而更容易接近成功。","triggers":"逆向,反向,避免失败,风险,反推","applicable":"投资决策、项目规划、人生规划、方案评审","not_applicable":"需要积极正向激励的场景、纯粹创造性思维场景","related_frameworks":"风险矩阵,决策矩阵,第一性原理","templates":"逆向思考检查清单","limitations":"可能导致过度保守；适合作为补充思维而非主导方法","mastery_level":"L2","last_used_date":null,"domain_code":"META"},{"id":"b0ed2574-ab09-4ff5-bbde-aabbda6f449d","name":"鱼骨图（因果分析）","category":"风险分析","scene":"质量问题根因分析、生产故障排查、项目延期原因分析、产品体验问题诊断、团队绩效问题诊断。","core_logic":"又称石川图/因果图，由日本质量管理大师石川馨提出。将问题（结果）放在鱼头位置，从「人、机、料、法、测、环」六大主因（5M+1E）出发，层层深挖细分原因，通过团队头脑风暴系统地梳理所有可能导致问题的因素，帮助找到根本原因。","steps":"[]","itto":"{\"tools\": [\"头脑风暴\", \"5Why\", \"专家访谈\"], \"inputs\": [\"待分析问题\", \"团队成员\"], \"outputs\": [\"因果图\", \"根因分析报告\"]}","tools":"头脑风暴、5Why 分析法、散点图验证、柏拉图排序","cases":"某 App 用户投诉率上升，团队用鱼骨图分析：人（客服培训不足）、机（系统响应慢）、料（用户文档不全）、法（投诉处理流程长）、测（无用户满意度监控）、环（近期竞品降价分流），最终定位核心原因是「投诉处理流程需 3 天」，优化后缩短到 4 小时，投诉率下降 60%。","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"问题/结果\", \"description\": \"明确要分析的问题，写在鱼头位置\"}, {\"name\": \"六大主因（5M+1E）\", \"items\": [\"人 Man：人员因素\", \"机 Machine：设备工具\", \"料 Material：物料资源\", \"法 Method：方法流程\", \"测 Measurement：测量标准\", \"环 Environment：环境因素\"]}, {\"name\": \"细分原因\", \"items\": [\"技能不足\", \"流程缺陷\", \"设备老化\", \"沟通不畅\", \"培训不够\", \"制度缺失\"]}]}","keywords":"鱼骨图,因果分析,石川图,根本原因","sort_order":12,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.763+08:00","_updated_by":"()","code":"SOL-CAU-001","aliases":"鱼骨图","summary":"又称石川图/因果图，由日本质量管理大师石川馨提出。将问题（结果）放在鱼头位置，从「人、机、料、法、测、环」六大主因（5M+1E）出发，层层深挖细分原因，通过团队","problem_statement":"找原因东找一个西找一个，零散不系统，找不到真正的主要原因，问题分析不深入、解决不彻底；鱼骨图从人、机、料、法、测、环六大主因出发层层深挖，系统梳理所有可能原因、聚焦关键因素。","triggers":"风险不明、决策犹豫、不确定性高","applicable":"质量问题根因分析、生产故障排查、项目延期原因分析、产品体验问题诊断、团队绩效问题诊断。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某 App 用户投诉率上升，团队用鱼骨图分析：人（客服培训不足）、机（系统响应慢）、料（用户文档不全）、法（投诉处理流程长）、测（无用户满意度监控）、环（近期竞品降价分流），最终定位核心原因是「投诉处","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"SOLVE"},{"id":"b0f68cdb-d850-4371-9d2c-23c52049ea2c","name":"二八法则（帕累托原则）","category":"效率工具","scene":"时间管理、资源分配、客户管理、产品功能优先级排序、销售业绩分析、问题排查。","core_logic":"意大利经济学家帕累托发现的普遍规律：在很多领域，80% 的结果来自 20% 的原因。例如 80% 的营收来自 20% 的客户，80% 的 bug 来自 20% 的代码模块。应用的关键是识别并聚焦那 20% 的关键因素，放弃或减少在 80% 次要因素上的投入。","steps":"[]","itto":"{\"tools\": [\"优先级矩阵\", \"价值评估\", \"ABC分类法\"], \"inputs\": [\"任务清单\", \"资源评估\"], \"outputs\": [\"高价值任务清单\", \"时间优化方案\"]}","tools":"ABC 分类法、价值排序矩阵、四象限工作法、数据分析","cases":"某 SaaS 公司分析客户收入发现：前 20% 的大客户贡献了 82% 的营收。据此调整客户成功策略——将 80% 的客户成功人力投入到 Top 20% 大客户，建立专属服务团队，其余客户采用自助+标准化服务，客户续费率提升了 25%。","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"80% 的成果\", \"description\": \"来自 20% 的关键因素——抓重点，做最重要的事\"}, {\"name\": \"关键的20%\", \"items\": [\"最重要的客户\", \"核心产品功能\", \"高价值任务\", \"关键人才\", \"主要收入来源\"]}, {\"name\": \"次要的80%\", \"items\": [\"普通客户\", \"边缘功能\", \"低价值事务\", \"琐碎邮件\", \"日常琐事\"]}]}","keywords":"二八法则,帕累托,时间管理,效率","sort_order":11,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.771+08:00","_updated_by":"()","code":"META-EFF-001","aliases":"二八法则","summary":"意大利经济学家帕累托发现的普遍规律：在很多领域，80% 的结果来自 20% 的原因。例如 80% 的营收来自 20% 的客户，80% 的 bug 来自 20% ","problem_statement":"做事平均用力，不分轻重缓急，80%的时间花在不重要的事情上，忙忙碌碌却没什么产出，效率低下；二八法则指出80%的结果来自20%的原因，帮你识别关键的少数，把精力聚焦在最有价值的事情上。","triggers":"时间不够、注意力分散、产出低下","applicable":"时间管理、资源分配、客户管理、产品功能优先级排序、销售业绩分析、问题排查。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"某 SaaS 公司分析客户收入发现：前 20% 的大客户贡献了 82% 的营收。据此调整客户成功策略——将 80% 的客户成功人力投入到 Top 20% 大客户，建立专属服务团队，其余客户采用自助+标","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"META"},{"id":"b125017c-344d-4f0f-a71b-f3c8e6426857","name":"Zachman 框架","category":"系统架构","scene":"企业架构建模、架构描述完整性检查、架构知识体系梳理的场景","core_logic":"Zachman框架是一个6行×6列的矩阵：行代表不同视角（范围/业务/系统/技术/组件/实例），列代表不同方面（数据/功能/网络/人员/时间/动机），共36个单元格，每个单元格描述架构的一个特定视角，确保架构描述的完整性。","steps":"[{\"name\": \"明确架构描述的目标和受众\", \"description\": \"\"}, {\"name\": \"确定需要覆盖的Zachman行列\", \"description\": \"\"}, {\"name\": \"逐格填写架构描述内容\", \"description\": \"\"}, {\"name\": \"检查覆盖完整性\", \"description\": \"\"}, {\"name\": \"输出架构文档\", \"description\": \"\"}]","itto":"{\"tools\": [\"Zachman矩阵、架构工具\"], \"inputs\": [\"架构需求、利益相关者\"], \"outputs\": [\"完整的架构描述文档\"]}","tools":"架构建模工具、EA工具、矩阵分析法","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"描述方面(数据/功能/网络/人员/时间/动机)\", \"y_label\": \"视角层次(范围/业务/系统/技术/组件/实例)\", \"quadrants\": {\"q1\": \"架构描述单元格\"}}","keywords":"Zachman,企业架构,分类框架,架构视图,矩阵","sort_order":2,"_created_at":"2026-09-15T18:34:26.425+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.778+08:00","_updated_by":"()","code":"ARCH-EA-002","aliases":"Zachman,扎克曼框架,企业架构分类框架","summary":"企业架构的分类学框架，用6×6矩阵定义架构描述的完整视角","problem_statement":"企业架构描述没有统一视角，不同角色各说各的架构，沟通成本高、架构设计有盲区，文档混乱不可用；Zachman框架用6×6矩阵定义架构描述的完整视角和分类体系，确保架构描述全面、系统、可沟通。","triggers":"Zachman,企业架构,分类学,架构矩阵,架构视图","applicable":"复杂系统架构描述、企业架构建模、架构文档体系建设","not_applicable":"小型简单系统、快速迭代的产品架构","related_frameworks":"TOGAF 企业架构,4+1 视图模型,ATAM 架构权衡分析","templates":"Zachman框架矩阵模板","limitations":"是分类框架不是方法论；36格全部完成成本极高；更适合作为检查清单","mastery_level":"L2","last_used_date":null,"domain_code":"ARCH"},{"id":"b18d76ac-4f24-4d77-9aea-d9f898de2e4b","name":"熵增定律与耗散结构","category":"思维模型","scene":"组织管理、个人成长、系统演化、对抗混乱、变革管理的场景","core_logic":"熵增定律（热力学第二定律）指出：封闭系统的熵（混乱程度）总是趋向增大，最终达到热寂（最大混乱）。普利高津的耗散结构理论进一步指出：开放系统通过与外界交换物质、能量和信息，在远离平衡态的条件下，可以自发形成有序结构（耗散结构）。对组织和个人的启示是：要对抗混乱和衰败，必须保持开放、持续输入能量、主动打破平衡、不断建立新秩序。","steps":"[{\"name\": \"识别系统状态\", \"description\": \"评估当前系统（组织/个人）的熵值水平——是有序还是混乱？\"}, {\"name\": \"判断系统开放性\", \"description\": \"系统是封闭的还是开放的？是否与外界有充分的物质/能量/信息交换？\"}, {\"name\": \"识别熵增来源\", \"description\": \"找出导致混乱增加的因素——信息不流通、组织僵化、人员懈怠等\"}, {\"name\": \"引入负熵流\", \"description\": \"从外界引入负熵：新知识、新人才、新技术、新信息、新挑战\"}, {\"name\": \"打破平衡态\", \"description\": \"主动制造适度的不平衡，激发系统的自组织能力\"}, {\"name\": \"建立耗散结构\", \"description\": \"通过持续的能量输入，让系统自发形成更高级的有序结构\"}, {\"name\": \"建立反馈机制\", \"description\": \"建立信息反馈和纠正机制，及时发现并修正偏差\"}, {\"name\": \"持续迭代进化\", \"description\": \"将对抗熵增变成持续的过程，不是一劳永逸的目标\"}]","itto":"{\"tools\": [\"开放系统思维、学习型组织、变革管理、持续改进、反馈机制\"], \"inputs\": [\"外部信息、新的能量/资源、变化的环境、学习与输入\"], \"outputs\": [\"有序的系统结构、持续进化的能力、对抗混乱的机制、组织活力\"]}","tools":"学习型组织、变革管理、PDCA循环、精益管理、反馈系统设计","cases":"华为的耗散结构管理、企业第二曲线创新、个人知识管理系统、生态系统演化","viz_type":"process","viz_config":"{}","keywords":"熵,熵增定律,耗散结构,热力学,混乱,有序,负熵,开放系统","sort_order":83,"_created_at":"2026-09-16T16:20:50.939+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.786+08:00","_updated_by":"()","code":"META-ENTROPY-001","aliases":"熵增定律,熵,热力学第二定律,耗散结构,Entropy,负熵","summary":"封闭系统必然趋向混乱，对抗混乱需要持续输入能量与秩序，适用于组织与个人管理","problem_statement":"组织和个人随着时间推移越来越混乱、效率越来越低，不理解为什么明明没做错什么却越来越差；熵增定律告诉我们封闭系统必然趋向混乱，对抗熵增需要持续输入能量与秩序，建立耗散结构。","triggers":"熵,熵增定律,耗散结构,热力学第二定律,混乱,负熵,有序,开放系统","applicable":"组织管理与变革、个人成长与自律、企业战略转型、系统设计、生态系统理解","not_applicable":"简单机械系统、物理封闭系统、短期项目不适用长期熵增视角","related_frameworks":"飞轮效应,复利思维,学习型组织,第二曲线,系统思维","templates":"熵值自评表、组织活力诊断表、负熵输入行动计划","limitations":"从物理学到社会/个人的类比有局限性；耗散结构需要持续输入能量，代价不菲；过度开放和变化也可能导致不稳定；概念容易被滥用和过度解读","mastery_level":"L1","last_used_date":null,"domain_code":"META"},{"id":"b25b4775-7297-4fb3-908e-f8230eb1070d","name":"DMAIC 六西格玛","category":"思维方法","scene":"流程改进、质量提升、运营效率优化的系统性项目","core_logic":"DMAIC是六西格玛的核心改进方法论：定义(Define)问题和目标→测量(Measure)当前绩效→分析(Analyze)根本原因→改进(Improve)设计并验证方案→控制(Control)标准化并维持成果。强调数据驱动和闭环。","steps":"[{\"name\": \"D 定义：明确问题、目标和范围\", \"description\": \"\"}, {\"name\": \"M 测量：收集数据，量化现状\", \"description\": \"\"}, {\"name\": \"A 分析：运用统计工具找根因\", \"description\": \"\"}, {\"name\": \"I 改进：设计并验证改进方案\", \"description\": \"\"}, {\"name\": \"C 控制：固化成果，建立监控机制\", \"description\": \"\"}]","itto":"{\"tools\": [\"统计分析工具、Minitab、SPC、数据采集与测量系统\"], \"inputs\": [\"流程问题、改进目标、现状数据、团队资源\"], \"outputs\": [\"流程优化方案、改进效果验证报告、控制计划、标准化作业\"]}","tools":"SPC、FMEA、DOE、假设检验、回归分析、控制图","cases":"需补充","viz_type":"cycle","viz_config":"{}","keywords":"DMAIC,六西格玛,流程改进,数据驱动,质量改进","sort_order":9,"_created_at":"2026-09-15T18:34:03.268+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.793+08:00","_updated_by":"()","code":"SOL-THK-005","aliases":"DMAIC,六西格玛,Define-Measure-Analyze-Improve-Control","summary":"六西格玛改进方法论，通过数据驱动实现流程优化","problem_statement":"流程改进凭感觉走，改来改去效果不明显，不知道问题在哪、也不知道改进了多少，质量提升停滞不前；DMAIC通过定义-测量-分析-改进-控制五步数据驱动的方法论，系统性实现流程优化和质量提升。","triggers":"六西格玛,流程改进,质量提升,数据驱动,DMAIC","applicable":"制造业质量改进、服务流程优化、运营效率提升、供应链改进","not_applicable":"创新型项目、完全没有历史数据的新业务","related_frameworks":"PDCA 循环,根本原因分析 RCA,8D 问题解决法","templates":"DMAIC项目报告模板、SIPOC图模板","limitations":"需要较强的统计基础；实施周期长；需要管理层支持和数据基础","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"b46626a2-a2c3-4198-b41f-b9eba401c844","name":"BOPPPS 课堂模型","category":"教学科研","scene":"单节课设计、微格教学、工作坊设计、培训课程设计的场景","core_logic":"BOPPPS将一节课(通常90分钟左右)划分为六个环节：Bridge-in(导入，激发兴趣)→Objective(目标，明确学习成果)→Pre-assessment(前测，了解基础)→Participatory learning(参与式学习，互动教学)→Post-assessment(后测，检验效果)→Summary(总结，回顾强化)。强调学生参与和效果检验。","steps":"[{\"name\": \"B 导入：引发兴趣，建立连接\", \"description\": \"\"}, {\"name\": \"O 目标：明确学习目标\", \"description\": \"\"}, {\"name\": \"P 前测：了解学员基础\", \"description\": \"\"}, {\"name\": \"P 参与式学习：互动练习、讨论、案例\", \"description\": \"\"}, {\"name\": \"P 后测：检验学习效果\", \"description\": \"\"}, {\"name\": \"S 总结：回顾要点，延伸应用\", \"description\": \"\"}]","itto":"{\"tools\": [\"BOPPPS六步法\"], \"inputs\": [\"教学内容、目标学员\"], \"outputs\": [\"课程设计方案、课堂活动\"]}","tools":"教学设计、互动工具、测验工具","cases":"Bridge-in, Objective, Pre-assessment, Participatory learning, Post-assessment, Summary。案例：在《项目管理》课程中，用BOPPPS设计了90分钟的一堂课。","viz_type":"process","viz_config":"{}","keywords":"BOPPPS,课堂设计,参与式学习,有效教学,六步法","sort_order":2,"_created_at":"2026-09-15T18:34:26.494+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.801+08:00","_updated_by":"()","code":"TEACH-BOPPPS-001","aliases":"BOPPPS,课堂设计,教学六步法","summary":"将课堂分为导入—目标—前测—参与—后测—总结六环节的有效教学设计模型","problem_statement":"课堂教学平铺直叙，学生注意力涣散，不知道学了什么、学得怎么样，课堂参与度低、教学效果差；BOPPPS将课堂分为导入-目标-前测-参与-后测-总结六环节，环环相扣、学生全程参与，教学效果显著提升。","triggers":"BOPPPS,课堂设计,六步法,参与式学习,有效教学","applicable":"高校教学、企业培训、工作坊、在线直播课、微课设计","not_applicable":"纯讲授式的大型讲座、自学材料","related_frameworks":"ADDIE 教学设计模型,布鲁姆认知分类法,OBE 成果导向教育","templates":"BOPPPS课堂设计模板","limitations":"更适合单节课设计；参与式学习需要教师引导能力；时间控制要求较高","mastery_level":"L3","last_used_date":null,"domain_code":"TEACH"},{"id":"b4f0e3c0-a649-44d0-97e8-80bc517848b6","name":"精益创业","category":"创新方法","scene":"创业项目、新产品开发、创新业务、快速验证假设的场景","core_logic":"精益创业由埃里克·莱斯提出，核心思想是：创业不是执行一个已验证的计划，而是在不断的探索中找到可行的商业模式。精益创业的核心循环是「构建-测量-学习」（Build-Measure-Learn）：快速构建最小可行产品（MVP）→ 用真实数据测量效果 → 从中学习并决定坚持、调整还是转型（Pivot）。它把创业从「执行计划」变成「科学实验」，用最小的成本验证关键假设。","steps":"[{\"name\": \"识别关键假设\", \"description\": \"找出创业/产品成功依赖的最关键、最不确定的假设（价值假设/增长假设）\"}, {\"name\": \"设计MVP（最小可行产品）\", \"description\": \"用最少的时间和资源构建一个能验证核心假设的最简产品版本\"}, {\"name\": \"构建MVP\", \"description\": \"快速开发/制作MVP，核心是快，而不是完美\"}, {\"name\": \"确定衡量指标\", \"description\": \"定义好什么是「成功」，用什么指标验证假设是否成立\"}, {\"name\": \"上线并测量\", \"description\": \"将MVP投放给真实用户，收集数据和反馈\"}, {\"name\": \"学习与认知\", \"description\": \"分析数据和反馈，验证假设是否成立，获得经过验证的认知\"}, {\"name\": \"决策：坚持 or 调整 or 转型\", \"description\": \"假设成立→坚持优化；部分成立→调整；不成立→转型(Pivot)换方向\"}, {\"name\": \"进入下一个循环\", \"description\": \"根据决策，进入下一轮Build-Measure-Learn循环，持续迭代\"}]","itto":"{\"tools\": [\"MVP方法、用户访谈、A/B测试、数据分析、精益画布、用户开发四步法\"], \"inputs\": [\"创意/想法、创业假设、资源团队、用户反馈渠道\"], \"outputs\": [\"经过验证的认知、迭代后的产品、明确的方向、PMF信号\"]}","tools":"MVP、用户访谈、A/B测试、数据分析、精益画布、用户开发","cases":"Dropbox（用视频验证需求）、Zappos（用假网站验证卖鞋需求）、大量硅谷创业公司、企业内部创新","viz_type":"cycle","viz_config":"{}","keywords":"精益创业,Lean Startup,MVP,Build-Measure-Learn,快速验证,转型,创业方法论","sort_order":95,"_created_at":"2026-09-16T16:20:51.041+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.809+08:00","_updated_by":"()","code":"PM-LEANSTARTUP-001","aliases":"精益创业,Lean Startup,Build-Measure-Learn,最小可行产品,MVP,快速验证","summary":"最小可行产品快速验证假设的迭代循环，Build-Measure-Learn 持续循环，降低创业失败率","problem_statement":"创业产品闭门造车，花了大量时间金钱做完美产品，上线后才发现没人要，失败率极高；精益创业用MVP快速验证假设，通过Build-Measure-Learn持续循环，用最小成本找到正确方向、降低失败率。","triggers":"精益创业,Lean Startup,MVP,Build-Measure-Learn,快速验证,转型Pivot,最小可行产品","applicable":"初创公司、新产品开发、企业内部创新、商业模式探索、互联网产品开发","not_applicable":"需求非常明确的项目、完全成熟的市场、重资产重研发长周期行业（如医药）、强监管行业","related_frameworks":"PMF产品市场契合,设计思维,蓝海战略ERRC框架,精益画布,A/B测试","templates":"精益画布模板、MVP设计模板、验证实验记录表、转型决策清单","limitations":"不适合需要大量前期投入的行业；过度MVP可能损害品牌体验；数据可能误导（样本小、偏差大）；需要快速迭代的工程能力；不是所有创新都能快速验证","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"b5e2dd96-fc44-4e4b-bbd8-ef8b609ef3c1","name":"TRIZ 理论","category":"思维方法","scene":"技术创新、产品设计、矛盾解决的场景","core_logic":"通过对百万专利的分析总结出技术系统进化的规律和解决发明问题的通用方法。核心是识别技术矛盾，用40条发明原理和矛盾矩阵找到解决方案，而不是依赖试错和灵感。","steps":"[{\"name\": \"识别问题中的技术矛盾\", \"description\": \"\"}, {\"name\": \"将矛盾转化为标准工程参数\", \"description\": \"\"}, {\"name\": \"查矛盾矩阵找到对应发明原理\", \"description\": \"\"}, {\"name\": \"应用发明原理生成解决方案\", \"description\": \"\"}, {\"name\": \"验证并优化方案\", \"description\": \"\"}]","itto":"{\"tools\": [\"矛盾矩阵、40发明原理、物场分析\"], \"inputs\": [\"技术问题/矛盾\"], \"outputs\": [\"创新解决方案\"]}","tools":"矛盾矩阵、40条发明原理、物场分析、ARIZ算法、技术进化定律","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"恶化参数\", \"y_label\": \"改善参数\", \"quadrants\": {\"q1\": \"40发明原理\"}}","keywords":"TRIZ,创新方法,发明原理,矛盾矩阵,技术进化","sort_order":15,"_created_at":"2026-09-15T18:34:03.15+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.816+08:00","_updated_by":"()","code":"META-THK-007","aliases":"TRIZ,发明问题解决理论,萃智","summary":"基于专利分析总结的系统化创新方法论","problem_statement":"创新全靠试错和灵感，效率低、成功率低，面对复杂技术问题更是无从下手，研发周期长、成本高；TRIZ基于百万专利分析总结出系统化创新规律，通过40个发明原理等工具快速找到创新突破口。","triggers":"创新,发明,矛盾,技术进化,专利","applicable":"技术研发、产品创新、工程问题、流程改进","not_applicable":"纯艺术创作、人文社会领域的非技术性问题","related_frameworks":"设计思维,第一性原理,SCAMPER 法","templates":"TRIZ矛盾分析表、40发明原理速查表","limitations":"学习曲线陡峭；主要适用于技术领域；需要结合领域知识才能有效应用","mastery_level":"L2","last_used_date":null,"domain_code":"META"},{"id":"b6ea0849-755c-4273-b95d-96037e6b80d5","name":"成本效益分析","category":"思维方法","scene":"投资决策、项目评估、政策评估等需要经济合理性判断的场景","core_logic":"将方案的所有成本和收益都尽可能量化为货币价值，计算净现值(NPV)、投资回收期、效益成本比等指标，判断方案是否经济可行以及各方案的优劣排序。","steps":"[{\"name\": \"明确备选方案和分析范围\", \"description\": \"\"}, {\"name\": \"识别所有成本和收益项\", \"description\": \"\"}, {\"name\": \"量化成本和收益（货币化）\", \"description\": \"\"}, {\"name\": \"计算NPV/ROI/回收期等指标\", \"description\": \"\"}, {\"name\": \"进行敏感性分析\", \"description\": \"\"}, {\"name\": \"得出决策结论\", \"description\": \"\"}]","itto":"{\"tools\": [\"财务计算、折现模型\"], \"inputs\": [\"备选方案、成本收益数据\"], \"outputs\": [\"经济评估报告、决策建议\"]}","tools":"NPV、IRR、回收期、敏感性分析、盈亏平衡分析","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"成本\", \"y_label\": \"收益\", \"quadrants\": {\"q1\": \"高收益高成本\", \"q2\": \"高收益低成本（理想）\", \"q3\": \"低收益低成本\", \"q4\": \"低收益高成本（避免）\"}}","keywords":"成本效益,投资回报,CBA,NPV,经济评估","sort_order":6,"_created_at":"2026-09-15T18:34:13.534+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.824+08:00","_updated_by":"()","code":"DEC-FIN-001","aliases":"成本效益分析,Cost-Benefit Analysis,CBA","summary":"通过量化比较成本和收益评估方案可行性的决策工具","problem_statement":"做决策只看收益不看成本，或者只看成本不看长远收益，拍脑袋上项目，最后发现投入产出比极低甚至亏损；成本效益分析通过量化比较各方案的成本和收益，理性评估方案可行性，让决策有据可依。","triggers":"成本效益,投资回报,ROI,NPV,经济性","applicable":"项目投资评估、公共政策评估、设备采购决策、商业计划","not_applicable":"难以量化的价值（如生命、环境）、纯粹的战略决策","related_frameworks":"决策矩阵,风险矩阵,EVM 挣值管理","templates":"成本效益分析表模板","limitations":"很多收益难以货币化；未来预测有不确定性；容易忽略非财务价值","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"b95dda72-b6ef-4884-b567-961c2bcc2872","name":"蒙特卡洛模拟","category":"问题解决","scene":"风险量化、项目工期估算、投资决策、金融风险分析、不确定性预测的场景","core_logic":"蒙特卡洛模拟以概率统计理论为基础，因摩纳哥蒙特卡洛赌场而得名（将随机过程类比为赌博游戏）。它通过对不确定变量设定概率分布，进行大量随机抽样计算，模拟成千上万种可能的结果，从而得到结果的概率分布。与单点估算不同，它不仅告诉你最可能的结果，还告诉你各种结果出现的概率，为风险决策提供量化依据。","steps":"[{\"name\": \"确定目标和输出变量\", \"description\": \"明确要分析的目标，如项目总成本、总工期、投资回报等\"}, {\"name\": \"识别关键不确定性变量\", \"description\": \"列出影响结果的主要不确定因素，如各任务工期、市场需求等\"}, {\"name\": \"定义概率分布\", \"description\": \"为每个不确定变量选择合适的概率分布（正态、三角、均匀等）和参数\"}, {\"name\": \"建立计算模型\", \"description\": \"建立输入变量与输出结果之间的数学关系模型\"}, {\"name\": \"进行随机抽样模拟\", \"description\": \"对各变量随机取值，计算对应的结果，重复数千到数万次\"}, {\"name\": \"统计结果分布\", \"description\": \"汇总所有模拟结果，生成概率分布直方图和累积概率曲线\"}, {\"name\": \"分析关键结论\", \"description\": \"分析均值、中位数、P10/P50/P90分位数、置信区间等关键指标\"}, {\"name\": \"辅助决策\", \"description\": \"基于概率分布评估风险，制定风险应对措施，优化决策\"}]","itto":"{\"tools\": [\"Excel/Google Sheets插件、Python(scipy/numpy)、@RISK、Crystal Ball、蒙特卡洛计算器\"], \"inputs\": [\"项目计划、历史数据、专家估算、变量分布假设\"], \"outputs\": [\"概率分布曲线、置信区间、敏感性分析报告、风险量化结果、决策建议\"]}","tools":"Excel + @RISK、Python(scipy/numpy)、Crystal Ball、风险分析软件","cases":"工程项目成本风险分析、股票投资组合风险评估、石油勘探投资决策、项目工期概率估算","viz_type":"chart","viz_config":"{}","keywords":"蒙特卡洛,随机模拟,概率分布,风险量化,不确定性,数据分析","sort_order":67,"_created_at":"2026-09-16T16:20:50.802+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.832+08:00","_updated_by":"()","code":"SOLVE-MONTE-001","aliases":"蒙特卡洛方法,蒙特卡洛仿真,Monte Carlo Simulation,随机模拟法","summary":"用随机抽样模拟大量可能结果，量化不确定性和风险概率分布","problem_statement":"面对不确定性只知道拍脑袋估个大概，不知道结果的概率分布和风险范围，决策心里没底；蒙特卡洛模拟通过随机抽样模拟大量可能结果，量化不确定性和风险的概率分布，让决策有据可依。","triggers":"蒙特卡洛,随机模拟,概率分布,风险量化,不确定性,项目估算,敏感性分析","applicable":"项目工期和成本估算、金融投资风险分析、供应链风险评估、工程可靠性分析、保险精算","not_applicable":"确定性问题、变量关系无法量化的问题、简单决策不需要概率分析的场景","related_frameworks":"敏感性分析,风险矩阵,期望值决策,情景规划法,贝叶斯思维","templates":"蒙特卡洛模拟Excel模板、项目工期估算模拟表、投资风险分析模板","limitations":"需要足够的历史数据或可靠的分布假设；结果质量取决于模型准确性；需要一定的统计学基础理解和解释结果","mastery_level":"L1","last_used_date":null,"domain_code":"SOLVE"},{"id":"b9d99b93-43ad-408b-afea-c0f9aa813444","name":"决策树","category":"思维方法","scene":"风险决策、投资评估、方案选择等存在不确定性的决策场景","core_logic":"将决策过程表示为树状结构：决策节点（需要选择）→ 机会节点（概率事件）→ 结果节点。通过计算每个分支的期望收益/成本，帮助决策者在不确定条件下做出最优选择。","steps":"[{\"name\": \"明确决策问题和目标\", \"description\": \"\"}, {\"name\": \"绘制决策树结构\", \"description\": \"\"}, {\"name\": \"标注各机会节点的概率\", \"description\": \"\"}, {\"name\": \"估计各结果的价值/成本\", \"description\": \"\"}, {\"name\": \"从右向左计算期望价值\", \"description\": \"\"}, {\"name\": \"选择最优路径\", \"description\": \"\"}]","itto":"{\"tools\": [\"决策树绘制、期望计算\"], \"inputs\": [\"决策问题、概率分布、收益预估\"], \"outputs\": [\"最优决策路径、期望值\"]}","tools":"决策树软件、蒙特卡洛模拟、敏感性分析","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"决策树,风险决策,期望价值,概率,决策分析","sort_order":11,"_created_at":"2026-09-15T18:34:03.293+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.84+08:00","_updated_by":"()","code":"SOL-THK-007","aliases":"决策树,Decision Tree","summary":"以树形结构展示决策路径和概率结果的决策分析工具","problem_statement":"复杂决策路径不清、概率不明，各个选项的后果和可能性说不清楚，决策全凭直觉和经验；决策树以树形结构展示决策路径、概率和结果，让复杂决策一目了然、风险和收益清晰可算。","triggers":"决策树,概率,风险,期望,选择","applicable":"投资决策、项目评估、风险管理、医疗诊断决策","not_applicable":"因素过多无法量化的复杂决策、完全定性的决策","related_frameworks":"决策矩阵,风险矩阵,成本效益分析","templates":"决策树分析模板","limitations":"概率和收益估计有主观性；树过于复杂时难以理解；忽略了非量化因素","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"b9ece594-34a4-4eb2-ac5f-216db795133f","name":"木桶原理","category":"管理思维","scene":"能力评估、组织诊断、项目风险识别、个人发展、资源优化配置的场景","core_logic":"木桶原理（短板效应）：一只木桶能盛多少水，并不取决于最长的那块木板，而是取决于最短的那块木板。任何一个组织或个人，各个部分往往是优劣不齐的，而劣势部分往往决定整个组织/个人的水平和竞争力。木桶原理提醒我们：要关注短板、补齐短板，才能提升整体水平。同时也要区分「真短板」和「假短板」——并非所有不足都需要补，要根据战略选择判断。","steps":"[{\"name\": \"界定木桶的容量\", \"description\": \"明确「木桶」要装的是什么——组织的整体效能？个人的综合能力？项目的成功概率？\"}, {\"name\": \"识别所有木板\", \"description\": \"列出构成木桶的所有木板（能力维度、关键要素、成功因素）\"}, {\"name\": \"测量各木板长度\", \"description\": \"评估每个维度/因素的当前水平，找出哪些长哪些短\"}, {\"name\": \"识别最短木板\", \"description\": \"找到对整体水平限制最大的那一块或几块短板\"}, {\"name\": \"评估短板的影响\", \"description\": \"这块短板到底限制了多少容量？是否真的是瓶颈？\"}, {\"name\": \"判断是否需要补齐\", \"description\": \"根据战略和目标判断：这块短板是否需要补？补到什么程度？是否有替代方案？\"}, {\"name\": \"制定补短板计划\", \"description\": \"制定针对性的改进计划，投入资源补齐短板\"}, {\"name\": \"验证整体提升效果\", \"description\": \"短板补齐后，重新评估整体水平，确认提升效果，再寻找下一块短板\"}]","itto":"{\"tools\": [\"能力模型、SWOT分析、差距分析、诊断评估、优先级排序\"], \"inputs\": [\"能力评估结果、各维度数据、战略目标、资源配置\"], \"outputs\": [\"短板诊断报告、改进提升计划、整体效能提升、风险降低\"]}","tools":"能力模型、差距分析、SWOT、人才盘点、诊断评估","cases":"企业能力诊断、个人职业生涯规划、项目风险识别、质量管理中的瓶颈工序","viz_type":"chart","viz_config":"{}","keywords":"木桶原理,短板效应,瓶颈,木桶理论,整体水平,能力提升","sort_order":96,"_created_at":"2026-09-16T16:20:51.051+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.847+08:00","_updated_by":"()","code":"PM-BUCKET-001","aliases":"木桶效应,木桶理论,短板理论,Law of the Bucket,Cannikin Law,短板效应","summary":"组织或个人的短板决定整体水平，识别并补齐关键短板才能提升整体效能","problem_statement":"只盯着优势和长板，忽视短板的限制作用，整体水平被最弱环节拖垮，投入产出不成正比；木桶原理指出短板决定整体容量，识别并补齐关键短板，才能有效提升组织或个人的整体效能。","triggers":"木桶原理,短板效应,木桶理论,瓶颈,短板,Law of the Bucket,整体水平","applicable":"组织能力建设、个人发展规划、项目风险管理、资源配置优化、质量管理、团队能力诊断","not_applicable":"竞争优势构建（应该发挥长板而非补短板）、创新领域（差异化比均衡更重要）、资源极其有限无法全面补齐的场景","related_frameworks":"SWOT分析,能力模型,差距分析,TOC约束理论,破窗效应","templates":"木桶原理诊断表、短板改进计划模板、能力评估矩阵","limitations":"并非所有场景都适用，有时发挥长板比补齐短板更重要；过度追求均衡可能导致平庸；不同木板之间可能有协同效应，不能简单相加；有的短板可以通过外包/合作来弥补","mastery_level":"L2","last_used_date":null,"domain_code":"PM"},{"id":"c2b3051c-a4c6-44b8-b611-527efab9d471","name":"比较历史分析","category":"科研写作","scene":"历史社会学、比较政治学、制度变迁研究、长期演化研究、经济史论文","core_logic":"比较历史分析（Comparative Historical Analysis）是社会科学中重要的研究方法，通过对不同国家/地区/时期的历史进行系统比较，揭示长期变迁的模式和机制。关注时间维度的关键概念：路径依赖、关键节点、时序性、反馈机制、制度变迁。历史制度主义是其重要理论基础。","steps":"[{\"name\": \"历史分期\", \"description\": \"将研究的历史时期划分为若干阶段，每个阶段有不同的主题和特征\"}, {\"name\": \"案例选择与时序梳理\", \"description\": \"选择具有可比性的历史案例，按时间顺序梳理其发展脉络\"}, {\"name\": \"关键节点分析\", \"description\": \"识别历史上的关键事件、转折点和路径依赖时刻\"}, {\"name\": \"跨时期比较\", \"description\": \"比较不同时期的异同，分析演进逻辑和变化机制\"}, {\"name\": \"历史解释\", \"description\": \"提供对历史变迁的因果解释，识别结构性因素和偶然性因素的作用\"}]","itto":"{\"tools\": [\"比较历史分析\", \"历史制度主义\", \"过程追踪\", \"路径依赖分析\"], \"inputs\": [\"历史文献\", \"档案资料\", \"时序数据\"], \"outputs\": [\"历史分析研究论文\", \"变迁机制解释\"]}","tools":"历史制度主义、路径依赖分析、关键节点分析、时间序列比较、过程追踪","cases":"中日韩现代化道路比较研究：比较三个国家从传统社会走向现代化的历史路径——为什么日本明治维新成功了、中国洋务运动失败了、韩国是后发追赶型？分析关键节点（开国、战争、改革）、路径依赖（制度遗产）、结构性因素（土地制度、官僚体系、外部压力）的作用。","viz_type":"process","viz_config":"{}","keywords":"比较历史分析,历史制度主义,路径依赖,历史社会学,时间序列,案例比较","sort_order":154,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.855+08:00","_updated_by":"()","code":"RES-035","aliases":"比较历史分析","summary":"比较历史分析（Comparative Historical Analysis）是社会科学中重要的研究方法，通过对不同国家/地区/时期的历史进行系统比较，揭示长期","problem_statement":"社会科学研究要么只看当下横截面、要么只讲单一国家历史，揭示不了长期因果规律和跨国差异的根源；比较历史分析通过对不同国家/地区/时期的历史进行系统比较，揭示长期制度变迁和因果机制。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"历史社会学、比较政治学、制度变迁研究、长期演化研究、经济史论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"中日韩现代化道路比较研究：比较三个国家从传统社会走向现代化的历史路径——为什么日本明治维新成功了、中国洋务运动失败了、韩国是后发追赶型？分析关键节点（开国、战争、改革）、路径依赖（制度遗产）、结构性因","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"c427a1b4-6817-4961-9d6b-c327db6f8b75","name":"刻意练习","category":"学习方法","scene":"技能提升、专业发展、能力突破的深度学习场景","core_logic":"刻意练习由安德斯·艾利克森提出，核心特征是：有明确定义的特定目标、专注在任务上、包含即时反馈、需要走出舒适区、依赖有效的心理表征。不是简单的重复，而是有针对性的改进。","steps":"[{\"name\": \"设定明确具体的小目标\", \"description\": \"\"}, {\"name\": \"找到该领域的最佳实践/导师\", \"description\": \"\"}, {\"name\": \"专注地进行针对性练习\", \"description\": \"\"}, {\"name\": \"获取即时反馈\", \"description\": \"\"}, {\"name\": \"走出舒适区挑战更难的内容\", \"description\": \"\"}, {\"name\": \"建立有效的心理表征\", \"description\": \"\"}]","itto":"{\"tools\": [\"导师反馈、练习设计\"], \"inputs\": [\"目标技能、学习资源\"], \"outputs\": [\"技能提升、专业水平突破\"]}","tools":"导师/教练、反馈机制、练习记录、心理表征","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"刻意练习,Deliberate Practice,技能提升,10000小时,舒适区","sort_order":3,"_created_at":"2026-09-15T18:34:26.553+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.863+08:00","_updated_by":"()","code":"LRN-STU-002","aliases":"刻意练习,Deliberate Practice,10000小时","summary":"有目的、有反馈、走出舒适区的高效练习方法","problem_statement":"重复练习却不见进步，陷入低水平重复的瓶颈，以为是不够努力其实是方法不对，越练越疲劳；刻意练习强调有明确目标、有即时反馈、走出舒适区、专注于薄弱环节，让每一次练习都带来真实提升。","triggers":"刻意练习,技能提升,10000小时,舒适区,心理表征","applicable":"专业技能提升、体育训练、音乐学习、职业发展","not_applicable":"简单知识了解、纯记忆性学习、不需要精熟的领域","related_frameworks":"费曼学习法,间隔重复,GROW 教练模型","templates":"刻意练习计划模板","limitations":"需要高度专注和自律；需要专业反馈（导师/教练）；过程辛苦且需要长期坚持","mastery_level":"L3","last_used_date":null,"domain_code":"LEARN"},{"id":"c6c587b2-e920-4484-aee6-d2c35f0599ee","name":"SOW 工作说明书","category":"客户交付","scene":"外包项目、咨询服务、定制开发等需要明确交付范围的场景","core_logic":"SOW是项目/服务合同的核心附件，详细描述工作范围、交付物、质量标准、时间计划、验收标准、双方责任等，是项目执行和验收的依据，也是避免范围蔓延和纠纷的关键。","steps":"[{\"name\": \"明确项目目标和范围\", \"description\": \"\"}, {\"name\": \"列出详细的工作内容\", \"description\": \"\"}, {\"name\": \"定义交付物和验收标准\", \"description\": \"\"}, {\"name\": \"制定时间计划和里程碑\", \"description\": \"\"}, {\"name\": \"明确双方责任和资源\", \"description\": \"\"}, {\"name\": \"约定变更和争议处理\", \"description\": \"\"}]","itto":"{\"tools\": [\"合同模板、项目管理\"], \"inputs\": [\"客户需求、商业条款\"], \"outputs\": [\"SOW文档、签署协议\"]}","tools":"合同模板、WBS、甘特图、需求文档","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"SOW,工作说明书,交付范围,验收标准,项目合同","sort_order":2,"_created_at":"2026-09-15T18:34:20.12+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.871+08:00","_updated_by":"()","code":"CUST-SOW-001","aliases":"SOW,工作说明书,Statement of Work","summary":"详细描述项目交付内容、标准和要求的合同附件","problem_statement":"项目交付内容和标准没说清，交付时各说各话，客户要的和你做的不一样，扯皮不断、验收困难；SOW详细描述项目交付内容、标准和要求，作为合同附件明确双方预期，减少争议、确保顺利验收。","triggers":"SOW,工作说明书,交付范围,验收标准,合同","applicable":"外包项目、咨询服务、定制开发、采购服务","not_applicable":"简单标准化产品、敏捷迭代合作模式","related_frameworks":"SLA 服务级别协议,需求跟踪矩阵 RTM,变更控制（CCB）","templates":"SOW工作说明书模板","limitations":"编写需要大量时间和专业能力；再详细也无法穷尽所有细节；与敏捷模式存在张力","mastery_level":"L2","last_used_date":null,"domain_code":"CUST"},{"id":"c8ee53ce-f6bd-470d-8efe-a0b4d355374d","name":"问题—目标—工具—执行—评估","category":"科研写作","scene":"公共政策设计与评估、政策工具选择研究、管理类应用研究论文","core_logic":"从问题出发的政策研究路径：先把问题分析透，然后设定明确目标，再根据问题性质和目标要求选择合适的政策工具组合，接着设计执行路径，最后建立评估机制闭环。是公共管理和政策研究的标准分析框架。","steps":"[{\"name\": \"问题界定\", \"description\": \"清晰定义要解决的公共问题，分析问题的性质、范围和严重程度\"}, {\"name\": \"目标设定\", \"description\": \"明确政策要达成的目标，区分总目标和子目标，设定量化指标\"}, {\"name\": \"工具选择\", \"description\": \"在多种政策工具（管制型、经济激励型、信息型等）中选择合适的工具组合\"}, {\"name\": \"执行实施\", \"description\": \"设计执行机制，明确执行主体、执行步骤、资源配置和时间安排\"}, {\"name\": \"效果评估\", \"description\": \"建立评估指标体系，对政策执行效果进行系统评估和反馈\"}]","itto":"{\"tools\": [\"政策工具理论\", \"成本收益分析\", \"政策评估方法\"], \"inputs\": [\"公共问题\", \"政策资源\", \"政策目标\"], \"outputs\": [\"政策设计方案\", \"评估报告\"]}","tools":"政策工具分类学（Howlett/Ringeling）、成本效益分析、多准则决策、政策执行评估","cases":"城市交通拥堵治理政策研究：问题（拥堵严重、通勤时间长）→ 目标（高峰期平均车速提升20%）→ 工具（限行+拥堵费+公共交通补贴组合）→ 执行（分阶段实施）→ 评估（前后对比+指标体系）","viz_type":"process","viz_config":"{}","keywords":"政策工具,政策设计,政策评估,公共政策,政策调研","sort_order":115,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.879+08:00","_updated_by":"()","code":"RES-WRI-010","aliases":"政策工具","summary":"从问题出发的政策研究路径：先把问题分析透，然后设定明确目标，再根据问题性质和目标要求选择合适的政策工具组合，接着设计执行路径，最后建立评估机制闭环。是公共管理和","problem_statement":"政策研究只提对策不讲工具选择，政策目标与工具不匹配，执行路径模糊，政策落地效果差、评估无依据；问题-目标-工具-执行-评估从问题出发，先明确目标再选择政策工具、设计执行路径、建立评估闭环，让政策研究系统完整。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"公共政策设计与评估、政策工具选择研究、管理类应用研究论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"城市交通拥堵治理政策研究：问题（拥堵严重、通勤时间长）→ 目标（高峰期平均车速提升20%）→ 工具（限行+拥堵费+公共交通补贴组合）→ 执行（分阶段实施）→ 评估（前后对比+指标体系）","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"cb113f1f-7fe3-4049-ba8d-5d5a7885ca20","name":"系统思考","category":"思维方法","scene":"复杂系统问题、多因素相互影响、存在反馈回路的场景","core_logic":"任何系统都是由相互关联的要素组成的整体，系统行为由其内部结构和反馈回路决定。通过识别因果关系链和增强/调节回路，理解系统行为背后的结构性原因，找到高杠杆解。","steps":"[{\"name\": \"界定系统边界\", \"description\": \"\"}, {\"name\": \"识别系统关键要素\", \"description\": \"\"}, {\"name\": \"绘制因果关系链\", \"description\": \"\"}, {\"name\": \"识别增强回路和调节回路\", \"description\": \"\"}, {\"name\": \"寻找高杠杆干预点\", \"description\": \"\"}]","itto":"{\"tools\": [\"因果回路图、系统基模\"], \"inputs\": [\"系统问题描述\"], \"outputs\": [\"系统分析报告、高杠杆解\"]}","tools":"因果回路图 CLD、存量流量图、系统基模","cases":"需补充","viz_type":"cycle","viz_config":"{}","keywords":"系统思考,因果回路,反馈,整体观,复杂系统","sort_order":12,"_created_at":"2026-09-15T18:34:03.111+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.886+08:00","_updated_by":"()","code":"META-THK-004","aliases":"系统思考,系统思维,因果回路图","summary":"从整体视角看待系统要素及相互关系的思维方式","problem_statement":"看问题只看局部不看整体，只看眼前不看长远，头痛医头脚痛医脚，治标不治本甚至越治越糟；系统思考从整体视角看待系统要素及其相互关系和反馈机制，找到根本解而非症状解。","triggers":"系统,反馈,循环,整体,复杂","applicable":"组织管理、生态系统分析、经济社会问题、复杂项目诊断","not_applicable":"简单线性问题、因果关系明确的单一问题","related_frameworks":"系统动力学,TRIZ 理论,决策矩阵","templates":"因果回路图模板、常见系统基模卡","limitations":"绘制和分析门槛较高；系统边界界定主观性强；难以量化验证","mastery_level":"L2","last_used_date":null,"domain_code":"META"},{"id":"cd4c504c-4c52-4973-93ee-82ccd1c9d2f3","name":"GRAI 复盘法","category":"知识管理","scene":"项目复盘、活动复盘、个人复盘、团队学习的场景","core_logic":"GRAI复盘法通过四个步骤进行结构化回顾：Goal（回顾目标，当初期望什么）→Result（评估结果，实际发生了什么）→Analysis（分析原因，为什么会这样）→Insight（提炼规律，学到了什么）。帮助从经验中系统学习。","steps":"[{\"name\": \"G 目标：回顾当初的目标和预期\", \"description\": \"\"}, {\"name\": \"R 结果：实际结果如何，亮点与不足\", \"description\": \"\"}, {\"name\": \"A 分析：深入分析成功/失败的原因\", \"description\": \"\"}, {\"name\": \"I 洞察：提炼规律和经验教训\", \"description\": \"\"}, {\"name\": \"行动：确定后续改进措施\", \"description\": \"\"}]","itto":"{\"tools\": [\"团队引导、数据分析\"], \"inputs\": [\"项目/事件记录\"], \"outputs\": [\"复盘报告、经验教训\"]}","tools":"5Why、鱼骨图、团队引导、数据分析","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"GRAI,复盘法,经验总结,反思,知识沉淀","sort_order":6,"_created_at":"2026-09-15T18:34:26.62+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.894+08:00","_updated_by":"()","code":"KNOW-RVW-001","aliases":"GRAI,复盘,Goal-Result-Analysis-Insight","summary":"目标—结果—分析—洞察的结构化复盘方法","problem_statement":"复盘只走形式，说说好的也说说不足，但分析不深入、洞察不到位，下次还是犯同样的错；GRAI复盘法按目标-结果-分析-洞察四层递进，从结果差距深挖原因、提炼可复用的认知和方法。","triggers":"GRAI,复盘,经验总结,反思,知识沉淀","applicable":"项目复盘、活动复盘、个人成长、团队学习、产品迭代","not_applicable":"重复性极高无需改进的事务、已经完全满意没有问题的场景","related_frameworks":"KPT 复盘法,PDCA 循环,SECI 模型","templates":"GRAI复盘模板","limitations":"需要坦诚的文化氛围；深度分析需要时间投入；复盘结论需要落地才能产生价值","mastery_level":"L3","last_used_date":null,"domain_code":"KNOW"},{"id":"cddd1eae-ce79-4323-b50c-0c0740d241e5","name":"PARA 分类法","category":"知识管理","scene":"个人知识管理、数字笔记整理、信息组织的场景","core_logic":"PARA将所有信息分为四类：Projects（项目，有明确目标和期限的任务）、Areas（领域，长期负责的领域）、Resources（资源，感兴趣的主题）、Archives（档案，已完成或不活跃的内容）。按可行动性排序，帮助快速找到需要的信息。","steps":"[{\"name\": \"列出所有信息来源\", \"description\": \"\"}, {\"name\": \"按PARA四分类整理\", \"description\": \"\"}, {\"name\": \"P：有明确目标和deadline的归为项目\", \"description\": \"\"}, {\"name\": \"A：长期持续负责的归为领域\", \"description\": \"\"}, {\"name\": \"R：感兴趣但不负责的归为资源\", \"description\": \"\"}, {\"name\": \"不活跃的移入档案Archive\", \"description\": \"\"}]","itto":"{\"tools\": [\"分类方法、笔记工具\"], \"inputs\": [\"散乱的信息/笔记\"], \"outputs\": [\"结构化的知识管理体系\"]}","tools":"Notion、Obsidian、笔记软件、文件管理器","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"PARA,知识分类,笔记管理,信息组织,Tiago Forte","sort_order":3,"_created_at":"2026-09-15T18:34:26.595+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.902+08:00","_updated_by":"()","code":"KNOW-PARA-001","aliases":"PARA,知识分类,项目领域资源档案","summary":"Tiago Forte提出的四类信息组织方法：项目—领域—资源—档案","problem_statement":"信息分类体系要么太复杂坚持不下去，要么太笼统找起来费劲，笔记和文件越存越乱、检索效率极低；PARA分类法按项目-领域-资源-档案四类组织信息，简单清晰、符合认知规律，容易坚持也容易查找。","triggers":"PARA,知识分类,笔记管理,信息组织,Tiago Forte","applicable":"个人知识管理、数字笔记、文件管理、工作信息组织","not_applicable":"信息极少的人、纯纸质笔记使用者","related_frameworks":"CODE 知识加工,卡片盒笔记法（Zettelkasten）,渐进式总结","templates":"PARA分类模板","limitations":"项目和领域边界有时模糊；需要定期维护归档；是分类法不涉及内容加工","mastery_level":"L3","last_used_date":null,"domain_code":"KNOW"},{"id":"cfde436c-4d99-423f-b8b0-dcba527a1ce6","name":"破窗效应","category":"思维模型","scene":"质量管理、团队管理、秩序维护、风险防控、细节管理的场景","core_logic":"破窗效应由心理学家津巴多提出、威尔逊和凯林完善：如果一栋建筑的一扇窗户破了没人修，很快其他窗户也会被打破；一面墙如果有涂鸦没清理，很快就会布满涂鸦。小的混乱和违规如果不及时制止，会传递「没人管」的信号，导致更多更严重的问题。启示是：必须及时修复「第一扇破窗」，对小问题零容忍，才能防止大问题发生。","steps":"[{\"name\": \"识别破窗信号\", \"description\": \"培养敏锐的观察力，及时发现小问题、小漏洞、小违规\"}, {\"name\": \"评估影响范围\", \"description\": \"判断这个小问题是否会产生示范效应，是否会引发更多问题\"}, {\"name\": \"立即修复小问题\", \"description\": \"对确认为「破窗」的问题，第一时间处理，不让它成为榜样\"}, {\"name\": \"明确标准和底线\", \"description\": \"向所有人明确什么是可接受的、什么是绝对不允许的\"}, {\"name\": \"建立快速响应机制\", \"description\": \"建立问题上报和快速处理的机制，确保小问题能被及时发现和解决\"}, {\"name\": \"做到零容忍执行\", \"description\": \"对违反底线的行为坚决处理，不因「事小」而放任\"}, {\"name\": \"巩固正面秩序\", \"description\": \"不仅制止坏事，更要树立正面标杆，强化良好秩序\"}, {\"name\": \"定期检查维护\", \"description\": \"定期巡检，防止破窗再次出现，保持长期有序\"}]","itto":"{\"tools\": [\"巡检制度、零容忍政策、快速响应流程、标杆管理、5S管理\"], \"inputs\": [\"问题观察、标准定义、处理机制、执行决心\"], \"outputs\": [\"良好的秩序、更少的大问题、高质量标准、团队纪律性\"]}","tools":"5S管理、巡检制度、零容忍政策、标杆管理、快速响应机制","cases":"纽约地铁治安治理（清除涂鸦→犯罪率下降）、日本企业质量管理、华为的细节管理、海底捞的服务细节","viz_type":"process","viz_config":"{}","keywords":"破窗效应,破窗理论,小问题,零容忍,细节管理,秩序","sort_order":84,"_created_at":"2026-09-16T16:20:50.95+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.909+08:00","_updated_by":"()","code":"META-BROKENWINDOW-001","aliases":"破窗理论,Broken Windows Theory,破窗效应,零容忍","summary":"小问题不及时处理会诱发更严重的失序，及时修复小问题能预防大问题","problem_statement":"小问题不重视、小毛病不纠正，以为无所谓，结果小问题引发大失序，局面越来越难以收拾；破窗效应揭示小问题不及时处理会诱发更严重的失序，及时修复小问题能有效预防大问题。","triggers":"破窗效应,破窗理论,小问题,零容忍,细节管理,秩序维护,Broken Windows","applicable":"质量管理、团队管理、城市治理、安全管理、客户服务、产品细节、制度执行","not_applicable":"创新试错场景（需要包容失败）、无关紧要的细枝末节、过度追求完美导致效率低下","related_frameworks":"FMEA失效模式与影响分析,海因里希法则,PDCA循环,质量控制,细节管理","templates":"破窗识别检查表、问题快速响应流程、巡检记录表","limitations":"容易走向极端的零容忍和过度管控；可能抑制创新和试错；需要投入大量资源监控；判断「破窗」的标准可能主观","mastery_level":"L2","last_used_date":null,"domain_code":"META"},{"id":"cfead769-f03a-4689-87e7-fe7cfdf228ca","name":"干系人参与计划","category":"项目管理","scene":"项目干系人复杂、需要主动管理和引导参与的场景","core_logic":"干系人参与计划在识别和分析干系人的基础上，制定每个关键干系人的当前参与水平、期望参与水平、参与策略、沟通计划、行动措施，确保干系人对项目的支持和参与度达到项目成功所需的水平。","steps":"[{\"name\": \"识别所有关键干系人\", \"description\": \"\"}, {\"name\": \"评估当前参与水平\", \"description\": \"\"}, {\"name\": \"定义期望参与水平\", \"description\": \"\"}, {\"name\": \"分析差距和影响因素\", \"description\": \"\"}, {\"name\": \"制定参与策略和沟通计划\", \"description\": \"\"}, {\"name\": \"执行并定期评估调整\", \"description\": \"\"}]","itto":"{\"tools\": [\"沟通管理、权力利益矩阵\"], \"inputs\": [\"干系人分析结果\"], \"outputs\": [\"干系人参与计划、沟通计划\"]}","tools":"权力利益矩阵、参与评估矩阵、沟通计划","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"干系人参与,干系人管理,沟通计划,项目支持","sort_order":18,"_created_at":"2026-09-15T18:34:13.687+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.917+08:00","_updated_by":"()","code":"PM-STK-002","aliases":"干系人参与,干系人管理计划,Stakeholder Engagement","summary":"系统性规划干系人参与策略和行动的管理计划","problem_statement":"项目干系人管理只做一次清单，没有持续的参与策略，关键人不支持、配合度低导致项目推进困难；干系人参与计划系统规划每位干系人的参与程度、沟通频率和行动策略，确保关键干系人持续支持项目。","triggers":"干系人,参与计划,干系人管理,沟通,支持","applicable":"复杂项目、变革项目、跨部门项目、对外合作项目","not_applicable":"干系人少且简单的小型项目","related_frameworks":"权力/利益矩阵,RACI 矩阵,客户旅程图","templates":"干系人参与计划模板","limitations":"干系人态度动态变化需要持续跟踪；策略执行需要时间和资源投入","mastery_level":"L2","last_used_date":null,"domain_code":"PM"},{"id":"d38db2f8-8151-4556-85d6-70905e930065","name":"逻辑框架法 LFA","category":"科研写作","scene":"项目设计与评估、政策逻辑分析、国际援助项目、科研课题申报书的逻辑梳理","core_logic":"逻辑框架法（Logical Framework Approach）通过一个4×4的矩阵（目标层级 × 验证指标 × 验证方法 + 假设条件）来描述项目的因果逻辑链：投入→产出→目的→目标。强调成果导向、指标可衡量和假设条件的明确性。","steps":"[]","itto":"{\"tools\": [\"LFA矩阵\", \"利益相关者分析\", \"风险分析\", \"指标体系设计\"], \"inputs\": [\"项目需求\", \"资源条件\", \"目标设定\"], \"outputs\": [\"逻辑框架矩阵\", \"项目设计方案\", \"评估框架\"]}","tools":"LFA 逻辑框架矩阵、指标体系设计、风险分析、利益相关者分析","cases":"世界银行贷款项目申请书标准格式：用LFA矩阵清晰展示项目逻辑——目标（减贫）→ 目的（提高农民收入）→ 产出（建设10个农业示范基地）→ 活动（技术培训、品种改良、市场对接），每一层都配验证指标和假设条件。","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"目标 Goal\", \"description\": \"项目/政策的宏观目标，为什么要做\"}, {\"name\": \"目的 Purpose\", \"items\": [\"项目直接产出效果，项目完成后受益群体的变化\"]}, {\"name\": \"产出 Outputs\", \"items\": [\"项目具体交付物、建设内容、量化成果\"]}, {\"name\": \"活动 Activities\", \"items\": [\"为实现产出需要开展的具体工作和行动\"]}]}","keywords":"逻辑框架法,LFA,项目设计,成果导向,指标体系,政策调研","sort_order":113,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.925+08:00","_updated_by":"()","code":"RES-WRI-008","aliases":"逻辑框架法","summary":"逻辑框架法（Logical Framework Approach）通过一个4×4的矩阵（目标层级 × 验证指标 × 验证方法 + 假设条件）来描述项目的因果逻辑","problem_statement":"项目设计逻辑混乱，投入产出关系说不清，目标没有验证指标，假设条件不明确，项目执行跑偏也没人发现；逻辑框架法通过4×4矩阵构建投入-产出-目的-目标的因果逻辑链，强调成果导向、指标可衡量和假设条件的显性化。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"项目设计与评估、政策逻辑分析、国际援助项目、科研课题申报书的逻辑梳理","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"世界银行贷款项目申请书标准格式：用LFA矩阵清晰展示项目逻辑——目标（减贫）→ 目的（提高农民收入）→ 产出（建设10个农业示范基地）→ 活动（技术培训、品种改良、市场对接），每一层都配验证指标和假设","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"d44569b1-e6d1-42a7-82f0-8bda4f174988","name":"A3 问题解决法","category":"问题解决","scene":"质量问题解决、流程改进、跨部门问题闭环、精益改善的场景","core_logic":"A3问题解决法源自丰田生产方式，用一张A3大小的纸系统性呈现问题解决的完整闭环：背景→问题描述→现状分析→目标设定→根因分析→对策方案→实施计划→效果验证→标准化，通过结构化思考和可视化呈现推动问题真正解决并形成共识。","steps":"[{\"name\": \"明确背景（Background）\", \"description\": \"说明问题发生的业务背景、重要性和来龙去脉，让读者理解问题的上下文\"}, {\"name\": \"问题描述（Problem）\", \"description\": \"清晰、具体地描述问题是什么、发生在哪里、影响有多大，界定问题边界\"}, {\"name\": \"现状分析（Current Situation）\", \"description\": \"用数据和事实描述当前状况，明确问题严重程度、发生频率和趋势\"}, {\"name\": \"目标设定（Goal）\", \"description\": \"确定期望达到的目标状态和可衡量的指标，设定明确的改善目标\"}, {\"name\": \"根因分析（Root Cause Analysis）\", \"description\": \"使用5Why或鱼骨图等工具追溯问题的根本原因，区分表面原因和根本原因\"}, {\"name\": \"对策方案（Countermeasures）\", \"description\": \"针对根本原因提出多种对策方案，评估并选择最优对策\"}, {\"name\": \"实施计划（Implementation Plan）\", \"description\": \"明确责任人、时间节点、所需资源和里程碑，制定详细实施计划\"}, {\"name\": \"效果确认（Effect Confirmation）\", \"description\": \"执行对策后收集数据，对比目标验证改善效果，确认是否达成目标\"}, {\"name\": \"标准化与横向展开（Standardize）\", \"description\": \"将有效对策固化为标准作业，推广到类似场景，防止再发并扩大收益\"}]","itto":"{\"tools\": [\"A3报告模板、5Why分析法、鱼骨图、柏拉图、PDCA循环\"], \"inputs\": [\"问题描述、现状数据、业务背景信息\"], \"outputs\": [\"A3报告、改善对策、标准化作业指导书、效果验证报告\"]}","tools":"A3报告模板、5Why分析法、鱼骨图、柏拉图、PDCA、价值流图","cases":"丰田生产方式中的质量问题解决、制造业精益改善、医疗行业流程优化","viz_type":"process","viz_config":"{}","keywords":"A3,问题解决,丰田,精益,根因分析,闭环","sort_order":61,"_created_at":"2026-09-16T16:20:50.718+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.933+08:00","_updated_by":"()","code":"SOLVE-A3-001","aliases":"A3报告,丰田A3,A3思维,A3 Problem Solving","summary":"丰田精益经典工具，一张A3纸完成问题描述-现状分析-根因-对策-计划-跟踪的闭环","problem_statement":"问题解决过程零散不系统，分析不深入、对策不落地、效果不跟踪，同样的问题反复出现；A3问题解决法用一张A3纸完成问题描述-现状分析-根因-对策-计划-跟踪的完整闭环，精益高效。","triggers":"A3,问题解决,质量问题,流程改进,根因分析,闭环管理,精益改善","applicable":"质量缺陷解决、流程优化、跨部门协作问题、持续改进项目、标准作业建立","not_applicable":"简单应急问题、完全创新性问题、需要长时间研究的基础科学问题","related_frameworks":"8D问题解决法,PDCA循环,5Why分析法,鱼骨图,FMEA失效模式与影响分析","templates":"A3报告模板、A3问题解决工作表","limitations":"实施需要数据支撑和耐心；过于结构化可能影响创造性；需要领导者支持和文化配合","mastery_level":"L3","last_used_date":null,"domain_code":"SOLVE"},{"id":"d505bdfc-a064-4c5f-9118-6cbc4add9d9b","name":"多准则决策 MCDA","category":"思维方法","scene":"复杂决策涉及多个相互冲突的评估维度的场景","core_logic":"多准则决策是处理包含多个相互冲突准则的复杂决策的方法论体系，包含AHP、TOPSIS、ELECTRE、PROMETHEE等多种方法，核心思想是将多维评价整合为可比较的综合指标，辅助决策者做出理性选择。","steps":"[{\"name\": \"识别决策问题和备选方案\", \"description\": \"\"}, {\"name\": \"确定评估准则体系\", \"description\": \"\"}, {\"name\": \"收集各方案在各准则下的数据\", \"description\": \"\"}, {\"name\": \"选择MCDA方法进行计算\", \"description\": \"\"}, {\"name\": \"进行敏感性分析\", \"description\": \"\"}, {\"name\": \"得出最终决策建议\", \"description\": \"\"}]","itto":"{\"tools\": [\"AHP、TOPSIS、ELECTRE等\"], \"inputs\": [\"决策问题、备选方案、评估准则\"], \"outputs\": [\"排序结果、敏感性分析\"]}","tools":"AHP、TOPSIS、ELECTRE、PROMETHEE、VIKOR","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"评估准则\", \"y_label\": \"备选方案\", \"quadrants\": {\"q1\": \"MCDA评分\"}}","keywords":"MCDA,多准则决策,综合评估,权衡分析,决策支持","sort_order":5,"_created_at":"2026-09-15T18:34:03.332+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.94+08:00","_updated_by":"()","code":"DEC-MCDA-001","aliases":"MCDA,多准则决策,Multi-Criteria Decision Analysis","summary":"在多个冲突准则下进行系统化决策的方法论体系","problem_statement":"决策涉及多个相互冲突的标准，顾此失彼，权重分配拍脑袋，决策过程不透明、难以说服利益相关方；MCDA提供系统化的多准则决策方法论，科学权衡冲突准则，让决策过程透明、结果可靠。","triggers":"多准则,决策,MCDA,权衡,综合评估","applicable":"战略决策、政策制定、项目选择、资源分配、环境评估","not_applicable":"单维简单决策、快速直觉决策场景","related_frameworks":"AHP 层次分析法,决策矩阵,成本效益分析","templates":"MCDA分析框架模板","limitations":"方法选择本身就是个决策问题；权重设定有主观性；计算复杂需要专业工具","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"d548e0db-2e97-4f62-9a86-9844caa5df93","name":"头脑风暴法","category":"思维方法","scene":"创意生成、问题解决、方案设计等需要大量想法的场景","core_logic":"通过延迟评判、鼓励发散、追求数量、组合改进四条原则，让参与者在无压力的氛围中自由联想，激发大量创意想法，为后续筛选提供丰富的素材。","steps":"[{\"name\": \"明确议题和目标\", \"description\": \"\"}, {\"name\": \"设定规则：不评判、求数量\", \"description\": \"\"}, {\"name\": \"参与者轮流/自由提出想法\", \"description\": \"\"}, {\"name\": \"记录所有想法\", \"description\": \"\"}, {\"name\": \"对想法进行归类和筛选\", \"description\": \"\"}]","itto":"{\"tools\": [\"白板、便签、引导师\"], \"inputs\": [\"议题/问题\"], \"outputs\": [\"创意想法清单\"]}","tools":"便签纸、白板、思维导图、SCAMPER","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"头脑风暴,创意发散,脑暴,Brainstorming,创新方法","sort_order":12,"_created_at":"2026-09-15T18:34:03.307+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.948+08:00","_updated_by":"()","code":"SOL-THK-008","aliases":"头脑风暴,Brainstorming,脑暴","summary":"通过群体自由联想激发大量创意的发散思维方法","problem_statement":"团队想创意时容易被权威和从众心理压制，好想法说不出来，创意数量少质量也不高，创新陷入瓶颈；头脑风暴法通过自由联想、延迟评判、以量求质、结合改善等规则，激发群体创意、最大化发散思维效果。","triggers":"头脑风暴,创意,发散,想法,脑暴","applicable":"产品设计、营销策划、问题解决方案、团队创新","not_applicable":"需要深度分析的问题、需要精确答案的场景","related_frameworks":"SCAMPER 法,设计思维,名义小组技术","templates":"头脑风暴引导手册","limitations":"质量参差不齐需要后续筛选；容易被主导者影响；需要良好的引导","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"d5ecbc11-8d37-49b8-944c-813a647581f9","name":"PMF 产品市场契合","category":"产品战略","scene":"创业验证、产品定位、用户增长、市场进入、产品迭代的场景","core_logic":"PMF（Product-Market Fit，产品市场契合）由马克·安德森提出，指「产品刚好满足市场强烈需求」的状态。达到PMF前，产品用起来很别扭、用户增长缓慢、留存率低、用户不愿主动推荐；达到PMF后，用户自发增长、留存率高、口碑传播、甚至用户会因为没有产品而感到痛苦。PMF是创业的第一座大山，找到PMF前应该集中精力验证和调整产品，找到PMF后才可以大规模投入增长。","steps":"[{\"name\": \"明确目标市场和用户\", \"description\": \"清晰定义你的目标市场和目标用户是谁，越具体越好\"}, {\"name\": \"定义价值假设\", \"description\": \"你认为用户为什么需要你的产品？能解决什么核心痛点？\"}, {\"name\": \"构建MVP并投放\", \"description\": \"快速构建最小可行产品，投放给真实用户使用\"}, {\"name\": \"收集PMF信号\", \"description\": \"观察和收集用户行为数据和反馈，判断是否达到PMF\"}, {\"name\": \"用Sean Ellis测试验证\", \"description\": \"问用户：如果明天不能用这个产品了，你会有多失望？(非常失望/有点失望/不失望)，40%以上选非常失望=达到PMF\"}, {\"name\": \"分析留存和口碑数据\", \"description\": \"分析用户留存率、NPS、推荐率、自然增长比例等关键指标\"}, {\"name\": \"判断是否达到PMF\", \"description\": \"综合多种信号判断是否真正达到产品市场契合\"}, {\"name\": \"未达PMF则迭代/转型\", \"description\": \"如果没达到PMF，分析原因，迭代产品或调整方向，必要时转型\"}, {\"name\": \"达到PMF后加速增长\", \"description\": \"达到PMF后，可以加大投入扩大用户规模，进入增长阶段\"}]","itto":"{\"tools\": [\"用户访谈、Sean Ellis测试、留存分析、NPS调研、数据分析、A/B测试\"], \"inputs\": [\"产品MVP、目标用户、用户反馈渠道、数据分析能力\"], \"outputs\": [\"PMF验证结果、产品迭代方向、是否达到PMF的判断、下一步行动建议\"]}","tools":"用户访谈、Sean Ellis测试、留存曲线分析、NPS调研、数据分析、用户画像","cases":"Dropbox、Slack、Airbnb、Uber、拼多多、抖音等都经历了PMF探索期","viz_type":"process","viz_config":"{}","keywords":"PMF,产品市场契合,Product-Market Fit,产品验证,创业,增长,Sean Ellis","sort_order":101,"_created_at":"2026-09-16T16:20:51.063+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.956+08:00","_updated_by":"()","code":"PROD-PMF-001","aliases":"PMF,产品市场契合,Product-Market Fit,产品市场匹配,马克安德森","summary":"产品与市场需求高度匹配的状态判断框架，是创业和产品成功的核心里程碑","problem_statement":"产品做了很久、功能加了一堆，但用户增长和留存就是上不去，不知道是产品不行还是市场不对；PMF帮助判断产品是否真正满足了市场需求，是创业和产品成功的核心里程碑，没达到PMF之前盲目扩张是灾难。","triggers":"PMF,产品市场契合,Product-Market Fit,产品验证,PMF验证","applicable":"创业公司、新产品验证、市场进入决策、产品方向调整、增长策略制定","not_applicable":"已有明确需求的定制化产品、成熟产品的功能迭代、政府/垄断性产品、非市场化产品","related_frameworks":"精益创业,MVP,蓝海战略ERRC框架,用户画像,用户旅程图","templates":"PMF验证清单、Sean Ellis测试问卷、留存分析模板、PMF指标仪表盘","limitations":"PMF的判断有主观性，没有精确的量化标准；不同行业PMF的表现形式不同；达到PMF也不代表最终成功；有时PMF是阶段性的，市场变化后可能失去PMF","mastery_level":"L3","last_used_date":null,"domain_code":"PROD"},{"id":"d69ad4d1-5d26-4683-a92f-8960bbdbccb6","name":"评价量规 Rubric","category":"教学科研","scene":"作业评分、项目评估、表现性评价、教学评估的场景","core_logic":"Rubric（评价量规）是一种结构化的评分工具，从多个评价维度出发，对每个维度的不同等级表现进行详细描述，使评分标准透明、客观、一致。既方便教师评分，也让学生清楚努力方向。","steps":"[{\"name\": \"明确评价的内容和目标\", \"description\": \"\"}, {\"name\": \"确定评价维度\", \"description\": \"\"}, {\"name\": \"为每个维度定义等级\", \"description\": \"\"}, {\"name\": \"描述各等级的具体表现\", \"description\": \"\"}, {\"name\": \"试用并调整\", \"description\": \"\"}, {\"name\": \"向学生解释说明\", \"description\": \"\"}]","itto":"{\"tools\": [\"量规设计方法\"], \"inputs\": [\"评价目标、作业/任务要求\"], \"outputs\": [\"评价量规表、评分标准\"]}","tools":"量规模板、评分标准、同行评议","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"表现等级\", \"y_label\": \"评价维度\", \"quadrants\": {\"q1\": \"等级描述\"}}","keywords":"Rubric,评价量规,评分标准,表现性评价,评估工具","sort_order":6,"_created_at":"2026-09-15T18:34:26.528+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.964+08:00","_updated_by":"()","code":"TEACH-RUB-001","aliases":"Rubric,评分量规,评价标准","summary":"详细描述评分标准和各等级表现的评估工具","problem_statement":"评分全凭主观感觉，学生不知道评分标准，老师评分不一致，反馈不具体，学生不知道该怎么改进；评价量规详细描述各维度的评分标准和等级表现，让评分透明客观、反馈具体可操作。","triggers":"Rubric,评价量规,评分标准,表现性评价,评估","applicable":"论文评分、项目评估、作品集评价、表现性评价、同伴互评","not_applicable":"客观题考试（有标准答案即可）、简单知识性考核","related_frameworks":"布鲁姆认知分类法,形成性评价与终结性评价,OBE 成果导向教育","templates":"Rubric评价量规模板","limitations":"设计一个好的量规需要时间；过于详细可能束缚学生创造力；量规本身也有主观性","mastery_level":"L2","last_used_date":null,"domain_code":"TEACH"},{"id":"d727f366-2f4e-4266-bbce-52142d7c0def","name":"麦肯锡七步成诗法","category":"问题解决","scene":"复杂商业问题分析、战略咨询项目、管理决策支持的场景","core_logic":"麦肯锡七步成诗法是麦肯锡咨询顾问的标准工作方法：界定问题→分解问题→优先排序→制定工作计划→关键分析→综合结果→沟通汇报，通过结构化拆解和假设驱动，将复杂问题逐步收敛为可执行的解决方案。","steps":"[{\"name\": \"界定问题\", \"description\": \"明确问题是什么、不是什么，界定问题边界和决策标准\"}, {\"name\": \"分解问题\", \"description\": \"使用逻辑树等工具将大问题拆解为可处理的子问题\"}, {\"name\": \"优先排序\", \"description\": \"按重要性和影响程度排序，聚焦关键问题，剔除非关键项\"}, {\"name\": \"制定工作计划\", \"description\": \"明确分析内容、责任人、时间节点和交付物\"}, {\"name\": \"关键分析\", \"description\": \"针对关键问题进行深度分析和验证，用数据说话\"}, {\"name\": \"综合结果\", \"description\": \"将各子问题的分析结论整合，形成整体解决方案\"}, {\"name\": \"沟通汇报\", \"description\": \"用金字塔原理结构化呈现结论，争取利益相关方认同\"}]","itto":"{\"tools\": [\"逻辑树、MECE原则、金字塔原理、假设驱动分析、80/20法则\"], \"inputs\": [\"问题描述、背景信息、相关数据、利益相关方诉求\"], \"outputs\": [\"问题分析报告、解决方案建议、执行路线图、汇报材料\"]}","tools":"逻辑树、MECE原则、金字塔原理、80/20法则、假设驱动","cases":"麦肯锡咨询项目方法论、企业战略规划、市场进入决策","viz_type":"process","viz_config":"{}","keywords":"麦肯锡,七步成诗,问题解决,结构化思考,MECE,逻辑树","sort_order":62,"_created_at":"2026-09-16T16:20:50.744+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.972+08:00","_updated_by":"()","code":"SOLVE-MCK-001","aliases":"麦肯锡七步法,七步问题解决法,McKinsey 7-step,问题解决七步法","summary":"麦肯锡标准问题解决流程，七步系统化拆解并解决复杂商业问题","problem_statement":"面对复杂商业问题不知道从何入手，分析没有章法，要么东一榔头西一棒子要么钻牛角尖；麦肯锡七步成诗法提供七步系统化问题解决流程：陈述问题-分解问题-优先排序-工作规划-分析论证-归纳结论-沟通方案。","triggers":"麦肯锡,七步成诗,问题分析,结构化思考,复杂问题,咨询方法","applicable":"复杂商业问题、战略决策、管理咨询项目、跨领域复杂问题分析","not_applicable":"简单常规问题、已有标准答案的问题、纯技术实现问题","related_frameworks":"MECE原则,金字塔原理,逻辑树,5W2H分析法,SWOT分析","templates":"七步成诗法工作表、问题定义模板、逻辑树模板","limitations":"依赖分析者的经验和判断力；需要较多数据和时间；对执行落地关注相对不足","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"d7b1742d-ea4d-4bdf-8121-be2b55049902","name":"GVC 全球价值链","category":"科研写作","scene":"国际贸易研究、产业升级研究、全球生产网络、价值链地位测度论文","core_logic":"GVC（Global Value Chain）理论将产品生产过程分解为散布在全球不同国家的多个环节，每个环节创造不同的增加值。一个国家/企业在全球价值链中的位置（上游还是下游、高附加值还是低附加值）决定了其收益分配。研究核心是测度GVC地位和探索升级路径。","steps":"[{\"name\": \"研发设计环节\", \"description\": \"产品研发、设计、品牌策划等前端环节，通常位于价值链高端，附加值高\"}, {\"name\": \"零部件生产\", \"description\": \"关键零部件和通用零部件的生产制造，附加值因技术含量而异\"}, {\"name\": \"组装加工\", \"description\": \"最终产品的组装和集成，劳动密集型，通常附加值最低\"}, {\"name\": \"营销销售\", \"description\": \"品牌营销、渠道建设、销售服务，品牌力强则附加值高\"}, {\"name\": \"售后服务\", \"description\": \"售后、维修、回收、增值服务等后端环节，服务业态的附加值\"}]","itto":"{\"tools\": [\"GVC测度\", \"投入产出分析\", \"增加值贸易\", \"微笑曲线\"], \"inputs\": [\"国际贸易数据\", \"投入产出表\", \"企业调研数据\"], \"outputs\": [\"全球价值链地位分析\", \"产业升级路径建议\"]}","tools":"投入产出表分析、WIOD数据库、GVC地位指数、GVC参与度、微笑曲线","cases":"中国制造业GVC升级研究：过去中国处于\"组装加工\"低端环节（微笑曲线底部），通过技术创新和品牌建设逐步向\"研发设计\"和\"营销品牌\"两端攀升，GVC地位指数持续提升，但与发达国家仍有差距。","viz_type":"process","viz_config":"{}","keywords":"全球价值链,GVC,增加值贸易,产业升级,微笑曲线,战略产业","sort_order":127,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.98+08:00","_updated_by":"()","code":"DEC-IND-006","aliases":"全球价值链","summary":"GVC（Global Value Chain）理论将产品生产过程分解为散布在全球不同国家的多个环节，每个环节创造不同的增加值。一个国家/企业在全球价值链中的位置","problem_statement":"研究国际贸易和产业竞争力只看最终产品和总量数据，看不到全球分工格局和增加值分配，国家定位判断容易失误偏差；GVC理论将生产过程分解为散布全球的多个环节，精准定位一个国家或企业在价值链中的位置和收益。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"国际贸易研究、产业升级研究、全球生产网络、价值链地位测度论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"中国制造业GVC升级研究：过去中国处于\"组装加工\"低端环节（微笑曲线底部），通过技术创新和品牌建设逐步向\"研发设计\"和\"营销品牌\"两端攀升，GVC地位指数持续提升，但与发达国家仍有差距。","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"d8241925-0e08-456a-978b-c7ba36bebb12","name":"计划行为理论 TPB","category":"科研写作","scene":"社会心理学研究、消费者行为研究、健康行为研究、环保行为研究、管理行为研究论文","core_logic":"Ajzen 提出的计划行为理论（Theory of Planned Behavior）是解释和预测人类行为最有影响力的社会心理学模型之一。核心观点是：人的行为由行为意向决定，行为意向又受态度、主观规范和知觉行为控制三个因素影响。TPB 被广泛应用于各种行为研究领域。","steps":"[]","itto":"{\"tools\": [\"TPB量表\", \"问卷调研\", \"结构方程模型\", \"行为实验\"], \"inputs\": [\"用户态度数据\", \"社会规范信息\", \"行为控制感知\"], \"outputs\": [\"行为影响因素分析\", \"行为干预建议\"]}","tools":"TPB量表设计、问卷调研、结构方程模型、纵向研究设计","cases":"消费者绿色购买行为研究：用TPB构建模型——态度（绿色产品好不好）、主观规范（家人朋友是否支持绿色消费）、知觉行为控制（是否有能力购买绿色产品、是否方便）→ 行为意向 → 实际购买行为。研究发现态度和PBC是主要影响因素。","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"核心：行为意向决定行为\", \"description\": \"行为是行为意向的函数，而行为意向由三个因素共同决定\"}, {\"name\": \"三大前因变量\", \"items\": [\"态度（Attitude）：对行为的正面或负面评价\", \"主观规范（Subjective Norm）：感受到的社会压力/他人期望\", \"知觉行为控制（PBC）：感知到的行为难易程度/控制力\"]}, {\"name\": \"影响路径\", \"items\": [\"态度 → 行为意向\", \"主观规范 → 行为意向\", \"PBC → 行为意向（并直接影响行为）\", \"行为意向 → 实际行为\"]}]}","keywords":"计划行为理论,TPB,Ajzen,行为意向,行为研究,管理社科","sort_order":138,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.987+08:00","_updated_by":"()","code":"RES-THY-006","aliases":"计划行为理论","summary":"Ajzen 提出的计划行为理论（Theory of Planned Behavior）是解释和预测人类行为最有影响力的社会心理学模型之一。核心观点是：人的行为由","problem_statement":"解释和预测人类行为只看单一因素，行为背后的心理机制说不清，干预措施设计盲目、效果差；TPB从态度、主观规范、知觉行为控制三个维度构建行为意向的预测模型，系统解释和预测人类行为。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"社会心理学研究、消费者行为研究、健康行为研究、环保行为研究、管理行为研究论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"消费者绿色购买行为研究：用TPB构建模型——态度（绿色产品好不好）、主观规范（家人朋友是否支持绿色消费）、知觉行为控制（是否有能力购买绿色产品、是否方便）→ 行为意向 → 实际购买行为。研究发现态度和","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"d89c8aea-6704-4da4-8d42-6ae4eba76bbd","name":"反向头脑风暴","category":"问题解决","scene":"创意枯竭时的产品改进、服务质量提升、流程优化、问题解决方案设计","core_logic":"反向头脑风暴是一种逆向思维方法，通过先思考\"如何让事情变得更糟\"来打破思维定式，然后将这些\"糟糕做法\"反向转化为改进方案。相比普通头脑风暴更容易打破惯性思维，发现被忽视的问题和机会。","steps":"[{\"name\": \"明确问题\", \"description\": \"清晰定义要解决的问题或要改进的对象\"}, {\"name\": \"反向提问\", \"description\": \"提出反向问题——\\\"如何让事情变得更糟/如何失败\\\"\"}, {\"name\": \"收集反向想法\", \"description\": \"团队 brainstorm 所有\\\"让事情变糟\\\"的做法，越多越好\"}, {\"name\": \"反向转化\", \"description\": \"将每个\\\"糟糕做法\\\"反向思考，转化为改进方案\"}, {\"name\": \"评估筛选\", \"description\": \"评估转化后的方案，选出最有价值的进行深化\"}, {\"name\": \"实施计划\", \"description\": \"为选定方案制定具体的行动计划\"}]","itto":"{\"tools\": [\"白板/在线协作工具、头脑风暴规则、亲和图法\"], \"inputs\": [\"待改进的问题或对象、团队成员、问题背景信息\"], \"outputs\": [\"改进方案清单、优先级排序后的行动计划、反向思维洞察\"]}","tools":"头脑风暴、亲和图法、思维导图、投票排序","cases":"产品用户体验改进、客户服务流程优化、员工满意度提升、营销策略创新","viz_type":"process","viz_config":"{}","keywords":"反向头脑风暴,逆向思维,创意,问题解决,创新","sort_order":69,"_created_at":"2026-09-16T16:20:51.153+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:50.995+08:00","_updated_by":"()","code":"SOLVE-REVBS-001","aliases":"逆向头脑风暴,反向思维法,Reverse Brainstorming","summary":"先系统列举\"如何让事情变糟\"再反向转化为改进方案的创新方法","problem_statement":"正向头脑风暴想不出好创意，或者创意都太常规、没突破，换了好几种方式还是打不开思路，创新陷入瓶颈；反向头脑风暴先系统列举'如何让事情变糟'，再反向转化为改进方案，用逆向思维激发突破性创意。","triggers":"反向头脑风暴,创意枯竭,改进方案,逆向思维,打破定式,问题解决","applicable":"产品/服务质量改进、流程优化、用户体验提升、寻找创新切入点、团队创意激发","not_applicable":"纯技术性问题、已有明确解决方案的问题、需要严格定量分析的场景","related_frameworks":"头脑风暴法,逆向思维,SCAMPER法,设计思维","templates":"反向头脑风暴工作表、问题反向提问模板","limitations":"依赖参与者的想象力；容易走向负面需要引导转化；不适用于需要精确答案的问题","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"d8c74689-7da2-4886-86fc-caf95cd5e131","name":"扎根理论","category":"科研写作","scene":"质性研究、探索性研究、新领域/新现象研究、管理研究、社会学论文","core_logic":"扎根理论（Grounded Theory）由 Glaser & Strauss 提出，是一种\"自下而上\"从资料中建构理论的质性研究方法。与传统的\"先有假设再验证\"不同，扎根理论强调从经验资料中归纳和发展理论，通过开放编码→主轴编码→选择编码的三级编码过程，逐步从数据中\"扎根\"出理论。","steps":"[{\"name\": \"资料收集\", \"description\": \"通过访谈、观察等方式收集原始质性资料，从数据出发而非从理论假设出发\"}, {\"name\": \"开放编码 Open Coding\", \"description\": \"逐行逐句分析资料，进行概念化和范畴化，提炼初始概念和范畴\"}, {\"name\": \"主轴编码 Axial Coding\", \"description\": \"发现和建立范畴之间的逻辑关系，形成主范畴和副范畴的关联结构\"}, {\"name\": \"选择编码 Selective Coding\", \"description\": \"提炼核心范畴，构建故事线，形成完整的理论框架\"}, {\"name\": \"持续比较与理论饱和\", \"description\": \"资料收集与分析同步进行，持续比较，直到新资料不再产生新范畴（理论饱和）\"}]","itto":"{\"tools\": [\"扎根理论方法\", \"三级编码\", \"持续比较法\", \"NVivo质性分析\"], \"inputs\": [\"原始资料数据\", \"研究问题\", \"理论敏感性\"], \"outputs\": [\"扎根理论研究论文\", \"新理论/新概念模型\"]}","tools":"NVivo/ATLAS.ti质性分析软件、三级编码技术、持续比较法、理论抽样","cases":"研究\"创业者如何在资源匮乏情况下构建商业模式\"：因为是新现象缺乏现成理论，适合用扎根理论。深度访谈20位创业者，对访谈资料进行三级编码，最终归纳出\"资源拼凑→效果推理→价值共创\"的三阶段理论模型。","viz_type":"cycle","viz_config":"{}","keywords":"扎根理论,Grounded Theory,质性研究,编码,格拉泽,施特劳斯,管理社科","sort_order":139,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.003+08:00","_updated_by":"()","code":"RES-028","aliases":"扎根理论","summary":"扎根理论（Grounded Theory）由 Glaser & Strauss 提出，是一种\"自下而上\"从资料中建构理论的质性研究方法。与传统的\"先有假设再验证","problem_statement":"质性研究要么先有理论再套资料、要么资料堆完了提炼不出理论，研究停留在描述层面，理论贡献不足；扎根理论是自下而上从资料中建构理论的方法，通过持续比较和三级编码实现从经验资料到理论的升华。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"质性研究、探索性研究、新领域/新现象研究、管理研究、社会学论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"研究\"创业者如何在资源匮乏情况下构建商业模式\"：因为是新现象缺乏现成理论，适合用扎根理论。深度访谈20位创业者，对访谈资料进行三级编码，最终归纳出\"资源拼凑→效果推理→价值共创\"的三阶段理论模型。","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"d9efc09a-5f94-47b8-ab25-d78ed774dddb","name":"逻辑树分析","category":"思维方法","scene":"复杂问题拆解、方案分析、议题研究等场景","core_logic":"把一个大问题作为树干，逐层分解为若干个子问题（树枝），再继续分解直到每个子问题都可以独立解决。通过MECE原则保证拆解不重不漏，从而化繁为简。","steps":"[{\"name\": \"明确核心问题\", \"description\": \"\"}, {\"name\": \"第一层拆解：关键子问题\", \"description\": \"\"}, {\"name\": \"逐层继续拆解到可操作层级\", \"description\": \"\"}, {\"name\": \"检查MECE（不重不漏）\", \"description\": \"\"}, {\"name\": \"逐个解决子问题并汇总\", \"description\": \"\"}]","itto":"{\"tools\": [\"MECE原则、思维导图\"], \"inputs\": [\"待分析的问题\"], \"outputs\": [\"结构化的问题树、解决方案\"]}","tools":"MECE原则、思维导图、Issue Tree","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"逻辑树,问题树,结构化分析,MECE,拆解","sort_order":6,"_created_at":"2026-09-15T18:34:03.229+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.011+08:00","_updated_by":"()","code":"SOL-THK-002","aliases":"逻辑树,问题树,议题树","summary":"将复杂问题逐层拆解为子问题，结构化求解的分析方法","problem_statement":"复杂问题一团乱麻，不知道从何下手，分析没有结构、东一榔头西一棒子，找不到问题的关键节点和突破口；逻辑树将复杂问题逐层拆解为可处理的子问题，化大为小、化繁为简，结构化地找到解决方案。","triggers":"拆解,逻辑树,问题树,结构化,分析","applicable":"战略分析、商业问题诊断、学术研究、问题定位","not_applicable":"简单直观的问题、高度创造性的探索","related_frameworks":"MECE 原则,问题域—解空间,金字塔原理","templates":"逻辑树分析模板","limitations":"拆解维度选择影响分析质量；容易陷入分析过度；需要一定的领域知识","mastery_level":"L3","last_used_date":null,"domain_code":"SOLVE"},{"id":"da2a790d-7a97-4239-902c-0eced61e1ac6","name":"NPS 净推荐值","category":"客户交付","scene":"客户满意度测量、口碑评估、客户体验管理的场景","core_logic":"NPS通过问一个简单问题：「你有多大可能向朋友或同事推荐我们？（0-10分）」，将客户分为推荐者(9-10分)、被动者(7-8分)、贬损者(0-6分)，NPS=推荐者%-贬损者%。配合原因追问，成为客户体验管理的核心指标。","steps":"[{\"name\": \"设计NPS调研问题和时机\", \"description\": \"\"}, {\"name\": \"选择触达渠道发送调研\", \"description\": \"\"}, {\"name\": \"收集并计算NPS得分\", \"description\": \"\"}, {\"name\": \"分析推荐/贬损原因\", \"description\": \"\"}, {\"name\": \"制定改进行动计划\", \"description\": \"\"}, {\"name\": \"持续追踪NPS变化\", \"description\": \"\"}]","itto":"{\"tools\": [\"NPS调研工具、问卷\"], \"inputs\": [\"客户列表\"], \"outputs\": [\"NPS得分、原因分析、改进计划\"]}","tools":"NPS调研工具、问卷星、客户成功平台","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"NPS,净推荐值,客户忠诚度,口碑,客户体验","sort_order":5,"_created_at":"2026-09-15T18:34:20.145+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.019+08:00","_updated_by":"()","code":"CUST-NPS-001","aliases":"NPS,净推荐值,Net Promoter Score","summary":"通过一个问题衡量客户忠诚度和口碑的指标体系","problem_statement":"客户满意度指标复杂难懂，无法快速衡量客户忠诚度，也不知道客户愿不愿意帮你口碑传播；NPS只用一个问题就能衡量客户忠诚度和口碑意愿，简单高效、行业通用，便于横向对比和追踪趋势。","triggers":"NPS,净推荐值,客户忠诚度,口碑,推荐","applicable":"SaaS产品、消费品牌、服务行业、客户体验管理","not_applicable":"B2G等关系型销售、客户数量极少的业务","related_frameworks":"客户满意度管理,客户旅程图,QBR 季度业务回顾","templates":"NPS调研模板","limitations":"只有一个指标不够深入；得分受行业和文化影响；需要结合原因分析才有行动价值","mastery_level":"L3","last_used_date":null,"domain_code":"CUST"},{"id":"dad09ad9-1e5c-4447-8f1b-1f59dda168c9","name":"典型案例—经验提炼—启示建议","category":"科研写作","scene":"政策咨询报告、地方发展研究、经验借鉴类论文、管理案例研究","core_logic":"非常实用的应用研究型论文/报告结构——通过解剖一个（或几个）成功的典型案例，从中提炼出可复制的经验模式，再结合本地实际提出可操作的启示建议。既要有案例的生动性，又要有提炼的普适性，最终落脚点是\"为我所用\"。","steps":"[{\"name\": \"典型案例选择与描述\", \"description\": \"选择具有代表性和借鉴意义的典型案例，完整描述其做法和成效\"}, {\"name\": \"经验模式提炼\", \"description\": \"从案例做法中归纳提炼出具有可复制性的经验模式和关键要素\"}, {\"name\": \"适用性分析\", \"description\": \"分析这些经验的适用条件、前提假设和边界条件，不能照搬\"}, {\"name\": \"启示与建议\", \"description\": \"结合本地区/本领域的实际情况，提出可借鉴的启示和具体建议\"}]","itto":"{\"tools\": [\"案例分析法\", \"经验提炼\", \"对标分析\", \"政策借鉴\"], \"inputs\": [\"典型案例资料\", \"本地实际情况\", \"对比分析\"], \"outputs\": [\"案例研究报告\", \"经验借鉴方案\", \"政策建议\"]}","tools":"案例研究、经验总结法、对标分析、SWOT对比","cases":"\"浙江\"最多跑一次\"改革对X省的启示\"：典型案例（浙江最多跑一次改革的做法、成效、关键举措）→ 经验提炼（顶层设计+技术支撑+流程再造+考核机制）→ 适用性分析（两省在经济水平、政务基础、治理能力上的异同）→ 启示建议（X省可以学什么、需要什么条件、如何分阶段推进）","viz_type":"process","viz_config":"{}","keywords":"案例借鉴,经验提炼,启示建议,典型案例,对标学习,案例比较","sort_order":156,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.026+08:00","_updated_by":"()","code":"RES-WRI-011","aliases":"案例借鉴","summary":"非常实用的应用研究型论文/报告结构——通过解剖一个（或几个）成功的典型案例，从中提炼出可复制的经验模式，再结合本地实际提出可操作的启示建议。既要有案例的生动性，","problem_statement":"应用研究型论文要么写成纯案例缺乏理论提炼，要么空谈理论脱离实践，可读性和实用性都不强；典型案例-经验提炼-启示建议结构既有案例生动性又有理论高度和实践指导性，非常适合应用研究类论文。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"政策咨询报告、地方发展研究、经验借鉴类论文、管理案例研究","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"\"浙江\"最多跑一次\"改革对X省的启示\"：典型案例（浙江最多跑一次改革的做法、成效、关键举措）→ 经验提炼（顶层设计+技术支撑+流程再造+考核机制）→ 适用性分析（两省在经济水平、政务基础、治理能力上的","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"db6ef933-9afd-47b9-8433-6add3d5b0c86","name":"SLA 服务级别协议","category":"客户交付","scene":"客户服务、IT运维、外包服务等需要明确服务承诺的场景","core_logic":"SLA是服务提供商与客户之间签订的正式协议，明确约定服务的质量标准、响应时间、可用性、考核指标、违约责任等，为服务交付提供可量化的衡量标准和约束机制。","steps":"[{\"name\": \"确定服务范围和内容\", \"description\": \"\"}, {\"name\": \"定义关键服务指标(SLI)\", \"description\": \"\"}, {\"name\": \"设定服务等级目标(SLO)\", \"description\": \"\"}, {\"name\": \"约定考核和赔偿机制\", \"description\": \"\"}, {\"name\": \"签订协议并公示\", \"description\": \"\"}, {\"name\": \"定期监控和报告\", \"description\": \"\"}]","itto":"{\"tools\": [\"监控系统、报表工具\"], \"inputs\": [\"服务内容、客户需求\"], \"outputs\": [\"SLA协议、服务报告\"]}","tools":"监控系统、服务报表、工单系统、SLA管理平台","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"SLA,服务级别协议,服务质量,响应时间,可用性","sort_order":1,"_created_at":"2026-09-15T18:34:20.112+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.034+08:00","_updated_by":"()","code":"CUST-SLA-001","aliases":"SLA,服务级别协议,Service Level Agreement","summary":"明确服务质量标准和考核指标的正式协议","problem_statement":"服务质量没有明确标准，客户期望和实际交付落差大，出了问题说不清是谁的责任，纠纷不断；SLA明确定义服务质量标准、考核指标和违约条款，让服务可衡量、责任可界定、客户有预期。","triggers":"SLA,服务级别,服务协议,响应时间,可用性","applicable":"IT运维服务、外包服务、客户支持、云服务、SaaS产品","not_applicable":"内部非关键服务、一次性项目交付","related_frameworks":"SOW 工作说明书,QBR 季度业务回顾,客户升级机制","templates":"SLA协议模板","limitations":"指标设定不合理会导致博弈；需要监控系统支撑；过度SLA化可能忽略客户真实体验","mastery_level":"L3","last_used_date":null,"domain_code":"CUST"},{"id":"dbec9802-520c-4206-a1d5-5fa4034a160a","name":"布鲁姆认知分类法","category":"教学科研","scene":"学习目标设计、教学活动设计、考试题设计、教学评估的场景","core_logic":"布鲁姆分类法将认知领域的学习目标从低到高分为六个层级：记忆→理解→应用→分析→评价→创造。帮助教师设计不同层次的学习目标和教学活动，确保教学从低级认知逐步进阶到高级认知。","steps":"[{\"name\": \"确定主题和内容范围\", \"description\": \"\"}, {\"name\": \"设计记忆层目标（知道什么）\", \"description\": \"\"}, {\"name\": \"设计理解层目标（能解释）\", \"description\": \"\"}, {\"name\": \"设计应用层目标（会使用）\", \"description\": \"\"}, {\"name\": \"设计分析层目标（能拆解）\", \"description\": \"\"}, {\"name\": \"设计评价层目标（能判断）\", \"description\": \"\"}, {\"name\": \"设计创造层目标（能生成）\", \"description\": \"\"}]","itto":"{\"tools\": [\"目标编写、教学活动设计\"], \"inputs\": [\"教学内容、目标学员水平\"], \"outputs\": [\"分层学习目标、教学方案\"]}","tools":"目标编写、教学活动设计、测验命题","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"布鲁姆,认知分类,学习目标,Bloom,教学设计","sort_order":4,"_created_at":"2026-09-15T18:34:26.511+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.042+08:00","_updated_by":"()","code":"TEACH-BLOOM-001","aliases":"布鲁姆,Bloom,认知目标分类,学习目标分类","summary":"将认知学习目标分为六个层级的经典分类框架","problem_statement":"教学目标写得笼统模糊，分不清是记忆还是理解、是应用还是创造，教学设计和评估都失去了方向；布鲁姆认知分类法将认知目标分为记忆-理解-应用-分析-评价-创造六个层级，让目标精准、教学对路、评估到位。","triggers":"布鲁姆,认知分类,学习目标,Bloom,记忆理解应用","applicable":"课程设计、教学目标编写、考试命题、教学评估、教师培训","not_applicable":"技能型学习（动作技能领域不同）、态度价值观学习（情感领域不同）","related_frameworks":"OBE 成果导向教育,评价量规 Rubric,BOPPPS 课堂模型","templates":"布鲁姆分类学习目标编写参考","limitations":"主要针对认知领域；六层边界有时不清晰；需要结合具体学科调整","mastery_level":"L3","last_used_date":null,"domain_code":"TEACH"},{"id":"dc317918-7523-44b3-bc60-af77f1613097","name":"SMART 目标设定","category":"项目管理","scene":"个人绩效目标制定、团队 OKR/KPI 设定、项目里程碑规划、年度目标拆解。","core_logic":"一个有效的目标必须同时满足五个条件：Specific（具体明确）、Measurable（可量化衡量）、Achievable（可实现）、Relevant（与战略相关）、Time-bound（有时间限制）。缺少任何一个要素都会导致目标模糊、难以落地或无法评估。","steps":"[{\"name\": \"S - Specific 具体\", \"description\": \"目标必须明确具体，不能模糊不清，回答6W：谁、什么、哪里、何时、哪个、为什么\"}, {\"name\": \"M - Measurable 可衡量\", \"description\": \"目标必须有量化指标，可以衡量进度和结果\"}, {\"name\": \"A - Achievable 可实现\", \"description\": \"目标在现实条件下可以达成，既有挑战性又不过高\"}, {\"name\": \"R - Relevant 相关性\", \"description\": \"目标与整体战略和其他目标相关联，有意义\"}, {\"name\": \"T - Time-bound 有时限\", \"description\": \"目标有明确的截止日期，有时间紧迫感\"}]","itto":"{\"tools\": [\"OKR\", \"KPI\", \"目标拆解\"], \"inputs\": [\"战略目标\", \"现状评估\"], \"outputs\": [\"可执行目标\", \"行动清单\"]}","tools":"OKR 工具（飞书/北森）、Excel 目标跟踪、季度复盘会","cases":"反例：「提高用户满意度」（不 SMART）——正例：「在 Q4 结束前，将 App 用户满意度从 3.8 分提升至 4.5 分以上，通过每月迭代 2 个核心体验优化点实现」（完全符合 SMART 五要素）。","viz_type":"process","viz_config":"{}","keywords":"SMART,目标管理,OKR","sort_order":5,"_created_at":"2026-09-15T17:23:12.573+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.049+08:00","_updated_by":"()","code":"PM-PLN-001","aliases":"SMART","summary":"一个有效的目标必须同时满足五个条件：Specific（具体明确）、Measurable（可量化衡量）、Achievable（可实现）、Relevant（与战略相","problem_statement":"目标设定模糊笼统，比如'提升质量''做好服务'，最后无法衡量、无法考核，干好干坏一个样；SMART原则从具体、可衡量、可实现、相关性、时限性五个维度约束目标，让目标清晰可落地、结果可验证。","triggers":"项目延期、进度失控、范围蔓延、资源不足","applicable":"个人绩效目标制定、团队 OKR/KPI 设定、项目里程碑规划、年度目标拆解。","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"反例：「提高用户满意度」（不 SMART）——正例：「在 Q4 结束前，将 App 用户满意度从 3.8 分提升至 4.5 分以上，通过每月迭代 2 个核心体验优化点实现」（完全符合 SMART 五要","limitations":"需结合具体场景灵活调整","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"dddfa3c8-d7d0-4f78-8856-8ca9e3dfecf8","name":"用例图","category":"需求管理","scene":"软件系统需求分析、功能范围界定、系统交互设计的场景","core_logic":"用例图通过参与者（Actor）、用例（Use Case）和关系（关联、包含、扩展、泛化）的图形化表示，清晰描述系统提供的功能、谁使用这些功能、以及功能之间的关系，是需求分析和系统设计的核心工具。","steps":"[{\"name\": \"识别系统参与者(Actor)\", \"description\": \"\"}, {\"name\": \"识别核心用例(Use Case)\", \"description\": \"\"}, {\"name\": \"定义参与者与用例的关系\", \"description\": \"\"}, {\"name\": \"识别用例间的包含/扩展关系\", \"description\": \"\"}, {\"name\": \"绘制用例图\", \"description\": \"\"}, {\"name\": \"编写用例规约\", \"description\": \"\"}]","itto":"{\"tools\": [\"UML建模工具\"], \"inputs\": [\"需求描述、用户角色\"], \"outputs\": [\"用例图、用例规约\"]}","tools":"Visio、StarUML、draw.io、UML工具","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"用例图,Use Case,UML,需求建模,系统功能","sort_order":10,"_created_at":"2026-09-15T18:34:20.019+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.057+08:00","_updated_by":"()","code":"PROD-USE-001","aliases":"用例图,Use Case,UML用例","summary":"UML中描述系统功能与参与者交互关系的可视化建模工具","problem_statement":"系统功能描述全靠文字，参与者和功能的关系说不清道不明，开发和测试各理解各的，最后对接不上；用例图以可视化方式描述系统功能与参与者的交互关系，让功能边界和交互逻辑一目了然。","triggers":"用例,用例图,Use Case,UML,需求建模","applicable":"软件系统需求分析、功能规格说明、系统设计、测试用例设计","not_applicable":"非软件系统、简单的小型工具","related_frameworks":"需求跟踪矩阵 RTM,用户故事,原型法","templates":"用例图模板、用例规约模板","limitations":"学习曲线；过度建模会陷入形式主义；无法表达非功能性需求","mastery_level":"L2","last_used_date":null,"domain_code":"PROD"},{"id":"df1cde89-e1e3-4733-a770-26de03f37131","name":"TAM / UTAUT 模型","category":"科研写作","scene":"信息系统研究、用户行为研究、新技术推广研究、教育技术研究论文","core_logic":"TAM（技术接受模型，Davis, 1989）是信息系统领域被引用最多的理论，核心是\"感知有用性\"和\"感知易用性\"决定用户对技术的接受度。UTAUT（技术接受与使用统一理论，Venkatesh等, 2003）整合了8个相关理论，提炼出绩效期望、努力期望、社会影响、促成条件四个核心变量和四个调节变量，解释力更强。","steps":"[]","itto":"{\"tools\": [\"TAM/UTAUT量表\", \"问卷调研\", \"结构方程模型\", \"回归分析\"], \"inputs\": [\"用户调研数据\", \"技术使用情境\", \"用户特征\"], \"outputs\": [\"技术接受影响因素分析\", \"推广策略建议\"]}","tools":"TAM/UTAUT量表设计、问卷调研、结构方程模型（SEM）、信效度检验","cases":"在线学习平台用户接受度研究：用UTAUT模型设计问卷，测量绩效期望（学了能提升成绩）、努力期望（平台好不好用）、社会影响（同学老师都在用）、促成条件（有手机有网）四个变量，用SEM分析哪些因素最影响学生的使用意愿。","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"核心：技术接受行为模型\", \"description\": \"解释和预测用户为什么接受或拒绝使用某项新技术\"}, {\"name\": \"TAM 核心结构\", \"items\": [\"感知有用性（PU）：认为用了能提升工作绩效\", \"感知易用性（PEOU）：认为使用该技术是否容易\", \"使用态度 → 行为意向 → 实际使用\"]}, {\"name\": \"UTAUT 四核心变量\", \"items\": [\"绩效期望（PE）：对应TAM的PU\", \"努力期望（EE）：对应TAM的PEOU\", \"社会影响（SI）：他人看法影响使用意愿\", \"促成条件（FC）：使用的客观条件支持\"]}, {\"name\": \"调节变量\", \"items\": [\"性别\", \"年龄\", \"经验\", \"自愿性\"]}]}","keywords":"TAM,UTAUT,技术接受模型,技术采纳,信息系统,Davis,管理社科","sort_order":137,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.066+08:00","_updated_by":"()","code":"RES-THY-005","aliases":"TAM","summary":"TAM（技术接受模型，Davis, 1989）是信息系统领域被引用最多的理论，核心是\"感知有用性\"和\"感知易用性\"决定用户对技术的接受度。UTAUT（技术接受与","problem_statement":"研究用户技术接受度时缺乏理论指导，想到什么因素就加什么因素，研究碎片化、结果难以对比和积累；TAM/UTAUT模型是信息系统领域最成熟的技术接受理论，提供了系统化的影响因素和测量体系。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"信息系统研究、用户行为研究、新技术推广研究、教育技术研究论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"在线学习平台用户接受度研究：用UTAUT模型设计问卷，测量绩效期望（学了能提升成绩）、努力期望（平台好不好用）、社会影响（同学老师都在用）、促成条件（有手机有网）四个变量，用SEM分析哪些因素最影响学","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"e1e3f107-8ec1-4e0c-9bf8-9b1f260dd82a","name":"德尔菲法","category":"思维方法","scene":"需要专家意见但又要避免权威影响的预测和决策场景","core_logic":"德尔菲法通过匿名、多轮反馈、统计收敛的方式收集专家意见。每一轮收集意见后将统计结果反馈给专家，专家可以根据群体意见调整自己的判断，经过多轮迭代后逐渐收敛到较为一致的结论。","steps":"[{\"name\": \"组建专家小组\", \"description\": \"\"}, {\"name\": \"第一轮：发放问卷收集初始意见\", \"description\": \"\"}, {\"name\": \"整理统计第一轮结果\", \"description\": \"\"}, {\"name\": \"第二轮：反馈统计结果，专家调整意见\", \"description\": \"\"}, {\"name\": \"重复多轮直到达成共识或收敛\", \"description\": \"\"}]","itto":"{\"tools\": [\"问卷、统计分析\"], \"inputs\": [\"预测/决策议题\"], \"outputs\": [\"专家共识结论\"]}","tools":"问卷设计、统计分析、中位数/四分位距","cases":"需补充","viz_type":"cycle","viz_config":"{}","keywords":"德尔菲法,专家调查,预测,匿名共识,多轮反馈","sort_order":9,"_created_at":"2026-09-15T18:34:13.567+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.074+08:00","_updated_by":"()","code":"DEC-DEL-001","aliases":"德尔菲法,Delphi Method,专家调查法","summary":"通过多轮匿名专家调查达成共识的预测和决策方法","problem_statement":"专家讨论容易被权威或多数意见主导，预测和决策结果受人际关系影响，得不到真实的专家判断，决策质量堪忧；德尔菲法通过多轮匿名专家调查和反馈收敛，排除人际干扰，最终达成高质量的专家共识。","triggers":"德尔菲,专家调查,预测,匿名,共识","applicable":"技术预测、风险评估、需求预测、战略规划、政策制定","not_applicable":"需要快速决策的场景、已有充分数据的问题","related_frameworks":"名义小组技术,头脑风暴法,风险矩阵","templates":"德尔菲法实施指南模板","limitations":"周期长、成本高；专家选择影响结果；过程复杂；不一定能达成共识","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"e444a679-b8e4-447a-8778-f92eda004447","name":"决策矩阵","category":"思维方法","scene":"多方案选择、供应商评估、项目选型等需要量化决策的场景","core_logic":"确定决策的多个评估维度并分配权重，对每个方案在各维度上打分，加权求和得到总分，以量化方式比较方案优劣，减少主观偏差。","steps":"[{\"name\": \"明确决策目标和备选方案\", \"description\": \"\"}, {\"name\": \"确定评估维度及权重\", \"description\": \"\"}, {\"name\": \"为每个方案在各维度打分\", \"description\": \"\"}, {\"name\": \"计算加权总分\", \"description\": \"\"}, {\"name\": \"比较总分并结合直觉判断\", \"description\": \"\"}]","itto":"{\"tools\": [\"评分表、权重分配\"], \"inputs\": [\"备选方案、评估标准\"], \"outputs\": [\"排序结果、决策建议\"]}","tools":"评分矩阵、AHP、敏感性分析","cases":"需补充","viz_type":"matrix","viz_config":"{\"x_label\": \"评估维度\", \"y_label\": \"备选方案\", \"quadrants\": {\"q1\": \"加权评分\"}}","keywords":"决策矩阵,加权评分,多维度评估,量化决策,方案比较","sort_order":18,"_created_at":"2026-09-15T18:34:03.191+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.082+08:00","_updated_by":"()","code":"META-THK-010","aliases":"决策矩阵,加权评分矩阵","summary":"通过多维度加权评分量化比较备选方案的决策工具","problem_statement":"备选方案太多不知道怎么选，凭感觉选又怕错，决策过程不系统不透明，选完了还后悔，也说服不了别人；决策矩阵通过多维度加权评分量化比较各备选方案，让选择过程有据可依、结果更客观、更有说服力。","triggers":"决策,选型,评估,比较,矩阵","applicable":"供应商选择、技术选型、投资决策、人员评估","not_applicable":"完全定性的价值判断、决策维度无法量化的场景","related_frameworks":"AHP 层次分析法,多准则决策 MCDA,成本效益分析","templates":"决策矩阵评分表模板","limitations":"权重和打分有主观性；容易产生虚假精确感；需结合经验判断","mastery_level":"L3","last_used_date":null,"domain_code":"META"},{"id":"e4c3face-229d-4778-995e-a6291b6996b1","name":"微服务架构","category":"系统架构","scene":"大型复杂系统演进、团队规模化、业务快速迭代的场景","core_logic":"微服务架构将单体应用拆分为一组小型、独立部署、松耦合的服务，每个服务围绕单一业务能力构建，独立开发、独立部署、独立扩展。通过API/消息队列通信，实现团队自治和技术栈多样化。","steps":"[{\"name\": \"梳理业务领域和限界上下文\", \"description\": \"\"}, {\"name\": \"确定服务拆分策略\", \"description\": \"\"}, {\"name\": \"设计服务间通信机制\", \"description\": \"\"}, {\"name\": \"设计服务治理方案\", \"description\": \"\"}, {\"name\": \"建设运维监控体系\", \"description\": \"\"}, {\"name\": \"渐进式拆分迁移\", \"description\": \"\"}]","itto":"{\"tools\": [\"DDD、容器化、服务网格\"], \"inputs\": [\"单体系统/业务域\"], \"outputs\": [\"微服务系统架构、服务清单\"]}","tools":"Docker、Kubernetes、服务网格、API网关、分布式追踪","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"微服务,Microservices,分布式架构,服务拆分,云原生","sort_order":5,"_created_at":"2026-09-15T18:34:26.451+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.089+08:00","_updated_by":"()","code":"ARCH-MS-001","aliases":"微服务,Microservices,微服务架构","summary":"将单体应用拆分为多个小型独立服务的架构风格","problem_statement":"单体应用越来越臃肿，部署慢、扩展难、技术栈锁定，一个模块出问题拖垮整个系统，团队协作也越来越困难；微服务架构将单体拆分为多个独立部署的小服务，每个服务可独立开发、独立部署、独立扩展。","triggers":"微服务,Microservices,服务拆分,分布式,松耦合","applicable":"大型互联网系统、业务复杂且多变的系统、多团队协作的组织","not_applicable":"小型简单系统、团队规模小、业务稳定的系统","related_frameworks":"DDD 领域驱动设计,分层架构,高可用架构设计","templates":"微服务拆分评估表","limitations":"分布式系统复杂度高；运维成本大幅增加；需要成熟的DevOps能力；服务拆分不当会更糟","mastery_level":"L3","last_used_date":null,"domain_code":"ARCH"},{"id":"e552df74-3198-40e1-9861-bbf4e3ae24da","name":"RACI 矩阵","category":"项目管理","scene":"项目启动、团队分工、流程优化等需要明确职责的场景","core_logic":"RACI矩阵将任务与角色交叉，明确每个任务中谁负责执行(R)、谁最终负责(A)、谁需要被咨询(C)、谁需要被告知(I)，避免职责不清、推诿扯皮和多头指挥。","steps":"[{\"name\": \"列出所有关键任务/活动\", \"description\": \"\"}, {\"name\": \"列出所有相关角色/人员\", \"description\": \"\"}, {\"name\": \"为每个任务分配R/A/C/I\", \"description\": \"\"}, {\"name\": \"确保每个任务有且只有一个A\", \"description\": \"\"}, {\"name\": \"与所有相关方沟通确认\", \"description\": \"\"}]","itto":"{\"tools\": [\"团队研讨\"], \"inputs\": [\"任务清单、角色清单\"], \"outputs\": [\"RACI职责矩阵\"]}","tools":"头脑风暴、工作坊、Excel矩阵","cases":"某跨部门项目启动时用RACI梳理：项目经理(Responsible)负责日常推进，项目总监(Accountable)最终批准，技术总监/产品总监(Consulted)提供专业意见，客户/相关部门(Informed)同步进度。解决了之前谁都管、谁都不管的问题。","viz_type":"matrix","viz_config":"{\"x_label\": \"角色\", \"y_label\": \"任务\", \"quadrants\": {\"q1\": \"R/A/C/I分配\"}}","keywords":"RACI,职责矩阵,分工,角色职责,项目管理","sort_order":17,"_created_at":"2026-09-15T18:34:13.674+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.097+08:00","_updated_by":"()","code":"PM-RACI-001","aliases":"RACI,职责矩阵,Responsible Accountable Consulted Informed","summary":"明确各角色在任务中的职责分配（执行/审批/咨询/知情）的工具","problem_statement":"团队任务职责不清，有人闲有人忙，出了问题互相甩锅，重要的事没人管、不重要的事抢着做；RACI矩阵明确每个任务的执行者、审批者、咨询者和知情者，消除职责重叠和责任真空。","triggers":"RACI,职责矩阵,分工,职责,角色","applicable":"项目团队分工、流程职责划分、组织架构调整、跨部门协作","not_applicable":"小型团队、职责清晰的简单任务","related_frameworks":"权力/利益矩阵,贝尔宾团队角色,授权与分工","templates":"RACI矩阵模板","limitations":"任务和角色过多时矩阵过于复杂；是静态工具需要定期更新；需要组织文化配合","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"e6d4a1af-6335-47e4-8332-2a4498877515","name":"仿真建模","category":"科研写作","scene":"复杂系统研究、管理科学、工程仿真、交通仿真、社会仿真论文","core_logic":"仿真建模通过在计算机中构建虚拟系统模型，模拟系统的运行来研究复杂问题。当真实系统难以做实验、成本太高或需要预测未来时，仿真就是最佳替代方案。主要类型包括：离散事件仿真、系统动力学仿真、基于Agent的仿真（ABM）、蒙特卡洛仿真等。","steps":"[{\"name\": \"问题与目标定义\", \"description\": \"明确仿真研究的问题和目标，确定要研究的系统和变量\"}, {\"name\": \"概念建模\", \"description\": \"建立系统的概念模型，确定主体、规则、环境和交互方式\"}, {\"name\": \"模型实现\", \"description\": \"用编程语言或仿真工具实现仿真模型，包括参数设置和数据输入\"}, {\"name\": \"校验与验证\", \"description\": \"模型校验（程序正确）和验证（模型反映真实系统），确保模型可信\"}, {\"name\": \"仿真实验与分析\", \"description\": \"设计仿真实验方案，运行多组实验，分析结果得出结论\"}]","itto":"{\"tools\": [\"AnyLogic\", \"NetLogo\", \"Python仿真\", \"蒙特卡洛模拟\", \"ABM\"], \"inputs\": [\"研究问题\", \"系统规则\", \"参数数据\"], \"outputs\": [\"仿真模型\", \"实验结果\", \"政策/设计建议\"]}","tools":"AnyLogic、NetLogo、Arena、Python（SimPy/Mesa）、MATLAB","cases":"城市急诊资源配置仿真研究：用离散事件仿真模拟急诊科室的患者到达、排队、诊疗过程，建立仿真模型后，测试不同医生配置、床位数量、分诊策略下的患者等待时间、资源利用率等指标，找到最优资源配置方案。","viz_type":"process","viz_config":"{}","keywords":"仿真建模,模拟仿真,ABM,蒙特卡洛,计算实验,工程系统","sort_order":164,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.104+08:00","_updated_by":"()","code":"SOL-SYS-002","aliases":"仿真建模","summary":"仿真建模通过在计算机中构建虚拟系统模型，模拟系统的运行来研究复杂问题。当真实系统难以做实验、成本太高或需要预测未来时，仿真就是最佳替代方案。主要类型包括：离散事","problem_statement":"真实系统太复杂、成本太高或无法做实验，只能靠拍脑袋决策，政策和方案的效果无法提前预测；仿真建模通过在计算机中构建虚拟系统模型，模拟系统运行来研究复杂问题，是预测和评估的有力工具。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"复杂系统研究、管理科学、工程仿真、交通仿真、社会仿真论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"城市急诊资源配置仿真研究：用离散事件仿真模拟急诊科室的患者到达、排队、诊疗过程，建立仿真模型后，测试不同医生配置、床位数量、分诊策略下的患者等待时间、资源利用率等指标，找到最优资源配置方案。","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"SOLVE"},{"id":"e7bfed98-1b1d-49c9-b3de-7f12be99298d","name":"4+1 视图模型","category":"系统架构","scene":"软件系统架构设计、架构文档编写、架构评审的场景","core_logic":"4+1视图模型由Philippe Kruchten提出，通过逻辑视图（功能需求）、开发视图（模块与包）、进程视图（并发与同步）、物理视图（部署与拓扑）四个视图，加上用例/场景视图（+1）来完整描述软件架构，不同视图满足不同干系人的关注点。","steps":"[{\"name\": \"用例视图(+1): 核心功能场景\", \"description\": \"\"}, {\"name\": \"逻辑视图: 功能模块与关系\", \"description\": \"\"}, {\"name\": \"开发视图: 代码模块和包结构\", \"description\": \"\"}, {\"name\": \"进程视图: 并发与同步机制\", \"description\": \"\"}, {\"name\": \"物理视图: 部署拓扑与硬件\", \"description\": \"\"}]","itto":"{\"tools\": [\"UML、架构设计工具\"], \"inputs\": [\"系统需求、非功能需求\"], \"outputs\": [\"架构设计文档、多视图模型\"]}","tools":"UML、Archimate、架构设计工具、C4模型","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"4+1视图,软件架构,架构视图,多视角设计,Kruchten","sort_order":3,"_created_at":"2026-09-15T18:34:26.434+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.112+08:00","_updated_by":"()","code":"ARCH-VIEW-001","aliases":"4+1视图,Philippe Kruchten,架构视图","summary":"从五个视图描述软件架构的多视角建模方法","problem_statement":"架构设计只画一张图就想说明白所有事情，不同干系人关注的内容不一样，架构文档看了等于没看，沟通效率低下；4+1视图模型从逻辑、进程、物理、开发四个视图加场景视角，多维度描述软件架构，满足不同角色需求。","triggers":"4+1视图,架构视图,软件架构,多视角,逻辑视图开发视图","applicable":"中大型软件系统架构设计、架构评审、架构文档","not_applicable":"小型简单系统、快速原型验证","related_frameworks":"TOGAF 企业架构,DDD 领域驱动设计,分层架构","templates":"4+1视图架构文档模板","limitations":"需要绘制多个视图工作量大；某些视图边界可能模糊；需要根据项目裁剪","mastery_level":"L3","last_used_date":null,"domain_code":"ARCH"},{"id":"e9e3aa83-cb17-402f-a634-74ccdf39322e","name":"蓝海战略 ERRC 框架","category":"战略决策","scene":"战略创新、商业模式重塑、产品/服务差异化、开创新市场的场景","core_logic":"蓝海战略由W.钱·金和勒妮·莫博涅提出，核心是通过「价值创新」同时追求差异化和低成本，打破价值与成本的权衡取舍。ERRC四步动作框架是其核心工具：消除（哪些行业默认元素该消除？）、减少（哪些元素应减少到行业标准以下？）、提升（哪些元素应提升到行业标准以上？）、创造（哪些元素是行业从未有过需要创造的？），四个动作共同作用开辟蓝海。","steps":"[{\"name\": \"描绘当前战略布局图\", \"description\": \"列出行业竞争的关键要素，描绘当前的价值曲线\"}, {\"name\": \"思考「消除」\", \"description\": \"哪些行业默认的竞争元素其实可以消除？（用户并不真正在乎）\"}, {\"name\": \"思考「减少」\", \"description\": \"哪些元素可以减少到行业标准以下？（过度服务浪费成本）\"}, {\"name\": \"思考「提升」\", \"description\": \"哪些元素应该大幅提升到行业标准以上？（用户痛点所在）\"}, {\"name\": \"思考「创造」\", \"description\": \"应该创造哪些行业从未有过的新元素？（全新价值主张）\"}, {\"name\": \"绘制新的战略布局图\", \"description\": \"将四个动作的结果绘制成新的价值曲线，检查是否差异化且聚焦\"}, {\"name\": \"验证蓝海创意\", \"description\": \"用买方效益、价格、成本、接受度四个步骤验证蓝海创意的可行性\"}, {\"name\": \"制定执行策略\", \"description\": \"制定蓝海战略的实施路线图和组织保障措施\"}]","itto":"{\"tools\": [\"ERRC四步动作框架、战略布局图、价值曲线、蓝海创意验证四步、客户洞察\"], \"inputs\": [\"行业分析、竞争格局、用户调研、成本结构、现有产品/服务分析\"], \"outputs\": [\"ERRC分析报告、新战略布局图、蓝海战略方案、实施路线图\"]}","tools":"ERRC框架模板、战略布局图、用户旅程分析、竞争对标分析","cases":"太阳马戏团（消除动物减少明星提升帐篷创造主题）、西南航空、任天堂Wii、小米生态链","viz_type":"matrix","viz_config":"{}","keywords":"蓝海战略,ERRC,价值创新,消除减少提升创造,差异化,商业模式","sort_order":74,"_created_at":"2026-09-16T16:20:50.86+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.12+08:00","_updated_by":"()","code":"DECIDE-ERRC-001","aliases":"蓝海战略,ERRC框架,消除-减少-提升-创造,Blue Ocean Strategy,ERRC Grid","summary":"通过消除-减少-提升-创造四步动作，打破价值成本权衡，开创无竞争市场空间","problem_statement":"在红海里和对手死磕，比成本比价格利润越来越薄，想跳出红海又不知道从哪下手、怎么差异化；蓝海战略通过消除-减少-提升-创造四步动作，打破价值成本权衡，开创无竞争的新市场空间。","triggers":"蓝海战略,ERRC,价值创新,消除减少提升创造,差异化,商业模式创新,蓝海","applicable":"战略转型、商业模式创新、新产品/服务设计、市场进入策略、传统行业破局","not_applicable":"受强监管无法改变行业规则的领域、已经是蓝海的新兴市场、纯技术驱动无服务元素的产品","related_frameworks":"安索夫矩阵,PMF产品市场契合,价值曲线分析,商业模式画布,精益创业","templates":"ERRC四步动作框架模板、战略布局图模板、蓝海创意验证清单","limitations":"执行难度大，需要深度用户洞察和勇气；蓝海可能随时间变红海；理论优美但实践成功率不高；模仿者可能快速跟进","mastery_level":"L2","last_used_date":null,"domain_code":"DECIDE"},{"id":"ec0f60e0-5b27-47ba-a06b-8a97db8ec1fa","name":"委托代理理论","category":"科研写作","scene":"公司治理研究、国企改革、公共管理（政府-公务员委托代理）、激励机制设计论文","core_logic":"委托代理理论研究在信息不对称条件下，委托人如何设计最优契约来激励和约束代理人。核心问题是代理人可能利用信息优势损害委托人利益（道德风险和逆向选择）。解决思路是建立\"激励兼容\"的机制，让代理人在追求自身利益的同时也实现委托人的目标。","steps":"[]","itto":"{\"tools\": [\"委托代理模型\", \"博弈论\", \"实证检验\", \"案例研究\"], \"inputs\": [\"委托代理关系信息\", \"激励制度\", \"监督机制\"], \"outputs\": [\"委托代理问题分析\", \"治理机制设计建议\"]}","tools":"委托-代理数学模型、面板回归、双重差分（DID）、案例研究","cases":"国企高管薪酬激励研究：股东（委托人）与高管（代理人）之间存在信息不对称，高管可能追求在职消费而非股东利益最大化。设计合理的薪酬-绩效挂钩机制（股权激励、业绩考核）可以缓解代理问题，降低代理成本。","viz_type":"hierarchy","viz_config":"{\"levels\": [{\"name\": \"委托-代理关系\", \"description\": \"委托人授权代理人代表其行事的契约关系，信息不对称是核心问题\"}, {\"name\": \"两大核心问题\", \"items\": [\"逆向选择（Adverse Selection）：签约前信息不对称，选错了人\", \"道德风险（Moral Hazard）：签约后信息不对称，代理人偷懒/谋私\"]}, {\"name\": \"治理机制\", \"items\": [\"激励机制：让代理人利益与委托人一致（薪酬、股权、期权）\", \"监督机制：监督代理人行为（董事会、审计、信息披露）\", \"市场机制：外部市场约束（经理人市场、并购市场、产品竞争）\"]}]}","keywords":"委托代理,代理成本,信息不对称,道德风险,逆向选择,公司治理,管理社科","sort_order":133,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.127+08:00","_updated_by":"()","code":"RES-THY-001","aliases":"委托代理","summary":"委托代理理论研究在信息不对称条件下，委托人如何设计最优契约来激励和约束代理人。核心问题是代理人可能利用信息优势损害委托人利益（道德风险和逆向选择）。解决思路是建","problem_statement":"信息不对称条件下的激励问题说不清，为什么员工会偷懒、为什么股东和管理层有矛盾，找不到系统性的分析框架；委托代理理论聚焦信息不对称下的道德风险和逆向选择问题，为契约设计和治理机制提供理论指导。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"公司治理研究、国企改革、公共管理（政府-公务员委托代理）、激励机制设计论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"国企高管薪酬激励研究：股东（委托人）与高管（代理人）之间存在信息不对称，高管可能追求在职消费而非股东利益最大化。设计合理的薪酬-绩效挂钩机制（股权激励、业绩考核）可以缓解代理问题，降低代理成本。","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"f07d0412-1c80-480b-825a-1263a19f5dea","name":"用户故事","category":"需求管理","scene":"敏捷开发、迭代规划、需求拆解的场景","core_logic":"用户故事以「作为一个<角色>，我想要<功能>，以便于<价值>」的格式描述需求，强调用户价值和对话而非文档。配合验收标准和故事点估算，成为敏捷团队管理需求的基本单位。","steps":"[{\"name\": \"识别用户角色和价值\", \"description\": \"\"}, {\"name\": \"按格式编写用户故事\", \"description\": \"\"}, {\"name\": \"定义验收标准(Acceptance Criteria)\", \"description\": \"\"}, {\"name\": \"估算故事点/工时\", \"description\": \"\"}, {\"name\": \"按优先级排序进入迭代\", \"description\": \"\"}, {\"name\": \"开发完成后验收\", \"description\": \"\"}]","itto":"{\"tools\": [\"故事卡片、敏捷工具\"], \"inputs\": [\"需求洞察、用户场景\"], \"outputs\": [\"用户故事卡片、验收标准\"]}","tools":"Jira、Trello、用户故事地图、故事点估算","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"用户故事,User Story,敏捷,需求管理,验收标准","sort_order":12,"_created_at":"2026-09-15T18:34:20.035+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.135+08:00","_updated_by":"()","code":"PROD-US-001","aliases":"用户故事,User Story,敏捷需求","summary":"以用户视角描述功能需求的轻量级需求表达方式","problem_statement":"需求写成技术术语和功能列表，开发不知道为谁做、为什么做，偏离用户真实场景和价值；用户故事以'作为某用户，我想要某功能，以便达成某目的'的轻量格式表达需求，始终保持用户视角。","triggers":"用户故事,User Story,敏捷,需求,故事点","applicable":"敏捷开发、迭代式开发、产品功能迭代","not_applicable":"需要详细规格的大型系统、外包项目（合同需要明确范围）","related_frameworks":"MoSCoW 优先级,原型法,用例图","templates":"用户故事模板、验收标准模板","limitations":"粒度把握需要经验；不适合描述复杂系统的整体结构；需要配合其他工具处理非功能性需求","mastery_level":"L3","last_used_date":null,"domain_code":"PROD"},{"id":"f18ff4fd-0718-45c3-a88d-261a9c0de955","name":"民族志研究","category":"科研写作","scene":"人类学、社会学、组织研究、文化研究、消费行为研究、教育研究论文","core_logic":"民族志（Ethnography）源自人类学，核心是研究者长期深入研究对象的生活现场，通过参与观察和深度访谈，从\"内部人视角\"理解其文化、行为和意义体系。格尔茨提出的\"深描\"是民族志写作的典范——不只是描述行为，更要解释行为背后的文化意义。","steps":"[{\"name\": \"进入田野\", \"description\": \"研究者进入研究现场，建立与研究对象的关系，获得进入许可和信任\"}, {\"name\": \"参与观察\", \"description\": \"长期参与研究对象的日常生活，在自然情境中观察和记录，这是民族志的核心方法\"}, {\"name\": \"深度访谈\", \"description\": \"对关键信息提供者进行深度访谈，了解他们的观点、意义和解释\"}, {\"name\": \"资料收集\", \"description\": \"收集实物、文档、影像等多元资料，进行三角验证\"}, {\"name\": \"深描与解释\", \"description\": \"对文化现象进行\\\"深描\\\"（thick description），从内部视角理解文化意义，提炼分析性结论\"}]","itto":"{\"tools\": [\"参与观察法\", \"深度访谈\", \"民族志方法\", \"深描分析\"], \"inputs\": [\"田野进入机会\", \"研究社区/群体\", \"长期时间投入\"], \"outputs\": [\"民族志研究论文\", \"文化解释\", \"质性发现\"]}","tools":"参与观察、深度访谈、田野笔记、三角验证、话语分析","cases":"程序员工作文化民族志研究：研究者进入一家互联网公司，以实习生身份参与日常工作6个月，通过参与观察和访谈，深入理解程序员的工作节奏、技术文化、加班文化、团队互动模式，最终写出\"代码的社会生活\"这样的深描式民族志。","viz_type":"process","viz_config":"{}","keywords":"民族志,Ethnography,参与观察,深描,格尔茨,质性研究,管理社科","sort_order":141,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.143+08:00","_updated_by":"()","code":"RES-030","aliases":"民族志","summary":"民族志（Ethnography）源自人类学，核心是研究者长期深入研究对象的生活现场，通过参与观察和深度访谈，从\"内部人视角\"理解其文化、行为和意义体系。格尔茨提","problem_statement":"研究文化和行为只靠问卷和访谈，理解浮于表面，无法深入研究对象的真实世界和意义体系；民族志研究要求研究者长期深入现场，通过参与观察和深度访谈，从内部人视角理解文化和行为的意义。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"人类学、社会学、组织研究、文化研究、消费行为研究、教育研究论文","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"程序员工作文化民族志研究：研究者进入一家互联网公司，以实习生身份参与日常工作6个月，通过参与观察和访谈，深入理解程序员的工作节奏、技术文化、加班文化、团队互动模式，最终写出\"代码的社会生活\"这样的深描","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"},{"id":"f2cd7758-9fb1-4d2f-81dd-281d5aacae17","name":"形成性评价与终结性评价","category":"教学科研","scene":"课程评价设计、教学质量提升、学习支持的场景","core_logic":"形成性评价是在学习过程中进行的、用于改进教学和学习的评价（如课堂提问、作业、小测验），目的是诊断问题、提供反馈、促进学习；终结性评价是在学习结束时进行的、用于判定学习成果的评价（如期末考试），目的是评分和认证。两者互补配合使用效果最佳。","steps":"[{\"name\": \"确定学习目标\", \"description\": \"\"}, {\"name\": \"设计终结性评价方式\", \"description\": \"\"}, {\"name\": \"设计形成性评价节点和方式\", \"description\": \"\"}, {\"name\": \"确定两者的权重和关系\", \"description\": \"\"}, {\"name\": \"实施并收集形成性反馈\", \"description\": \"\"}, {\"name\": \"学期末进行终结性评价\", \"description\": \"\"}]","itto":"{\"tools\": [\"测验、作业、反馈\"], \"inputs\": [\"课程目标、教学内容\"], \"outputs\": [\"评价方案、学习数据\"]}","tools":"课堂提问、作业、测验、项目、Portfolio","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"形成性评价,终结性评价,教学评估,反馈,学习改进","sort_order":7,"_created_at":"2026-09-15T18:34:26.536+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.15+08:00","_updated_by":"()","code":"TEACH-EVAL-001","aliases":"形成性评价,终结性评价,Formative Summative Assessment","summary":"两种互补的评价类型：过程性改进 vs 结果性判定","problem_statement":"评价只看期末一次性考试，学生学习过程中得不到反馈，问题积累到最后才暴露，已经来不及补救，学习效果差；形成性评价与终结性评价相结合，过程中持续反馈改进、结束时判定最终成绩，兼顾改进和判定双重目的。","triggers":"形成性评价,终结性评价,评估,反馈,学习改进","applicable":"课程评价设计、教学改革、在线教育、培训评估","not_applicable":"完全自学无评估的学习","related_frameworks":"评价量规 Rubric,BOPPPS 课堂模型,布鲁姆认知分类法","templates":"课程评价方案模板","limitations":"形成性评价增加教师工作量；终结性评价可能导致应试；平衡两者需要教学设计能力","mastery_level":"L2","last_used_date":null,"domain_code":"TEACH"},{"id":"f46b259e-72d4-493c-96ea-9dc35979abc1","name":"GE-McKinsey 九宫格","category":"战略决策","scene":"多业务组合战略评估、投资优先级排序、业务资源分配的场景","core_logic":"GE-McKinsey九宫格是通用电气和麦肯锡联合开发的业务组合分析工具，用「行业吸引力」（纵轴，高/中/低）和「业务竞争力」（横轴，强/中/弱）两个多维度复合指标，将业务划分为九宫格。左上区域（吸引力高+竞争力强）→投资增长；对角线区域→选择性投资/维持；右下区域→收割/剥离。相比BCG的两单变量，它考虑因素更全面。","steps":"[{\"name\": \"确定分析的业务单元\", \"description\": \"明确要评估的各战略业务单元(SBU)\"}, {\"name\": \"确定行业吸引力因素及权重\", \"description\": \"选择行业吸引力的关键因素（市场规模、增长率、利润率等）并赋予权重\"}, {\"name\": \"确定业务竞争力因素及权重\", \"description\": \"选择业务竞争力的关键因素（市场份额、品牌、技术、盈利能力等）并赋予权重\"}, {\"name\": \"对每个业务进行评分\", \"description\": \"对每个业务的行业吸引力和竞争力逐项打分，计算加权总分\"}, {\"name\": \"将业务定位到九宫格\", \"description\": \"按得分将各业务标在3×3矩阵中，圆圈大小表示市场规模\"}, {\"name\": \"确定各业务战略\", \"description\": \"左上格→投资增长；中间格→选择维持；右下格→收割/剥离\"}, {\"name\": \"评估业务组合健康度\", \"description\": \"检查业务组合是否均衡，是否有足够的增长型业务和现金牛业务\"}, {\"name\": \"制定资源分配方案\", \"description\": \"根据战略定位调整资源分配，制定行动计划\"}]","itto":"{\"tools\": [\"GE矩阵图、评分表、加权评分模型、行业研究报告\"], \"inputs\": [\"行业数据、竞争格局、财务数据、业务能力评估\"], \"outputs\": [\"GE-McKinsey矩阵图、业务组合分析报告、战略建议、资源分配方案\"]}","tools":"加权评分模型、行业研究报告、竞争分析、财务分析工具","cases":"通用电气GE业务组合管理、大型多元化集团战略规划、投资公司投资组合管理","viz_type":"matrix","viz_config":"{}","keywords":"GE矩阵,麦肯锡矩阵,九宫格,业务组合,行业吸引力,竞争力","sort_order":73,"_created_at":"2026-09-16T16:20:50.849+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.158+08:00","_updated_by":"()","code":"DECIDE-GEMCK-001","aliases":"GE矩阵,麦肯锡矩阵,行业吸引力-竞争力矩阵,GE-McKinsey Matrix,九宫格矩阵","summary":"以行业吸引力和业务竞争力两个多因素维度对业务组合进行战略定位，比BCG更精细","problem_statement":"用BCG矩阵评估业务太粗糙，只看增长率和市场份额两个指标太简单，复杂业务决策不够用；GE-McKinsey九宫格以行业吸引力和业务竞争力两个多因素维度综合评估，比BCG更精细、决策更可靠。","triggers":"GE矩阵,麦肯锡矩阵,九宫格,行业吸引力,业务竞争力,业务组合分析","applicable":"多元化企业业务组合管理、战略投资决策、业务优先级排序、资源分配优化","not_applicable":"单一业务企业、初创公司业务未定、因素权重难以确定的模糊场景","related_frameworks":"波士顿矩阵BCG,安索夫矩阵,SWOT分析,平衡计分卡BSC,价值链分析","templates":"GE-McKinsey矩阵模板、行业吸引力评分表、业务竞争力评分表","limitations":"因素选择和权重设定主观性强；数据收集和评分工作量大；静态分析需要定期更新；不同行业难以横向比较","mastery_level":"L1","last_used_date":null,"domain_code":"DECIDE"},{"id":"f8bc1511-5eac-4be5-b474-e26595e9cc7f","name":"JTBD 理论","category":"需求管理","scene":"产品创新、需求挖掘、市场定位、用户研究的场景","core_logic":"JTBD（Jobs to Be Done）理论认为，用户不是买一个产品，而是在特定情境下雇佣一个产品来完成一项任务（Job）。理解用户想要完成的任务以及任务的场景、痛点、期望，才能做出真正满足需求的产品。","steps":"[{\"name\": \"识别用户的核心任务(Job)\", \"description\": \"\"}, {\"name\": \"理解任务的情境和触发条件\", \"description\": \"\"}, {\"name\": \"分析任务中的痛点和期望\", \"description\": \"\"}, {\"name\": \"定义功能任务和情感任务\", \"description\": \"\"}, {\"name\": \"设计产品解决方案\", \"description\": \"\"}, {\"name\": \"验证产品是否帮助用户完成任务\", \"description\": \"\"}]","itto":"{\"tools\": [\"用户访谈、情景观察\"], \"inputs\": [\"用户场景、用户行为数据\"], \"outputs\": [\"任务定义、产品概念\"]}","tools":"用户访谈、情境调查、用户故事、需求映射","cases":"用户不是买电钻，而是买墙上的洞。案例：客户说\"要更快\"，实际需求是\"减少等待焦虑\"。","viz_type":"process","viz_config":"{}","keywords":"JTBD,Job to Be Done,用户任务,需求理论,产品创新","sort_order":7,"_created_at":"2026-09-15T18:34:13.762+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.166+08:00","_updated_by":"()","code":"PROD-JTBD-001","aliases":"JTBD,Job to Be Done,用户任务理论","summary":"用户不是买产品，而是雇佣产品完成一项任务的需求理论","problem_statement":"产品设计从功能出发而非用户任务出发，功能堆砌但用户不会用、也不需要，产品找不到市场切入点、屡屡失败；JTBD理论指出用户是'雇佣'产品来完成特定任务的，聚焦用户要完成的'任务'而非产品功能本身。","triggers":"JTBD,用户任务,需求理论,Job to Be Done,雇佣","applicable":"产品创新、需求挖掘、市场定位、用户研究、功能规划","not_applicable":"纯技术驱动的产品、用户明确说出需求的场景","related_frameworks":"价值主张画布,访谈法,JTBD 理论","templates":"JTBD任务分析模板","limitations":"需要深入的用户研究；任务定义较抽象；需要结合其他工具落地","mastery_level":"L3","last_used_date":null,"domain_code":"PROD"},{"id":"f9ed33ec-48f4-478a-bd70-66a23422c4de","name":"甘特图","category":"项目管理","scene":"项目进度计划制定、进度跟踪和汇报的场景","core_logic":"甘特图以条形图的方式在时间轴上展示项目的所有任务，每个条形的长度代表持续时间，位置代表起止时间。可以直观展示任务的先后顺序、并行关系、里程碑和项目整体进度。","steps":"[{\"name\": \"列出所有项目任务\", \"description\": \"\"}, {\"name\": \"确定任务间的依赖关系\", \"description\": \"\"}, {\"name\": \"估算每个任务的工期\", \"description\": \"\"}, {\"name\": \"安排任务的起止时间\", \"description\": \"\"}, {\"name\": \"绘制甘特图\", \"description\": \"\"}, {\"name\": \"标注关键路径和里程碑\", \"description\": \"\"}]","itto":"{\"tools\": [\"Project、甘特图软件\"], \"inputs\": [\"WBS、任务清单\"], \"outputs\": [\"进度计划、进度报告\"]}","tools":"MS Project、Excel、各类项目管理软件、关键路径法","cases":"某项目用甘特图展示37个任务的时间安排和依赖关系：需求调研(5天)→系统设计(7天)→前后端开发并行(前端15天/后端20天)→集成测试(5天)→上线(3天)。关键路径清晰可见，帮助团队聚焦核心任务。","viz_type":"process","viz_config":"{}","keywords":"甘特图,进度计划,项目排期,时间管理,横道图","sort_order":12,"_created_at":"2026-09-15T18:34:13.598+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.174+08:00","_updated_by":"()","code":"PM-SCH-001","aliases":"甘特图,Gantt Chart,横道图","summary":"以时间为横轴的条形图，直观展示项目进度和任务安排","problem_statement":"项目进度全靠脑子记或Excel表格乱排，任务依赖关系看不清，延期了不知道影响哪些后续工作；甘特图以时间为横轴直观展示任务起止时间和依赖关系，让项目进度一目了然、延期影响快速可查。","triggers":"甘特图,进度计划,时间轴,任务排期,横道图","applicable":"各类项目的进度计划与跟踪、项目汇报、资源协调","not_applicable":"高度不确定的探索性项目（更适合看板）","related_frameworks":"WBS 工作分解结构,关键路径法,看板","templates":"甘特图模板（Excel/Project）","limitations":"任务太多时图表复杂；需要定期更新维护；不适合频繁变更的敏捷项目","mastery_level":"L3","last_used_date":null,"domain_code":"PM"},{"id":"fa1239b5-33f5-4958-925e-90b718b99c98","name":"OBE 成果导向教育","category":"教学科研","scene":"课程体系设计、专业建设、教学改革、教育评估的场景","core_logic":"OBE（成果导向教育）以学生最终应达到的学习成果为起点，反向设计课程体系、教学方法和评估方式。核心原则是：清楚聚焦（明确成果）、扩大机会（让每个学生都能成功）、高期望（设定高标准）、反向设计（从终点倒推）。","steps":"[{\"name\": \"定义毕业要求/学习成果\", \"description\": \"\"}, {\"name\": \"设计课程体系支撑成果达成\", \"description\": \"\"}, {\"name\": \"设计教学活动促进学习\", \"description\": \"\"}, {\"name\": \"建立评估机制衡量成果\", \"description\": \"\"}, {\"name\": \"持续改进教学\", \"description\": \"\"}]","itto":"{\"tools\": [\"反向设计、评估方法\"], \"inputs\": [\"培养目标、专业要求\"], \"outputs\": [\"课程体系、教学方案、评估体系\"]}","tools":"课程地图、评估矩阵、持续改进机制","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"OBE,成果导向教育,反向设计,学习成果,教育改革","sort_order":3,"_created_at":"2026-09-15T18:34:26.503+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.182+08:00","_updated_by":"()","code":"TEACH-OBE-001","aliases":"OBE,成果导向教育,Outcome-Based Education","summary":"以学习成果为起点反向设计教学的教育理念和方法","problem_statement":"传统教育以教师和教材为中心，教了什么比学生学到了什么更重要，学生毕业达不到培养要求，教育质量堪忧；OBE以学习成果为起点反向设计教学，从预期产出倒推课程和教学，确保学生真正达到培养目标。","triggers":"OBE,成果导向,反向设计,学习成果,教育改革","applicable":"高等教育、职业教育、专业建设、课程改革、工程教育认证","not_applicable":"通识教育、探索性学习、无法明确定义成果的领域","related_frameworks":"布鲁姆认知分类法,ADDIE 教学设计模型,建构对齐","templates":"OBE课程体系设计模板","limitations":"成果定义有难度；过度量化可能导致窄化；需要整体体系配合","mastery_level":"L3","last_used_date":null,"domain_code":"TEACH"},{"id":"fbf1e190-62f7-4ec6-9723-4c7fbd5ff2ba","name":"路径依赖","category":"思维模型","scene":"战略转型、职业选择、技术路线决策、组织变革、习惯改变的场景","core_logic":"路径依赖理论由经济学家道格拉斯·诺斯（Douglass North）提出并系统阐释，他因此贡献获得诺贝尔经济学奖。路径依赖指的是：一旦人们做了某种选择，就好比走上了一条不归路，惯性的力量会使这一选择不断自我强化，并让你轻易走不出去。路径依赖的形成原因包括：沉没成本、收益递增、网络效应、学习效应、适应性预期等。典型案例是键盘的QWERTY布局——它并不是效率最高的，但一旦成为标准就很难改变。识别路径依赖是突破自我、实现变革的前提。","steps":"[{\"name\": \"识别当前路径\", \"description\": \"明确当前所处的「路径」是什么——工作方式、技术栈、商业模式、思维习惯等\"}, {\"name\": \"追溯路径的起源\", \"description\": \"这条路径当初是怎么形成的？基于什么条件和背景做出的选择？\"}, {\"name\": \"评估路径是否仍然最优\", \"description\": \"当初的条件现在还成立吗？这条路径还能带来最好的结果吗？\"}, {\"name\": \"识别路径依赖的机制\", \"description\": \"是什么在维持这条路径？沉没成本、网络效应、学习效应、还是适应性预期？\"}, {\"name\": \"探索替代路径\", \"description\": \"有哪些其他可能的路径？如果从零开始，你会选择哪条路？\"}, {\"name\": \"评估转换成本和收益\", \"description\": \"转换路径需要付出什么成本？能带来什么长期收益？\"}, {\"name\": \"制定转换策略\", \"description\": \"如果决定转换，制定渐进式或跨越式的转换计划，降低转换风险\"}, {\"name\": \"建立新路径的正反馈\", \"description\": \"在新路径上快速积累优势，形成新的、更好的路径依赖\"}]","itto":"{\"tools\": [\"第二曲线创新、逆向思考、零基思考、第一性原理、成本收益分析\"], \"inputs\": [\"历史分析、现状评估、替代方案、成本收益分析\"], \"outputs\": [\"路径依赖诊断报告、转换路径决策、变革实施计划\"]}","tools":"第一性原理、零基思考、第二曲线创新、逆向思维、成本收益分析","cases":"QWERTY键盘、诺基亚的功能机路径依赖、企业数字化转型困难、个人职业路径转换","viz_type":"hierarchy","viz_config":"{}","keywords":"路径依赖,路径锁定,惯性,沉没成本,网络效应,QWERTY,变革","sort_order":85,"_created_at":"2026-09-16T16:20:50.961+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.189+08:00","_updated_by":"()","code":"META-PATHDEP-001","aliases":"路径依赖,Path Dependence,路径锁定,惯性思维,历史锁定","summary":"历史选择会锁定未来方向，即使当前选择不是最优的，识别并突破惯性才能跃迁","problem_statement":"过去的选择限制了现在的决策，明知当前路径不是最优的却难以改变，被历史包袱锁死在低水平轨道；路径依赖揭示历史选择如何锁定未来方向，识别惯性并主动突破才能实现跃迁。","triggers":"路径依赖,路径锁定,惯性,历史包袱,沉没成本,QWERTY,网络效应","applicable":"战略转型、技术路线选择、职业规划、组织变革、产品设计、制度改革","not_applicable":"路径正确且持续产生正反馈的情况、初期尚未形成路径依赖时、简单的一次性决策","related_frameworks":"第一性原理,第二曲线创新,沉没成本谬误,逆向思维,精益创业","templates":"路径依赖自查表、路径转换评估表、零基思考模板","limitations":"路径依赖并不总是坏事，成熟路径往往效率最高；盲目切换路径可能付出巨大代价；识别路径依赖容易，但打破它非常困难；可能过度强调突破而忽视积累的价值","mastery_level":"L2","last_used_date":null,"domain_code":"META"},{"id":"fc658332-65c1-42a1-8ea9-4d3b5a3cac80","name":"假设驱动开发","category":"思维方法","scene":"产品开发、科研探索、业务创新等不确定场景","core_logic":"将想法和信念转化为可验证的假设，设计最小化实验来验证假设的真伪，根据验证结果迭代调整，从而降低不确定性、提高决策质量。","steps":"[{\"name\": \"识别关键假设\", \"description\": \"\"}, {\"name\": \"将假设表述为可验证的命题\", \"description\": \"\"}, {\"name\": \"设计最小验证实验\", \"description\": \"\"}, {\"name\": \"执行实验收集数据\", \"description\": \"\"}, {\"name\": \"分析结果验证/证伪假设\", \"description\": \"\"}, {\"name\": \"迭代调整\", \"description\": \"\"}]","itto":"{\"tools\": [\"实验设计、A/B测试\"], \"inputs\": [\"待验证的想法/问题\"], \"outputs\": [\"验证结论、迭代方案\"]}","tools":"A/B测试、MVP、用户访谈、数据分析、实验设计","cases":"需补充","viz_type":"cycle","viz_config":"{}","keywords":"假设驱动,验证,实验,迭代,科学思维","sort_order":14,"_created_at":"2026-09-15T18:34:03.137+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.198+08:00","_updated_by":"()","code":"META-THK-006","aliases":"假设驱动,Hypothesis Driven","summary":"以假设为起点，通过验证逐步逼近真相的科学思维方式","problem_statement":"做事情不先验证假设就全力投入，做了很多才发现方向错了，浪费大量时间和资源，试错成本极高；假设驱动开发以假设为起点，通过小步验证逐步逼近真相，用最小成本确认正确方向。","triggers":"假设,验证,实验,迭代,不确定性","applicable":"产品创新、创业探索、科研研究、市场验证","not_applicable":"已有明确答案的确定性问题、日常例行事务","related_frameworks":"MVP 最小可行产品,精益创业,设计思维","templates":"假设验证画布、实验日志模板","limitations":"假设的质量决定结果；实验设计不当可能得出错误结论；验证成本可能较高","mastery_level":"L2","last_used_date":null,"domain_code":"META"},{"id":"fc7f40de-23ce-4b24-b076-b2f1b6ac2423","name":"GROW 教练模型","category":"团队管理","scene":"一对一辅导、绩效沟通、问题解决、员工发展的场景","core_logic":"GROW是最经典的教练模型：Goal（目标，明确要达成什么）→ Reality（现状，现在在哪里、有什么资源和障碍）→ Options（选项，有哪些可能的路径）→ Will（行动，决定做什么、什么时候做）。通过提问引导对方自己找到答案。","steps":"[{\"name\": \"G 目标：明确想要达成的目标\", \"description\": \"\"}, {\"name\": \"R 现状：了解当前的实际情况\", \"description\": \"\"}, {\"name\": \"O 选项：探索可能的解决方案\", \"description\": \"\"}, {\"name\": \"W 行动：确定具体行动和时间\", \"description\": \"\"}, {\"name\": \"跟进：后续复盘和支持\", \"description\": \"\"}]","itto":"{\"tools\": [\"提问倾听、教练技巧\"], \"inputs\": [\"被教练者的问题/目标\"], \"outputs\": [\"行动方案、新的认知\"]}","tools":"积极倾听、有力提问、反馈技术","cases":"需补充","viz_type":"process","viz_config":"{}","keywords":"GROW,教练模型,辅导,一对一,员工发展","sort_order":3,"_created_at":"2026-09-15T18:34:20.06+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.205+08:00","_updated_by":"()","code":"TEAM-COACH-001","aliases":"GROW教练,教练模型,Goal-Reality-Options-Will","summary":"目标—现状—选项—行动的结构化教练辅导框架","problem_statement":"给下属辅导直接给答案，下属永远不会独立思考，下次遇到问题还是来找你，团队成长缓慢、能力薄弱；GROW教练模型通过目标-现状-选项-行动的结构化提问，引导对方自己找到答案，实现授人以渔。","triggers":"GROW,教练,辅导,一对一,绩效沟通","applicable":"员工辅导、绩效沟通、职业发展、问题解决、领导力发展","not_applicable":"紧急情况需要直接指令的场景、纯知识传授","related_frameworks":"情境领导模型,非暴力沟通,授权与分工","templates":"GROW教练对话模板","limitations":"需要教练具备良好的提问和倾听能力；对复杂问题可能不够深入；需要建立信任关系","mastery_level":"L3","last_used_date":null,"domain_code":"TEAM"},{"id":"fede0e8f-b81b-48d2-8f1e-57a5cdb5f7b4","name":"5Why 分析法","category":"思维方法","scene":"质量问题、运营异常、故障排查等根因分析场景","core_logic":"5Why分析法由丰田生产方式的创始人大野耐一推广，是丰田生产体系的重要根因分析工具。面对问题时，不满足于表面原因，连续追问五次为什么，层层深入直到找到问题的根本原因，从而避免治标不治本。该方法强调现场现地现物（三现主义），通过连续追问穿透现象直达本质。","steps":"[{\"name\": \"明确具体问题\", \"description\": \"\"}, {\"name\": \"问第一个为什么：为什么会发生？\", \"description\": \"\"}, {\"name\": \"基于答案继续问下一个为什么\", \"description\": \"\"}, {\"name\": \"重复追问直到找到根本原因\", \"description\": \"\"}, {\"name\": \"验证根本原因并制定对策\", \"description\": \"\"}]","itto":"{\"tools\": [\"追问法、现场观察\"], \"inputs\": [\"问题现象描述\"], \"outputs\": [\"根本原因、改进措施\"]}","tools":"追问法、现场三现主义、鱼骨图","cases":"需补充","viz_type":"hierarchy","viz_config":"{}","keywords":"5Why,五问法,根因分析,连续追问,根本原因","sort_order":5,"_created_at":"2026-09-15T18:34:03.216+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.213+08:00","_updated_by":"()","code":"SOL-THK-001","aliases":"5Why,五问法,五个为什么","summary":"通过连续追问为什么找到问题根本原因的分析方法","problem_statement":"出了问题只找表面原因，找到一个就停了，治标不治本，同样的问题反复发生，永远在救火从不防火；5Why通过连续追问五个为什么层层深入，挖到问题的根本原因，从根源上彻底解决问题。","triggers":"根因,为什么,追问,根本原因,质量问题","applicable":"质量改进、故障排查、流程优化、问题复盘","not_applicable":"复杂多因问题、需要数据验证的系统性问题","related_frameworks":"鱼骨图,根本原因分析 RCA,8D 问题解决法","templates":"5Why分析表","limitations":"容易受分析者知识水平限制；可能追溯到错误方向；复杂问题需要结合其他工具","mastery_level":"L3","last_used_date":null,"domain_code":"SOLVE"},{"id":"ff8dbb14-eff4-44dd-87bc-160e7124b07c","name":"DPSIR：驱动力—压力—状态—影响—响应","category":"科研写作","scene":"环境政策研究、可持续发展研究、资源管理、生态保护类论文和报告","core_logic":"DPSIR 是欧洲环境署提出的分析框架，用于描述社会与环境之间的因果链条：社会经济驱动力产生环境压力，压力改变环境状态，状态变化带来影响，社会做出响应（政策），响应又作用于驱动力/压力/状态，形成一个反馈循环。","steps":"[{\"name\": \"D - Driving Forces 驱动力\", \"description\": \"引发环境变化的深层社会经济因素，如人口增长、经济发展、技术进步\"}, {\"name\": \"P - Pressures 压力\", \"description\": \"驱动力作用下对环境产生的直接压力，如污染排放、资源消耗、土地利用变化\"}, {\"name\": \"S - State 状态\", \"description\": \"环境系统在压力作用下的当前状态，如空气质量、水质、生物多样性\"}, {\"name\": \"I - Impacts 影响\", \"description\": \"环境状态变化对人类和生态系统产生的影响，如健康影响、经济损失\"}, {\"name\": \"R - Responses 响应\", \"description\": \"社会对环境问题做出的政策和行动回应，又反过来作用于驱动力，形成循环\"}]","itto":"{\"tools\": [\"环境经济学\", \"系统分析\", \"指标体系\", \"政策分析\"], \"inputs\": [\"社会经济数据\", \"环境监测数据\", \"政策文件\"], \"outputs\": [\"环境政策研究报告\", \"DPSIR分析框架\"]}","tools":"环境经济学、生命周期评价（LCA）、系统动力学、指标体系法","cases":"城市空气质量治理研究：驱动力（机动车保有量增长、工业发展）→ 压力（尾气排放、工业废气）→ 状态（PM2.5浓度超标天数）→ 影响（呼吸系统疾病增加、能见度下降）→ 响应（限行政策、产业升级、新能源推广）","viz_type":"cycle","viz_config":"{}","keywords":"DPSIR,驱动力压力状态影响响应,环境政策,可持续发展,政策调研","sort_order":114,"_created_at":"2026-09-15T17:41:51.994+08:00","_created_by":"()","_updated_at":"2026-09-17T08:16:51.221+08:00","_updated_by":"()","code":"RES-WRI-009","aliases":"DPSIR","summary":"DPSIR 是欧洲环境署提出的分析框架，用于描述社会与环境之间的因果链条：社会经济驱动力产生环境压力，压力改变环境状态，状态变化带来影响，社会做出响应（政策），","problem_statement":"环境与社会关系的研究缺乏系统性因果链条，要么只看环境状态、要么只看政策响应，逻辑不完整、建议不落地；DPSIR框架建立了驱动力-压力-状态-影响-响应的完整因果链条，让环境研究逻辑清晰、对策精准。","triggers":"论文写不下去、框架混乱、思路不清、结构松散","applicable":"环境政策研究、可持续发展研究、资源管理、生态保护类论文和报告","not_applicable":"简单问题无需复杂框架","related_frameworks":"","templates":"城市空气质量治理研究：驱动力（机动车保有量增长、工业发展）→ 压力（尾气排放、工业废气）→ 状态（PM2.5浓度超标天数）→ 影响（呼吸系统疾病增加、能见度下降）→ 响应（限行政策、产业升级、新能源推","limitations":"需结合具体场景灵活调整","mastery_level":"L2","last_used_date":null,"domain_code":"RES"}];
